/// The owner-side half of the pin, established once per probe.
pub(in crate::analysis) struct OwnerReturnPin {
    name: String,
    call: PinCall,
    path: ReturnPathGate,
    /// Where the owner `fn` starts. It serves the #6957 exemption, where a
    /// same-name type declaration in the owner's own enclosing module is the
    /// production declaration, not a test-local shadow. It also places the
    /// owner among its file's inline modules and crate root, which a
    /// path-qualified call (`crate::m::name(..)`, `krate::name(..)`) must
    /// reach (#6974).
    owner_file: PathBuf,
    owner_start_line: usize,
    /// The owner declares `-> bool`, so `assert!(owner(..))` pins its whole
    /// return value to `true` and `assert!(!owner(..))` to `false`.
    returns_bool: bool,
    /// The owner declares a primitive scalar return (`u32`, `bool`, `char`,
    /// ...). An immutable `let` of its result is `Copy` with no interior
    /// mutability, so no later statement can change it (cell-0094).
    returns_scalar: bool,
    /// A [`Self::returns_scalar`] owner whose return type is a built-in
    /// integer, so `.min(K)`, `.max(K)`, `* 1` and `+ 0` keep their std
    /// meaning on it (trap-ceiling-wide-min-control).
    returns_integer: bool,
    /// The owner is an `async fn`, so a test reads its return value as
    /// `owner(..).await` (RIPR-SPEC-0197 rule 1, `#[tokio::test]`).
    awaited: bool,
    /// Every record type the owner's return expression constructs has at
    /// most a plain (empty) `Drop` impl in the workspace, so dropping the
    /// receiver while unwinding from a failed assertion cannot exit the
    /// process before the failure is reported (#8480).
    drop_plain: bool,
    /// Per test file: whether the owner's trait is in scope. The trait is
    /// fixed per pin and the scan masks the whole file, so it runs once.
    trait_scope_by_file: SyncMemo<BTreeMap<PathBuf, bool>>,
    /// Same-named module-level rivals in the owner's package, settled per
    /// test by the call's spelled path (#6544). `None` when there are none.
    /// Shared per analysis run with the relation stage's identity (#7716).
    identity: Option<std::sync::Arc<OwnerCallIdentity>>,
}

/// A file's `std`/`core`-rooted `assert_eq!` paths and, for each of the four
/// rooted spellings, whether the file can rebind that root.
#[derive(Clone, Debug, Default)]
struct StdRootedCalls {
    calls: BTreeSet<String>,
    unrebound: BTreeSet<String>,
}

const STD_ROOTED_ASSERT_EQ: [&str; 4] = [
    "std::assert_eq",
    "core::assert_eq",
    "::std::assert_eq",
    "::core::assert_eq",
];

impl StdRootedCalls {
    fn of(source: &str) -> Self {
        let Some(file) = parse_clean_source_file(source) else {
            return Self::default();
        };
        let root = file.tree().syntax().clone();
        Self {
            calls: std_rooted_assert_eq_calls(&root),
            unrebound: STD_ROOTED_ASSERT_EQ
                .iter()
                .filter(|path| {
                    crate::analysis::syntax::ra::std_macro_root_is_unrebound(path, &root)
                })
                .map(|path| (*path).to_string())
                .collect(),
        }
    }
}

/// Run-scoped syntax decisions shared by every probe against one index.
/// No cache outlives that immutable index; no public/file facts are changed.
#[derive(Clone, Debug, Default)]
pub(in crate::analysis) struct OwnerPinSyntax {
    /// Per test file, its `std`/`core`-rooted `assert_eq!` calls and which
    /// of those roots the file itself leaves unrebound (#7857). Parsed once
    /// per file, not once per assertion.
    std_rooted: SyncMemo<BTreeMap<PathBuf, StdRootedCalls>>,
    fallible_dependencies:
        SyncMemo<BTreeMap<PathBuf, (String, Option<crate::analysis::workspace::AnyhowIdentity>)>>,
    ambiguous_macro_bindings: SyncMemo<Option<BTreeSet<String>>>,
    /// Definitions confined to one inline module or function body, keyed by
    /// file: they make a name ambiguous only for tests inside that scope.
    scoped_macro_bindings: SyncMemo<Option<ScopedMacroBindings>>,
    /// Crate-local sites keyed by the recognized target root that holds
    /// them: they make a name ambiguous only for tests in that crate.
    crate_macro_bindings: SyncMemo<Option<CrateMacroBindings>>,
    /// #8255: the workspace-wide sites the single trusted-macro ambiguity
    /// pass retained, completed on demand, so naming a refusal never
    /// rescans the workspace per (name, test root).
    workspace_site_scan: SyncMemo<Option<WorkspaceMacroSiteIndex>>,
    /// #8255 test witness: full-index macro-site passes this run paid.
    #[cfg(test)]
    workspace_scan_passes: SyncMemo<u32>,
    /// Disclosure memo: each test file's sites per refused name. A file's
    /// sites depend only on the name and the index, and parsing the file
    /// once per (probe, test, assertion) made a diff with many related tests
    /// run for an hour.
    test_file_macro_sites: SyncMemo<TestFileMacroSites>,
    by_file: SyncMemo<BTreeMap<PathBuf, OwnerPinAssertions>>,
    /// #6648 (RIPR-SPEC-0279): per doc example test (file, start line), its
    /// assertion admission read from its synthetic source, parsed once per
    /// run. A doctest is its own crate, so the file holding the comment
    /// declares no function its assertions could be read under.
    doctest_pins: SyncMemo<BTreeMap<(PathBuf, usize), OwnerPinAssertions>>,
    /// Per file: the exact pattern pins of its tests through a verified
    /// local `assert_matches!` (#6616), parsed once per run.
    pattern_pins: SyncMemo<BTreeMap<PathBuf, PatternPins>>,
    empty_macro_ambiguities: SyncMemo<BTreeMap<PathBuf, BTreeSet<String>>>,
    /// Per file: the expansion-coordinate admission facts of the tests a
    /// same-file `macro_rules!` generated (#5334).
    generated: SyncMemo<BTreeMap<PathBuf, Vec<GeneratedTestPins>>>,
    resolved_modules: OnceLock<BTreeSet<(PathBuf, usize, String)>>,
    /// Workspace-wide inputs to [`TargetRoots::root`], computed once.
    target_roots: OnceLock<TargetRoots>,
    /// #6974: path-call memos. A path-shaped assertion is read once per
    /// probe, test and assertion, and each input below scans the workspace,
    /// so every answer is kept for the run under the key it depends on.
    path_memo: SyncMemo<PathCallMemo>,
    /// #7097: per-file module scopes (direct `use`s and value-taking
    /// items), parsed once per run; `None` when the file does not parse.
    /// `Arc` so the run-scoped instance stays `Send` behind the seam
    /// walk's shared `Mutex` (#8282); the table is immutable once built.
    file_scopes: SyncMemo<BTreeMap<PathBuf, Option<Arc<FileScopes>>>>,
    /// #7097: bare-call binding verdicts per [`BareCallKey`].
    bare_call_memo: SyncMemo<BTreeMap<BareCallKey, bool>>,
    /// #7097: out-of-line module children per (parent file, `mod` name):
    /// the composed child file, or `None` when declarations conflict.
    /// Built once per run; the index is immutable.
    mod_children: OnceLock<BTreeMap<(PathBuf, String), Option<PathBuf>>>,
    /// #7172: [`unit_struct_value`]'s workspace-wide scan verdicts,
    /// computed once per run over the once-built module-name set.
    /// The index is immutable, so the memo never goes stale.
    unit_struct_facts: OnceLock<UnitStructFacts>,
    /// RIPR-SPEC-0225 decision 9: whether the workspace is closed for
    /// iteration, a whole-index scan computed once per run.
    iteration_closed: OnceLock<bool>,
    /// The same closed-field premise without the array iteration restriction.
    field_projection_workspace_closed: OnceLock<bool>,
    /// RIPR-SPEC-0225 decision 9: the names a workspace macro may declare a
    /// type under, `None` when any name may be declared.
    macro_type_names: OnceLock<Option<BTreeSet<String>>>,
    /// RIPR-SPEC-0225 decision 9: [`field_builtin_integer`] answers per
    /// [`FieldIntegerKey`]; the index is immutable, so none goes stale.
    field_integer_memo: SyncMemo<BTreeMap<FieldIntegerKey, Option<&'static str>>>,
    withheld: WithheldMacroBindings,
}

/// #7097: a bare-call binding verdict key: owner file, owner line, owner
/// name, test file, test line.
type BareCallKey = (PathBuf, usize, String, PathBuf, usize);

/// RIPR-SPEC-0225 decision 9: a field-integer key: owner file, owner name,
/// record type name, field name.
type FieldIntegerKey = (PathBuf, String, String, String);

/// #6974: run-scoped answers for [`OwnerReturnPin::path_reaches_owner`].
#[derive(Clone, Debug, Default)]
struct PathCallMemo {
    /// Per (owner file, owner start line, owner name, path prefix, test
    /// file, test line): the verdict.
    verdicts: BTreeMap<(PathBuf, usize, String, String, PathBuf, usize), bool>,
    /// Per (file, fn name, start line): the inline modules enclosing that
    /// item, or `None` when ripr cannot place it.
    nesting: BTreeMap<(PathBuf, String, usize), Option<ItemNesting>>,
    /// Per (owner crate root, owner name): whether the crate may hold an
    /// item of the name ripr cannot see.
    hidden: BTreeMap<(PathBuf, String), bool>,
    /// Per file: whether a `cfg` may drop the whole file (#7082).
    file_gated: BTreeMap<PathBuf, bool>,
    /// Per (test crate root, path root): whether the test's crate may bind
    /// the root itself.
    test_crate_binds: BTreeMap<(PathBuf, String), bool>,
}

/// The macro bindings of files a narrowed diff index withheld (#5320).
/// The ambiguity unions below run over every indexed file, so the withheld
/// files' share is folded in to keep the decision the full selection made.
/// Name-specific empty-macro bindings need no entry here: the diff scope
/// admits every file that spells a test file's local empty-macro name.
#[derive(Clone, Debug, Default)]
pub(in crate::analysis) struct WithheldMacroBindings {
    /// Some withheld file may shadow any macro name.
    any_name: bool,
    /// A crate-local site routed by root may shadow any macro name. The
    /// trusted set stays per root, but a test file's local empty-macro names
    /// are refused workspace-wide, as the full scan's empty-macro check
    /// reads every indexed file without crate routing.
    root_any_name: bool,
    /// Trusted macro names withheld files may shadow.
    trusted: BTreeSet<String>,
    /// The first withheld site per trusted name, so a refusal can still
    /// name where the binding is.
    sites: BTreeMap<String, (PathBuf, MacroBindingSite)>,
    /// Crate-local sites in a withheld crate root file, keyed by that root:
    /// as in the full scan, they reach only tests in the same crate.
    by_root: CrateMacroBindings,
    /// The first such site per trusted name and root, for disclosure.
    root_sites: BTreeMap<(String, PathBuf), (PathBuf, MacroBindingSite)>,
}

impl WithheldMacroBindings {
    /// Fold one withheld file in. Returns `true` once nothing further can
    /// change the result, so the caller can stop reading.
    pub(in crate::analysis) fn absorb(
        &mut self,
        path: &Path,
        source: &str,
        packages: &BTreeSet<String>,
        drop_ins: &DropInManifests,
    ) -> bool {
        if self.any_name {
            return true;
        }
        let drop_in_verified = |krate: &str| {
            if krate == "serde_json" {
                drop_ins.verified_literal_json(path)
            } else {
                drop_ins.verified_root(path, krate)
            }
        };
        let root = withheld_crate_root(path);
        for (name, site) in macro_binding_scan(
            source,
            packages,
            &assertion_context_macros(),
            &drop_in_verified,
        ) {
            if let Some(root) = root.as_ref().filter(|_| site.crate_local) {
                self.root_any_name |= site.kind.binds_any_name();
                self.by_root
                    .entry(root.clone())
                    .or_default()
                    .insert(name.clone());
                self.root_sites
                    .entry((name, root.clone()))
                    .or_insert_with(|| (path.to_path_buf(), site));
                continue;
            }
            self.any_name |= site.kind.binds_any_name();
            self.trusted.insert(name.clone());
            self.sites
                .entry(name)
                .or_insert_with(|| (path.to_path_buf(), site));
        }
        self.any_name
    }
}

/// A withheld file is not indexed, so its module edges are unknown; only a
/// file that is itself a `src/lib.rs`, `src/main.rs` or `src/bin/*.rs` crate
/// root has a root known from its path, matching [`target_root`] for it.
/// Any other withheld file keeps its sites workspace-wide (fails closed).
fn withheld_crate_root(path: &Path) -> Option<PathBuf> {
    let names: Vec<&str> = path
        .iter()
        .map(|part| part.to_str().unwrap_or_default())
        .collect();
    let recognized = matches!(
        names.as_slice(),
        [.., "src", "lib.rs" | "main.rs"] | [.., "src", "bin", _]
    );
    (recognized && path.extension().is_some_and(|extension| extension == "rs"))
        .then(|| path.to_path_buf())
}

impl OwnerPinSyntax {
    /// The run's memo of a whole-index verdict that `compute` reads once.
    pub(in crate::analysis) fn iteration_closed(&self, compute: impl FnOnce() -> bool) -> bool {
        *self.iteration_closed.get_or_init(compute)
    }

    pub(in crate::analysis) fn field_projection_workspace_closed(
        &self,
        compute: impl FnOnce() -> bool,
    ) -> bool {
        *self.field_projection_workspace_closed.get_or_init(compute)
    }

    /// Whether a macro in the workspace may declare a type named `name`.
    fn macro_may_declare(&self, name: &str, index: &RustIndex) -> bool {
        self.macro_type_names
            .get_or_init(|| macro_type_names(index))
            .as_ref()
            .is_none_or(|names| names.contains("$") || names.contains(name))
    }

    /// Bounded targeted-selection identity for a non-generic inherent call.
    /// Cross-file imports, nested type paths and receiver inference stay
    /// unresolved; this is not a general Rust name resolver.
    pub(in crate::analysis) fn targeted_inherent_call_is_local(
        &self,
        test: &TestSummary,
        owner: &FunctionSummary,
        prefix: &str,
        index: &RustIndex,
    ) -> bool {
        let FunctionContainer::Inherent { self_ty } = &owner.item.container else {
            return false;
        };
        if owner.file != test.file || !is_plain_identifier(self_ty) {
            return false;
        }
        let Some(facts) = index.files().get(&test.file) else {
            return false;
        };
        if facts.used_lexical_fallback
            || file_aliases_type(&facts.source, self_ty)
            || file_renames_to(&facts.source, self_ty)
            || file_imports_foreign_callee_name(&facts.source, self_ty, &index.package_names)
            || declares_type(&mask_comments_and_strings(&test.body), self_ty)
            || file_aliases_type(&test.body, self_ty)
        {
            return false;
        }
        let (Some(owner_scope), Some(test_scope)) = (
            item_nesting_with_impl(&facts.source, &owner.name, owner.start_line, true),
            self.item_nesting(index, &test.file, &test.name, test.start_line),
        ) else {
            return false;
        };
        if owner_scope.cfg_gated || self.file_cfg_gated(index, &owner.file) {
            return false;
        }
        if prefix == self_ty {
            // Imported bindings and globs can shadow the local type, including
            // evidence-only support owners excluded from candidate collection.
            // Without scope resolution, conservatively refuse any such import
            // in this file; an explicit crate-root path is checked separately.
            owner_scope.modules == test_scope.modules
                && !file_use_statements(&facts.source).iter().any(|statement| {
                    // Include raw bindings and grouped `Type::{self}` imports;
                    // unrelated mentions of this type also stay conservative.
                    contains_as_whole_word(statement, self_ty) || statement.contains('*')
                })
        } else if prefix == format!("crate::{self_ty}") {
            owner_scope.modules.is_empty()
                && self.target_roots(index).root(&owner.file, index).as_ref() == Some(&owner.file)
        } else {
            false
        }
    }

    /// #6974: [`item_nesting`], kept per (file, name, line).
    fn item_nesting(
        &self,
        index: &RustIndex,
        file: &Path,
        name: &str,
        line: usize,
    ) -> Option<ItemNesting> {
        let key = (file.to_path_buf(), name.to_string(), line);
        if let Some(known) = self.path_memo.borrow().nesting.get(&key) {
            return known.clone();
        }
        let nesting = index
            .files()
            .get(file)
            .and_then(|facts| item_nesting(&facts.source, name, line));
        self.path_memo
            .borrow_mut()
            .nesting
            .insert(key, nesting.clone());
        nesting
    }

    /// #7082: whether a `cfg` may drop `file` as a whole, kept per file: a
    /// dropping inner attribute ([`has_cfg_that_may_drop`]) at the top of
    /// the file or of any file on the chain that compiles it into its
    /// crate, or a dropping attribute on any `mod` declaration on that
    /// chain. A complementary cfg may then compile a same-named module in
    /// its place. An include edge, an unresolved chain, an unparsable file,
    /// or a non-root file with no recorded chain (ripr records no edge for
    /// a `mod` whose `#[path]` it cannot resolve, such as one under
    /// `cfg_attr`) fails closed. The root test is per file, not the
    /// workspace-wide [`TargetRoots`] switch, so an unrelated unresolvable
    /// module elsewhere keeps other owners pinned (#7104 review).
    fn file_cfg_gated(&self, index: &RustIndex, file: &Path) -> bool {
        if let Some(known) = self.path_memo.borrow().file_gated.get(file) {
            return *known;
        }
        let roots = self.target_roots(index);
        let inner_gated = |path: &Path| {
            index.files().get(path).is_none_or(|facts| {
                parse_clean_source_file(&facts.source)
                    .is_none_or(|parse| has_cfg_that_may_drop(&parse.tree()))
            })
        };
        let gated = inner_gated(file)
            || index.files().get(file).is_none_or(|facts| {
                let provenance = &facts.role_provenance;
                (provenance.edges.is_empty()
                    && target_root(file, index, &roots.src_dirs).as_deref() != Some(file))
                    || provenance.earliest_unresolved_reason.is_some()
                    || provenance.edges.iter().any(|edge| {
                        edge.kind != SourceRoleProvenanceEdgeKind::Module
                            || inner_gated(&edge.parent)
                            || module_declaration_cfg_gated(
                                index,
                                &edge.parent,
                                &edge.declaration,
                                edge.line,
                            )
                    })
            });
        self.path_memo
            .borrow_mut()
            .file_gated
            .insert(file.to_path_buf(), gated);
        gated
    }

    /// #6974: whether the crate rooted at `owner_root` may hold an item
    /// named `name` that ripr cannot see, kept per (root, name): a raw
    /// `r#name` anywhere in the workspace, or a macro invocation in the
    /// crate whose input names it (`twin!(name)` may emit a `fn name` under
    /// a cfg that drops the owner).
    fn crate_may_hide_name(
        &self,
        index: &RustIndex,
        owner_root: &Path,
        name: &str,
        roots: &TargetRoots,
    ) -> bool {
        let key = (owner_root.to_path_buf(), name.to_string());
        if let Some(known) = self.path_memo.borrow().hidden.get(&key) {
            return *known;
        }
        let hidden = workspace_mentions_raw(index, name)
            || index.files().iter().any(|(path, facts)| {
                facts.source.contains(name)
                    && roots.root(path, index).as_deref() == Some(owner_root)
                    && bound_by_macro(&mask_comments_and_strings(&facts.source), name)
            });
        self.path_memo.borrow_mut().hidden.insert(key, hidden);
        hidden
    }

    /// Fold in the macro bindings of files the diff index withheld.
    pub(in crate::analysis) fn with_withheld(mut self, withheld: WithheldMacroBindings) -> Self {
        self.withheld = withheld;
        self
    }

    /// Shared assertion admission for the bounded supported families.
    /// Execution provenance is independent of the error/boundary/value matcher.
    /// Applicability is the invocation
    /// identity, not the more restrictive owner-pin operand shape, so token
    /// matches and nested diagnostic syntax cannot bypass the same refusal.
    pub(in crate::analysis) fn admits_equality_assertion(
        &self,
        probe: &Probe,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> bool {
        let gated = (matches!(
            probe.family,
            ProbeFamily::ReturnValue | ProbeFamily::ErrorPath | ProbeFamily::Predicate
        ) && is_admission_gated_assert_eq(&assertion.text))
            || (probe.family == ProbeFamily::MatchArm
                && outer_macro_path(&assertion.text).is_some_and(|path| {
                    let leaf = drop_in_assertion_leaf(&path).unwrap_or(&path);
                    leaf.strip_prefix("r#").unwrap_or(leaf) == "assert"
                }));
        !gated || self.admits(test, assertion, index)
    }

    /// Why [`Self::admits_equality_assertion`] refused this assertion, for
    /// disclosure only. `None` when it is admitted. Computed after the
    /// decision, so it never changes what is credited.
    pub(in crate::analysis) fn equality_assertion_refusal(
        &self,
        probe: &Probe,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> Option<AssertionRefusal> {
        if self.admits_equality_assertion(probe, test, assertion, index) {
            return None;
        }
        let refusal = self
            .refusal(test, assertion, index)
            .unwrap_or(AssertionRefusal::Syntax(
                AssertionContextRefusal::UnidentifiedTest,
            ));
        Some(match refusal {
            AssertionRefusal::Syntax(AssertionContextRefusal::MacroBinding(name)) => {
                let resolved_modules = self.resolved_module_declarations(index);
                let resolved = |path: &Path, line: usize, declaration: &str| {
                    resolved_modules.contains(&(path.to_path_buf(), line, declaration.to_string()))
                };
                let test_root = self.target_roots(index).root(&test.file, index);
                // #8255: the single ambiguity pass retained the earliest
                // sites; a lookup completes that pass once when it stopped
                // early, instead of rescanning the workspace per
                // (name, test root).
                let workspace = self
                    .workspace_macro_site(&name, test_root.as_deref(), index)
                    .or_else(|| self.withheld.sites.get(&name).cloned())
                    .or_else(|| {
                        self.withheld
                            .root_sites
                            .iter()
                            .find_map(|((site_name, root), site)| {
                                (*site_name == name
                                    && test_root.as_ref().is_none_or(|test_root| test_root == root))
                                .then(|| site.clone())
                            })
                    });
                // A definition or `use` covering the test is a real
                // rebinding; it outranks a workspace site that only may
                // rebind the name, or the refusal would read as an analyzer
                // limit (RIPR-SPEC-0240) for a macro that is really replaced.
                let local = test_macro_binding_site(
                    &name,
                    test,
                    assertion.line,
                    index,
                    &self.test_file_macro_sites,
                    &resolved,
                );
                let site = if local.as_ref().is_some_and(|(_, site)| rebinds(site)) {
                    local
                } else {
                    workspace.or(local)
                };
                AssertionRefusal::MacroBinding { name, site }
            }
            refusal => refusal,
        })
    }

    /// Every out-of-line `mod name;` the module composition resolved to an
    /// indexed file, keyed by declaring file, line and declaration text.
    fn resolved_module_declarations(
        &self,
        index: &RustIndex,
    ) -> &BTreeSet<(PathBuf, usize, String)> {
        self.resolved_modules.get_or_init(|| {
            index
                .files()
                .values()
                .flat_map(|facts| {
                    facts
                        .role_provenance
                        .edges
                        .iter()
                        .filter(|edge| edge.kind == SourceRoleProvenanceEdgeKind::Module)
                        .map(|edge| (edge.parent.clone(), edge.line, edge.declaration.clone()))
                        .collect::<Vec<_>>()
                })
                .collect()
        })
    }

    pub(in crate::analysis) fn admits(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> bool {
        self.refusal(test, assertion, index).is_none()
    }

    /// The context gates every assertion shares (parser-backed file,
    /// resolved module composition) with no visible binding that may rebind
    /// `assert!`, `assert_ne!` or `matches!` on the assertion's line.
    /// RIPR-SPEC-0231 sibling exclusion credits an `assert_ne!` or
    /// `assert!(!matches!(..))` only through it.
    pub(in crate::analysis) fn admits_assertion_context(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> bool {
        self.context_ambiguities(test, assertion.line, index)
            .is_ok_and(|ambiguous| {
                !["assert", "assert_ne", "matches"]
                    .iter()
                    .any(|name| ambiguous.contains(*name))
            })
    }

    /// The test-local check helper an `assertion` this admission admits is
    /// borrowed from (#6482); `None` for the test's own assertion or one it
    /// refuses.
    pub(in crate::analysis) fn helper_loan(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> Option<HelperLoan> {
        if !self.admits(test, assertion, index) {
            return None;
        }
        if index.doctest_source(test).is_some() {
            return self
                .doctest_pins
                .borrow()
                .get(&(test.file.clone(), test.start_line))?
                .helper_loan(
                    (test.start_line, test.end_line, DOCTEST_FUNCTION_NAME),
                    (assertion.line, &assertion.text),
                )
                .cloned();
        }
        self.by_file
            .borrow()
            .get(&test.file)?
            .helper_loan(
                (test.start_line, test.end_line, &test.name),
                (assertion.line, &assertion.text),
            )
            .cloned()
    }

    /// Exact call syntax is authority only when the selected source composes
    /// through admitted module declarations. This shares the assertion gate,
    /// including its supported test-build cfg rules.
    pub(in crate::analysis) fn targeted_source_provenance_is_admitted(
        &self,
        test: &TestSummary,
        index: &RustIndex,
    ) -> bool {
        if self.source_provenance_refusal(test, index).is_some() {
            return false;
        }
        let Some(facts) = index.files().get(&test.file) else {
            return false;
        };
        let mut by_file = self.by_file.borrow_mut();
        facts.role_provenance.edges.iter().all(|edge| {
            let Some(parent) = index.files().get(&edge.parent) else {
                return false;
            };
            by_file
                .entry(edge.parent.clone())
                .or_insert_with(|| owner_pin_assertions(&parent.source, NON_RETURNING_MACROS))
                .admits_targeted_module_declaration(edge.line, &edge.declaration)
        })
    }

    /// Call occurrence parsing borrows binding authority only. It does not
    /// grant assertion execution, oracle strength or receiver identity.
    pub(in crate::analysis) fn targeted_macro_binding_is_unambiguous(
        &self,
        test: &TestSummary,
        line: usize,
        name: &str,
        index: &RustIndex,
    ) -> bool {
        let name = if let Some(leaf) = drop_in_assertion_leaf(name) {
            let Some((root, _)) = name.strip_prefix("::").unwrap_or(name).split_once("::") else {
                return false;
            };
            let verified = if matches!(root, "std" | "core") {
                matches!(leaf, "assert" | "assert_eq" | "assert_ne")
                    && index
                        .drop_in_manifests
                        .unbound_standard_root(&test.file, root)
            } else {
                matches!(leaf, "assert_eq" | "assert_ne")
                    && index.drop_in_manifests.verified(&test.file, root)
            };
            if !verified {
                return false;
            }
            // A qualified root does not borrow a custom bare leaf's
            // ambiguity. Source availability and all binding-capable
            // statement macros are checked separately by the collector.
            let Some(facts) = index.files().get(&test.file) else {
                return false;
            };
            return self.targeted_source_provenance_is_admitted(test, index)
                && std::iter::once(&test.file)
                    .chain(facts.role_provenance.edges.iter().map(|e| &e.parent))
                    .all(|path| {
                        index.files().get(path).is_some_and(|facts| {
                            crate::analysis::syntax::parse_clean_source_file(&facts.source)
                                .is_some_and(|file| {
                                    crate::analysis::syntax::ra::assertion_root_is_available(
                                        name,
                                        file.tree().syntax(),
                                    )
                                })
                        })
                    })
                && facts.role_provenance.edges.iter().all(|edge| {
                    parse_clean_source_file(&edge.declaration).is_some_and(|file| {
                        file.tree()
                            .syntax()
                            .descendants()
                            .filter_map(ast::Module::cast)
                            .all(|module| {
                                crate::analysis::syntax::ra::assertion_root_is_available(
                                    name,
                                    module.syntax(),
                                )
                            })
                    })
                });
        } else {
            if name.contains("::") {
                return false;
            }
            name
        };
        self.targeted_source_provenance_is_admitted(test, index)
            && !self.trusted_macro_ambiguities(index).contains(name)
            && !self
                .scoped_names_for(test, line)
                .iter()
                .any(|candidate| candidate == name)
            && !self
                .crate_names_for(test, index)
                .iter()
                .any(|candidate| candidate == name)
    }

    fn trusted_macro_ambiguities(&self, index: &RustIndex) -> BTreeSet<String> {
        let resolved_modules = self.resolved_module_declarations(index);
        let module_resolved = |file: &Path, line: usize, declaration: &str| {
            resolved_modules.contains(&(file.to_path_buf(), line, declaration.to_string()))
        };
        let mut ambiguous = self.ambiguous_macro_bindings.borrow_mut();
        ambiguous
            .get_or_insert_with(|| {
                let (mut global, scoped, by_root, retained) =
                    trusted_macro_sites_in(index, self.target_roots(index), &module_resolved);
                *self.scoped_macro_bindings.borrow_mut() = Some(scoped);
                #[cfg(test)]
                {
                    *self.workspace_scan_passes.borrow_mut() += 1;
                }
                let mut by_root = by_root;
                for (root, names) in &self.withheld.by_root {
                    by_root
                        .entry(root.clone())
                        .or_default()
                        .extend(names.iter().cloned());
                }
                *self.crate_macro_bindings.borrow_mut() = Some(by_root);
                *self.workspace_site_scan.borrow_mut() = Some(retained);
                // Withheld crate-root files' crate-local sites are routed by
                // root below; every other withheld site is workspace-wide.
                global.extend(self.withheld.trusted.iter().cloned());
                global
            })
            .clone()
    }

    /// The workspace-wide site that makes `name` ambiguous for a test
    /// rooted at `test_root`: the earliest rebinding site in path order,
    /// else the earliest site that only may rebind it, each over the sites
    /// that reach the test — the same selection the replaced per-(name,
    /// test root) scan made, served from the single ambiguity pass (#8255).
    /// `None` when no retained site reaches the test.
    fn workspace_macro_site(
        &self,
        name: &str,
        test_root: Option<&Path>,
        index: &RustIndex,
    ) -> Option<(PathBuf, MacroBindingSite)> {
        if !assertion_context_macros().contains(&name) {
            return None;
        }
        self.complete_workspace_site_scan(index);
        let scan = self.workspace_site_scan.borrow();
        let retained = scan.as_ref()?;
        let mut rebinding: Option<&(PathBuf, MacroBindingSite)> = None;
        let mut may_rebind: Option<&(PathBuf, MacroBindingSite)> = None;
        if let Some(rank) = retained.global.get(name) {
            merge_macro_site_rank(&mut rebinding, &mut may_rebind, rank);
        }
        match test_root {
            Some(root) => {
                if let Some(rank) = retained.by_root.get(root).and_then(|names| names.get(name)) {
                    merge_macro_site_rank(&mut rebinding, &mut may_rebind, rank);
                }
            }
            // A test with no recognized root is reached by every
            // crate-local site, exactly as the reach rule read it.
            None => {
                for names in retained.by_root.values() {
                    if let Some(rank) = names.get(name) {
                        merge_macro_site_rank(&mut rebinding, &mut may_rebind, rank);
                    }
                }
            }
        }
        rebinding.cloned().or_else(|| may_rebind.cloned())
    }

    /// #8255: finish the retained-site scan the ambiguity pass skipped. It
    /// stops once every trusted name is already ambiguous — later files
    /// cannot change an admission — but an earlier file's site can still be
    /// the one a refusal names, so the first site lookup completes the pass
    /// once. At most one full-index completion runs, however many (name,
    /// test root) lookups follow.
    fn complete_workspace_site_scan(&self, index: &RustIndex) {
        if self
            .workspace_site_scan
            .borrow()
            .as_ref()
            .is_some_and(|scan| scan.complete)
        {
            return;
        }
        // Runs the single pass when a refusal lookup is its first consumer.
        self.trusted_macro_ambiguities(index);
        {
            let scan = self.workspace_site_scan.borrow();
            if scan.as_ref().is_none_or(|scan| scan.complete) {
                return;
            }
        }
        let resolved_modules = self.resolved_module_declarations(index);
        let module_resolved = |file: &Path, line: usize, declaration: &str| {
            resolved_modules.contains(&(file.to_path_buf(), line, declaration.to_string()))
        };
        let (_, rest) = partition_macro_scan_files(index);
        let sites = scan_macro_sites(&rest, index, &module_resolved);
        // Resolved before the map borrow: target roots never re-enter the
        // site scan, and the mutable borrow must not outlive its purpose.
        let roots = self.target_roots(index);
        let mut scan = self.workspace_site_scan.borrow_mut();
        let Some(retained) = scan.as_mut() else {
            return;
        };
        if retained.complete {
            return;
        }
        for (path, name, site) in sites {
            match site.crate_local.then(|| roots.root(&path, index)).flatten() {
                Some(root) => {
                    retained
                        .by_root
                        .entry(root)
                        .or_default()
                        .entry(name)
                        .or_default()
                        .absorb(&path, &site);
                }
                // A site whose file has no recognized root reaches tests of
                // every root, exactly as the reach rule reads it.
                None => {
                    retained
                        .global
                        .entry(name)
                        .or_default()
                        .absorb(&path, &site);
                }
            }
        }
        retained.complete = true;
        #[cfg(test)]
        {
            *self.workspace_scan_passes.borrow_mut() += 1;
        }
    }

    /// #8255 test witness: how many full-index macro-site passes this run
    /// paid, bounded at two (the ambiguity pass plus at most one
    /// completion) however many (name, test root) refusals follow.
    #[cfg(test)]
    pub(in crate::analysis) fn workspace_scan_passes(&self) -> u32 {
        *self.workspace_scan_passes.borrow()
    }

    /// File composition authority shared by assertion admission and targeted
    /// assertion operands. Syntax in an included or unadmitted module cannot
    /// borrow a standard macro binding from an incomplete scope view.
    fn source_provenance_refusal(
        &self,
        test: &TestSummary,
        index: &RustIndex,
    ) -> Option<AssertionRefusal> {
        let Some(facts) = index
            .files()
            .get(&test.file)
            .filter(|facts| !facts.used_lexical_fallback)
        else {
            return Some(AssertionRefusal::LexicalFallback);
        };
        if let Some(reason) = &facts.role_provenance.earliest_unresolved_reason {
            return Some(AssertionRefusal::UnresolvedModule(reason.clone()));
        }
        let mut by_file = self.by_file.borrow_mut();
        for edge in &facts.role_provenance.edges {
            // Module composition already owns resolution. Include expansions
            // lack an exact declaration coordinate here, so remain unknown.
            if edge.kind != SourceRoleProvenanceEdgeKind::Module {
                return Some(AssertionRefusal::IncludedFile {
                    parent: edge.parent.clone(),
                    line: edge.line,
                });
            }
            let Some(parent) = index
                .files()
                .get(&edge.parent)
                .filter(|facts| !facts.used_lexical_fallback)
            else {
                return Some(AssertionRefusal::LexicalFallback);
            };
            if !by_file
                .entry(edge.parent.clone())
                .or_insert_with(|| owner_pin_assertions(&parent.source, NON_RETURNING_MACROS))
                .admits_module_declaration(edge.line, &edge.declaration)
            {
                return Some(AssertionRefusal::ModuleDeclaration {
                    parent: edge.parent.clone(),
                    line: edge.line,
                    declaration: edge.declaration.clone(),
                });
            }
        }
        None
    }

    /// The gates every assertion of `test` shares, whatever its macro: a
    /// parser-backed file, resolved module composition, and each module
    /// declaration on the chain admitted. `Ok` holds the macro names some
    /// visible binding may rebind for an assertion on `line`.
    fn context_ambiguities(
        &self,
        test: &TestSummary,
        line: usize,
        index: &RustIndex,
    ) -> Result<BTreeSet<String>, Box<AssertionRefusal>> {
        if let Some(refusal) = self.source_provenance_refusal(test, index) {
            return Err(Box::new(refusal));
        }
        let resolved_modules = self.resolved_module_declarations(index);
        let module_resolved = |file: &Path, line: usize, declaration: &str| {
            resolved_modules.contains(&(file.to_path_buf(), line, declaration.to_string()))
        };
        let ambiguous = self.trusted_macro_ambiguities(index);
        let Some(facts) = index
            .files()
            .get(&test.file)
            .filter(|facts| !facts.used_lexical_fallback)
        else {
            return Err(Box::new(AssertionRefusal::LexicalFallback));
        };
        let mut empty_by_file = self.empty_macro_ambiguities.borrow_mut();
        let empty_ambiguities = empty_by_file.entry(test.file.clone()).or_insert_with(|| {
            let names = local_empty_macro_names(&facts.source);
            if names.is_empty() {
                return BTreeSet::new();
            }
            index
                .files()
                .iter()
                .flat_map(|(path, file)| {
                    empty_macro_binding_ambiguities(
                        &file.source,
                        index.macro_scope_crates(),
                        &names,
                        path == &test.file,
                        &|line, declaration| module_resolved(path, line, declaration),
                    )
                })
                .chain(
                    (self.withheld.any_name || self.withheld.root_any_name)
                        .then(|| names.clone())
                        .into_iter()
                        .flatten(),
                )
                .collect()
        });
        let mut ambiguous: BTreeSet<_> = ambiguous.union(empty_ambiguities).cloned().collect();
        // Recheck provenance for every admission even when syntax is memoized.
        if facts.source.contains("json")
            && !index.drop_in_manifests.verified_literal_json(&test.file)
        {
            ambiguous.insert("json".to_string());
        }
        ambiguous.extend(self.scoped_names_for(test, line));
        ambiguous.extend(self.crate_names_for(test, index));
        Ok(ambiguous)
    }

    /// RIPR-SPEC-0229 (#6616): the value operand of `assertion` when it is
    /// an exact pattern pin through the test file's verified local
    /// `assert_matches!` (see `syntax::pattern_pins`), under the gates every
    /// assertion of the test shares and with no visible rebinding of a
    /// standard macro the pin relies on. `None` refuses.
    pub(in crate::analysis) fn exact_pattern_pin_value(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> Option<String> {
        if !assertion.text.starts_with("assert_matches") {
            return None;
        }
        let facts = index.files().get(&test.file)?;
        // Look the cached pin up first; the ambiguity scan only matters when
        // a pin exists. The memo borrow ends before that scan runs.
        let pin = {
            let mut memo = self.pattern_pins.borrow_mut();
            let pins = memo
                .entry(test.file.clone())
                .or_insert_with(|| pattern_pins(&facts.source));
            pins.pin(
                (test.start_line, test.end_line, &test.name),
                &test.body,
                (assertion.line, &assertion.text),
            )?
            .clone()
        };
        let ambiguous = self.context_ambiguities(test, assertion.line, index).ok()?;
        pin.macros.is_disjoint(&ambiguous).then_some(pin.value)
    }

    fn refusal(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> Option<AssertionRefusal> {
        Some(match self.context_refusal(test, assertion, index)? {
            AssertionRefusal::Syntax(AssertionContextRefusal::GuardedReturn(condition)) => {
                match value_guard_subject(&condition, &assertion.text) {
                    Some(subject) => AssertionRefusal::ValueGuard {
                        condition,
                        subject: subject.to_string(),
                    },
                    None => {
                        AssertionRefusal::Syntax(AssertionContextRefusal::GuardedReturn(condition))
                    }
                }
            }
            refusal => refusal,
        })
    }

    fn context_refusal(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
    ) -> Option<AssertionRefusal> {
        let ambiguous = match self.context_ambiguities(test, assertion.line, index) {
            Ok(ambiguous) => ambiguous,
            Err(refusal) => return Some(*refusal),
        };
        let Some(facts) = index.files().get(&test.file) else {
            return Some(AssertionRefusal::LexicalFallback);
        };
        // #6648 (RIPR-SPEC-0279): a doc example is its own crate, so its
        // assertions are read from its synthetic source under the synthetic
        // name, never from the file that holds the comment.
        if let Some(source) = index.doctest_source(test) {
            return self.doctest_refusal(test, assertion, source, ambiguous, index);
        }
        // #7857: a `std`/`core`-rooted `assert_eq!` needs the same root proof
        // as targeted call syntax (manifest, crate provenance) plus the
        // test's real file, which a generated test's expansion does not show.
        // The escape scan admits every such call in the file's tests and
        // helpers on file-local evidence, so each one anywhere in the file
        // needs the proof, not only the credited assertion: an unproved
        // `std::assert_eq!` may expand to an early return that skips it.
        let rooted = self
            .std_rooted
            .borrow_mut()
            .entry(test.file.clone())
            .or_insert_with(|| StdRootedCalls::of(&facts.source))
            .clone();
        let qualified: BTreeSet<String> = std_rooted_macro_path(&assertion.text, "assert_eq")
            .into_iter()
            .chain(rooted.calls)
            .collect();
        if let Some(path) = qualified.into_iter().find(|path| {
            !(rooted.unrebound.contains(path)
                && self.targeted_macro_binding_is_unambiguous(test, assertion.line, path, index))
        }) {
            return Some(AssertionRefusal::Syntax(
                AssertionContextRefusal::OpaqueMacro(path),
            ));
        }
        let mut by_file = self.by_file.borrow_mut();
        // A terminal Err-return guard is keyed by its condition; the oracle
        // text may join continuation lines or elide the Err payload.
        let guard_key = err_return_guard_twin(&assertion.text)
            .map(|(condition, _)| err_return_guard_key(condition));
        let file_refusal = by_file
            .entry(test.file.clone())
            .or_insert_with(|| owner_pin_assertions(&facts.source, &assertion_context_macros()))
            .refusal(
                (test.start_line, test.end_line, &test.name),
                &test.body,
                (
                    assertion.line,
                    guard_key.as_deref().unwrap_or(&assertion.text),
                ),
                &ambiguous,
            );
        let file_refusal = file_refusal?;
        // A generated test is not in the file's text: the same admission
        // runs over its invocation's expansion, matched by name, attributes,
        // body and assertion text in the expansion's own coordinates. A
        // matched assertion carries the expansion's own verdict — admitted
        // reads like the hand-written twin, and a refusal surfaces the
        // expansion's reason, not the file text's "test not identified"
        // (the invocation line holds no `fn`), so both twins refuse as the
        // same kind.
        let generated_verdicts = self
            .generated
            .borrow_mut()
            .entry(test.file.clone())
            .or_insert_with(|| generated_test_pins(&test.file, &facts.source, NON_RETURNING_MACROS))
            .iter()
            .filter(|invocation| {
                invocation.start_line == test.start_line && invocation.end_line == test.end_line
            })
            .flat_map(|invocation| {
                invocation
                    .tests
                    .iter()
                    .filter(|local| {
                        local.name == test.name
                            && local.attrs == test.attrs
                            && local.body == test.body
                    })
                    .map(move |local| (invocation, local))
            })
            .flat_map(|(invocation, local)| {
                local
                    .assertions
                    .iter()
                    .filter(|local_assertion| local_assertion.text == assertion.text)
                    .map(|local_assertion| {
                        invocation.pins.refusal(
                            (local.start_line, local.end_line, &local.name),
                            &local.body,
                            (local_assertion.line, &local_assertion.text),
                            &ambiguous,
                        )
                    })
            })
            .collect::<Vec<_>>();
        if generated_verdicts.iter().any(|verdict| verdict.is_none()) {
            return None;
        }
        if let Some(Some(generated_refusal)) = generated_verdicts.into_iter().next() {
            return Some(AssertionRefusal::Syntax(generated_refusal));
        }
        Some(AssertionRefusal::Syntax(file_refusal))
    }
}

impl OwnerPinSyntax {
    /// #6648 (RIPR-SPEC-0279): the shared admission over a doc example's
    /// synthetic source. `ambiguous` already holds what the workspace and
    /// the holding file may rebind (conservative: that file's items are not
    /// in the example's scope, but its exported macros may be). The
    /// example's own bindings are added on top; no module of it resolves
    /// and no drop-in crate is verified for it, so each stays broad. A
    /// `std::`/`core::`-rooted `assert_eq!` needs root proof this path does
    /// not establish for the example's crate, so it refuses.
    fn doctest_refusal(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        source: &str,
        mut ambiguous: BTreeSet<String>,
        index: &RustIndex,
    ) -> Option<AssertionRefusal> {
        let context_macros = assertion_context_macros();
        ambiguous.extend(
            trusted_macro_binding_sites(
                source,
                index.macro_scope_crates(),
                &context_macros,
                &|_, _| false,
                &|_| false,
            )
            .into_iter()
            .map(|(name, _)| name),
        );
        if let Some(path) = std_rooted_macro_path(&assertion.text, "assert_eq")
            .or_else(|| StdRootedCalls::of(source).calls.into_iter().next())
        {
            return Some(AssertionRefusal::Syntax(
                AssertionContextRefusal::OpaqueMacro(path),
            ));
        }
        let guard_key = err_return_guard_twin(&assertion.text)
            .map(|(condition, _)| err_return_guard_key(condition));
        self.doctest_pins
            .borrow_mut()
            .entry((test.file.clone(), test.start_line))
            .or_insert_with(|| owner_pin_assertions(source, &context_macros))
            .refusal(
                (test.start_line, test.end_line, DOCTEST_FUNCTION_NAME),
                &test.body,
                (
                    assertion.line,
                    guard_key.as_deref().unwrap_or(&assertion.text),
                ),
                &ambiguous,
            )
            .map(AssertionRefusal::Syntax)
    }
}

type ScopedMacroBindings = BTreeMap<PathBuf, Vec<(String, MacroBindingSite)>>;
type CrateMacroBindings = BTreeMap<PathBuf, BTreeSet<String>>;
/// Keyed by trusted name and the test's recognized root.
type TestFileMacroSites = BTreeMap<(String, PathBuf), Vec<(String, MacroBindingSite)>>;

/// The earliest unscoped workspace-wide binding sites per trusted name,
/// retained by the single ambiguity pass (`trusted_macro_sites_in`) so a
/// refusal names its site without rescanning the workspace (#8255). A
/// crate-local site reaches only tests whose recognized root matches the
/// site's; every other retained site reaches all of them, exactly the
/// reach rule the replaced per-(name, root) scan applied.
#[derive(Clone, Debug, Default)]
struct WorkspaceMacroSiteIndex {
    /// Per name: the earliest sites over the files that reach every test.
    global: BTreeMap<String, MacroSiteRank>,
    /// Per recognized root: the same retention over that root's
    /// crate-local sites; a test consults only its own root.
    by_root: BTreeMap<PathBuf, BTreeMap<String, MacroSiteRank>>,
    /// Whether every indexed file contributed. The ambiguity pass stops
    /// after the likely files once every trusted name is already ambiguous
    /// — later files cannot change an admission, but an earlier file's
    /// site can still be the one a refusal names — so the first site
    /// lookup completes the pass once, bounded by the index (#8255).
    complete: bool,
}

/// The earliest rebinding site, else the earliest site that only may
/// rebind the name: the replaced per-(name, root) scan answered the first
/// rebinding in path order, wherever it sits, else the first may-rebind
/// site.
#[derive(Clone, Debug, Default)]
struct MacroSiteRank {
    rebinding: Option<(PathBuf, MacroBindingSite)>,
    may_rebind: Option<(PathBuf, MacroBindingSite)>,
}

impl MacroSiteRank {
    /// Keep the earlier of the retained and a fresh site. Sites arrive in
    /// path order within one scan pass, so equal paths keep the
    /// first-in-source-order site.
    fn absorb(&mut self, path: &Path, site: &MacroBindingSite) {
        let slot = if rebinds(site) {
            &mut self.rebinding
        } else {
            &mut self.may_rebind
        };
        if slot.as_ref().is_none_or(|(kept, _)| path < kept) {
            *slot = Some((path.to_path_buf(), site.clone()));
        }
    }
}

/// Keep the earlier of a retained site reference and a candidate, by path.
fn keep_earliest_site<'a>(
    slot: &mut Option<&'a (PathBuf, MacroBindingSite)>,
    candidate: Option<&'a (PathBuf, MacroBindingSite)>,
) {
    if let Some(candidate) = candidate
        && slot.as_ref().is_none_or(|(kept, _)| candidate.0 < *kept)
    {
        *slot = Some(candidate);
    }
}

/// Fold one name's retained sites into the running earliest rebinding and
/// may-rebind candidates of a lookup.
fn merge_macro_site_rank<'a>(
    rebinding: &mut Option<&'a (PathBuf, MacroBindingSite)>,
    may_rebind: &mut Option<&'a (PathBuf, MacroBindingSite)>,
    rank: &'a MacroSiteRank,
) {
    keep_earliest_site(rebinding, rank.rebinding.as_ref());
    keep_earliest_site(may_rebind, rank.may_rebind.as_ref());
}

/// The crate root whose module tree holds `file`, when that root is one of
/// Cargo's autodiscovered targets (`src/lib.rs`, `src/main.rs`,
/// `src/bin/*.rs`, `tests/*.rs`, `benches/*.rs`, `examples/*.rs`,
/// `build.rs`) and every module edge to it resolved. `None` keeps a
/// binding workspace-wide: an unlinked file may belong to any crate.
///
/// A file another crate can also compile is never charged to one root:
/// an `include!` fragment (its text lands in every includer, with or
/// without a recorded edge), a shared integration-test helper whose
/// provenance keeps only the first of several `tests/*.rs` owners, and
/// every file while any `include!` is unresolved in the workspace: an
/// ambiguous, cfg-conflicting, capped or unindexed include leaves its
/// fragment, and the fragment's module children, looking like a root.
#[derive(Clone, Debug)]
struct TargetRoots {
    /// An unresolved `include!`, or an unresolvable `#[path]` (which
    /// records no module edge for its target), may compile any file into
    /// another crate, so no file is charged to one root.
    disabled: bool,
    /// Every indexed `<package>/src` directory, for the `tests/`, `benches/`,
    /// `examples/` and `build.rs` roots beside one.
    src_dirs: BTreeSet<PathBuf>,
    /// Per-file answers, so repeated admissions do not recompute them.
    memo: SyncMemo<BTreeMap<PathBuf, Option<PathBuf>>>,
}

impl TargetRoots {
    fn new(index: &RustIndex) -> Self {
        // A lexical-fallback file records no module declarations, so its
        // children get no edge either.
        let disabled = !index.include_limitations.is_empty()
            || index.files().iter().any(|(_, facts)| {
                facts.used_lexical_fallback
                    || facts
                        .module_declarations
                        .iter()
                        .any(|declaration| declaration.path_target == ModulePathTarget::Unknown)
            });
        let src_dirs = index
            .files()
            .iter()
            .flat_map(|(path, _)| path.ancestors().skip(1))
            .filter(|directory| directory.file_name().is_some_and(|name| name == "src"))
            .map(Path::to_path_buf)
            .collect();
        Self {
            disabled,
            src_dirs,
            memo: SyncMemo::default(),
        }
    }

    fn root(&self, file: &Path, index: &RustIndex) -> Option<PathBuf> {
        if self.disabled {
            return None;
        }
        if let Some(root) = self.memo.borrow().get(file) {
            return root.clone();
        }
        let root = target_root(file, index, &self.src_dirs);
        self.memo
            .borrow_mut()
            .insert(file.to_path_buf(), root.clone());
        root
    }
}

/// The crate root file `file` composes under: a recognized Cargo target root
/// (`src/lib.rs`, `src/main.rs`, `src/bin/*.rs`, an integration test, bench,
/// example or build script), or `None` when composition is unresolved, goes
/// through `include!`, or ends at an unrecognized file.
pub(super) fn target_root(
    file: &Path,
    index: &RustIndex,
    src_dirs: &BTreeSet<PathBuf>,
) -> Option<PathBuf> {
    let facts = index.files().get(file)?;
    let provenance = &facts.role_provenance;
    if provenance.earliest_unresolved_reason.is_some()
        || index.include_targets.contains(file)
        || provenance.edges.iter().any(|edge| {
            edge.kind == SourceRoleProvenanceEdgeKind::Include
                || index.include_targets.contains(&edge.parent)
        })
    {
        return None;
    }
    let root = provenance
        .edges
        .first()
        .map_or_else(|| file.to_path_buf(), |edge| edge.parent.clone());
    // `tests/common/mod.rs` (or `tests/common.rs`) declared by several
    // integration-test roots composes under the first owner only.
    if root != file
        && root
            .parent()
            .and_then(Path::file_name)
            .is_some_and(|directory| directory == "tests")
    {
        return None;
    }
    let names: Vec<&str> = root
        .iter()
        .map(|part| part.to_str().unwrap_or_default())
        .collect();
    let package_has_src = |package: &[&str]| {
        let prefix: PathBuf = package.iter().chain(&["src"]).collect();
        src_dirs.contains(&prefix)
    };
    let recognized = match names.as_slice() {
        [.., "src", "lib.rs" | "main.rs"] | [.., "src", "bin", _] => true,
        [package @ .., "tests" | "benches" | "examples", _] => package_has_src(package),
        [package @ .., "build.rs"] => package_has_src(package),
        _ => false,
    };
    (recognized && root.extension().is_some_and(|extension| extension == "rs")).then_some(root)
}

impl OwnerPinSyntax {
    /// Workspace routing inputs, computed once per run.
    fn target_roots(&self, index: &RustIndex) -> &TargetRoots {
        self.target_roots.get_or_init(|| TargetRoots::new(index))
    }

    /// Trusted names a crate-local site makes ambiguous for `test`: those in
    /// the test's own recognized root, or every one when that root is not
    /// established.
    fn crate_names_for(&self, test: &TestSummary, index: &RustIndex) -> Vec<String> {
        let by_root = self.crate_macro_bindings.borrow();
        let Some(by_root) = by_root.as_ref().filter(|by_root| !by_root.is_empty()) else {
            return Vec::new();
        };
        match self.target_roots(index).root(&test.file, index) {
            Some(root) => by_root.get(&root).into_iter().flatten().cloned().collect(),
            None => by_root.values().flatten().cloned().collect(),
        }
    }

    /// Trusted names that a scoped definition or import makes ambiguous for
    /// `test`, or for the invocation at `assertion_line`: an assertion a
    /// check helper lends (#6482) sits in the helper's body, whose scoped
    /// bindings never overlap the test's span. Filled by the workspace scan
    /// in `refusal`.
    fn scoped_names_for(&self, test: &TestSummary, assertion_line: usize) -> Vec<String> {
        self.scoped_macro_bindings
            .borrow()
            .as_ref()
            .and_then(|scoped| scoped.get(&test.file))
            .into_iter()
            .flatten()
            .filter(|(_, site)| site_covers_assertion(site, test, assertion_line))
            .map(|(name, _)| name.clone())
            .collect()
    }
}

/// Whether a scoped site may reach the invocation at `assertion_line` in
/// `test`: it overlaps the test, or (for an assertion a check helper lends,
/// #6482) its scope holds the assertion's own line in the helper's body.
fn site_covers_assertion(
    site: &MacroBindingSite,
    test: &TestSummary,
    assertion_line: usize,
) -> bool {
    site_covers(site, test)
        || site
            .scope
            .is_some_and(|(start, end)| (start..=end).contains(&assertion_line))
}

/// Whether a scoped site may reach `test`: any overlap of their line spans.
/// A `use` in the test's own body is scoped to the body block, which starts
/// after the `fn` line when the signature wraps, so containment would miss it.
fn site_covers(site: &MacroBindingSite, test: &TestSummary) -> bool {
    site.scope
        .is_some_and(|(start, end)| start <= test.end_line && test.start_line <= end)
}

/// Why an `assert_eq!` was not credited as executing the standard macro.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(in crate::analysis) enum AssertionRefusal {
    /// The test file was indexed by the lexical fallback, not the parser.
    LexicalFallback,
    /// Module composition could not place the test file; the reason code.
    UnresolvedModule(String),
    /// The test file is composed through `include!`, so its declaration
    /// context is not exact.
    IncludedFile { parent: PathBuf, line: usize },
    /// The `mod` declaration that brings the test file in is gated or nested.
    ModuleDeclaration {
        parent: PathBuf,
        line: usize,
        declaration: String,
    },
    /// A test-local reason from the parser-backed scan.
    Syntax(AssertionContextRefusal),
    /// `name!` may be rebound somewhere in the workspace; the first site
    /// that does so, when ripr could find it.
    MacroBinding {
        name: String,
        site: Option<(PathBuf, MacroBindingSite)>,
    },
    /// The test's only `return` sits under `if <condition> { return; }`,
    /// whose condition compares `subject` (the call the assertion compares)
    /// with a literal and does not hold for the value the assertion
    /// expects: the assertion runs for that value, and whether it runs for
    /// another depends on a value ripr does not evaluate.
    ValueGuard { condition: String, subject: String },
}

impl AssertionRefusal {
    /// The call a [`Self::ValueGuard`] reads, so a caller can require it to
    /// be the owner's.
    pub(in crate::analysis) fn value_guard_subject(&self) -> Option<&str> {
        match self {
            Self::ValueGuard { subject, .. } => Some(subject),
            _ => None,
        }
    }

    /// Whether the refusal rests on a limit of ripr's own reading (the file,
    /// module, test identity, or a binding that only *may* rebind), rather
    /// than on a shape that can keep the assertion from running or rebind it
    /// for real. Runtime controls pin the second kind as real gaps
    /// (`tests/owner_pin_execution.rs`), so only the first kind lets
    /// RIPR-SPEC-0240 withhold a gap.
    pub(in crate::analysis) fn is_analyzer_limit(&self) -> bool {
        match self {
            Self::LexicalFallback | Self::UnresolvedModule(_) | Self::IncludedFile { .. } => true,
            // trap-tally-reached-assert-control: the guard spares the
            // expected value, so the assertion's reach is value-dependent.
            Self::ValueGuard { .. } => true,
            // A gated `mod` declaration may be `cfg(any())`, which never runs.
            Self::ModuleDeclaration { .. } => false,
            Self::Syntax(refusal) => match refusal {
                AssertionContextRefusal::UnparsedFile
                | AssertionContextRefusal::UnidentifiedTest
                | AssertionContextRefusal::AsyncTest
                | AssertionContextRefusal::DuplicateSpelling
                | AssertionContextRefusal::StaleSource => true,
                AssertionContextRefusal::TestAttribute(attribute) => {
                    !attribute_settles_test_outcome(attribute)
                }
                AssertionContextRefusal::NestedItem
                | AssertionContextRefusal::GatedItem(_)
                | AssertionContextRefusal::OpaqueMacro(_)
                | AssertionContextRefusal::MacroOperandExit(_)
                | AssertionContextRefusal::ClosureExit
                | AssertionContextRefusal::ConditionalPath(_)
                | AssertionContextRefusal::GuardedReturn(_)
                | AssertionContextRefusal::MacroBinding(_) => false,
            },
            // A definition or `use` of the name in reach is a real rebinding;
            // a foreign glob, unresolved `#[macro_use]`, macro argument, or an
            // unparsed file only may rebind it.
            Self::MacroBinding { site, .. } => {
                !site.as_ref().is_some_and(|(_, site)| rebinds(site))
            }
        }
    }

    /// One reader-facing clause: what blocked crediting the assertion.
    pub(in crate::analysis) fn describe(&self) -> String {
        let at = |path: &Path, line: usize| {
            if line == 0 {
                path.display().to_string()
            } else {
                format!("{}:{line}", path.display())
            }
        };
        match self {
            Self::LexicalFallback => {
                "its file did not parse cleanly, so ripr read it with a lexical fallback".into()
            }
            Self::UnresolvedModule(reason) => {
                format!("ripr could not place its file in the crate's module tree ({reason})")
            }
            Self::IncludedFile { parent, line } => {
                format!(
                    "its file is pulled in by `include!` at {}",
                    at(parent, *line)
                )
            }
            Self::ModuleDeclaration {
                parent,
                line,
                declaration,
            } => format!(
                "`{declaration}` at {} is gated by a `cfg` ripr cannot evaluate, or nested",
                at(parent, *line)
            ),
            Self::Syntax(refusal) => match refusal {
                AssertionContextRefusal::UnparsedFile => "its file did not parse cleanly".into(),
                AssertionContextRefusal::UnidentifiedTest => {
                    "ripr could not identify the test function uniquely".into()
                }
                AssertionContextRefusal::AsyncTest => {
                    "the test is `async`, and ripr does not model its executor".into()
                }
                AssertionContextRefusal::TestAttribute(attribute) => {
                    format!(
                        "the test carries `{attribute}`, which may change whether or how it runs"
                    )
                }
                AssertionContextRefusal::NestedItem => {
                    "the test is declared inside a function body, which ripr does not model".into()
                }
                AssertionContextRefusal::GatedItem(attribute) => format!(
                    "an enclosing module carries `{attribute}`, which ripr cannot evaluate for test builds"
                ),
                AssertionContextRefusal::OpaqueMacro(name) => format!(
                    "the test calls `{name}!`, whose expansion ripr cannot see, so a hidden `return` or `?` could skip the assertion"
                ),
                AssertionContextRefusal::MacroOperandExit(name) => format!(
                    "an argument of `{name}!` contains a `return`, `?` or nested macro that may leave the test before the comparison"
                ),
                AssertionContextRefusal::ClosureExit => {
                    "a closure in the test can return early, or the test yields".into()
                }
                AssertionContextRefusal::DuplicateSpelling => {
                    "the same assertion text appears twice on one line".into()
                }
                AssertionContextRefusal::ConditionalPath(construct) => {
                    format!("the assertion is inside {construct}")
                }
                AssertionContextRefusal::GuardedReturn(condition) => format!(
                    "the assertion is inside a block that an earlier `if {condition} {{ return; }}` can skip"
                ),
                AssertionContextRefusal::MacroBinding(name) => {
                    format!("`{name}!` may be redefined somewhere in the workspace")
                }
                AssertionContextRefusal::StaleSource => {
                    "the test's source changed while ripr was reading it".into()
                }
            },
            Self::ValueGuard { condition, subject } => format!(
                "an earlier `if {condition} {{ return; }}` spares the value the assertion expects, so whether the assertion runs depends on the value of `{subject}`, which ripr does not evaluate"
            ),
            Self::MacroBinding { name, site } => match site {
                None => format!("`{name}!` may be redefined somewhere in the workspace"),
                Some((path, site)) => {
                    let place = at(path, site.line);
                    match &site.kind {
                        MacroBindingKind::Unparsed => format!(
                            "{} did not parse cleanly, so it may redefine `{name}!`",
                            path.display()
                        ),
                        MacroBindingKind::NoImplicitPrelude => format!(
                            "`#![no_implicit_prelude]` at {place} removes the standard `{name}!`"
                        ),
                        MacroBindingKind::MacroUse(item) => format!(
                            "`#[macro_use] {item}` at {place} imports macros from code ripr did not index, which may redefine `{name}!`"
                        ),
                        MacroBindingKind::ForeignGlob(import) => format!(
                            "`{import}` at {place} glob-imports from outside the workspace, which may bring in a different `{name}!`"
                        ),
                        MacroBindingKind::Definition => {
                            format!("{place} defines a macro named `{name}`")
                        }
                        MacroBindingKind::Import => {
                            format!("{place} imports a different `{name}` by name")
                        }
                        MacroBindingKind::UnverifiedDropIn(krate) => format!(
                            "{place} imports `{name}` from `{krate}`, and no Cargo.toml ripr read declares `{krate}` as the plain registry package; declare it by version only (no `package`, `path`, `git`, `registry` or `[patch]`)"
                        ),
                        MacroBindingKind::MacroArgument(macro_name) => format!(
                            "`{macro_name}!` at {place} mentions `{name}` in its arguments, so its expansion may define it"
                        ),
                        MacroBindingKind::ArgumentAttribute { wrapper, attribute } => format!(
                            "`{wrapper}!` at {place} carries `{attribute}` in its arguments, which its expansion may apply, bringing in a different `{name}!`"
                        ),
                        MacroBindingKind::MacroBody(macro_name) => format!(
                            "the body of `{macro_name}!` at {place} defines or imports `{name}`, so its expansion may rebind it"
                        ),
                        MacroBindingKind::BodyBindsAny {
                            macro_name,
                            binding,
                        } => format!(
                            "the body of `{macro_name}!` at {place} carries `{binding}`, which its expansion may apply, bringing in a different `{name}!`"
                        ),
                    }
                }
            },
        }
    }
}

/// A workspace site, in path order, whose scan makes `name` ambiguous
/// everywhere. The admission decision uses the set; the site decides only
/// whether the refusal is an analyzer limit (RIPR-SPEC-0240). A definition or
/// `use` of the name is a real rebinding, so it outranks a site that only may
/// rebind the name, wherever each sits.
///
/// #8255 reference oracle: production answers come from the single-pass
/// retention ([`OwnerPinSyntax::workspace_macro_site`]); this scan stays as
/// the test-side authority that the retention answers identically.
#[cfg(test)]
fn workspace_macro_binding_site(
    name: &str,
    test_root: Option<&Path>,
    index: &RustIndex,
    roots: &TargetRoots,
    module_resolved: &(dyn Fn(&Path, usize, &str) -> bool + Sync),
) -> Option<(PathBuf, MacroBindingSite)> {
    if !assertion_context_macros().contains(&name) {
        return None;
    }
    // Every file may be parsed for this one name, which was a quarter of a
    // warm `ripr check` on ripr-swarm when run serially. Each file's answer
    // is independent, so files are scanned on the rayon pool in path-ordered
    // batches: the earliest file still wins, and a rebinding in an early
    // batch still stops the scan before later files are parsed.
    // Roots memoize behind a lock, so they are resolved before the pool.
    let files: Vec<_> = index
        .files()
        .iter()
        .map(|(path, facts)| {
            let root = test_root.and_then(|_| roots.root(path, index));
            (path, facts, root)
        })
        .collect();
    let scan = |(path, facts, root): &(&PathBuf, FileFactsView<'_>, Option<PathBuf>)| {
        // The same rule as the decision: a crate-local site in another
        // recognized root does not reach this test.
        let reaches = |site: &MacroBindingSite| {
            !site.crate_local
                || test_root.is_none()
                || root
                    .as_ref()
                    .is_none_or(|site_root| Some(site_root.as_path()) == test_root)
        };
        let mut first = None;
        for (_, site) in macro_binding_sites(
            name,
            path,
            &facts.source,
            facts.macro_candidates.as_deref(),
            index,
            module_resolved,
        ) {
            if site.scope.is_some() || !reaches(&site) {
                continue;
            }
            if rebinds(&site) {
                return (Some(site), first);
            }
            first.get_or_insert(site);
        }
        (None, first)
    };
    // Wide enough that one large file does not stall the pool for long.
    let batch = rayon::current_num_threads().max(1) * 32;
    let mut first = None;
    for chunk in files.chunks(batch) {
        let per_file: Vec<_> = if nested_parallelism_allowed() {
            chunk.par_iter().map(scan).collect()
        } else {
            chunk.iter().map(scan).collect()
        };
        for ((path, _, _), (rebinding, site)) in chunk.iter().zip(per_file) {
            if let Some(site) = rebinding {
                return Some(((*path).clone(), site));
            }
            if first.is_none() {
                first = site.map(|site| ((*path).clone(), site));
            }
        }
    }
    first
}

/// A definition or `use` of the name: a real rebinding, not one that only
/// may rebind it.
fn rebinds(site: &MacroBindingSite) -> bool {
    matches!(
        site.kind,
        MacroBindingKind::Definition | MacroBindingKind::Import
    )
}

/// The scoped site in the test's own file that covers the test.
fn test_macro_binding_site(
    name: &str,
    test: &TestSummary,
    assertion_line: usize,
    index: &RustIndex,
    memo: &SyncMemo<TestFileMacroSites>,
    module_resolved: &dyn Fn(&Path, usize, &str) -> bool,
) -> Option<(PathBuf, MacroBindingSite)> {
    if !assertion_context_macros().contains(&name) {
        return None;
    }
    let facts = index.files().get(&test.file)?;
    memo.borrow_mut()
        .entry((name.to_string(), test.file.clone()))
        .or_insert_with(|| {
            macro_binding_sites(
                name,
                &test.file,
                &facts.source,
                facts.macro_candidates.as_deref(),
                index,
                module_resolved,
            )
        })
        .iter()
        .find(|(_, site)| site_covers_assertion(site, test, assertion_line))
        .map(|(_, site)| (test.file.clone(), site.clone()))
}

/// `candidates` are the file's stored [`MacroBindingCandidates`]: a name
/// they rule out has no site, so the file is not parsed for it.
fn macro_binding_sites(
    name: &str,
    path: &Path,
    source: &str,
    candidates: Option<&MacroBindingCandidates>,
    index: &RustIndex,
    module_resolved: &dyn Fn(&Path, usize, &str) -> bool,
) -> Vec<(String, MacroBindingSite)> {
    if candidates.is_some_and(|candidates| !candidates.may_bind(name)) {
        return Vec::new();
    }
    trusted_macro_binding_sites(
        source,
        index.macro_scope_crates(),
        &[name],
        &|line, declaration| module_resolved(path, line, declaration),
        &|krate| {
            if krate == "serde_json" {
                index.drop_in_manifests.verified_literal_json(path)
            } else {
                index.drop_in_manifests.verified_root(path, krate)
            }
        },
    )
}

/// Trusted macro names some workspace file may rebind for every test, and
/// the scoped sites (an inline module or block) kept per file.
///
/// Parses workspace files, so on a warm `ripr check` of a large workspace
/// this scan dominated wall time (37% on ripr-swarm). Files are independent,
/// so the scan runs on the rayon pool; the ordered collect keeps each file's
/// scoped sites in source order.
///
/// #8255: the pass also retains, per trusted name, the earliest unscoped
/// rebinding and may-rebind sites (workspace-wide and per crate-local
/// root), so a refused assertion names its site from this pass instead of
/// rescanning the workspace per (name, test root).
fn trusted_macro_sites_in(
    index: &RustIndex,
    roots: &TargetRoots,
    module_resolved: &(dyn Fn(&Path, usize, &str) -> bool + Sync),
) -> (
    BTreeSet<String>,
    ScopedMacroBindings,
    CrateMacroBindings,
    WorkspaceMacroSiteIndex,
) {
    let mut global = BTreeSet::new();
    let mut scoped = ScopedMacroBindings::new();
    // A crate-local site in a recognized target root other than the test's
    // (a bench's `#[macro_use] extern crate bencher;`) is kept per root.
    let mut by_root = CrateMacroBindings::new();
    let mut retained = WorkspaceMacroSiteIndex::default();
    // One foreign glob import, `#[macro_use]` or unparsable file makes
    // every trusted name ambiguous, and most workspaces have one. Scan
    // the files that can do that first; once every name is ambiguous for
    // every test, no later file (scoped sites included) changes an answer,
    // so the rest are skipped. A refusal that needs a site completes the
    // retained scan once instead (#8255).
    let (likely, rest) = partition_macro_scan_files(index);
    absorb_macro_sites(
        scan_macro_sites(&likely, index, module_resolved),
        &mut global,
        &mut scoped,
        &mut by_root,
        &mut retained,
        roots,
        index,
    );
    if global.len() < assertion_context_macros().len() {
        absorb_macro_sites(
            scan_macro_sites(&rest, index, module_resolved),
            &mut global,
            &mut scoped,
            &mut by_root,
            &mut retained,
            roots,
            index,
        );
        retained.complete = true;
    }
    (global, scoped, by_root, retained)
}

/// One indexed file ready for the trusted-macro site scan: its path, source
/// and stored [`MacroBindingCandidates`].
type MacroScanFile<'a> = (&'a PathBuf, &'a str, Option<&'a MacroBindingCandidates>);

/// The scan-order partition behind [`trusted_macro_sites_in`]: files that
/// may saturate the ambiguity on their own, then the rest, each in path
/// order. #8255 recomputes it for the one on-demand completion of the
/// retained sites; the partition reads no file contents beyond cheap
/// substring checks.
fn partition_macro_scan_files(
    index: &RustIndex,
) -> (Vec<MacroScanFile<'_>>, Vec<MacroScanFile<'_>>) {
    index
        .files()
        .iter()
        .map(|(path, facts)| {
            let data = facts.data();
            (path, data.source.as_ref(), data.macro_candidates.as_deref())
        })
        .partition(|(_, source, _)| may_saturate_macro_ambiguity(source))
}

/// Every trusted name's sites in `files`, in path then source order. Files
/// whose stored candidates rule out every trusted name are not parsed.
fn scan_macro_sites(
    files: &[MacroScanFile<'_>],
    index: &RustIndex,
    module_resolved: &(dyn Fn(&Path, usize, &str) -> bool + Sync),
) -> Vec<(PathBuf, String, MacroBindingSite)> {
    let context_macros = assertion_context_macros();
    let scan_file = |(path, source, candidates): &MacroScanFile<'_>| {
        // A file whose stored candidates rule out every trusted name
        // reports no site, so it is not parsed.
        if !candidates.is_none_or(MacroBindingCandidates::may_bind_any_trusted) {
            return Vec::new();
        }
        trusted_macro_binding_sites(
            source,
            index.macro_scope_crates(),
            &context_macros,
            &|line, declaration| module_resolved(path, line, declaration),
            &|krate| {
                if krate == "serde_json" {
                    index.drop_in_manifests.verified_literal_json(path)
                } else {
                    index.drop_in_manifests.verified_root(path, krate)
                }
            },
        )
        .into_iter()
        .map(|(name, site)| ((*path).clone(), name, site))
        .collect::<Vec<_>>()
    };
    if nested_parallelism_allowed() {
        files.par_iter().flat_map_iter(scan_file).collect()
    } else {
        files.iter().flat_map(scan_file).collect()
    }
}

/// Whether a scan may fan out on the rayon pool. A probe classified on a pool
/// worker already runs beside its siblings, and a worker blocked in a nested
/// `par_iter` steals sibling probes onto its own stack while it may hold a
/// memo lock that those probes need (#8756), which `SyncMemo` cannot survive.
/// Scans reached from classification therefore run in line.
pub(in crate::analysis) fn nested_parallelism_allowed() -> bool {
    rayon::current_thread_index().is_none()
}

/// Route scanned sites into the ambiguity name sets, the scoped-site map,
/// the per-root name sets and #8255's retained earliest sites. Sites arrive
/// in path then source order; scoped sites never reach the retained index,
/// exactly as the replaced per-(name, test root) scan skipped them.
#[allow(
    clippy::too_many_arguments,
    reason = "one ordered fold over four run-scoped ambiguity outputs and the retention index"
)]
fn absorb_macro_sites(
    sites: Vec<(PathBuf, String, MacroBindingSite)>,
    global: &mut BTreeSet<String>,
    scoped: &mut ScopedMacroBindings,
    by_root: &mut CrateMacroBindings,
    retained: &mut WorkspaceMacroSiteIndex,
    roots: &TargetRoots,
    index: &RustIndex,
) {
    for (path, name, site) in sites {
        if site.scope.is_some() {
            scoped.entry(path).or_default().push((name, site));
            continue;
        }
        match site.crate_local.then(|| roots.root(&path, index)).flatten() {
            Some(root) => {
                retained
                    .by_root
                    .entry(root.clone())
                    .or_default()
                    .entry(name.clone())
                    .or_default()
                    .absorb(&path, &site);
                by_root.entry(root).or_default().insert(name);
            }
            None => {
                retained
                    .global
                    .entry(name.clone())
                    .or_default()
                    .absorb(&path, &site);
                global.insert(name);
            }
        }
    }
}

/// Scan-order hint for the trusted-macro ambiguity scan, never its answer:
/// a glob import not rooted at `super`/`self`/`crate`, `#[macro_use]` or
/// `no_implicit_prelude`. `use super::*;` in nearly every test module is
/// workspace-owned and would otherwise put every file first.
fn may_saturate_macro_ambiguity(source: &str) -> bool {
    source.contains("macro_use")
        || source.contains("no_implicit_prelude")
        || source.match_indices("::*").any(|(offset, _)| {
            let before = source[..offset].trim_end_matches(|character: char| {
                character.is_ascii_alphanumeric() || character == '_'
            });
            !matches!(&source[before.len()..offset], "super" | "self" | "crate")
        })
}

/// Whether a test file imports a name from outside the workspace; the
/// caller supplies its run-scoped memo.
pub(in crate::analysis) type ForeignImport<'a> = &'a dyn Fn(&Path, &str) -> bool;

enum PinCall {
    /// `name(..)`: the owner is a module-level function.
    Bare,
    /// `recv.name(..)`: the receiver's type must be one of `receivers`, and
    /// a trait method also needs its trait in the test's scope.
    Method {
        receivers: Vec<ReceiverType>,
        trait_scope: Option<TraitScope>,
    },
    /// `T::name(..)` (#6617, RIPR-SPEC-0172): the owner is an associated
    /// function (no `self`) of an inherent `impl T`, and the test must name
    /// the owner's own `T` through a direct import of the owner's library.
    /// A bare `name(..)` never takes it: that call names a module-level
    /// function, never an associated one.
    Associated { type_name: String },
}

/// Which call syntax [`other_definition_competes`] judges.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CallKind {
    /// `name(..)` or a module path `a::b::name(..)`.
    Bare,
    /// `recv.name(..)`.
    Method,
    /// `T::name(..)` on an inherent associated function (#6617).
    Associated,
}

impl PinCall {
    fn kind(&self) -> CallKind {
        match self {
            Self::Bare => CallKind::Bare,
            Self::Method { .. } => CallKind::Method,
            Self::Associated { .. } => CallKind::Associated,
        }
    }
}

/// A trait method is callable with method syntax only while its trait is
/// in scope.
struct TraitScope {
    trait_name: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum ReceiverType {
    /// A struct, enum or union declared in the workspace.
    Named(String),
    /// `&[u8]`, read from `&[..][..]` or `&b".."[..]`.
    ByteSlice,
}

enum ReturnPathGate {
    /// The changed expression is the owner's only exit.
    Any,
    /// The pinned value must start with this constructor. `Head("Err")`
    /// comes only from an early `return Err(..)`, and like `EarlyHead` it
    /// refuses an owner file that binds `Ok` or `Err` as a value.
    Head(&'static str),
    /// #7581: a changed early `return Some(..)` / `return Ok(..)` beside
    /// exits that build only `None` / `Err(..)`. Admits like `Head`; the
    /// owner's file must not bind `None`, `Some`, `Ok` or `Err`, since a
    /// rebound opposite name could build a second `Some` / `Ok` exit.
    EarlyHead(&'static str),
    /// The pinned value must be exactly this unit variant (`None`).
    Exact(&'static str),
    /// #7063: a changed early `return Err(Type::Variant ..);` that is the
    /// owner's only exit building `Type::Variant`, beside other exits that
    /// build only `Ok(..)` or another variant of `Type`. The pinned value
    /// must be one `Err(..)` call constructing that same `Type::Variant`, and
    /// `Type` is a workspace enum compared by its derived `==`, so a
    /// whole-value pin compares the variant's payload too.
    ///
    /// `siblings` are the other variants the remaining exits build; each,
    /// like `variant`, must be a declared variant of `Type`
    /// ([`error_enum_admits_variant_pin`]), so an associated constant
    /// (`Type::NO_EQUALS`) never passes for a sibling.
    ErrVariant {
        qualifier: String,
        variant: String,
        siblings: Vec<String>,
    },
    /// #6692: a field of a hand-written `Clone::clone`'s returned struct
    /// literal. The pinned value must be the clone's own receiver
    /// (`assert_eq!(w.clone(), w)`), compared through a derived
    /// `PartialEq`, so every field of the clone is compared with the
    /// original's.
    CloneReceiver,
    /// RIPR-SPEC-0265 rule 2: the changed tail is the owner's whole body,
    /// `P.iter().A(|x| E)[.T()]`, whose closure runs once per element of
    /// the parameter at `position`. The pinned call must pass that
    /// parameter a non-empty literal sequence, so the closure runs at least
    /// once on the pinned input.
    Adaptor { position: usize },
    /// RIPR-SPEC-0197 rule 3: the changed tail is the owner's whole body and
    /// one pure `&&` or `||` chain over its parameters. The pinned call
    /// must evaluate every operand on some run.
    ShortCircuit(short_circuit::ShortCircuitTail),
    /// RIPR-SPEC-0225: field `field` of the `type_name { .. }` literal the
    /// owner returns (inside `wrapper(..)` when the owner returns
    /// `Result`/`Option`). The pinned value must be a literal of that type,
    /// in the same wrapper, naming the field with an independent value.
    WholeValueField(WholeValueField),
}

/// The owner-side facts [`ReturnPathGate::WholeValueField`] checks a test's
/// expected literal against.
struct WholeValueField {
    type_name: String,
    field: String,
    wrapper: Option<&'static str>,
    /// The field is declared `String`, so `"x".into()` converts through the
    /// standard library, not a workspace `From` impl.
    field_is_string: bool,
    /// CamelCase names the workspace gives a `const`, `static` or `fn`: an
    /// expected value naming one may be computed, not a constructor.
    computed_names: BTreeSet<String>,
    /// Struct, enum, union and variant names the workspace declares, plus
    /// the standard `None`/`Some`/`Ok`/`Err`: a bare CamelCase name outside
    /// this set may be a test-local binding (`let Expected = ..;`).
    constructor_names: BTreeSet<String>,
    /// `String` may name a workspace item (`mod String`, a type, fn, const,
    /// static, trait, macro or variant of that name, a rename to it, or a
    /// non-std `use` of it), so an expected `String::from(..)` is not the
    /// standard conversion and gives no credit (#7066 review).
    string_from_may_be_rebound: bool,
}

/// #8480: records constructed in exit positions of `body`: the block
/// tail and every `return` value of the owner itself (a `return` inside
/// a nested closure or item returns from that closure or item, not the
/// owner), plus records a `let` or assignment binds and an exit value
/// then names. Deduplicated by source range.
fn exit_position_records(body: &ast::BlockExpr) -> Vec<ast::RecordExpr> {
    let mut records: Vec<ast::RecordExpr> = Vec::new();
    let mut roots: Vec<ast::Expr> = Vec::new();
    if let Some(tail) = body.stmt_list().and_then(|list| list.tail_expr()) {
        roots.push(tail);
    }
    for node in body.syntax().descendants() {
        let Some(returned) = ast::ReturnExpr::cast(node) else {
            continue;
        };
        let nested = returned
            .syntax()
            .ancestors()
            .take_while(|ancestor| ancestor != body.syntax())
            .any(|ancestor| {
                ast::ClosureExpr::can_cast(ancestor.kind()) || ast::Fn::can_cast(ancestor.kind())
            });
        if !nested && let Some(value) = returned.expr() {
            roots.push(value);
        }
    }
    for root in &roots {
        collect_exit_records(root, &mut records);
    }
    // A record bound by a `let` or an assignment becomes the result
    // when an exit value names the binding; follow such names through
    // binding initializers to a fixed point. Bindings no exit value
    // names stay local.
    let mut sought: BTreeSet<String> = roots
        .iter()
        .flat_map(|root| syntax_identifiers(root.syntax()))
        .collect();
    let mut bindings: Vec<(String, ast::Expr)> = Vec::new();
    for node in body.syntax().descendants() {
        if let Some(binding) = ast::LetStmt::cast(node.clone())
            && let Some(initializer) = binding.initializer()
        {
            let names: Vec<String> = binding
                .pat()
                .map(|pat| {
                    pat.syntax()
                        .descendants()
                        .filter_map(ast::IdentPat::cast)
                        .filter_map(|ident| ident.name().map(|name| name.text().to_string()))
                        .collect()
                })
                .unwrap_or_default();
            // A pattern binding no name (`let _ = ..`, a literal
            // pattern) cannot carry the value into an exit value.
            for name in names {
                bindings.push((name, initializer.clone()));
            }
        }
        if let Some(binary) = ast::BinExpr::cast(node)
            && matches!(binary.op_kind(), Some(ast::BinaryOp::Assignment { .. }))
            && let (Some(lhs), Some(rhs)) = (binary.lhs(), binary.rhs())
            && let ast::Expr::PathExpr(path) = unwrap_exit_parens(&lhs)
            && let Some(name) = path
                .path()
                .and_then(|path| path.segment())
                .map(|segment| segment.syntax().text().to_string())
        {
            bindings.push((name, rhs));
        }
    }
    let mut resolved: BTreeSet<(usize, usize)> = BTreeSet::new();
    loop {
        let mut progressed = false;
        for (name, initializer) in &bindings {
            let range = initializer.syntax().text_range();
            let key = (usize::from(range.start()), usize::from(range.end()));
            if !sought.contains(name) || !resolved.insert(key) {
                continue;
            }
            collect_exit_records(initializer, &mut records);
            for identifier in syntax_identifiers(initializer.syntax()) {
                sought.insert(identifier);
            }
            progressed = true;
        }
        if !progressed {
            break;
        }
    }
    records
}

fn syntax_identifiers(node: &SyntaxNode) -> Vec<String> {
    node.descendants_with_tokens()
        .filter_map(|element| element.into_token())
        .filter(|token| token.kind() == ra_ap_syntax::SyntaxKind::IDENT)
        .map(|token| token.text().to_string())
        .collect()
}

fn push_record(record: &ast::RecordExpr, records: &mut Vec<ast::RecordExpr>) {
    let range = record.syntax().text_range();
    if !records
        .iter()
        .any(|known| known.syntax().text_range() == range)
    {
        records.push(record.clone());
    }
}

fn collect_all_records(node: &SyntaxNode, records: &mut Vec<ast::RecordExpr>) {
    for descendant in node.descendants() {
        if let Some(record) = ast::RecordExpr::cast(descendant) {
            push_record(&record, records);
        }
    }
}

fn unwrap_exit_parens(expression: &ast::Expr) -> ast::Expr {
    let mut expression = expression.clone();
    while let ast::Expr::ParenExpr(paren) = &expression {
        let Some(inner) = paren.expr() else {
            break;
        };
        expression = inner;
    }
    expression
}

/// Collect records in `expression`, which sits in an exit position.
/// Only wrappers that carry a value into the result are followed;
/// every other shape in an exit position fails closed and contributes
/// all of its records.
fn collect_exit_records(expression: &ast::Expr, records: &mut Vec<ast::RecordExpr>) {
    match expression {
        ast::Expr::RecordExpr(record) => {
            push_record(record, records);
            if let Some(fields) = record.record_expr_field_list() {
                for field in fields.fields() {
                    if let Some(value) = field.expr() {
                        collect_exit_records(&value, records);
                    }
                }
                if let Some(spread) = fields.spread() {
                    collect_exit_records(&spread, records);
                }
            }
        }
        ast::Expr::ParenExpr(paren) => {
            if let Some(inner) = paren.expr() {
                collect_exit_records(&inner, records);
            }
        }
        ast::Expr::BlockExpr(block) => {
            if let Some(tail) = block.stmt_list().and_then(|list| list.tail_expr()) {
                collect_exit_records(&tail, records);
            }
        }
        ast::Expr::IfExpr(if_expr) => {
            if let Some(then_branch) = if_expr.then_branch() {
                collect_exit_records(&ast::Expr::BlockExpr(then_branch), records);
            }
            match if_expr.else_branch() {
                Some(ast::ElseBranch::Block(block)) => {
                    collect_exit_records(&ast::Expr::BlockExpr(block), records);
                }
                Some(ast::ElseBranch::IfExpr(else_if)) => {
                    collect_exit_records(&ast::Expr::IfExpr(else_if), records);
                }
                None => {}
            }
        }
        ast::Expr::MatchExpr(match_expr) => {
            if let Some(arms) = match_expr.match_arm_list() {
                for arm in arms.arms() {
                    if let Some(value) = arm.expr() {
                        collect_exit_records(&value, records);
                    }
                }
            }
        }
        ast::Expr::CallExpr(call) => {
            if let Some(args) = call.arg_list() {
                for arg in args.args() {
                    collect_exit_records(&arg, records);
                }
            }
        }
        ast::Expr::TupleExpr(tuple) => {
            for field in tuple.fields() {
                collect_exit_records(&field, records);
            }
        }
        ast::Expr::ArrayExpr(array) => {
            for element in array.exprs() {
                collect_exit_records(&element, records);
            }
        }
        ast::Expr::ReturnExpr(returned) => {
            if let Some(value) = returned.expr() {
                collect_exit_records(&value, records);
            }
        }
        ast::Expr::BreakExpr(break_expr) => {
            if let Some(value) = break_expr.expr() {
                collect_exit_records(&value, records);
            }
        }
        ast::Expr::TryExpr(try_expr) => {
            if let Some(value) = try_expr.expr() {
                collect_exit_records(&value, records);
            }
        }
        ast::Expr::AwaitExpr(await_expr) => {
            if let Some(value) = await_expr.expr() {
                collect_exit_records(&value, records);
            }
        }
        ast::Expr::PathExpr(_)
        | ast::Expr::Literal(_)
        | ast::Expr::ContinueExpr(_)
        | ast::Expr::UnderscoreExpr(_) => {}
        other => collect_all_records(other.syntax(), records),
    }
}

impl OwnerReturnPin {
    /// The owner-side gates: `None` when the probe is not a return value
    /// (or a changed `return Err(..)`, filed as `error_path`),
    /// the owner's declaration or return paths are not established, or
    /// another workspace definition could take a call by the owner's name.
    pub(in crate::analysis) fn establish(
        probe: &Probe,
        owner: &FunctionSummary,
        index: &RustIndex,
    ) -> Option<Self> {
        if matches!(probe.family, ProbeFamily::FieldConstruction) {
            // A `clone` owner is #6692's alone: which `Clone` impl a call
            // runs is that path's question, not one this one asks.
            return if owner.name == "clone" {
                Self::establish_clone_field(probe, owner, index)
            } else {
                Self::establish_whole_value_field(probe, owner, index)
                    .or_else(|| Self::establish_err_variant_field(probe, owner, index))
            };
        }
        if !owner.item.has_body {
            return None;
        }
        let returns_bool = declared_return_type(&owner.body).as_deref() == Some("bool");
        // A predicate that is a bool owner's whole tail is the owner's return
        // value, so the same pin observes it.
        match probe.family {
            ProbeFamily::ReturnValue | ProbeFamily::ErrorPath => {}
            ProbeFamily::Predicate if returns_bool => {}
            _ => return None,
        }
        let parser_backed = index
            .files()
            .get(&owner.file)
            .is_some_and(|facts| !facts.used_lexical_fallback);
        if !parser_backed {
            return None;
        }
        let name = owner.name.as_str();
        let changed_line = probe.location.line.checked_sub(owner.start_line)?;
        let path = match return_path_gate_from(
            &owner.body,
            &probe.expression,
            probe.before.as_deref(),
            changed_line,
        ) {
            Some(path) => path,
            // RIPR-SPEC-0265 rule 2: only a changed return value that is the
            // whole admitted adaptor tail; the test side reads the input.
            // This fallback implements that spec's amendment of the pin's
            // closure refusal ("a closure in the tail no longer refuses it
            // on this shape") and must stay unguarded: 0265's keeping-pair
            // registry is what tells a closure-carried change apart there.
            None if matches!(probe.family, ProbeFamily::ReturnValue) => {
                closure_adaptor::admitted_owner_adaptor_tail(owner, index)
                    .filter(|tail| tail.tail_is(&probe.expression))
                    .map(|tail| ReturnPathGate::Adaptor {
                        position: tail.position,
                    })?
            }
            None => return None,
        };
        // #7063: an early error-variant pin reads the other exits' variants
        // of the owner's own error enum, and the pinned `==` must compare the
        // variant's payload.
        // A payload-carrying `Err(Type::Variant ..)` of a workspace enum
        // under the `Err` head gate is held to the same variant rules: its
        // payload is pinned only through `Type`'s derived `==`
        // (RIPR-SPEC-0197 early error-variant pins, rule 3). An associated
        // function call (`Err(String::from(..))`) keeps the `Err` head gate.
        let path = match path {
            ReturnPathGate::Head("Err") => match payload_variant_construction(&probe.expression)
                .filter(|(qualifier, variant)| {
                    workspace_enum_declares_variant(qualifier, variant, index)
                }) {
                Some((qualifier, variant)) => ReturnPathGate::ErrVariant {
                    qualifier,
                    variant,
                    siblings: Vec::new(),
                },
                None => ReturnPathGate::Head("Err"),
            },
            other => other,
        };
        if let ReturnPathGate::ErrVariant {
            qualifier,
            variant,
            siblings,
        } = &path
            && !error_enum_admits_variant_pin(qualifier, variant, siblings, owner, index)
        {
            return None;
        }
        // The early `Some`/`Ok`/`Err` gates read the other exits' `None`,
        // `Err(..)` and `Ok(..)` as the prelude variants; a `const None` or
        // `fn Ok` in the owner's file can build a second source of the
        // changed value under that spelling (#7581 and #7712 reviews).
        if path.prelude_names().iter().any(|name| {
            index
                .files()
                .get(&owner.file)
                .is_none_or(|facts| source_binds_value_name(&facts.source, name))
        }) {
            return None;
        }
        let call = pin_call(owner, index)?;
        // #6544: a bare call's same-package module-level rivals are settled
        // per test by the import or path that spells the call; every other
        // competing definition still refuses the pin here.
        let identity = match call.kind() {
            CallKind::Bare => super::call_identity::shared_owner_call_identity(index, owner),
            CallKind::Method | CallKind::Associated => None,
        };
        if other_definition_competes(owner, index, call.kind(), identity.as_deref()) {
            return None;
        }
        Some(Self {
            name: name.to_string(),
            call,
            path,
            returns_bool,
            returns_scalar: returns_primitive_scalar(owner, index),
            returns_integer: returns_primitive_scalar(owner, index)
                && declared_return_type(&owner.body)
                    .is_some_and(|returned| INTEGER_TYPES.contains(&returned.as_str())),
            awaited: declares_async(owner, index),
            drop_plain: Self::returned_types_drop_plain(owner, index),
            owner_file: owner.file.clone(),
            owner_start_line: owner.start_line,
            trait_scope_by_file: SyncMemo::default(),
            identity,
        })
    }

    /// Whether every record type constructed in an exit position of
    /// the owner has at most a plain `Drop` impl in the workspace
    /// (#8480). Exit positions are values that can become the function
    /// result: the block tail, a `return` value, branch and match-arm
    /// tails feeding one of those, and records nested in wrappers along
    /// such a path. Records built only in non-exit positions (let
    /// initializers that are not returned, statement expressions,
    /// conditions, loop bodies, statement call arguments) drop inside
    /// the owner and do not refuse. Shapes ripr cannot place in one of
    /// those positions fail closed and still count as exit positions.
    /// Types constructed in no exit position (scalar returns, calls)
    /// have nothing to refuse.
    pub(in crate::analysis) fn returned_types_drop_plain(
        owner: &FunctionSummary,
        index: &RustIndex,
    ) -> bool {
        let source = owner.body.as_str();
        let Some(parse) = parse_clean_source_file(source) else {
            return false;
        };
        let Some(function) = parse.tree().syntax().descendants().find_map(ast::Fn::cast) else {
            return false;
        };
        let Some(body) = function.body() else {
            return false;
        };
        exit_position_records(&body).iter().all(|record| {
            record
                .path()
                .and_then(|path| path.segment())
                .is_some_and(|segment| {
                    super::element_field_pin::drop_is_plain(
                        index,
                        &segment.syntax().text().to_string(),
                    )
                })
        })
    }

    /// #6692: the owner-side gates for a `field_construction` probe in a
    /// hand-written `impl Clone for T`. Established only when the changed
    /// line is a field of the struct literal that is `clone`'s only exit,
    /// `T` is declared once in the workspace with `#[derive(PartialEq)]`
    /// and has no hand-written `PartialEq` impl, no workspace trait is
    /// named `Clone`, and no other `fn clone` with a receiver competes.
    /// The test-side gate then requires `assert_eq!(recv.clone(), recv)`.
    fn establish_clone_field(
        probe: &Probe,
        owner: &FunctionSummary,
        index: &RustIndex,
    ) -> Option<Self> {
        if owner.name != "clone" || !owner.item.has_body || !owner.item.has_self_param {
            return None;
        }
        let FunctionContainer::TraitImpl {
            trait_path,
            self_ty,
        } = &owner.item.container
        else {
            return None;
        };
        // The standard `Clone`: bare, or a `std`/`core` path; the owner's
        // file may not import, glob or rename `Clone` from elsewhere
        // (`impl dupe::Clone for Window`, `use dupe::Clone;`).
        let trait_path = trait_path.trim().trim_start_matches("::");
        if !matches!(
            trait_path,
            "Clone" | "std::clone::Clone" | "core::clone::Clone"
        ) {
            return None;
        }
        // `extern crate other as std;` makes `std::clone::Clone` foreign.
        if let Some((root, _)) = trait_path.split_once("::")
            && workspace_renames_to(index, root)
        {
            return None;
        }
        let owner_source = index
            .files()
            .get(&owner.file)
            .filter(|facts| !facts.used_lexical_fallback)
            .map(|facts| facts.data().source.clone())?;
        if declaring_file_rebinds(&owner_source, "Clone", false, index) {
            return None;
        }
        // `impl Clone for W<Foo>`: an instantiation of a generic type,
        // whose type parameters ripr does not substitute.
        if self_ty.contains('<') {
            return None;
        }
        let receiver = declared_receiver(self_ty, index)?;
        let ReceiverType::Named(type_name) = &receiver else {
            return None;
        };
        let changed_line = probe.location.line.checked_sub(owner.start_line)?;
        let field = initialized_field_name(&probe.expression)?;
        if !clone_tail_literal_spans(&owner.body, type_name, changed_line, &probe.expression)
            || !field_compares_with_derived_equality(type_name, field, index)
            || derives_clone(type_name, index)
            || workspace_declares_trait(index, "Clone")
            || other_definition_competes(owner, index, CallKind::Method, None)
        {
            return None;
        }
        Some(Self {
            name: owner.name.clone(),
            call: PinCall::Method {
                receivers: vec![receiver],
                // `Clone` is in the prelude; a workspace `trait Clone` is
                // refused above and a foreign import in `admits`.
                trait_scope: None,
            },
            path: ReturnPathGate::CloneReceiver,
            returns_bool: false,
            returns_scalar: false,
            returns_integer: false,
            awaited: declares_async(owner, index),
            drop_plain: Self::returned_types_drop_plain(owner, index),
            owner_file: owner.file.clone(),
            owner_start_line: owner.start_line,
            trait_scope_by_file: SyncMemo::default(),
            identity: None,
        })
    }

    /// RIPR-SPEC-0225: the owner-side gates for a `field_construction`
    /// probe on a field of the struct literal the owner returns. The literal
    /// (or `Ok(..)`/`Some(..)` around it, matching the declared return type)
    /// is the owner's tail and only value exit, the changed line is one whole
    /// field initializer of it that evaluates on every input, and `==` on the
    /// literal's type compares that field by value (rules 3 and 4).
    fn establish_whole_value_field(
        probe: &Probe,
        owner: &FunctionSummary,
        index: &RustIndex,
    ) -> Option<Self> {
        if !owner.item.has_body
            || index
                .files()
                .get(&owner.file)
                .is_none_or(|facts| facts.used_lexical_fallback)
        {
            return None;
        }
        let changed_line = probe.location.line.checked_sub(owner.start_line)?;
        let field = initialized_field_name(&probe.expression)?;
        let tail = whole_value_tail(&owner.body, changed_line, field, &probe.expression)?;
        let type_name = if tail.type_name == "Self" {
            match &owner.item.container {
                FunctionContainer::Inherent { self_ty }
                | FunctionContainer::TraitImpl { self_ty, .. }
                    if !self_ty.contains('<') =>
                {
                    path_base_name(self_ty)?.to_string()
                }
                _ => return None,
            }
        } else {
            tail.type_name
        };
        let declared = declared_return_type(&owner.body)?;
        let names_type = |ty: &str| ty == type_name || ty == "Self";
        let declared_matches = match tail.wrapper {
            None => names_type(&declared),
            Some(wrapper) => {
                let (path, arguments) = declared.split_once('<')?;
                let arguments = arguments.strip_suffix('>')?;
                let first = top_level_arguments(arguments).into_iter().next()?;
                let container = if wrapper == "Ok" { "Result" } else { "Option" };
                path_base_name(path) == Some(container)
                    && !type_declared_in_workspace(container, index)
                    && names_type(first.trim())
            }
        };
        if !declared_matches || !field_compares_with_derived_equality(&type_name, field, index) {
            return None;
        }
        // The owner's file must name the workspace declaration: a `use
        // other::Config;` there makes the literal another crate's type.
        let owner_source = &index.files().get(&owner.file)?.source;
        if declaring_file_rebinds(owner_source, &type_name, true, index)
            || tail
                .wrapper
                .into_iter()
                .chain(tail.early_exit)
                .any(|constructor| wrapper_may_be_rebound(constructor, index))
        {
            return None;
        }
        let field_is_string = derived_equality(&type_name, index).is_some_and(|(facts, _)| {
            facts.fields.iter().any(|candidate| {
                candidate.name.as_deref() == Some(field) && candidate.ty == "String"
            })
        });
        let call = pin_call(owner, index)?;
        // #6617 keeps the associated-function pin to a return value: a
        // `T::new()` whole-value field pin is a separate claim.
        if matches!(call, PinCall::Associated { .. })
            || other_definition_competes(owner, index, call.kind(), None)
        {
            return None;
        }
        Some(Self {
            name: owner.name.clone(),
            call,
            path: ReturnPathGate::WholeValueField(WholeValueField {
                type_name,
                field: field.to_string(),
                wrapper: tail.wrapper,
                field_is_string,
                computed_names: camel_case_value_items(index),
                constructor_names: declared_constructor_names(index),
                string_from_may_be_rebound: wrapper_may_be_rebound("String", index),
            }),
            returns_bool: false,
            returns_scalar: false,
            returns_integer: false,
            awaited: declares_async(owner, index),
            drop_plain: Self::returned_types_drop_plain(owner, index),
            owner_file: owner.file.clone(),
            owner_start_line: owner.start_line,
            trait_scope_by_file: SyncMemo::default(),
            identity: None,
        })
    }

    /// #7063: the owner-side gates for a `field_construction` probe on one
    /// field initializer of a changed early `return Err(Type::Variant { .. });`
    /// written on one line. The construction must pass the early
    /// error-variant gate ([`err_variant_gate`]), so a pin expecting
    /// `Err(Type::Variant { .. })` observes this return and, through the
    /// derived `==` of `Type`, compares the changed field.
    fn establish_err_variant_field(
        probe: &Probe,
        owner: &FunctionSummary,
        index: &RustIndex,
    ) -> Option<Self> {
        if !owner.item.has_body
            || index
                .files()
                .get(&owner.file)
                .is_none_or(|facts| facts.used_lexical_fallback)
        {
            return None;
        }
        let changed_line = probe.location.line.checked_sub(owner.start_line)?;
        initialized_field_name(&probe.expression)?;
        let initializer = collapse_whitespace(probe.expression.trim().trim_end_matches(','));
        let statement = owner.body.lines().nth(changed_line)?.trim();
        let construction = statement
            .strip_prefix("return ")?
            .trim()
            .strip_suffix(';')?
            .trim_end();
        constructor_call_span(construction, "Err")?;
        let (qualifier, variant) = error_variant_key(construction)?;
        // One brace-delimited payload, closed right before the `Err(..)`
        // closes, whose top-level fields include the changed initializer.
        let masked = mask_comments_and_strings(construction);
        let open = masked.find('{')?;
        let close = masked.rfind('}')?;
        if masked.matches('{').count() != 1
            || masked.matches('}').count() != 1
            || close < open
            || masked[close + 1..].trim() != ")"
        {
            return None;
        }
        let names_field = top_level_arguments(&construction[open + 1..close])
            .into_iter()
            .any(|field| collapse_whitespace(field) == initializer);
        if !names_field {
            return None;
        }
        let siblings = match return_path_gate_from(&owner.body, statement, None, changed_line)? {
            ReturnPathGate::Head("Err") => Vec::new(),
            ReturnPathGate::ErrVariant { siblings, .. } => siblings,
            _ => return None,
        };
        if !error_enum_admits_variant_pin(&qualifier, &variant, &siblings, owner, index) {
            return None;
        }
        let path = ReturnPathGate::ErrVariant {
            qualifier,
            variant,
            siblings,
        };
        if path.prelude_names().iter().any(|name| {
            index
                .files()
                .get(&owner.file)
                .is_none_or(|facts| source_binds_value_name(&facts.source, name))
        }) {
            return None;
        }
        let call = pin_call(owner, index)?;
        // As for a whole-value field: no associated-function pin, and no
        // other definition may take a call by the owner's name.
        if matches!(call, PinCall::Associated { .. })
            || other_definition_competes(owner, index, call.kind(), None)
        {
            return None;
        }
        Some(Self {
            name: owner.name.clone(),
            call,
            path,
            returns_bool: false,
            returns_scalar: false,
            returns_integer: false,
            awaited: declares_async(owner, index),
            drop_plain: Self::returned_types_drop_plain(owner, index),
            owner_file: owner.file.clone(),
            owner_start_line: owner.start_line,
            trait_scope_by_file: SyncMemo::default(),
            identity: None,
        })
    }

    /// RIPR-SPEC-0197 check-helper argument pins: the test-scope texts a
    /// borrowed helper assertion's two compared parameters stand for, read
    /// only for a whole-return owner pin whose assertion is
    /// `assert_eq!(a, b)` or `assert!(a == b)` over two plain parameters of
    /// a helper that never names the owner.
    fn substituted_helper_operands(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
        compared: &[String; 2],
        skip: usize,
    ) -> Option<[String; 2]> {
        if !matches!(self.path, ReturnPathGate::Any)
            || (test.start_line..=test.end_line).contains(&assertion.line)
            || !compared.iter().all(|operand| is_plain_identifier(operand))
        {
            return None;
        }
        let loan = syntax.helper_loan(test, assertion, index)?;
        // A helper that names the owner may feed it into either side.
        if contains_as_whole_word(&mask_comments_and_strings(&loan.helper), &self.name) {
            return None;
        }
        helper_arguments::substituted_operands(
            test,
            &loan,
            [compared[0].as_str(), compared[1].as_str()],
            &self.name,
            index,
            |operands| self.substituted_pin(operands, index).is_some(),
            skip,
        )
    }

    /// The owner call, the literal expected value and the call text of a
    /// substituted helper comparison: one side is the owner call (or a
    /// template rendering of a scalar owner's call), the other a literal.
    fn substituted_pin<'a>(
        &self,
        operands: &'a [String; 2],
        index: &RustIndex,
    ) -> Option<(CallShape<'a>, String, Option<&'a str>)> {
        [(0, 1), (1, 0)].into_iter().find_map(|(at, other)| {
            let expected = helper_arguments::expected_literal(&operands[other], index)?;
            if let Some(call) = self.awaited_call_shape(&operands[at], &self.name) {
                return Some((call, expected, Some(operands[at].as_str())));
            }
            let rendered = self
                .returns_scalar
                .then(|| helper_arguments::rendered_template_call(&operands[at], &expected))
                .flatten()?;
            self.awaited_call_shape(rendered, &self.name)
                .map(|call| (call, expected, None))
        })
    }

    /// The test-side gates: whether `assertion` in `test` pins the owner's
    /// return value through a call that names the owner.
    /// [`owner_call_shape`], reading an `async` owner's result through one
    /// trailing `.await` (`total(&[1, 2]).await`). A sync owner's `.await`
    /// awaits a future it returns, whose output its return expression does
    /// not hold, so that stays refused.
    fn awaited_call_shape<'a>(&self, operand: &'a str, name: &str) -> Option<CallShape<'a>> {
        let operand = operand.trim();
        // An async owner's bare call is its future, not its return value.
        match (self.awaited, operand.strip_suffix(".await")) {
            (true, Some(call)) => owner_call_shape(call.trim_end(), name),
            (true, None) => None,
            (false, _) => owner_call_shape(operand, name),
        }
    }

    pub(in crate::analysis) fn admits(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
        imports_foreign: ForeignImport<'_>,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        // A selected check-helper argument pin that a later gate refuses
        // (another owner of the same name, a scope or identity gate) leaves
        // the helper's later eager calls to try: an unrelated earlier call
        // must not hide the genuine pin.
        let mut probe = HelperCallProbe::default();
        loop {
            if self.admits_candidate(test, assertion, index, imports_foreign, syntax, &probe) {
                return true;
            }
            if !probe.selected.get() {
                return false;
            }
            probe.skip += 1;
            probe.selected.set(false);
        }
    }

    fn admits_candidate(
        &self,
        test: &TestSummary,
        assertion: &OracleFact,
        index: &RustIndex,
        imports_foreign: ForeignImport<'_>,
        syntax: &OwnerPinSyntax,
        probe: &HelperCallProbe,
    ) -> bool {
        // A `#[should_panic]` test passes when the values differ.
        if test
            .attrs
            .iter()
            .map(String::as_str)
            .chain(std::iter::once(test.body.as_str()))
            .any(|text| text.contains("should_panic"))
        {
            return false;
        }
        // #8480: a non-plain `Drop` on a constructed return type runs
        // while unwinding from a failed assertion and may exit 0 first.
        if !self.drop_plain {
            return false;
        }
        // #6648 (RIPR-SPEC-0279): a doc example's scope is its synthetic
        // source, not the file that holds the comment.
        let doctest = index.doctest_source(test);
        let condition;
        let matches_operands: [String; 2];
        let expect_operands: [String; 2];
        // RIPR-SPEC-0197: `assert!(owner(..) == v)` and its guard twin
        // `if owner(..) != v { return Err(..) }` read like `assert_eq!`. A
        // guard reads only its condition, never a macro inside its body,
        // since the syntax gate admits the guard's path, not the body's.
        let is_guard = err_return_guard_twin(&assertion.text).is_some();
        // A nested `format!` is read only as a rendered scalar pin, and a
        // nested `vec!` only as a single-element index.
        let renders = !is_guard && is_assert_eq_over(&assertion.text, "format");
        let indexes = !is_guard && is_assert_eq_over(&assertion.text, "vec");
        let reads_assert_eq = renders
            || indexes
            || (!is_guard && is_plain_or_std_macro(&assertion.text, "assert_eq"));
        let equality = if reads_assert_eq {
            None
        } else {
            equality_condition_operands(&assertion.text)
        };
        // RIPR-SPEC-0225 decision 6: beside an `Ok(..)`/`Some(..)` tail, the
        // test may compare `owner(..).unwrap()` (or `.expect("..")`) with the
        // bare literal; that reads as comparing the call with the wrapped one.
        // #7063: beside an early error-variant gate the test may compare
        // `owner(..).unwrap_err()` (or `.expect_err("..")`) with the bare
        // variant; that reads as comparing the call with `Err(..)` of it.
        let unwrap_wrapper = match &self.path {
            ReturnPathGate::WholeValueField(gate) => gate.wrapper,
            ReturnPathGate::ErrVariant { .. } => Some("Err"),
            _ => None,
        };
        let unwrap_read: fn(&str) -> Option<&str> =
            if matches!(self.path, ReturnPathGate::ErrVariant { .. }) {
                unwrapped_err_call
            } else {
                unwrapped_call
            };
        let mut unwrapped = false;
        // RIPR-SPEC-0197 check-helper argument pins: a borrowed helper
        // assertion that compares two of the helper's own parameters reads
        // as comparing the arguments the test's eager call passes.
        let compared = if is_guard || renders || indexes {
            None
        } else if reads_assert_eq {
            assertion_comparison_operands(&assertion.text)
                .map(|[left, right]| [left.trim().to_string(), right.trim().to_string()])
        } else {
            equality.clone()
        };
        let substituted = compared.and_then(|compared| {
            self.substituted_helper_operands(test, assertion, index, syntax, &compared, probe.skip)
        });
        if probe.skip > 0 && substituted.is_none() {
            // Every eligible call was already tried; the plain readings
            // below were not what the first attempt selected.
            return false;
        }
        probe.selected.set(substituted.is_some());
        let substituted_expected;
        // RIPR-SPEC-0265: the text of the owner call, when one operand is it,
        // so an adaptor gate can read the argument the call passes.
        let (call, expected, call_text): (_, _, Option<&str>) = if let Some(operands) = &substituted
        {
            let Some((call, expected, call_text)) = self.substituted_pin(operands, index) else {
                return false;
            };
            substituted_expected = expected;
            (call, substituted_expected.as_str(), call_text)
        } else if reads_assert_eq {
            let Some(operands) = assertion_comparison_operands(&assertion.text) else {
                return false;
            };
            // trap-shine-debug-exact-control: the std rendering of a
            // primitive scalar names its value, so an exact string pins it.
            let rendered = (self.returns_scalar && matches!(self.path, ReturnPathGate::Any))
                .then(|| {
                    [(0, 1), (1, 0)].into_iter().find_map(|(at, other)| {
                        helper_arguments::rendered_template_call(operands[at], operands[other])
                            .and_then(|call| self.awaited_call_shape(call, &self.name))
                            .map(|call| (call, operands[other], None))
                    })
                })
                .flatten()
                // trap-ceiling-wide-min-control / trap-muffle-times-one-control:
                // a projection that keeps every value of an integer owner the
                // literal expected value can name.
                .or_else(|| {
                    (self.returns_integer && matches!(self.path, ReturnPathGate::Any) && !renders)
                        .then(|| {
                            [(0, 1), (1, 0)].into_iter().find_map(|(at, other)| {
                                exact_integer_projection(operands[at], operands[other])
                                    .filter(|_| !ord_method_rebindable(operands[at], test, index))
                                    .and_then(|call| self.awaited_call_shape(call, &self.name))
                                    .map(|call| (call, operands[other], None))
                            })
                        })
                        .flatten()
                })
                // trap-pile-first-element-control: `vec![call][0]` is the
                // call's own value.
                .or_else(|| {
                    (self.returns_scalar && matches!(self.path, ReturnPathGate::Any) && indexes)
                        .then(|| {
                            [(0, 1), (1, 0)].into_iter().find_map(|(at, other)| {
                                single_element_index(operands[at])
                                    .and_then(|call| self.awaited_call_shape(call, &self.name))
                                    .map(|call| (call, operands[other], None))
                            })
                        })
                        .flatten()
                });
            let unwrapped_direct = unwrap_wrapper.and_then(|_| {
                let shape = |at: usize| {
                    unwrap_read(operands[at])
                        .and_then(|call| self.awaited_call_shape(call, &self.name))
                };
                match (shape(0), shape(1)) {
                    (Some(call), None) => Some((call, operands[1], None)),
                    (None, Some(call)) => Some((call, operands[0], None)),
                    _ => None,
                }
            });
            match (
                self.awaited_call_shape(operands[0], &self.name),
                self.awaited_call_shape(operands[1], &self.name),
                rendered,
            ) {
                (_, _, Some(pin)) if renders || indexes => pin,
                // A `vec!` elsewhere (the expected value, the message) leaves
                // the direct readings below.
                _ if renders => return false,
                (Some(call), None, _) => (call, operands[1], Some(operands[0])),
                (None, Some(call), _) => (call, operands[0], Some(operands[1])),
                (None, None, Some(pin)) => pin,
                (None, None, _) if unwrapped_direct.is_some() => {
                    let Some(pair) = unwrapped_direct else {
                        return false;
                    };
                    unwrapped = true;
                    pair
                }
                // #6974: `let result = owner(..); assert_eq!(result, 7);`.
                // Only a test that names the owner outside this assertion
                // can bind its result, and only in the test's own body: a
                // borrowed helper assertion names the helper's parameters,
                // not the test's bindings (#6482).
                (None, None, None)
                    if (test.start_line..=test.end_line).contains(&assertion.line)
                        && owner_named_outside(test, &assertion.text, &self.name) =>
                {
                    let bound = |at: usize| {
                        let_bound_owner_call(
                            test,
                            assertion,
                            operands[at],
                            &self.name,
                            self.returns_scalar,
                        )
                        .and_then(|text| {
                            self.awaited_call_shape(text, &self.name)
                                .map(|call| (call, text))
                        })
                    };
                    match (bound(0), bound(1)) {
                        (Some((call, text)), None) => (call, operands[1], Some(text)),
                        (None, Some((call, text))) => (call, operands[0], Some(text)),
                        // RIPR-SPEC-0225 rule 1: `let c = owner(..);` named
                        // only by its `let` and this comparison.
                        (None, None)
                            if matches!(
                                self.path,
                                ReturnPathGate::WholeValueField(_)
                                    | ReturnPathGate::ErrVariant { .. }
                            ) =>
                        {
                            let bound_whole = |at: usize| {
                                let initializer =
                                    bound_owner_initializer(test, operands[at], &self.name)?;
                                self.awaited_call_shape(initializer, &self.name)
                                    .map(|call| (call, false))
                                    .or_else(|| {
                                        unwrap_wrapper
                                            .and(unwrap_read(initializer))
                                            .and_then(|call| {
                                                self.awaited_call_shape(call, &self.name)
                                            })
                                            .map(|call| (call, true))
                                    })
                            };
                            match (bound_whole(0), bound_whole(1)) {
                                (Some((call, unwraps)), None) => {
                                    unwrapped = unwraps;
                                    (call, operands[1], None)
                                }
                                (None, Some((call, unwraps))) => {
                                    unwrapped = unwraps;
                                    (call, operands[0], None)
                                }
                                _ => return false,
                            }
                        }
                        _ => return false,
                    }
                }
                _ => return false,
            }
        } else if let Some([left, right]) = &equality {
            match (
                self.awaited_call_shape(left, &self.name),
                self.awaited_call_shape(right, &self.name),
            ) {
                (Some(call), None) => (call, right.as_str(), Some(left.as_str())),
                (None, Some(call)) => (call, left.as_str(), Some(right.as_str())),
                _ => return false,
            }
        } else if !is_guard
            && is_plain_assert_of_matches(&assertion.text)
            && let Some(operands) = outer_assertion_condition(&assertion.text)
                .as_deref()
                .and_then(literal_matches_operands)
        {
            // RIPR-SPEC-0197 literal `matches!` pins: `assert!(matches!(owner(..), Ok(5)))`
            // with a literal-only pattern pins the value as
            // `assert_eq!(owner(..), Ok(5))` does.
            matches_operands = operands;
            let Some(call) = owner_call_shape(&matches_operands[0], &self.name) else {
                return false;
            };
            // A pattern resolves `None` or `Some(..)` in the test's scope, so
            // a `const None` there matches some other value (#7581 review).
            let pattern = &matches_operands[1];
            if ["Some", "None", "Ok", "Err"].iter().any(|name| {
                contains_as_whole_word(pattern, name)
                    && (index
                        .files()
                        .get(&test.file)
                        .is_none_or(|facts| source_binds_value_name(&facts.source, name))
                        || doctest.is_some_and(|source| source_binds_value_name(source, name)))
            }) {
                return false;
            }
            (
                call,
                matches_operands[1].as_str(),
                Some(matches_operands[0].as_str()),
            )
        } else if let Some(operands) = inline_expect_operands(&assertion.text) {
            // #6578: `expect![["alice: 42"]].assert_eq(&render_row("alice", 41))`
            // compares the actual text with the inline literal and panics on
            // a mismatch, as `assert_eq!(render_row("alice", 41), "alice: 42")`
            // does.
            expect_operands = operands;
            // #6578 review: a golden file the test itself writes (from the
            // owner, say) before comparing fixes nothing, so a test that
            // writes, copies or renames a file, or sets `UPDATE_EXPECT`,
            // lends no golden-file pin.
            if is_golden_file_comparison(&assertion.text)
                && (test_may_write_files(&test.body)
                    || index
                        .files()
                        .get(&test.file)
                        .is_none_or(|facts| file_renames_fs_or_env_import(&facts.source)))
            {
                return false;
            }
            let Some(call) = self.awaited_call_shape(&expect_operands[0], &self.name) else {
                return false;
            };
            (
                call,
                expect_operands[1].as_str(),
                Some(expect_operands[0].as_str()),
            )
        } else if !is_guard && self.returns_bool && is_plain_macro(&assertion.text, "assert") {
            // `assert!(owner(..))` is `assert_eq!(owner(..), true)` and
            // `assert!(!owner(..))` is `assert_eq!(owner(..), false)`. The
            // message arguments never decide whether the test fails.
            let Some(text) = outer_assertion_condition(&assertion.text) else {
                return false;
            };
            condition = text;
            let operand = condition.trim();
            let (operand, expected) = match operand.strip_prefix('!') {
                Some(negated) => (negated.trim_start(), "false"),
                None => (operand, "true"),
            };
            let Some(call) = self.awaited_call_shape(operand, &self.name) else {
                return false;
            };
            (call, expected, Some(operand))
        } else {
            return false;
        };
        if !syntax.admits(test, assertion, index) {
            return false;
        }
        // The assertion must be the test's own, or an assertion the
        // shared admission borrows from a test-local check helper the test
        // calls eagerly (#6482). A harness trial's body is only its
        // registration, and an assertion attributed to it from anywhere else
        // sees bindings that are not in it.
        let loan = syntax.helper_loan(test, assertion, index);
        let loaned = loan.as_ref().map(|loan| loan.helper.clone());
        let in_body = (test.start_line..=test.end_line).contains(&assertion.line);
        if in_body == loaned.is_some() {
            return false;
        }
        // A substituted pin reads both operands in the test's own scope, so
        // the gates below treat it as the test's assertion, not the helper's.
        let helper = loaned.filter(|_| substituted.is_none());
        // #6578 review: a borrowed helper assertion compares the helper's
        // parameters, which the test may fill from a fixture that calls the
        // owner (`check(want)` with `#[fixture] fn want() { weight(4) }`).
        // The expected-operand scan below reads the test's names, not the
        // helper's, so a test with a fixture lends no helper assertion.
        if helper.is_some()
            && fixture_parameters(test, &mask_comments_and_strings(&test.body))
                .is_none_or(|fixtures| !fixtures.is_empty())
        {
            return false;
        }
        // SPEC-0225 example 5: resolve only the adjacent, immutable,
        // once-used literal binding in this test's own block. Helpers keep
        // their own scope, and every existing literal/owner gate below still
        // checks the initializer rather than trusting its identifier.
        let expected_literal = if matches!(self.path, ReturnPathGate::WholeValueField(_))
            && is_plain_identifier(expected.trim())
        {
            if !reads_assert_eq || helper.is_some() {
                return false;
            }
            let Some(literal) =
                expected_binding::expected_literal_binding(test, assertion, expected)
            else {
                return false;
            };
            Some(literal)
        } else if let ReturnPathGate::WholeValueField(gate) = &self.path
            && reads_assert_eq
            && helper.is_none()
            && let Some(literal) =
                expected_binding::expected_item_literal(index, expected, &gate.type_name)
        {
            // SPEC-0225 decision 7: `expected()` and `T { .., ..T::default() }`
            // read as the one literal each stands for; the gates below check
            // that literal.
            Some(literal)
        } else {
            None
        };
        let expected = match &expected_literal {
            Some(literal) => literal.as_str(),
            None => expected,
        };
        let wrapped_expected;
        let expected = match (unwrapped, unwrap_wrapper) {
            (true, Some(wrapper)) => {
                wrapped_expected = format!("{wrapper}({expected})");
                wrapped_expected.as_str()
            }
            (true, None) => return false,
            (false, _) => expected,
        };
        // #8097: an expected operand read from a file the test itself may
        // write fixes nothing: the test rewrites the golden from the owner
        // before comparing, so every mutant of the owner survives.
        // Fail-closed like the neighbouring golden guard: unknown file
        // facts cannot prove the import set is rename-free.
        let renamed_fs_import = index
            .files()
            .get(&test.file)
            .is_none_or(|facts| file_renames_fs_or_env_import(&facts.source));
        if expected_reads_written_file(test, renamed_fs_import, expected) {
            return false;
        }
        // `assert_eq!(f(4), f(2) + f(2))` compares the owner with itself.
        if expected_reaches_owner(test, &assertion.text, expected, &self.name)
            || expected_reaches_fixture(test, expected)
            || expected_constant_reaches_owner(
                index,
                test,
                expected,
                &self.name,
                &self.call,
                &self.owner_file,
            )
        {
            return false;
        }
        match (&self.path, call) {
            // #6692: the clone must be compared with its own receiver, and
            // the test's file must not import some other `Clone`.
            // The receiver's type is read from the test's own bindings,
            // which do not bind a helper's parameters.
            (ReturnPathGate::CloneReceiver, _) if helper.is_some() => return false,
            (ReturnPathGate::CloneReceiver, CallShape::Method(receiver)) => {
                let independent = match &self.call {
                    PinCall::Method { receivers, .. } => receivers.iter().any(|receiver_type| {
                        matches!(receiver_type, ReceiverType::Named(type_name)
                            if clone_receiver_is_independent(test, receiver, type_name, index))
                    }),
                    PinCall::Bare | PinCall::Associated { .. } => false,
                };
                if expected.trim() != receiver
                    || imports_foreign(&test.file, "Clone")
                    || !independent
                {
                    return false;
                }
            }
            (
                ReturnPathGate::CloneReceiver,
                CallShape::Bare | CallShape::Path(_) | CallShape::Associated(_),
            ) => return false,
            (path, _) => {
                if !path.admits(expected) {
                    return false;
                }
                // RIPR-SPEC-0265 rule 2: the pinned call must run the
                // closure at least once.
                if let ReturnPathGate::Adaptor { position } = path
                    && !call_text.is_some_and(|text| {
                        closure_adaptor::pinned_call_runs_closure(
                            test,
                            loan.as_ref(),
                            text,
                            &self.name,
                            *position,
                        )
                    })
                {
                    return false;
                }
                // RIPR-SPEC-0197 rule 3: a short-circuit tail pins only on a
                // call that evaluates every operand.
                if let ReturnPathGate::ShortCircuit(chain) = path
                    && !call_text.is_some_and(|text| {
                        chain.pinned_call_evaluates_every_operand(
                            test,
                            loan.as_ref(),
                            text,
                            assertion.line,
                            &self.name,
                        )
                    })
                {
                    return false;
                }
                // The expected `Err(..)` / `Ok(..)` / `Some(..)` / `None`
                // resolves in the test's scope: a test-local `fn Err`
                // returning `Ok` passes the pin without the changed return
                // (#7712 review). Opaque globs do not count here; see
                // `source_declares_value_name`.
                if ["Some", "None", "Ok", "Err"].iter().any(|name| {
                    starts_with_word(expected.trim(), name)
                        && (index
                            .files()
                            .get(&test.file)
                            .is_none_or(|facts| source_declares_value_name(&facts.source, name))
                            || doctest
                                .is_some_and(|source| source_declares_value_name(source, name)))
                }) {
                    return false;
                }
            }
        }
        // The expected literal's bare name must reach the workspace type in
        // the test's file too (`use external::Config;` there makes it another).
        if let ReturnPathGate::WholeValueField(gate) = &self.path
            && (index.files().get(&test.file).is_none_or(|facts| {
                declaring_file_rebinds(&facts.source, &gate.type_name, true, index)
            }) || doctest
                .is_some_and(|source| declaring_file_rebinds(source, &gate.type_name, true, index)))
        {
            return false;
        }
        // #7063: the same for the expected variant's enum.
        if let ReturnPathGate::ErrVariant { qualifier, .. } = &self.path
            && index
                .files()
                .get(&test.file)
                .is_none_or(|facts| declaring_file_rebinds(&facts.source, qualifier, true, index))
        {
            return false;
        }
        // #6648 (RIPR-SPEC-0279): a doc example reaches the owner only by a
        // free call through the library's import name. A method or
        // associated call types its receiver from file scopes, and a rival
        // owner settles in the holding file's scopes; neither is the
        // example's, so both refuse.
        if doctest.is_some()
            && (self.identity.is_some()
                || !matches!(
                    (&self.call, &call),
                    (PinCall::Bare, CallShape::Bare | CallShape::Path(_))
                ))
        {
            return false;
        }
        let test_source = doctest.or_else(|| {
            index
                .files()
                .get(&test.file)
                .map(|facts| facts.data().source.as_ref())
        });
        // The single-file exemption resolves the owner's enclosing module
        // in the test file's own parse (#6957), while the parent-chain walk
        // resolves it in whichever chain file holds the owner (#6950); a
        // cross-file owner keeps the fail-closed single-file check.
        let owner_scope =
            OwnerScope::new(self.name.as_str(), self.owner_start_line, &self.owner_file);
        let masked_body = mask_comments_and_strings(&test.body);
        match (&self.call, call) {
            // #7082: a cfg on the owner or an enclosing module may compile
            // a same-named `static`, `const` or `use` in its place, which
            // the bare name then reaches instead.
            (PinCall::Bare, CallShape::Bare) => {
                !syntax
                    .item_nesting(index, &self.owner_file, &self.name, self.owner_start_line)
                    .is_none_or(|owner| owner.cfg_gated)
                    && !syntax.file_cfg_gated(index, &self.owner_file)
                    // #6544: among same-named rivals, the asserted bare call
                    // itself must name the owner, resolved in the test's
                    // scopes; another call elsewhere in the test that names
                    // the owner lends this one nothing. A helper's call sits
                    // in the helper's scopes, which this does not read.
                    && self.identity.as_ref().is_none_or(|identity| {
                        helper.is_none() && identity.resolve_call(test, index, &[]) == CallTarget::Owner
                    })
                    && !test_body_shadows_owner(test, &self.name)
                    && !binds_outside_let(&masked_body, &self.name)
                    && !bound_by_macro(&masked_body, &self.name)
                    && helper.as_deref().is_none_or(|helper| {
                        helper_pins_owner_call(helper, &masked_body, &self.name)
                    })
                    && test_source.is_some_and(|source| {
                        !file_renames_to(source, &self.name)
                            && self.bare_call_reaches_owner(test, source, index, syntax)
                    })
            }
            // As for the clone receiver: a helper's parameters are not the
            // test's bindings.
            (PinCall::Method { .. }, _) if helper.is_some() => false,
            // #6974: a path names the owner without the bare name's scope,
            // so a test-local binding of the name cannot capture it; the
            // path itself must reach the owner.
            (PinCall::Bare, CallShape::Path(prefix)) => {
                helper.is_none()
                    && self.identity.as_ref().is_none_or(|identity| {
                        identity.resolve_call(test, index, &path_prefix_segments(prefix))
                            == CallTarget::Owner
                    })
                    && test_source.is_some_and(|source| {
                        self.path_reaches_owner(prefix, test, source, index, syntax)
                    })
            }
            (
                PinCall::Method {
                    receivers,
                    trait_scope,
                },
                CallShape::Method(_) | CallShape::Constructed(_),
            ) => {
                let receiver_type = match call {
                    CallShape::Method(receiver) => {
                        if bound_by_macro(&masked_body, receiver) {
                            return false;
                        }
                        test_receiver_type(
                            test,
                            receiver,
                            test_source,
                            index,
                            imports_foreign,
                            owner_scope,
                            syntax,
                        )
                    }
                    // An inline constructor types the receiver the same way
                    // a `let receiver = Type::constructor(..);` binding does.
                    CallShape::Constructed(receiver) => binding_type(
                        &format!("= {receiver}"),
                        test,
                        test_source,
                        index,
                        imports_foreign,
                        owner_scope,
                        syntax,
                    ),
                    CallShape::Bare | CallShape::Path(_) | CallShape::Associated(_) => None,
                };
                let Some(receiver_type) = receiver_type else {
                    return false;
                };
                if !receivers.contains(&receiver_type) {
                    return false;
                }
                let shadowed_by_std = match &receiver_type {
                    ReceiverType::ByteSlice => BYTE_SLICE_METHODS.contains(&self.name.as_str()),
                    ReceiverType::Named(_) => {
                        BY_VALUE_PRELUDE_METHODS.contains(&self.name.as_str())
                    }
                };
                !shadowed_by_std
                    && trait_scope.as_ref().is_none_or(|scope| {
                        self.trait_in_scope(test, test_source, &scope.trait_name, index)
                    })
            }
            // #6617: `T::name(..)` names the owner only through the owner's
            // own `T`. A module path `a::b::name(..)` is `CallShape::Path`
            // (its segments are never CamelCase), so it never reaches here.
            //
            // A cfg on the owner, its `impl`, an enclosing module or its file
            // may drop it from the build, and `T::name` then reaches a trait
            // default the index never sees (#7082, #7724).
            (PinCall::Associated { type_name }, CallShape::Associated(named)) => {
                helper.is_none()
                    && named == type_name
                    && index
                        .files()
                        .get(&self.owner_file)
                        .and_then(|facts| {
                            item_nesting_with_impl(
                                &facts.source,
                                &self.name,
                                self.owner_start_line,
                                true,
                            )
                        })
                        .is_some_and(|owner| !owner.cfg_gated)
                    && !syntax.file_cfg_gated(index, &self.owner_file)
                    && !bound_by_macro(&masked_body, type_name)
                    && !body_rebinds_type(&masked_body, type_name)
                    && test_source.is_some_and(|source| {
                        self.associated_type_reaches_owner(type_name, test, source, index, syntax)
                    })
            }
            _ => false,
        }
    }

    fn binding(&self) -> FreeOwnerBinding<'_> {
        FreeOwnerBinding {
            name: &self.name,
            owner_file: &self.owner_file,
            owner_start_line: self.owner_start_line,
        }
    }

    fn path_reaches_owner(
        &self,
        prefix: &str,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        self.binding()
            .path_reaches_owner(prefix, test, test_source, index, syntax)
    }

    fn bare_call_reaches_owner(
        &self,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        self.binding()
            .bare_call_reaches_owner(test, test_source, index, syntax)
    }

    /// #6617 (RIPR-SPEC-0172): whether a top-level test's `T::name(..)`
    /// names the owner's own `T`. The owner-side gate already made `T` the
    /// one workspace type of that name, with no `mod`, `trait` or `type` of
    /// it and no competing path-callable `fn name`. Here the test's file
    /// must import `T` directly, `use <krate>::T;`, at file level,
    /// where `<krate>` names the owner's library from the test's crate (the
    /// RIPR-SPEC-0197 manifest authority) and nothing in the test's crate
    /// binds it, and the library must not export another `T`. Every `use`
    /// of the file that names `T` must be such an import: an alias (`as`),
    /// a glob, a brace list or another root refuses, and so does a
    /// declaration of `T` in the test's file. Any doubt refuses.
    fn associated_type_reaches_owner(
        &self,
        type_name: &str,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        // Only file-level imports reach a test at the file's top level.
        if syntax
            .item_nesting(index, &test.file, &test.name, test.start_line)
            .is_none_or(|nesting| !nesting.modules.is_empty())
        {
            return false;
        }
        if file_renames_to(test_source, type_name) || file_aliases_type(test_source, type_name) {
            return false;
        }
        let masked = mask_comments_and_strings(test_source);
        let declares_name = ["struct", "enum", "union", "trait", "mod"]
            .iter()
            .any(|keyword| {
                whole_word_offsets(&masked, keyword)
                    .into_iter()
                    .any(|offset| {
                        starts_with_word(masked[offset + keyword.len()..].trim_start(), type_name)
                    })
            });
        if declares_name {
            return false;
        }
        let file_level = file_use_statements(&super::related_tests::file_level_use_text(&masked));
        if !file_level
            .iter()
            .any(|statement| contains_as_whole_word(statement, type_name))
        {
            return false;
        }
        let binding = self.binding();
        let imports_owner_type = |statement: &String| {
            let Some(path) = statement.trim_start().strip_prefix("use") else {
                return false;
            };
            let path = path.trim();
            let path = path.strip_prefix("::").map_or(path, str::trim_start);
            if path.contains(['{', '}', '*']) || !whole_word_offsets(path, "as").is_empty() {
                return false;
            }
            // Only `use <krate>::T;`: a middle segment can be a `pub use`
            // of another crate (`pub use other as fs;`), whose own `T` this
            // check cannot place.
            let segments: Vec<&str> = path.split("::").map(str::trim).collect();
            let [root, last] = segments[..] else {
                return false;
            };
            last == type_name
                && is_plain_identifier(root)
                && binding.krate_root_names_owner_crate(root, &test.file, test_source, index)
                && !test_crate_binds_root(test, root, index, syntax)
        };
        if !file_use_statements(test_source)
            .iter()
            .filter(|statement| contains_as_whole_word(statement, type_name))
            .all(imports_owner_type)
        {
            return false;
        }
        syntax
            .target_roots(index)
            .root(&self.owner_file, index)
            .is_some_and(|owner_root| !library_may_export_other(index, &owner_root, type_name))
    }

    fn trait_in_scope(
        &self,
        test: &TestSummary,
        test_source: Option<&str>,
        trait_name: &str,
        index: &RustIndex,
    ) -> bool {
        let Some(source) = test_source else {
            return false;
        };
        if let Some(known) = self.trait_scope_by_file.borrow().get(&test.file) {
            return *known;
        }
        let in_scope = trait_in_scope(source, trait_name, index);
        self.trait_scope_by_file
            .borrow_mut()
            .insert(test.file.clone(), in_scope);
        in_scope
    }
}

/// Identity-only view shared by return pins and targeted owner selection.
/// It carries no return-value probe, expected-value oracle or pin credit.
struct FreeOwnerBinding<'a> {
    name: &'a String,
    owner_file: &'a PathBuf,
    owner_start_line: usize,
}

impl FreeOwnerBinding<'_> {
    /// #6974: whether `prefix::name` can only name the owner. The path must
    /// resolve to exactly the module that declares the owner. An explicit
    /// `fn` there takes the value name from every glob, and any other item
    /// of the name in the same module fails to compile, so a rename, a
    /// re-export or a type elsewhere cannot capture the path. The path is:
    /// - `self::`/`super::` from a test in the owner's own file, resolved
    ///   from the test's inline modules without leaving the file;
    /// - `crate::` from a test that composes under the owner's crate root,
    ///   when the owner's file is that root; or
    /// - an import name of the owner's library from the test's crate
    ///   manifest (`krate::name(..)` in an integration test) that nothing
    ///   renames or binds in the test's crate, when the owner's file is the
    ///   library root.
    ///
    /// Any `r#name` in the workspace (a raw twin the name match misses) and
    /// a macro invocation naming the owner in its crate (it may emit a
    /// twin under another cfg) fail closed.
    fn path_reaches_owner(
        &self,
        prefix: &str,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let key = (
            (*self.owner_file).clone(),
            self.owner_start_line,
            (*self.name).clone(),
            prefix.to_string(),
            test.file.clone(),
            test.start_line,
        );
        if let Some(known) = syntax.path_memo.borrow().verdicts.get(&key) {
            return *known;
        }
        let verdict = self.path_reaches_owner_uncached(prefix, test, test_source, index, syntax);
        syntax.path_memo.borrow_mut().verdicts.insert(key, verdict);
        verdict
    }

    fn path_reaches_owner_uncached(
        &self,
        prefix: &str,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let segments: Vec<&str> = prefix.split("::").collect();
        let Some((root, rest)) = segments.split_first() else {
            return false;
        };
        // #6648 (RIPR-SPEC-0279): in a doc example `crate`, `self` and
        // `super` name the example's own crate, never the library.
        if index.doctest_source(test).is_some() && matches!(*root, "self" | "super" | "crate") {
            return false;
        }
        let roots = syntax.target_roots(index);
        let Some(owner_root) = roots.root(self.owner_file, index) else {
            return false;
        };
        let owner_is_root = *self.owner_file == owner_root;
        let mut module = match *root {
            "self" | "super" => {
                if test.file != *self.owner_file {
                    return false;
                }
                let Some(ItemNesting {
                    modules: mut module,
                    ..
                }) = syntax.item_nesting(index, &test.file, &test.name, test.start_line)
                else {
                    return false;
                };
                if *root == "super" && module.pop().is_none() {
                    return false;
                }
                module
            }
            "crate" => {
                if !owner_is_root || roots.root(&test.file, index).as_ref() != Some(&owner_root) {
                    return false;
                }
                Vec::new()
            }
            _ => {
                if !owner_is_root
                    || !self.library_root_names_owner(root, test, test_source, index, syntax)
                {
                    return false;
                }
                Vec::new()
            }
        };
        let leading_supers = rest
            .iter()
            .take_while(|segment| **segment == "super")
            .count();
        if leading_supers > 0 && !matches!(*root, "self" | "super") {
            return false;
        }
        for _ in 0..leading_supers {
            if module.pop().is_none() {
                return false;
            }
        }
        for segment in &rest[leading_supers..] {
            if matches!(*segment, "self" | "super" | "crate") {
                return false;
            }
            module.push((*segment).to_string());
        }
        syntax
            .item_nesting(index, self.owner_file, self.name, self.owner_start_line)
            .is_some_and(|owner| !owner.cfg_gated && owner.modules == module)
            && !syntax.file_cfg_gated(index, self.owner_file)
            && !syntax.crate_may_hide_name(index, &owner_root, self.name, roots)
    }

    /// #6974: whether `root::` in `test` names the owner's library: an
    /// import name of it in the test crate's manifest that no workspace
    /// file renames another item to and the test's crate does not bind.
    fn library_root_names_owner(
        &self,
        root: &str,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let roots = syntax.target_roots(index);
        let Some(owner_root) = roots.root(self.owner_file, index) else {
            return false;
        };
        if file_renames_to(test_source, root)
            || !index
                .member_crates
                .import_names(&test.file, &owner_root)
                .iter()
                .any(|import| import == root)
        {
            return false;
        }
        !test_crate_binds_root(test, root, index, syntax)
    }

    /// #7097: whether the test's bare `name(..)` can only reach the
    /// owner. The establish gate refused every other `fn` of the name, but
    /// a same-named `static`, `const`, tuple struct or `use` still takes a
    /// bare call: an item in the test's body or own module scope shadows
    /// every import, an explicit `use` must name the owner's own path, a
    /// glob must deliver the owner from a twin-free module, and with
    /// neither the test must sit beside the owner. Anything unplaced
    /// refuses.
    fn bare_call_reaches_owner(
        &self,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let key = (
            (*self.owner_file).clone(),
            self.owner_start_line,
            (*self.name).clone(),
            test.file.clone(),
            test.start_line,
        );
        if let Some(known) = syntax.bare_call_memo.borrow().get(&key) {
            return *known;
        }
        let verdict = self.bare_call_reaches_owner_uncached(test, test_source, index, syntax);
        syntax.bare_call_memo.borrow_mut().insert(key, verdict);
        verdict
    }

    fn bare_call_reaches_owner_uncached(
        &self,
        test: &TestSummary,
        test_source: &str,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let Some(owner_inline) = syntax
            .item_nesting(index, self.owner_file, self.name, self.owner_start_line)
            .map(|nesting| nesting.modules)
        else {
            return false;
        };
        if let Some(source) = index.doctest_source(test) {
            return self.doctest_bare_call_reaches_owner(
                test,
                source,
                &owner_inline,
                index,
                syntax,
            );
        }
        let Some(scopes) = syntax.file_scopes(index, &test.file) else {
            return false;
        };
        let Some(scope) = scopes.scope_of_test(test_source, test) else {
            return false;
        };
        // The body binds first: an item there shadows every import, an
        // explicit `use` there shadows the module scope, and a glob there
        // shadows the module scope too.
        if body_defines_value_twin(&test.body, self.name) {
            return false;
        }
        let body_uses = flattened_use_paths(&test.body);
        let (body_bindings, body_globs) = partition_name_uses(&body_uses, self.name);
        if !body_bindings.is_empty() {
            let context = ScopeContext {
                file: &test.file,
                source: test_source,
                stack: &scope.stack,
            };
            return body_bindings.len() == 1
                && self.use_names_owner(body_bindings[0], context, &owner_inline, index, syntax);
        }
        if !body_globs.is_empty() {
            let context = ScopeContext {
                file: &test.file,
                source: test_source,
                stack: &scope.stack,
            };
            return body_globs
                .iter()
                .all(|glob| self.glob_delivers_owner(glob, context, &owner_inline, index, syntax));
        }
        // The test's own module scope: a twin item takes the call from a
        // glob or lexical resolution, and an explicit `use` takes it from
        // a glob. Ancestor items are invisible without a glob, which the
        // glob rule below places.
        if scope.has_twin(self.name) {
            return false;
        }
        let (bindings, globs) = partition_name_uses(&scope.uses, self.name);
        if !bindings.is_empty() {
            let context = ScopeContext {
                file: &test.file,
                source: test_source,
                stack: &scope.stack,
            };
            return bindings.len() == 1
                && self.use_names_owner(bindings[0], context, &owner_inline, index, syntax);
        }
        if !globs.is_empty() {
            let context = ScopeContext {
                file: &test.file,
                source: test_source,
                stack: &scope.stack,
            };
            return globs
                .iter()
                .all(|glob| self.glob_delivers_owner(glob, context, &owner_inline, index, syntax));
        }
        // Neither: the owner is lexically visible only beside the test.
        // Anywhere else the bare name is unresolved, the prelude, or a
        // macro-emitted import ripr cannot see — never the owner.
        test.file == *self.owner_file && scope.stack == owner_inline
    }

    /// #6648 (RIPR-SPEC-0279): whether a doc example's bare `name(..)`
    /// can only reach the owner. The example is its own crate, so the name
    /// resolves only through the example's own `use`: exactly one binding
    /// `use <krate>::..::name;`, or globs `use <krate>::..::*;` that each
    /// deliver the owner, where `<krate>` is an import name of the owner's
    /// library (a local `mod` or rename of that name in the example is
    /// refused by the twin, rename and single-binding checks). A `crate`,
    /// `self` or `super` root names the example's crate, a twin item in the
    /// example takes the call, and with no `use` the name is not the
    /// owner's.
    fn doctest_bare_call_reaches_owner(
        &self,
        test: &TestSummary,
        source: &str,
        owner_inline: &[String],
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        if body_defines_value_twin(&test.body, self.name) {
            return false;
        }
        let uses = flattened_use_paths(&test.body);
        let (bindings, globs) = partition_name_uses(&uses, self.name);
        let library_rooted = |path: &str| {
            let stripped = path.strip_prefix("::").unwrap_or(path);
            let first = stripped.split("::").next().map_or("", strip_raw);
            !matches!(first, "" | "crate" | "self" | "super")
        };
        let context = ScopeContext {
            file: &test.file,
            source,
            stack: &[],
        };
        if let [binding] = bindings.as_slice() {
            return globs.is_empty()
                && library_rooted(&binding.path)
                && self.use_names_owner(binding, context, owner_inline, index, syntax);
        }
        bindings.is_empty()
            && !globs.is_empty()
            && globs.iter().all(|glob| {
                library_rooted(&glob.path)
                    && self.glob_delivers_owner(glob, context, owner_inline, index, syntax)
            })
    }

    /// #7097: whether the binding `use_path` delivers the owner to
    /// `scope`: its module prefix resolves, and that module holds the
    /// owner with no twin — the owner itself, or one `use` hop
    /// re-exporting it. A twin's path, a foreign crate, a bare crate
    /// name, a renamed root, or a re-export chain past one hop refuses.
    fn use_names_owner(
        &self,
        use_path: &UsePath,
        scope: ScopeContext<'_>,
        owner_inline: &[String],
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let Some((first, middle)) = split_binding_use(use_path, self.name) else {
            return false;
        };
        let Some((target_file, target_stack)) =
            self.resolve_use_prefix(first, &middle, scope, index, syntax)
        else {
            return false;
        };
        self.resolved_module_delivers_owner(target_file, target_stack, owner_inline, index, syntax)
    }

    /// #7097: whether the binding `use_path` resolves exactly to the
    /// owner's module from `scope`: no re-export hop, so one-hop
    /// transport and twin checks end here and import cycles cannot
    /// recurse.
    fn use_resolves_to_owner_module(
        &self,
        use_path: &UsePath,
        scope: ScopeContext<'_>,
        owner_inline: &[String],
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let Some((first, middle)) = split_binding_use(use_path, self.name) else {
            return false;
        };
        self.resolve_use_prefix(first, &middle, scope, index, syntax)
            .is_some_and(|(file, stack)| {
                file == *self.owner_file && stack.as_slice() == owner_inline
            })
    }

    /// #7097: resolve a `use` path's module prefix to its (file, inline
    /// stack): `self`/`super` walk from the scope, `crate` and the
    /// owner's library crate name walk from the owner's crate root, each
    /// step an inline child module or a composed out-of-line `mod`.
    /// `None` when a step is foreign, renamed, ambiguous, or unplaced.
    fn resolve_use_prefix(
        &self,
        first: &str,
        segments: &[&str],
        scope: ScopeContext<'_>,
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> Option<(PathBuf, Vec<String>)> {
        match first {
            "self" | "super" => {
                let (file, stack, rest) = pop_super_across_files(
                    index,
                    syntax,
                    scope.file,
                    scope.stack,
                    first,
                    segments,
                )?;
                resolve_module_path(index, syntax, &file, &stack, &rest)
            }
            "crate" => {
                let root = composed_root(self.owner_file, index);
                if composed_root(scope.file, index) != root {
                    return None;
                }
                resolve_module_path(index, syntax, &root, &[], segments)
            }
            _ => {
                if !self.krate_root_names_owner_crate(first, scope.file, scope.source, index) {
                    return None;
                }
                let root = composed_root(self.owner_file, index);
                resolve_module_path(index, syntax, &root, &[], segments)
            }
        }
    }

    /// #7097: whether a resolved module delivers the owner: it holds no
    /// twin of the name, and either is the owner's own module or
    /// transports one `use` resolving exactly to it.
    fn resolved_module_delivers_owner(
        &self,
        target_file: PathBuf,
        target_stack: Vec<String>,
        owner_inline: &[String],
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let Some(target_source) = index
            .files()
            .get(&target_file)
            .map(|facts| facts.data().source.clone())
        else {
            return false;
        };
        let Some(target_scopes) = syntax.file_scopes(index, &target_file) else {
            return false;
        };
        let Some(target) = target_scopes.scope_with_stack(&target_stack) else {
            return false;
        };
        if self.scope_has_twin_binding(
            target,
            &target_file,
            &target_source,
            owner_inline,
            index,
            syntax,
        ) {
            return false;
        }
        if target_file == *self.owner_file && target_stack.as_slice() == owner_inline {
            return true;
        }
        let context = ScopeContext {
            file: &target_file,
            source: &target_source,
            stack: &target.stack,
        };
        let (transports, _) = partition_name_uses(&target.uses, self.name);
        transports.iter().any(|transport| {
            self.use_resolves_to_owner_module(transport, context, owner_inline, index, syntax)
        })
    }

    /// #7097: whether the glob `use_path` (`*`-terminated) delivers
    /// the owner's binding to `scope`: its target module resolves and
    /// holds the owner with no twin — the owner itself, or one `use` hop
    /// re-exporting it. An unplaced glob refuses: it may import a twin,
    /// and it can never import the workspace owner from a foreign crate.
    fn glob_delivers_owner(
        &self,
        use_path: &UsePath,
        scope: ScopeContext<'_>,
        owner_inline: &[String],
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        let Some((first, prefix)) = split_glob_prefix(&use_path.path) else {
            return false;
        };
        let Some((target_file, target_stack)) =
            self.resolve_use_prefix(first, &prefix, scope, index, syntax)
        else {
            return false;
        };
        self.resolved_module_delivers_owner(target_file, target_stack, owner_inline, index, syntax)
    }

    /// #7097: whether the first segment of a `use` path names the owner's
    /// library crate from `scope_file`'s crate: a manifest import name, or
    /// — in synthetic indexes without manifest authority — a workspace
    /// package name. A rename to the segment refuses.
    fn krate_root_names_owner_crate(
        &self,
        first: &str,
        scope_file: &Path,
        scope_source: &str,
        index: &RustIndex,
    ) -> bool {
        if first.is_empty() || file_renames_to(scope_source, first) {
            return false;
        }
        let owner_root = composed_root(self.owner_file, index);
        if index
            .member_crates
            .import_names(scope_file, &owner_root)
            .iter()
            .any(|name| name == first)
        {
            return true;
        }
        !index.member_crates.has_manifest_root() && crate_names_package(first, &index.package_names)
    }

    /// #7097: whether `scope` binds the owner's name to anything but the
    /// owner: a twin item or macro, or a `use` resolving anywhere but
    /// the owner's module. Globs need no hop here: a further glob only
    /// matters beside an owner binding (an ambiguity error either way)
    /// or without one (already refused).
    fn scope_has_twin_binding(
        &self,
        scope: &ModuleScope,
        scope_file: &Path,
        scope_source: &str,
        owner_inline: &[String],
        index: &RustIndex,
        syntax: &OwnerPinSyntax,
    ) -> bool {
        if scope.has_twin(self.name) {
            return true;
        }
        let context = ScopeContext {
            file: scope_file,
            source: scope_source,
            stack: &scope.stack,
        };
        let (bindings, _) = partition_name_uses(&scope.uses, self.name);
        bindings.iter().any(|binding| {
            !self.use_resolves_to_owner_module(binding, context, owner_inline, index, syntax)
        })
    }
}

/// The bare-call identity gates applied to a borrowed check helper (#6482):
/// the helper binds the owner's name nowhere (parameter, `let`, pattern,
/// closure, nested `fn` or macro), and the calling test never names the
/// owner, so no call-site argument can feed the owner's own value back in
/// as the expected one (`check(4, weight(4))`).
pub(in crate::analysis) fn helper_pins_owner_call(
    helper: &str,
    masked_test_body: &str,
    name: &str,
) -> bool {
    let masked = mask_comments_and_strings(helper);
    !binds_outside_let(&masked, name)
        && !bound_by_macro(&masked, name)
        && !test_body_defines_callee_fn(&masked, name)
        && test_body_let_shadow_line(&masked, name).is_none()
        && !contains_as_whole_word(masked_test_body, name)
        && whole_word_count(&masked, name) == 1
}

/// How often `name` occurs as a whole identifier in `text`. A helper that
/// names the owner anywhere besides its asserted call (`let e = owner(b);`,
/// `let f = owner;`, `super::owner(b)`) may compare the owner with itself,
/// and the test-body self-comparison scan never reads the helper.
fn whole_word_count(text: &str, name: &str) -> usize {
    let is_ident = |ch: Option<char>| ch.is_some_and(|ch| ch.is_alphanumeric() || ch == '_');
    text.match_indices(name)
        .filter(|(at, found)| {
            !is_ident(text[..*at].chars().next_back())
                && !is_ident(text[at + found.len()..].chars().next())
        })
        .count()
}

/// How a test calls `owner`: a bare call for a free function, a method call
/// on a receiver of one of the owner's `impl` types, or `T::name(..)` for an
/// associated function of an inherent `impl T` (#6617). `None` for a shape
/// no pin reads (a trait or trait-impl associated function, a generic or
/// ambiguous self type, a free fn with `self`).
fn pin_call(owner: &FunctionSummary, index: &RustIndex) -> Option<PinCall> {
    Some(match (&owner.item.container, owner.item.has_self_param) {
        (FunctionContainer::Free, false) => PinCall::Bare,
        (FunctionContainer::Inherent { self_ty }, false) => PinCall::Associated {
            type_name: associated_owner_type(self_ty, index)?,
        },
        (FunctionContainer::Inherent { self_ty }, true) => PinCall::Method {
            receivers: vec![declared_receiver(self_ty, index)?],
            trait_scope: None,
        },
        (
            FunctionContainer::TraitImpl {
                trait_path,
                self_ty,
            },
            true,
        ) => PinCall::Method {
            receivers: vec![declared_receiver(self_ty, index)?],
            trait_scope: Some(TraitScope {
                trait_name: path_base_name(trait_path)?.to_string(),
            }),
        },
        (FunctionContainer::Trait { trait_name }, true) => {
            let receivers = trait_impl_receivers(trait_name, index);
            if receivers.is_empty() {
                return None;
            }
            PinCall::Method {
                receivers,
                trait_scope: Some(TraitScope {
                    trait_name: trait_name.clone(),
                }),
            }
        }
        _ => return None,
    })
}

impl ReturnPathGate {
    /// The prelude variant names this gate's exit reasoning relies on.
    fn prelude_names(&self) -> &'static [&'static str] {
        match self {
            Self::EarlyHead("Some") => &["Some", "None"],
            Self::EarlyHead(_) | Self::Head("Err") | Self::ErrVariant { .. } => &["Ok", "Err"],
            _ => &[],
        }
    }

    fn admits(&self, expected: &str) -> bool {
        match self {
            Self::Any | Self::Adaptor { .. } | Self::ShortCircuit(_) => true,
            Self::Head(head) | Self::EarlyHead(head) => {
                constructor_call_span(expected.trim(), head).is_some()
            }
            Self::Exact(value) => expected.trim() == *value,
            Self::ErrVariant {
                qualifier, variant, ..
            } => {
                constructor_call_span(expected.trim(), "Err").is_some()
                    && error_variant_key(expected.trim())
                        .is_some_and(|(q, v)| q == *qualifier && v == *variant)
            }
            Self::CloneReceiver => false,
            Self::WholeValueField(gate) => gate.admits(expected),
        }
    }
}

/// The module segments of a `CallShape::Path` prefix, which
/// `path_call_prefix` admits only as `::`-separated plain identifiers.
fn path_prefix_segments(prefix: &str) -> Vec<String> {
    prefix
        .split("::")
        .map(|segment| segment.trim().to_string())
        .collect()
}

#[derive(Clone, Copy)]
enum CallShape<'a> {
    Bare,
    Method(&'a str),
    /// `Type::constructor(..).name(..)`: the receiver is built inline.
    Constructed(&'a str),
    /// `a::b::name(..)`: a free-function call through a module path of
    /// plain identifiers; holds the path before `::name` (#6974).
    Path(&'a str),
    /// `T::name(..)` with one CamelCase identifier `T` (#6617): an
    /// associated-function call; holds `T`. A module path never has a
    /// CamelCase segment ([`path_call_prefix`]), so the two never overlap.
    Associated(&'a str),
}

/// Whether `owner` is declared `async fn`, read from the parsed `async`
/// token of the one `fn <name>` item whose span holds the owner's start
/// line. No parse, or no single match, reads as sync: an async owner then
/// gets no `.await` credit, and its bare call (a future) does not compile.
fn declares_async(owner: &FunctionSummary, index: &RustIndex) -> bool {
    let Some(facts) = index.files().get(&owner.file) else {
        return false;
    };
    let source: &str = &facts.source;
    let Some(parse) = parse_clean_source_file(source) else {
        return false;
    };
    let line_of = |offset: ra_ap_syntax::TextSize| {
        let at = (u32::from(offset) as usize).min(source.len());
        source.as_bytes()[..at]
            .iter()
            .filter(|byte| **byte == b'\n')
            .count()
            + 1
    };
    let mut matches = parse
        .tree()
        .syntax()
        .descendants()
        .filter_map(ast::Fn::cast)
        .filter(|function| {
            function
                .name()
                .is_some_and(|name| name.text() == owner.name.as_str())
        })
        .filter(|function| {
            let Some(fn_token) = function.fn_token() else {
                return false;
            };
            (line_of(function.syntax().text_range().start())
                ..=line_of(fn_token.text_range().start()))
                .contains(&owner.start_line)
        });
    match (matches.next(), matches.next()) {
        (Some(function), None) => function.async_token().is_some(),
        _ => false,
    }
}

/// The operand as a complete call of `name`: `name(..)` or `recv.name(..)`
/// with a plain identifier receiver and nothing chained after the call.
fn owner_call_shape<'a>(operand: &'a str, name: &str) -> Option<CallShape<'a>> {
    let operand = operand.trim();
    if let Some(inner) = unsafe_block_value(operand) {
        return owner_call_shape(inner, name);
    }
    if let Some(receiver) = constructed_receiver(operand, name) {
        let call_start = receiver.len() + 1;
        let masked = mask_comments_and_strings(operand);
        let closing = matching_close(&masked, call_start + name.len(), b'(', b')')?;
        return operand[closing + 1..]
            .trim()
            .is_empty()
            .then_some(CallShape::Constructed(receiver));
    }
    if let Some(prefix) = path_call_prefix(operand, name) {
        let opening = prefix.len() + "::".len() + name.len();
        let masked = mask_comments_and_strings(operand);
        let closing = matching_close(&masked, opening, b'(', b')')?;
        return operand[closing + 1..]
            .trim()
            .is_empty()
            .then_some(CallShape::Path(prefix));
    }
    if let Some(type_name) = associated_call_type(operand, name) {
        let opening = type_name.len() + "::".len() + name.len();
        let masked = mask_comments_and_strings(operand);
        let closing = matching_close(&masked, opening, b'(', b')')?;
        return operand[closing + 1..]
            .trim()
            .is_empty()
            .then_some(CallShape::Associated(type_name));
    }
    let call_start = if operand.starts_with(name) {
        0
    } else {
        let dot = operand.find('.')?;
        let receiver = &operand[..dot];
        if !is_plain_identifier(receiver) || receiver == "self" {
            return None;
        }
        if !operand[dot + 1..].starts_with(name) {
            return None;
        }
        dot + 1
    };
    let after_name = &operand[call_start + name.len()..];
    if !after_name.starts_with('(') {
        return None;
    }
    let masked = mask_comments_and_strings(operand);
    let opening = call_start + name.len();
    let closing = matching_close(&masked, opening, b'(', b')')?;
    if !operand[closing + 1..].trim().is_empty() {
        return None;
    }
    Some(if call_start == 0 {
        CallShape::Bare
    } else {
        CallShape::Method(&operand[..call_start - 1])
    })
}

/// RIPR-SPEC-0225 rule 1: the initializer of the local binding an operand
/// names, which the caller then reads as the owner call (or, under decision
/// 6, its `.unwrap()`). The operand is a plain name that the test binds
/// once, with `let name = <init>;` (an optional type annotation, never `mut`),
/// and mentions nowhere else: any other use could borrow it mutably,
/// shadow it, write through it or copy a field of it into the expected
/// value. A macro that may bind the name refuses it too.
fn bound_owner_initializer<'a>(
    test: &'a TestSummary,
    operand: &str,
    owner: &str,
) -> Option<&'a str> {
    let name = operand.trim();
    if !is_plain_identifier(name) || name == owner {
        return None;
    }
    let masked = mask_comments_and_strings(&test.body);
    let uses = whole_word_offsets(&masked, name);
    let [first_use, _] = uses[..] else {
        return None;
    };
    if bound_by_macro(&masked, name) {
        return None;
    }
    let mut bindings = whole_word_offsets(&masked, "let")
        .into_iter()
        .filter_map(|start| {
            // Only the test block's own statements: a `let` in an inner
            // block goes out of scope, and the operand may then name an
            // outer item.
            let before = &masked[..start];
            if before.matches('{').count() != before.matches('}').count() + 1 {
                return None;
            }
            // An attribute (`#[cfg(..)] let c = ..;`) may compile the
            // binding away, leaving the operand naming some outer item.
            if before.trim_end().ends_with(']') {
                return None;
            }
            // The binding is the name's first occurrence, so the
            // assertion's use comes after it, not before a shadowing `let`.
            let named = masked[start + 3..].trim_start();
            if masked.len() - named.len() != first_use {
                return None;
            }
            let rest = named.strip_prefix(name)?;
            if rest.starts_with(|ch: char| ch.is_ascii_alphanumeric() || ch == '_') {
                return None;
            }
            let rest = rest.trim_start();
            // `let c = ..` or `let c: T = ..`; a type cannot hold `=`.
            if !rest.starts_with(['=', ':']) {
                return None;
            }
            let equals = masked.len() - rest.len() + rest.find('=')?;
            if masked[equals + 1..].starts_with(['=', '>']) {
                return None;
            }
            let end = equals + masked[equals..].find(';')?;
            Some((equals, end))
        });
    let (Some((equals, end)), None) = (bindings.next(), bindings.next()) else {
        return None;
    };
    test.body.get(equals + 1..end)
}

/// RIPR-SPEC-0225 decision 6: the call `operand` unwraps, when it is
/// `<call>.unwrap()` or `<call>.expect("..")` with one plain string literal
/// message. Both panic on `Err`/`None`, so a passing comparison of the
/// unwrapped value reads the call's `Ok`/`Some` payload. `Result::unwrap`
/// and `Option::unwrap` are inherent, so no trait method can stand in.
fn unwrapped_call(operand: &str) -> Option<&str> {
    let operand = operand.trim();
    if let Some(call) = operand.strip_suffix(".unwrap()") {
        return Some(call.trim_end());
    }
    let (call, message) = operand.strip_suffix(')')?.rsplit_once(".expect(")?;
    let message = message.trim();
    let literal = message
        .strip_prefix('"')
        .and_then(|rest| rest.strip_suffix('"'))
        .is_some_and(|inner| !inner.contains(['"', '\\']));
    literal.then(|| call.trim_end())
}

/// #7063: the call `operand` unwraps the error of, when it is
/// `<call>.unwrap_err()` or `<call>.expect_err("..")` with one plain string
/// literal message. Both panic on `Ok`, so a passing comparison of the
/// unwrapped value reads the call's `Err` payload.
fn unwrapped_err_call(operand: &str) -> Option<&str> {
    let operand = operand.trim();
    if let Some(call) = operand.strip_suffix(".unwrap_err()") {
        return Some(call.trim_end());
    }
    let (call, message) = operand.strip_suffix(')')?.rsplit_once(".expect_err(")?;
    let message = message.trim();
    let literal = message
        .strip_prefix('"')
        .and_then(|rest| rest.strip_suffix('"'))
        .is_some_and(|inner| !inner.contains(['"', '\\']));
    literal.then(|| call.trim_end())
}

/// #6974: whether `test`'s crate (or the workspace) may bind `root` before
/// the extern prelude does: a rename to it, a raw twin, or a `mod`, `use`,
/// type or glob in the test's crate. An unplaced test crate binds.
fn test_crate_binds_root(
    test: &TestSummary,
    root: &str,
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
) -> bool {
    // #6648 (RIPR-SPEC-0279): a doc example is its own crate; only its
    // own source binds there.
    if let Some(source) = index.doctest_source(test) {
        return workspace_renames_to(index, root)
            || workspace_mentions_raw(index, root)
            || source_may_bind_root(source, root);
    }
    let roots = syntax.target_roots(index);
    let Some(test_root) = roots.root(&test.file, index) else {
        return true;
    };
    let binds_key = (test_root, root.to_string());
    let known = syntax
        .path_memo
        .borrow()
        .test_crate_binds
        .get(&binds_key)
        .copied();
    known.unwrap_or_else(|| {
        let binds = workspace_renames_to(index, root)
            || workspace_mentions_raw(index, root)
            || test_crate_may_bind(&binds_key.0, root, index, roots);
        syntax
            .path_memo
            .borrow_mut()
            .test_crate_binds
            .insert(binds_key.clone(), binds);
        binds
    })
}

/// #6974 review: whether the test's own crate may bind `root` before the
/// extern prelude does: a `mod root`, a `use` binding `root`, or any glob
/// in a file of the test's crate. A module or import of the name shadows
/// the dependency, and a glob may bring one in.
fn test_crate_may_bind(
    test_root: &Path,
    root: &str,
    index: &RustIndex,
    roots: &TargetRoots,
) -> bool {
    index.files().iter().any(|(path, facts)| {
        roots.root(path, index).as_deref() == Some(test_root)
            && source_may_bind_root(&facts.source, root)
    })
}

/// Whether `source` may bind `root` before the extern prelude does: a
/// `mod root`, a type, trait or alias of the name, a `use` binding it, or
/// a glob.
fn source_may_bind_root(source: &str, root: &str) -> bool {
    let masked = mask_comments_and_strings(source);
    declared_module_names(&masked).contains(&root)
        // A type, trait or alias of the root's name shadows the
        // extern prelude too, turning `root::name` into an
        // associated item (#6974 rev-4 review).
        || declares_type(&masked, root)
        || ["trait", "type"].iter().any(|keyword| {
            whole_word_offsets(&masked, keyword).into_iter().any(|offset| {
                starts_with_word(masked[offset + keyword.len()..].trim_start(), root)
            })
        })
        || file_use_statements(source).iter().any(|statement| {
            use_statement_binds_name(statement, root) || statement.contains('*')
        })
}

/// #6974: the inline modules enclosing the one `fn name` item that starts
/// on `line` (1-based) in `source`, outermost first, with `r#` dropped.
/// `None` when the file does not parse, no single such item is found, or
/// it sits anywhere but directly in a module (a fn body, an `impl`).
/// Where a `fn` sits among its file's inline modules (#6974).
#[derive(Clone, Debug)]
struct ItemNesting {
    /// The inline modules enclosing the `fn`, outermost first.
    modules: Vec<String>,
    /// Whether the `fn` or an enclosing inline module carries a `cfg` or
    /// `cfg_attr` attribute. A complementary cfg may then compile a
    /// same-named `static`, `const`, `use` or module in its place, so a path
    /// to the module no longer has to reach the `fn` (#7061 review).
    cfg_gated: bool,
}

fn item_nesting(source: &str, name: &str, line: usize) -> Option<ItemNesting> {
    item_nesting_with_impl(source, name, line, false)
}

fn item_nesting_with_impl(
    source: &str,
    name: &str,
    line: usize,
    allow_impl: bool,
) -> Option<ItemNesting> {
    let parse = parse_clean_source_file(source)?;
    let line_of = |offset: u32| source[..offset as usize].matches('\n').count() + 1;
    let base = |text: String| text.strip_prefix("r#").map_or(text.clone(), str::to_string);
    let wanted = name.strip_prefix("r#").unwrap_or(name);
    let mut found = parse
        .tree()
        .syntax()
        .descendants()
        .filter_map(ast::Fn::cast)
        .filter(|function| {
            function
                .name()
                .is_some_and(|ident| base(ident.text().to_string()) == wanted)
                && {
                    let range = function.syntax().text_range();
                    let start = line_of(range.start().into());
                    let end = line_of(range.end().into());
                    start <= line && line <= end
                }
        });
    let function = found.next()?;
    if found.next().is_some() {
        return None;
    }
    let mut modules = Vec::new();
    // An inner `#![cfg]` in the body gates the whole fn too.
    let mut cfg_gated = has_cfg_attr(&function)
        || function
            .body()
            .and_then(|body| body.stmt_list())
            .is_some_and(|statements| has_cfg_attr(&statements));
    for ancestor in function.syntax().ancestors().skip(1) {
        if let Some(module) = ast::Module::cast(ancestor.clone()) {
            cfg_gated |= has_cfg_attr(&module)
                || module.item_list().is_some_and(|items| has_cfg_attr(&items));
            modules.push(base(module.name()?.text().to_string()));
        } else if allow_impl && let Some(implementation) = ast::Impl::cast(ancestor.clone()) {
            cfg_gated |= has_cfg_attr(&implementation);
        } else if !(ast::ItemList::can_cast(ancestor.kind())
            || ast::SourceFile::can_cast(ancestor.kind())
            || allow_impl && ast::AssocItemList::can_cast(ancestor.kind()))
        {
            return None;
        }
    }
    modules.reverse();
    Some(ItemNesting { modules, cfg_gated })
}

/// Whether `node` carries a `cfg` or `cfg_attr` attribute, outer or inner.
fn has_cfg_attr(node: &impl ast::HasAttrs) -> bool {
    // `cfg` and `cfg_attr` parse to their own metas, which have no `path`.
    node.attrs().any(|attr| {
        matches!(
            attr.meta(),
            Some(ast::Meta::CfgMeta(_) | ast::Meta::CfgAttrMeta(_))
        )
    })
}

/// #7082: whether the out-of-line `mod <name>;` that `declaration` names,
/// with its `mod` token on `line` of `parent`, carries a `cfg` or
/// `cfg_attr`. An unreadable parent or declaration, or no such declaration
/// on that line, fails closed.
fn module_declaration_cfg_gated(
    index: &RustIndex,
    parent: &Path,
    declaration: &str,
    line: usize,
) -> bool {
    let name = declaration
        .split_whitespace()
        .skip_while(|word| *word != "mod")
        .nth(1)
        .map(|word| word.trim_end_matches(';'));
    let Some(name) = name.filter(|name| !name.is_empty()) else {
        return true;
    };
    let name = name.strip_prefix("r#").unwrap_or(name);
    let Some(facts) = index.files().get(parent) else {
        return true;
    };
    let source = &facts.source;
    let Some(parse) = parse_clean_source_file(source) else {
        return true;
    };
    let line_of = |offset: u32| source[..offset as usize].matches('\n').count() + 1;
    let mut on_line = parse
        .tree()
        .syntax()
        .descendants()
        .filter_map(ast::Module::cast)
        .filter(|module| module.item_list().is_none())
        .filter(|module| {
            module
                .mod_token()
                .is_some_and(|token| line_of(token.text_range().start().into()) == line)
                && module.name().is_some_and(|ident| {
                    let text = ident.text().to_string();
                    text.strip_prefix("r#").unwrap_or(&text) == name
                })
        })
        .peekable();
    on_line.peek().is_none() || on_line.any(|module| has_cfg_that_may_drop(&module))
}

/// #7082: whether `node` carries an attribute that may drop or relocate it
/// under some cfg: a `cfg`, or a `cfg_attr` whose attributes name `cfg`,
/// `cfg_attr` or `path`. `#![cfg_attr(docsrs, feature(doc_cfg))]` and other
/// lint or doc toggles cannot, so they keep the pin (#7104 review).
fn has_cfg_that_may_drop(node: &impl ast::HasAttrs) -> bool {
    node.attrs().any(|attr| match attr.meta() {
        Some(ast::Meta::CfgMeta(_)) => true,
        Some(ast::Meta::CfgAttrMeta(meta)) => {
            cfg_attr_payload_may_drop(&meta.syntax().text().to_string())
        }
        _ => false,
    })
}

/// The attributes after a `cfg_attr(predicate, ..)`'s first top-level
/// comma name `cfg`, `cfg_attr` or `path`; unreadable text fails closed.
fn cfg_attr_payload_may_drop(text: &str) -> bool {
    let Some(open) = text.find('(') else {
        return true;
    };
    let inner = &text[open + 1..];
    // Scan the masked text: a comma inside a predicate string must not
    // select the payload boundary (#7104 review). Splitting the unmasked
    // text at a string comma leaves a dangling quote whose masking then
    // hides the real payload (`cfg_attr(mode = "a,b", cfg(..))` would
    // admit a droppable owner). The masker preserves byte length and the
    // matched comma is a literal `,` byte in both, so `at` slices the
    // original soundly.
    let masked_inner = mask_comments_and_strings(inner);
    let mut depth = 0_i32;
    let mut payload = None;
    for (at, character) in masked_inner.char_indices() {
        match character {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            ',' if depth == 0 => {
                payload = Some(&inner[at + 1..]);
                break;
            }
            _ => {}
        }
    }
    // Strings and comments are masked first, so `doc = "path"` names no
    // `path` attribute.
    payload.is_none_or(|payload| {
        let payload = mask_comments_and_strings(payload);
        ["cfg", "cfg_attr", "path"]
            .iter()
            .any(|word| contains_as_whole_word(&payload, word))
    })
}

/// #6974 review: whether any workspace file spells `r#name`, a raw
/// identifier that word matches on `name` miss.
fn workspace_mentions_raw(index: &RustIndex, name: &str) -> bool {
    let raw = format!("r#{name}");
    index.files().values().any(|facts| {
        facts.source.contains(raw.as_str())
            && whole_word_offsets(&mask_comments_and_strings(&facts.source), name)
                .into_iter()
                .any(|offset| offset >= 2 && facts.source.get(offset - 2..offset) == Some("r#"))
    })
}

/// The module path before `::name(` when `operand` starts `a::b::name(`
/// with every segment a plain identifier: no leading `::`, generics,
/// whitespace or type-cased segment (`Type::name(..)` is an associated
/// function, not a free one).
fn path_call_prefix<'a>(operand: &'a str, name: &str) -> Option<&'a str> {
    let mut end = 0;
    loop {
        let segment_end = end + operand[end..].find("::")?;
        let segment = &operand[end..segment_end];
        if !is_plain_identifier(segment)
            || segment.starts_with(|character: char| character.is_ascii_uppercase())
        {
            return None;
        }
        end = segment_end + "::".len();
        if operand[end..]
            .strip_prefix(name)
            .is_some_and(|after| after.starts_with('('))
        {
            return Some(&operand[..segment_end]);
        }
    }
}

/// #6617: `T` when `operand` starts `T::name(` with `T` one CamelCase
/// identifier other than `Self`.
fn associated_call_type<'a>(operand: &'a str, name: &str) -> Option<&'a str> {
    let (head, tail) = operand.split_once("::")?;
    (is_plain_identifier(head)
        && head != "Self"
        && head.starts_with(|character: char| character.is_ascii_uppercase())
        && tail
            .strip_prefix(name)
            .is_some_and(|after| after.starts_with('(')))
    .then_some(head)
}

/// The value expression of `unsafe { <expr> }` when `operand` is exactly that
/// block and the block holds one expression and no statement. Calling an
/// `unsafe fn` needs the block, and the block's value is the call's value.
fn unsafe_block_value(operand: &str) -> Option<&str> {
    let rest = operand.strip_prefix("unsafe")?;
    let open = operand.len() - rest.trim_start().len();
    if !operand[open..].starts_with('{') {
        return None;
    }
    let masked = mask_comments_and_strings(operand);
    let close = matching_close(&masked, open, b'{', b'}')?;
    if !operand[close + 1..].trim().is_empty() || masked[open + 1..close].contains(';') {
        return None;
    }
    // Trim by the masked text so a `// SAFETY:` or `/* .. */` comment around
    // the call is not read as part of it. The call starts with its name and
    // ends with `)`, neither of which masking touches.
    let body = &masked[open + 1..close];
    let start = body.len() - body.trim_start().len();
    let end = body.trim_end().len();
    (start < end).then(|| &operand[open + 1 + start..open + 1 + end])
}

/// The receiver of `Type::constructor(..).name(` when `operand` starts with
/// one associated-function call on a capitalized type path and the method
/// call follows it directly.
fn constructed_receiver<'a>(operand: &'a str, name: &str) -> Option<&'a str> {
    let separator = operand.find("::")?;
    let type_name = &operand[..separator];
    if !is_plain_identifier(type_name)
        || !type_name.starts_with(|character: char| character.is_ascii_uppercase())
    {
        return None;
    }
    let call = &operand[separator + 2..];
    let call_end =
        call.find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))?;
    if call_end == 0 || !call[call_end..].starts_with('(') {
        return None;
    }
    let opening = separator + 2 + call_end;
    let masked = mask_comments_and_strings(operand);
    let closing = matching_close(&masked, opening, b'(', b')')?;
    let after = &operand[closing + 1..];
    let method = after.strip_prefix('.')?;
    (method.starts_with(name) && method[name.len()..].starts_with('('))
        .then_some(&operand[..=closing])
}

/// The span of `head(..)` when `text` is exactly one `head(..)` call.
fn constructor_call_span(text: &str, head: &str) -> Option<usize> {
    let rest = text.strip_prefix(head)?;
    if !rest.starts_with('(') {
        return None;
    }
    let masked = mask_comments_and_strings(text);
    let closing = matching_close(&masked, head.len(), b'(', b')')?;
    text[closing + 1..].trim().is_empty().then_some(closing)
}

/// Whether the owner's return value can only have come through the changed
/// expression, and if so what the pinned value must look like.
/// `changed_line` is the changed line's offset from the body's first line;
/// the tail must span it, so an identical expression elsewhere in the body
/// is not mistaken for the changed one.
#[cfg(test)]
fn return_path_gate(body: &str, expression: &str, changed_line: usize) -> Option<ReturnPathGate> {
    return_path_gate_from(body, expression, None, changed_line)
}

/// [`return_path_gate`] with the changed line's old text, when the diff
/// pairs one: only the part that differs must be evaluated on every input
/// (see [`changed_part_evaluates_conditionally`]).
fn return_path_gate_from(
    body: &str,
    expression: &str,
    before: Option<&str>,
    changed_line: usize,
) -> Option<ReturnPathGate> {
    let masked = mask_comments_and_strings(body);
    let open = body_block_open(&masked)?;
    let close = matching_close(&masked, open, b'{', b'}')?;
    let inner = &masked[open + 1..close];
    let inner_text = &body[open + 1..close];
    let changed = collapse_whitespace(expression.trim().trim_end_matches(';'));
    let changed = changed
        .strip_prefix("return ")
        .map_or(changed.as_str(), str::trim);
    if changed.is_empty() {
        return None;
    }
    let spans_changed_line = |start: usize, end: usize| {
        let line_of = |offset: usize| body[..open + 1 + offset].matches('\n').count();
        let text = &inner_text[start..end];
        let first = start + (text.len() - text.trim_start().len());
        let last = start + text.trim_end().len();
        (line_of(first)..=line_of(last)).contains(&changed_line)
    };
    let (after_semicolon, after_brace) = top_level_tail_starts(inner);
    // Comments between the last statement and the tail (`// SAFETY: ..`
    // before an `unsafe` block) are not part of the tail, so the tail is
    // compared with comments and strings masked on both sides. Masking
    // also hides string contents, so the unmasked tail must still end
    // with the changed text (`Ok("a")` is not `Ok("b")`).
    let masked_changed = collapse_whitespace(&mask_comments_and_strings(changed));
    let tail_is_changed = [after_semicolon, after_brace].into_iter().any(|start| {
        let tail = collapse_whitespace(&inner_text[start..]);
        (tail == changed
            || (collapse_whitespace(&inner[start..]) == masked_changed && tail.ends_with(changed)))
            && spans_changed_line(start, inner_text.len())
    });
    // `return <changed>;` as the final statement is also the tail.
    let final_return_is_changed = !tail_is_changed
        && inner[after_semicolon..].trim().is_empty()
        && final_statement(inner, after_semicolon).is_some_and(|(start, end)| {
            collapse_whitespace(&inner_text[start..end])
                .strip_prefix("return ")
                .is_some_and(|value| value.trim() == changed)
                && spans_changed_line(start, end)
        });
    if !tail_is_changed && !final_return_is_changed {
        if has_unbounded_macro(inner) {
            return None;
        }
        return early_return_gate(body, inner, inner_text, changed, &spans_changed_line)
            .or_else(|| err_variant_gate(body, inner, inner_text, changed, &spans_changed_line));
    }
    if has_unbounded_macro(inner) {
        return None;
    }
    let returns = whole_word_offsets(inner, "return");
    let other_returns = returns.len() - usize::from(final_return_is_changed);
    let early_exits = inner.bytes().filter(|byte| *byte == b'?').count() + other_returns;
    // The uncollapsed expression: collapsing would also merge whitespace
    // inside a string literal that the change touched.
    if changed_part_evaluates_conditionally(expression, before) {
        // RIPR-SPEC-0197 rule 3: a pure `&&`/`||` chain is the one
        // conditional tail a pin may observe, and only on a pinned call
        // that evaluates every operand (checked per test).
        return (early_exits == 0)
            .then(|| short_circuit::ShortCircuitTail::parse(body, changed))
            .flatten()
            .map(ReturnPathGate::ShortCircuit);
    }
    if early_exits == 0 {
        return Some(ReturnPathGate::Any);
    }
    let (head, other) = if constructor_call_span(changed, "Ok").is_some() {
        ("Ok", "Err")
    } else if constructor_call_span(changed, "Some").is_some() {
        ("Some", "None")
    } else {
        return None;
    };
    let head_calls = whole_word_offsets(inner, head)
        .into_iter()
        .filter(|offset| inner[offset + head.len()..].trim_start().starts_with('('))
        .count();
    if head_calls != 1 {
        return None;
    }
    // Every other `return` must build the other constructor. When the
    // changed expression is the final `return`, it is the last one.
    let last = returns.len().checked_sub(1);
    let returns_agree = returns.iter().enumerate().all(|(position, offset)| {
        (final_return_is_changed && Some(position) == last)
            || starts_with_word(inner[offset + "return".len()..].trim_start(), other)
    });
    returns_agree.then_some(ReturnPathGate::Head(head))
}

/// An early `return None;` / `return Err(..);` is the only source of that
/// value when every other exit builds the opposite constructor: each other
/// `return` and the tail are one `Some(..)` / `Ok(..)` call, and no `?` can
/// produce a second `None` / `Err`. A pin expecting that value then observes
/// the changed return. A second return of the same value, a `?`, or any
/// other exit shape leaves the source ambiguous.
///
/// RIPR-SPEC-0231 example 23: the mirror holds for an early
/// `return Some(..);` / `return Ok(..);` when every other `return` and the
/// tail are exactly `None` / one `Err(..)` call. A `?` there builds only the
/// opposite constructor, so it does not compete.
fn early_return_gate(
    body: &str,
    inner: &str,
    inner_text: &str,
    changed: &str,
    spans_changed_line: &dyn Fn(usize, usize) -> bool,
) -> Option<ReturnPathGate> {
    let some_call = |value: &str| constructor_call_span(value, "Some").is_some();
    let ok_call = |value: &str| constructor_call_span(value, "Ok").is_some();
    let err_call = |value: &str| constructor_call_span(value, "Err").is_some();
    let is_none = |value: &str| value == "None";
    // `other` names the changed value's constructor; `opposite` is the only
    // shape every other exit may build. A `?` builds `None` / `Err`, so it
    // is a second source of those but never of `Some(..)` / `Ok(..)`.
    let (gate, other, opposite, question_mark_agrees): (_, _, &dyn Fn(&str) -> bool, _) =
        if changed == "None" {
            (ReturnPathGate::Exact("None"), "None", &some_call, false)
        } else if err_call(changed) {
            (ReturnPathGate::Head("Err"), "Err", &ok_call, false)
        } else if some_call(changed) {
            (ReturnPathGate::EarlyHead("Some"), "Some", &is_none, true)
        } else if ok_call(changed) {
            (ReturnPathGate::EarlyHead("Ok"), "Ok", &err_call, true)
        } else {
            return None;
        };
    // `return Err(if .. { A } else { B })`: a pin on `A` never evaluates a
    // changed `B`, as on the tail path.
    if (inner.contains('?') && !question_mark_agrees)
        || !returns_leave_the_function(body)
        || evaluates_conditionally(&mask_comments_and_strings(changed))
    {
        return None;
    }
    let mut changed_returns = 0usize;
    for offset in whole_word_offsets(inner, "return") {
        let value_start = offset + "return".len();
        let value_end = value_start + inner[value_start..].find(';')?;
        let value = collapse_whitespace(&inner_text[value_start..value_end]);
        let value = value.trim();
        if starts_with_word(value, other) {
            if value != changed || !spans_changed_line(offset, value_end) {
                return None;
            }
            changed_returns += 1;
        } else if !opposite(value) {
            return None;
        }
    }
    let (after_semicolon, after_brace) = top_level_tail_starts(inner);
    let tail = collapse_whitespace(&inner_text[after_semicolon.max(after_brace)..]);
    let tail = tail.trim();
    // The tail must itself build the opposite constructor: an empty tail
    // after a trailing `if .. { .. } else { None }` hides a second source.
    (changed_returns == 1 && opposite(tail)).then_some(gate)
}

/// #7063: the enum and variant segments (`ConfigError`, `MissingEquals`) of
/// the one exact error variant an `Err(..)` construction builds, read by the
/// shared RIPR-SPEC-0106 identity owner. A bare `Err(Variant ..)` (a glob
/// import of the variants) names no enum and is refused.
///
/// The text must be exactly one `Err(..)` call whose argument is the path,
/// optionally followed by one `(..)` or `{ .. }` payload that ends the
/// argument: `Err(E::V { line: 0 }.relabel())` or `Err(E::V(1) + x)` is a
/// computed value that may be any variant, and is refused. Whether the last
/// segment is a declared variant (not an associated constant such as
/// `E::NO_EQUALS`) is [`error_enum_admits_variant_pin`]'s question.
fn error_variant_key(text: &str) -> Option<(String, String)> {
    let text = text.trim();
    constructor_call_span(text, "Err")?;
    let argument = text.strip_prefix("Err(")?.strip_suffix(')')?.trim();
    let head_len = argument
        .find(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_' || ch == ':'))
        .unwrap_or(argument.len());
    let head = &argument[..head_len];
    let rest = argument[head_len..].trim_start();
    if !rest.is_empty() {
        let masked = mask_comments_and_strings(rest);
        let (open, close) = match masked.as_bytes().first() {
            Some(b'(') => (b'(', b')'),
            Some(b'{') => (b'{', b'}'),
            _ => return None,
        };
        if matching_close(&masked, 0, open, close)? + 1 != masked.len() {
            return None;
        }
    }
    local_variant_path(head)
}

/// #7063: the enum and variant of a variant path written `Type::Variant` or
/// `crate::Type::Variant`. Any other prefix (`external::Type::Variant`,
/// `self::`, `super::`, a leading `::`) may name a different enum that only
/// shares the trailing names of a workspace one, so it names none here.
fn local_variant_path(path: &str) -> Option<(String, String)> {
    let path = path.trim();
    let path = path.strip_prefix("crate::").unwrap_or(path);
    let (qualifier, variant) = path.split_once("::")?;
    let (qualifier, variant) = (qualifier.trim(), variant.trim());
    (is_plain_identifier(variant) && is_plain_identifier(qualifier))
        .then(|| (qualifier.to_string(), variant.to_string()))
}

/// #7063: the enum and variant of a changed `[return ]Err(Type::Variant(..))`
/// or `Err(Type::Variant { .. })` whose variant carries a payload.
fn payload_variant_construction(expression: &str) -> Option<(String, String)> {
    let text = expression.trim().trim_end_matches(';').trim_end();
    let text = text.strip_prefix("return ").map_or(text, str::trim);
    let key = error_variant_key(text)?;
    let argument = text.strip_prefix("Err(")?.strip_suffix(')')?;
    argument.trim_end().ends_with([')', '}']).then_some(key)
}

/// #7063: a changed early `return Err(Type::Variant ..);` beside other
/// `return Err(..)` exits. A pin expecting `Err(Type::Variant ..)` observes
/// the changed return when no other exit can build that variant: every other
/// `return` and the tail build one `Ok(..)` call or one `Err(..)` call of a
/// different variant of the same `Type` (an opaque `Err(e)` may hold any
/// variant), the body has no `?` (a converted callee error may be any
/// variant), and the changed value evaluates all of its parts. Exits are
/// read by spelling, so the owner file's binding of `Ok` or `Err` refuses
/// it as for the other early gates ([`ReturnPathGate::prelude_names`]).
fn err_variant_gate(
    body: &str,
    inner: &str,
    inner_text: &str,
    changed: &str,
    spans_changed_line: &dyn Fn(usize, usize) -> bool,
) -> Option<ReturnPathGate> {
    constructor_call_span(changed, "Err")?;
    let (qualifier, variant) = error_variant_key(changed)?;
    if inner.contains('?')
        || !returns_leave_the_function(body)
        || evaluates_conditionally(&mask_comments_and_strings(changed))
    {
        return None;
    }
    // `Some` when `value` is an exit that cannot build the changed variant,
    // `None` when it may.
    let siblings = std::cell::RefCell::new(BTreeSet::new());
    let other_exit = |value: &str| {
        if constructor_call_span(value, "Ok").is_some() {
            return true;
        }
        match error_variant_key(value) {
            Some((q, v)) if q == qualifier && v != variant => {
                siblings.borrow_mut().insert(v);
                true
            }
            _ => false,
        }
    };
    let mut changed_returns = 0usize;
    for offset in whole_word_offsets(inner, "return") {
        let value_start = offset + "return".len();
        let value_end = value_start + inner[value_start..].find(';')?;
        let value = collapse_whitespace(&inner_text[value_start..value_end]);
        let value = value.trim();
        if other_exit(value) {
            continue;
        }
        if value != changed || !spans_changed_line(offset, value_end) {
            return None;
        }
        changed_returns += 1;
    }
    let (after_semicolon, after_brace) = top_level_tail_starts(inner);
    let tail = collapse_whitespace(&inner_text[after_semicolon.max(after_brace)..]);
    (changed_returns == 1 && other_exit(tail.trim())).then(|| ReturnPathGate::ErrVariant {
        qualifier,
        variant,
        siblings: siblings.into_inner().into_iter().collect(),
    })
}

/// Whether `text` starts with the whole word `word`.
fn starts_with_word(text: &str, word: &str) -> bool {
    text.strip_prefix(word).is_some_and(|after| {
        !after.starts_with(|character: char| character.is_ascii_alphanumeric() || character == '_')
    })
}

/// Byte offset of the `{` that opens the function body: the first brace
/// after the parameter list closes.
fn body_block_open(masked: &str) -> Option<usize> {
    let params = masked.find('(')?;
    let params_close = matching_close(masked, params, b'(', b')')?;
    masked[params_close..]
        .find('{')
        .map(|offset| params_close + offset)
}

/// Where the tail expression may start: after the last top-level `;`, and
/// after the last top-level `}` (a block-like statement needs no `;`).
fn top_level_tail_starts(inner: &str) -> (usize, usize) {
    let mut depth = 0usize;
    let mut after_semicolon = 0usize;
    let mut after_brace = 0usize;
    for (offset, byte) in inner.bytes().enumerate() {
        match byte {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' => depth = depth.saturating_sub(1),
            b'}' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    after_brace = offset + 1;
                }
            }
            b';' if depth == 0 => after_semicolon = offset + 1,
            _ => {}
        }
    }
    (after_semicolon, after_brace.max(after_semicolon))
}

/// The span of the top-level statement that ends at the `;` just before
/// `end`, without the `;`.
fn final_statement(masked: &str, end: usize) -> Option<(usize, usize)> {
    let statement_end = end.checked_sub(1)?;
    let (previous_semicolon, previous_brace) = top_level_tail_starts(&masked[..statement_end]);
    Some((previous_semicolon.max(previous_brace), statement_end))
}

/// Macros that cannot return a value from the enclosing function. Any other
/// macro in the owner body (`bail!`, `ensure!`, a crate's own macro) may
/// hide a `return`, so the return paths are not established. The list is
/// owned by the syntax scan, which also bounds the names a file's stored
/// [`crate::analysis::syntax::MacroBindingCandidates`] can report.
const NON_RETURNING_MACROS: &[&str] = TRUSTED_MACRO_NAMES;

// `json` is a construction candidate only in assertion context. It must never
// enter the owner-side generic non-returning list: an opaque owner macro can exit.
fn assertion_context_macros() -> Vec<&'static str> {
    NON_RETURNING_MACROS
        .iter()
        .copied()
        .chain(["json"])
        .collect()
}

/// Trusted names whose trust is the test-side binding scan's alone (#6578).
/// `expect!` and `expect_file!` are no `std` macros: outside a test that
/// verifies `use expect_test::{expect, expect_file};`, a bare one is a
/// crate's own (a try-style `expect!(x)` may hide a `return`), so owner
/// bodies and binding reads never count it as bounded.
const TEST_SCOPED_TRUSTED_MACROS: &[&str] = &["expect", "expect_file"];

/// Whether a macro named `name` neither returns nor binds a name, whatever
/// file it sits in.
fn is_bounded_macro(name: &str) -> bool {
    NON_RETURNING_MACROS.contains(&name) && !TEST_SCOPED_TRUSTED_MACROS.contains(&name)
}

fn has_unbounded_macro(masked: &str) -> bool {
    macro_invocations(masked)
        .into_iter()
        .any(|(name, _)| !is_bounded_macro(name))
}

/// Every `name!` macro invocation in masked text, with the offset of its
/// opening delimiter. Whitespace may separate the name, the `!` and the
/// delimiter (`ensure !(..)`); a keyword before `!` is a negation
/// (`if !done`), not a macro.
fn macro_invocations(masked: &str) -> Vec<(&str, usize)> {
    let bytes = masked.as_bytes();
    let mut invocations = Vec::new();
    for (offset, byte) in bytes.iter().enumerate() {
        if *byte != b'!' || bytes.get(offset + 1) == Some(&b'=') {
            continue;
        }
        let before = masked[..offset].trim_end();
        // Step past the whole boundary character: a non-ASCII one is more
        // than one byte, and `position + 1` would split it (#7926 review).
        let start = before
            .char_indices()
            .rev()
            .find(|(_, character)| !(character.is_ascii_alphanumeric() || *character == '_'))
            .map_or(0, |(position, character)| position + character.len_utf8());
        let name = &before[start..];
        if !is_plain_identifier(name) || NEGATING_KEYWORDS.contains(&name) {
            continue;
        }
        let after = &masked[offset + 1..];
        let delimiter = offset + 1 + (after.len() - after.trim_start().len());
        if matches!(bytes.get(delimiter), Some(b'(' | b'[' | b'{')) {
            invocations.push((name, delimiter));
        }
    }
    invocations
}

/// Keywords a `!` negation can follow; never macro names.
const NEGATING_KEYWORDS: &[&str] = &[
    "if", "while", "return", "match", "in", "else", "break", "let", "mut", "move", "as",
];

/// #6578: whether the part of the changed tail that differs from its old
/// text (`before`) is evaluated only on some inputs, or passes through code
/// that may not use it. In `lines.iter().map(|l| l.cents).sum::<u64>() + 50`
/// → `.. + 25 * 2` the closure is unchanged and the changed operand of the
/// outer `+` runs on every input and reaches the sum directly, so the
/// closure does not make the change conditional.
///
/// Only a tail the whole-text check refuses is read more closely, and it is
/// admitted only in one narrow shape: the changed span (the text between
/// the longest common prefix and suffix) holds no closure, block,
/// assignment or conditional text, and every node from it up to and
/// including the tail is an operator that evaluates all its operands
/// (arithmetic, comparison or bitwise; not `&&`, `||` or an assignment), a
/// parenthesis, prefix operator or cast, or a call to a named function or
/// method that is no skipping combinator and holds no closure anywhere. A
/// closure beside the change in a call (`items.iter().map(|l| ..)` with
/// `items` changed, `fold(51, |a, l| ..)`) may discard or transform it, and
/// a block, labeled `break`, `const` or `async` around it may skip or
/// rebind it, so each refuses. Without a paired old text, or when the tail
/// does not parse as one expression, the whole tail is read as before.
pub(super) fn changed_part_evaluates_conditionally(changed: &str, before: Option<&str>) -> bool {
    if !evaluates_conditionally(&mask_comments_and_strings(changed)) {
        return false;
    }
    let Some(span) = super::changed_span::ChangedSpan::of(changed, before) else {
        return true;
    };
    // What the change removed may itself have been a closure, block, macro
    // or branch that gave the same value (`(|| 51)()` → `51`), so it must
    // be as plain as what replaced it. The removed text may start inside a
    // string, so it is read unmasked: a quoted `|` or `if` also refuses.
    let removed = span.removed.as_str();
    if evaluates_conditionally(removed)
        || removed.contains(['|', '{', '!', '?'])
        || has_keyword(
            removed,
            &["return", "break", "async", "unsafe", "const", "static"],
        )
    {
        return true;
    }
    if evaluates_conditionally(&mask_comments_and_strings(
        &span.covering.text().to_string(),
    )) || span.covering.descendants().any(|node| {
        ast::ClosureExpr::can_cast(node.kind())
            || ast::BlockExpr::can_cast(node.kind())
            || ast::Item::can_cast(node.kind())
            || is_short_circuit_or_assignment(&node)
    }) {
        return true;
    }
    !span
        .enclosing()
        .iter()
        .all(|(ancestor, _)| evaluates_every_operand(ancestor))
}

/// Whether `text` holds one of `keywords` as a whole word.
fn has_keyword(text: &str, keywords: &[&str]) -> bool {
    text.split(|character: char| !character.is_alphanumeric() && character != '_')
        .any(|word| keywords.contains(&word))
}

/// A `&&`/`||` or an assignment (`=`, `+=`, ..) operator.
fn is_short_circuit_or_assignment(node: &SyntaxNode) -> bool {
    ast::BinExpr::cast(node.clone()).is_some_and(|binary| {
        binary.op_token().is_some_and(|op| {
            let op = op.text();
            op == "&&"
                || op == "||"
                || (op.ends_with('=') && !matches!(op, "==" | "!=" | "<=" | ">="))
        })
    })
}

/// Whether `node`, enclosing the changed span, evaluates every operand and
/// passes the changed one on without a closure or skipping combinator.
fn evaluates_every_operand(node: &SyntaxNode) -> bool {
    // An argument list is judged by the call that holds it.
    if ast::ArgList::can_cast(node.kind())
        || ast::ParenExpr::can_cast(node.kind())
        || ast::PrefixExpr::can_cast(node.kind())
        || ast::CastExpr::can_cast(node.kind())
    {
        return true;
    }
    if ast::BinExpr::can_cast(node.kind()) {
        return !is_short_circuit_or_assignment(node);
    }
    let name = if let Some(method) = ast::MethodCallExpr::cast(node.clone()) {
        method.name_ref().map(|name| name.text().to_string())
    } else if let Some(call) = ast::CallExpr::cast(node.clone()) {
        match call.expr() {
            Some(ast::Expr::PathExpr(path)) => path
                .path()
                .and_then(|path| path.segment())
                .and_then(|segment| segment.name_ref())
                .map(|name| name.text().to_string()),
            _ => None,
        }
    } else {
        return false;
    };
    name.is_some_and(|name| !CONDITIONAL_COMBINATORS.contains(&name.as_str()))
        && !node
            .descendants()
            .any(|inner| ast::ClosureExpr::can_cast(inner.kind()))
}

/// Whether the changed tail evaluates some of its parts only on some
/// inputs: a closure or `|`/`||`/`&&` operator, a branch or loop, or a
/// combinator that skips its argument (`map_or(0, ..)` on `None`). A pin on
/// such an input never evaluates the changed part, so the tail's value is
/// not established to come through it.
///
/// A binary bitwise `|` evaluates both operands on every input, so it is
/// not conditional (#6675); every other pipe (`||`, `|=`, a closure's
/// parameter list) still is. See [`has_non_bitwise_pipe`].
fn evaluates_conditionally(masked_tail: &str) -> bool {
    if has_non_bitwise_pipe(masked_tail) || masked_tail.contains("&&") {
        return true;
    }
    if [
        "if", "match", "else", "loop", "while", "for", "break", "continue",
    ]
    .iter()
    .any(|keyword| contains_as_whole_word(masked_tail, keyword))
    {
        return true;
    }
    CONDITIONAL_COMBINATORS.iter().any(|combinator| {
        whole_word_offsets(masked_tail, combinator)
            .into_iter()
            .any(|offset| {
                let before = masked_tail[..offset].trim_end();
                (before.ends_with('.') || before.ends_with("::"))
                    && masked_tail[offset + combinator.len()..]
                        .trim_start()
                        .starts_with(['(', ':'])
            })
    })
}

/// #6692: whether the changed line (`changed_line`, offset from the body's
/// first line) lies in a struct literal of `type_name` (or `Self`) that is
/// the whole tail of `body`, and that literal is the body's only exit: no
/// `?`, no `return`, no macro that may hide an exit, and no part evaluated
/// only on some inputs. The changed line must be one whole field
/// initializer of that literal's own braces (depth 1): a field of a nested
/// literal or an argument of a call inside a field is not the outer
/// field's value.
fn clone_tail_literal_spans(
    body: &str,
    type_name: &str,
    changed_line: usize,
    expression: &str,
) -> bool {
    let masked = mask_comments_and_strings(body);
    let Some(open) = body_block_open(&masked) else {
        return false;
    };
    let Some(close) = matching_close(&masked, open, b'{', b'}') else {
        return false;
    };
    let inner = &masked[open + 1..close];
    if has_unbounded_macro(inner)
        || inner.contains('?')
        || !whole_word_offsets(inner, "return").is_empty()
    {
        return false;
    }
    let (after_semicolon, _) = top_level_tail_starts(inner);
    let tail = &inner[after_semicolon..];
    let tail_start = after_semicolon + (tail.len() - tail.trim_start().len());
    let tail = tail.trim();
    let Some(after_type) = tail
        .strip_prefix(type_name)
        .or_else(|| tail.strip_prefix("Self"))
    else {
        return false;
    };
    let after_type = after_type.trim_start();
    if !after_type.starts_with('{') {
        return false;
    }
    let literal_open = tail.len() - after_type.len();
    let Some(literal_close) = matching_close(tail, literal_open, b'{', b'}') else {
        return false;
    };
    if literal_close + 1 != tail.len() || evaluates_conditionally(tail) {
        return false;
    }
    let line_of = |offset: usize| masked[..open + 1 + offset].matches('\n').count();
    let first = line_of(tail_start + literal_open);
    let last = line_of(tail_start + literal_close);
    if !(first < changed_line && changed_line < last) {
        return false;
    }
    let Some(line_start) = masked
        .match_indices('\n')
        .nth(changed_line - 1)
        .map(|(position, _)| position + 1)
    else {
        return false;
    };
    let line_end = masked[line_start..]
        .find('\n')
        .map_or(masked.len(), |position| line_start + position);
    let literal_start = open + 1 + tail_start + literal_open;
    let depth = masked[literal_start..line_start]
        .bytes()
        .fold(0_isize, |depth, byte| match byte {
            b'{' | b'(' | b'[' => depth + 1,
            b'}' | b')' | b']' => depth - 1,
            _ => depth,
        });
    let line = masked[line_start..line_end].trim();
    let field_text = |text: &str| collapse_whitespace(text.trim().trim_end_matches(',').trim());
    depth == 1
        && !line.contains(['{', '}'])
        && field_text(&body[line_start..line_end]) == field_text(expression)
}

/// The struct literal an owner returns, as [`whole_value_tail`] reads it.
struct WholeValueTail {
    /// The literal's type as written: its last path segment, or `Self`.
    type_name: String,
    /// `Ok` or `Some` when the tail wraps the literal in that constructor.
    wrapper: Option<&'static str>,
    /// `Err` or `None` when the owner also exits early through that
    /// constructor; it must be the prelude's, like the wrapper.
    early_exit: Option<&'static str>,
}

/// RIPR-SPEC-0225: the literal whose field `field` the changed line
/// initializes, when that literal is the owner's tail value (directly, or as
/// the one argument of a tail `Ok(..)`/`Some(..)`). The body may not
/// `return`, nor hold a macro that may hide an exit, and `?` is allowed only
/// around a wrapped tail, where it exits with `Err`/`None`, never the pinned
/// constructor. The changed line must be the field's whole initializer, at
/// the literal's top level, with a value evaluated on every input and no
/// functional-update base in the literal. Fails closed on anything else.
fn whole_value_tail(
    body: &str,
    changed_line: usize,
    field: &str,
    expression: &str,
) -> Option<WholeValueTail> {
    let masked = mask_comments_and_strings(body);
    if has_unbounded_macro(&masked) {
        return None;
    }
    let returns = !whole_word_offsets(&masked, "return").is_empty();
    let parse = parse_clean_source_file(body)?;
    let function = parse
        .tree()
        .syntax()
        .descendants()
        .find_map(ast::Fn::cast)?;
    let block = function.body()?;
    let mut tail = block.tail_expr()?;
    while let ast::Expr::ParenExpr(inner) = &tail {
        tail = inner.expr()?;
    }
    let (literal, wrapper) = match tail {
        ast::Expr::RecordExpr(literal) => (literal, None),
        ast::Expr::CallExpr(call) => {
            let wrapper = match call.expr()?.syntax().text().to_string().as_str() {
                "Ok" => "Ok",
                "Some" => "Some",
                _ => return None,
            };
            let mut arguments = call.arg_list()?.args();
            let (Some(ast::Expr::RecordExpr(literal)), None) = (arguments.next(), arguments.next())
            else {
                return None;
            };
            (literal, Some(wrapper))
        }
        _ => return None,
    };
    // RIPR-SPEC-0225 decision 6: beside an `Ok(..)`/`Some(..)` tail, an
    // early `return Err(..)`/`return None` exits with the other variant, as
    // `?` does, so every `Ok`/`Some` the owner returns is the tail literal.
    // Any other `return` may hand back another value of the wrapped type.
    if returns
        && !wrapper.is_some_and(|wrapper| {
            let returned = function
                .syntax()
                .descendants()
                .filter_map(ast::ReturnExpr::cast)
                .collect::<Vec<_>>();
            returned.len() == whole_word_offsets(&masked, "return").len()
                && returned
                    .iter()
                    .all(|exit| returns_other_variant(exit, wrapper))
        })
    {
        return None;
    }
    if wrapper.is_none()
        && block
            .syntax()
            .descendants()
            .any(|node| ast::TryExpr::can_cast(node.kind()))
    {
        return None;
    }
    let path = literal.path()?;
    // `Self::Variant { .. }` or `module::Type { .. }` names something other
    // than the type the equality gates read.
    if path.qualifier().is_some()
        || path
            .segments()
            .any(|segment| segment.generic_arg_list().is_some())
    {
        return None;
    }
    let type_name = path.segment()?.name_ref()?.text().to_string();
    let fields = literal.record_expr_field_list()?;
    if fields.spread().is_some() || fields.dotdot_token().is_some() {
        return None;
    }
    let mut named = fields.fields().filter(|candidate| {
        candidate
            .field_name()
            .is_some_and(|name| name.text().trim_start_matches("r#") == field)
    });
    let (Some(initializer), None) = (named.next(), named.next()) else {
        return None;
    };
    let range = initializer.syntax().text_range();
    let line_of = |offset: usize| body[..offset].matches('\n').count();
    let (first, last) = (
        line_of(usize::from(range.start())),
        line_of(usize::from(range.end())),
    );
    let value = initializer.expr()?;
    let field_text = |text: &str| collapse_whitespace(text.trim().trim_end_matches(',').trim());
    (first == changed_line
        && last == changed_line
        && field_text(&initializer.syntax().text().to_string()) == field_text(expression)
        && !evaluates_conditionally(&mask_comments_and_strings(
            &value.syntax().text().to_string(),
        )))
    .then_some(WholeValueTail {
        type_name,
        wrapper,
        early_exit: wrapper
            .filter(|_| returns)
            .map(|wrapper| if wrapper == "Ok" { "Err" } else { "None" }),
    })
}

/// Whether `exit` is `return Err(..)` beside an `Ok` tail, or `return None`
/// beside a `Some` tail: an exit with the variant the tail does not build.
fn returns_other_variant(exit: &ast::ReturnExpr, wrapper: &str) -> bool {
    match (wrapper, exit.expr()) {
        ("Ok", Some(ast::Expr::CallExpr(call))) => call
            .expr()
            .is_some_and(|callee| callee.syntax().text() == "Err"),
        ("Some", Some(ast::Expr::PathExpr(path))) => path.syntax().text() == "None",
        _ => false,
    }
}

impl WholeValueField {
    /// RIPR-SPEC-0225 rule 2: `expected` is a literal of the owner's type,
    /// in the owner's wrapper, that names the field once, explicitly, with an
    /// independent value ([`independent_value`]), and no functional-update
    /// base anywhere in it.
    fn admits(&self, expected: &str) -> bool {
        let Some(parse) =
            parse_clean_source_file(&format!("fn ripr_expected() {{ ({expected}); }}"))
        else {
            return false;
        };
        let Some(mut value) = parse
            .tree()
            .syntax()
            .descendants()
            .find_map(ast::ParenExpr::cast)
            .and_then(|paren| paren.expr())
        else {
            return false;
        };
        if let Some(wrapper) = self.wrapper {
            let ast::Expr::CallExpr(call) = value else {
                return false;
            };
            if call
                .expr()
                .is_none_or(|callee| callee.syntax().text() != wrapper)
            {
                return false;
            }
            let Some(mut arguments) = call.arg_list().map(|list| list.args()) else {
                return false;
            };
            let (Some(inner), None) = (arguments.next(), arguments.next()) else {
                return false;
            };
            value = inner;
        }
        let ast::Expr::RecordExpr(literal) = value else {
            return false;
        };
        if literal.syntax().descendants().any(|node| {
            ast::RecordExprFieldList::cast(node)
                .is_some_and(|list| list.spread().is_some() || list.dotdot_token().is_some())
        }) {
            return false;
        }
        // A bare name only: a qualified path (`external::Config`) may name
        // another type whose equality with the owner's ignores the field.
        let names_type = literal.path().is_some_and(|path| {
            path.qualifier().is_none()
                && path
                    .segments()
                    .all(|segment| segment.generic_arg_list().is_none())
                && path
                    .segment()
                    .and_then(|segment| segment.name_ref())
                    .is_some_and(|name| name.text() == self.type_name.as_str())
        });
        let Some(fields) = literal.record_expr_field_list() else {
            return false;
        };
        let mut named = fields.fields().filter(|candidate| {
            candidate
                .field_name()
                .is_some_and(|name| name.text().trim_start_matches("r#") == self.field)
        });
        let (Some(pinned), None) = (named.next(), named.next()) else {
            return false;
        };
        // A shorthand `field` reads a local binding of that name.
        names_type
            && pinned.name_ref().is_some()
            && pinned.expr().is_some_and(|value| {
                independent_value(
                    &value,
                    self.field_is_string,
                    self.string_from_may_be_rebound,
                )
            })
            && !literal.syntax().descendants().any(|node| {
                ast::NameRef::cast(node.clone())
                    .is_some_and(|name| self.computed_names.contains(name.text()))
                    // #7066 review: a bare CamelCase value the workspace never
                    // declares as a type or variant may be a local binding.
                    || ast::PathExpr::cast(node)
                        .and_then(|path| path.path())
                        .filter(|path| path.qualifier().is_none())
                        .and_then(|path| path.segment()?.name_ref())
                        .is_some_and(|name| {
                            !self.constructor_names.contains(name.text())
                        })
            })
    }
}

/// RIPR-SPEC-0225 rule 2: an expected value that cannot carry the owner's
/// result: literals (negated too), tuples and arrays of them, unit and tuple
/// variants or structs and struct literals named by a CamelCase path, and a
/// string literal's `.to_string()`, `.to_owned()`, `String::from(..)`, or
/// `.into()` when the field is a `String`. `String::from(..)` counts only
/// when `String` names the standard type workspace-wide; a workspace
/// `mod String` or rename makes the call an unknown function (#7066 review).
/// A local binding, a constant, a workspace function or any other method can
/// carry the owner's output (`retries: c.retries`, `RETRIES` from a
/// `const fn`) and gives no credit.
fn independent_value(
    value: &ast::Expr,
    string_field: bool,
    string_from_may_be_rebound: bool,
) -> bool {
    let string_literal = |expr: Option<ast::Expr>| {
        matches!(expr, Some(ast::Expr::Literal(literal))
            if matches!(literal.kind(), ast::LiteralKind::String(_)))
    };
    match value {
        ast::Expr::Literal(_) => true,
        ast::Expr::PrefixExpr(prefix) => {
            prefix.op_kind() == Some(ast::UnaryOp::Neg)
                && matches!(prefix.expr(), Some(ast::Expr::Literal(_)))
        }
        ast::Expr::ParenExpr(inner) => inner.expr().is_some_and(|inner| {
            independent_value(&inner, string_field, string_from_may_be_rebound)
        }),
        ast::Expr::TupleExpr(tuple) => tuple
            .fields()
            .all(|item| independent_value(&item, string_field, string_from_may_be_rebound)),
        ast::Expr::ArrayExpr(items) => {
            items.semicolon_token().is_none()
                && items
                    .exprs()
                    .all(|item| independent_value(&item, string_field, string_from_may_be_rebound))
        }
        ast::Expr::PathExpr(path) => path.path().is_some_and(|path| constructor_path(&path)),
        ast::Expr::CallExpr(call) => {
            let Some(ast::Expr::PathExpr(callee)) = call.expr() else {
                return false;
            };
            let Some(path) = callee.path() else {
                return false;
            };
            let arguments = call.arg_list().map(|list| list.args().collect::<Vec<_>>());
            if path.syntax().text() == "String::from" {
                return !string_from_may_be_rebound
                    && arguments.is_some_and(|arguments| {
                        arguments.len() == 1 && string_literal(arguments.into_iter().next())
                    });
            }
            constructor_path(&path)
                && arguments.is_some_and(|arguments| {
                    arguments
                        .iter()
                        .all(|argument| independent_value(argument, false, false))
                })
        }
        ast::Expr::RecordExpr(literal) => {
            literal.path().is_some_and(|path| constructor_path(&path))
                && literal.record_expr_field_list().is_some_and(|fields| {
                    fields.spread().is_none()
                        && fields.dotdot_token().is_none()
                        && fields.fields().all(|field| {
                            field.name_ref().is_some()
                                && field
                                    .expr()
                                    .is_some_and(|value| independent_value(&value, false, false))
                        })
                })
        }
        ast::Expr::MethodCallExpr(call) => {
            let Some(method) = call.name_ref() else {
                return false;
            };
            let method = method.text();
            call.generic_arg_list().is_none()
                && call
                    .arg_list()
                    .is_some_and(|list| list.args().next().is_none())
                && (method == "to_string"
                    || method == "to_owned"
                    || (method == "into" && string_field))
                && string_literal(call.receiver())
        }
        _ => false,
    }
}

/// CamelCase names of `const`, `static` and `fn` items anywhere in the
/// workspace, and CamelCase `use .. as` aliases (`use crate::four as Four;`
/// names a fn). Naming lints only warn on them, so [`constructor_path`]'s
/// case test alone cannot tell `Limits::Max` (a constant) from `Mode::Fast`.
/// An alias of a real type or variant is refused too, which fails closed.
fn camel_case_value_items(index: &RustIndex) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for facts in index.files().values() {
        let masked = mask_comments_and_strings(&facts.source);
        for keyword in ["const", "static", "fn", "as"] {
            for start in whole_word_offsets(&masked, keyword) {
                // `*const T`, `&'static T` and a cast's `as T` name a type,
                // not a value item; only an import's `as` renames.
                let before = masked[..start].trim_end();
                let names_type = match keyword {
                    "const" => before.ends_with('*'),
                    "static" => before.ends_with('\''),
                    "as" => !in_import_item(&masked, start),
                    _ => false,
                };
                if names_type {
                    continue;
                }
                let rest = masked[start + keyword.len()..].trim_start();
                let rest = rest.strip_prefix("mut ").map_or(rest, str::trim_start);
                let name: String = rest
                    .chars()
                    .take_while(|ch| ch.is_ascii_alphanumeric() || *ch == '_')
                    .collect();
                if name.starts_with(|ch: char| ch.is_ascii_uppercase())
                    && name.chars().any(|ch| ch.is_ascii_lowercase())
                {
                    names.insert(name);
                }
            }
        }
    }
    names
}

/// Whether the `as` at `offset` of `masked` sits in a `use` or `extern
/// crate` item: the item's keyword follows the previous `;` (or the file
/// start), and only path tokens (`a::{b, c::*}`, earlier renames) lie
/// between it and the `as`. A cast's operand has other tokens (`(`, `.`,
/// `=`) or no import keyword at all.
fn in_import_item(masked: &str, offset: usize) -> bool {
    let statement_start = masked[..offset].rfind(';').map_or(0, |index| index + 1);
    let statement = &masked[statement_start..offset];
    let Some(keyword_end) = ["use", "crate"]
        .iter()
        .filter_map(|keyword| {
            whole_word_offsets(statement, keyword)
                .last()
                .map(|start| start + keyword.len())
        })
        .max()
    else {
        return false;
    };
    // Raw (`r#async`) and non-ASCII identifiers are path tokens too.
    statement[keyword_end..].chars().all(|ch| {
        ch.is_alphanumeric()
            || ch.is_whitespace()
            || matches!(ch, '_' | '#' | ':' | '{' | '}' | ',' | '*')
    })
}

/// #7066 review: the struct, enum and union names every indexed file
/// declares, the variants of each `enum` (names that open an item at the
/// body's top level), and the standard `None`, `Some`, `Ok` and `Err`.
/// Lexical: a name missed here only withholds credit.
fn declared_constructor_names(index: &RustIndex) -> BTreeSet<String> {
    let mut names: BTreeSet<String> = ["None", "Some", "Ok", "Err"]
        .into_iter()
        .map(str::to_string)
        .collect();
    let ident = |text: &str| -> String {
        text.trim_start()
            .chars()
            .take_while(|ch| ch.is_alphanumeric() || *ch == '_')
            .collect()
    };
    for facts in index.files().values() {
        let masked = mask_comments_and_strings(&facts.source);
        for keyword in ["struct", "enum", "union"] {
            for offset in whole_word_offsets(&masked, keyword) {
                let rest = &masked[offset + keyword.len()..];
                let name = ident(rest);
                if name.is_empty() {
                    continue;
                }
                names.insert(name);
                if keyword != "enum" {
                    continue;
                }
                let Some(open) = rest.find('{') else {
                    continue;
                };
                let mut depth = 0usize;
                let mut item_start = true;
                for (at, ch) in rest[open..].char_indices() {
                    match ch {
                        '{' | '(' | '[' => {
                            depth += 1;
                            if depth == 1 {
                                item_start = true;
                            }
                        }
                        '}' | ')' | ']' => {
                            depth = depth.saturating_sub(1);
                            if depth == 0 {
                                break;
                            }
                            // An attribute's `]` leaves the variant to come.
                            if depth == 1 && ch == ']' {
                                item_start = true;
                            }
                        }
                        ',' if depth == 1 => item_start = true,
                        '#' if depth == 1 => {}
                        _ if depth == 1 && item_start && !ch.is_whitespace() => {
                            let variant = ident(&rest[open + at..]);
                            if !variant.is_empty() {
                                names.insert(variant);
                            }
                            item_start = false;
                        }
                        _ => {}
                    }
                }
            }
        }
    }
    names
}

/// A path that names a variant or a struct: its last segment is CamelCase
/// (`None`, `Some`, `Count`, `Mode::Fast`) and no segment has generic
/// arguments. A SCREAMING_CASE constant may be computed (a `const fn` of the
/// workspace) and does not qualify.
fn constructor_path(path: &ast::Path) -> bool {
    path.segments()
        .all(|segment| segment.generic_arg_list().is_none())
        && path
            .segment()
            .and_then(|segment| segment.name_ref())
            .is_some_and(|name| {
                let text = name.text();
                text.starts_with(|ch: char| ch.is_ascii_uppercase())
                    && text.chars().any(|ch| ch.is_ascii_lowercase())
            })
}

/// The field a struct-literal initializer names: `start: self.start,` and
/// the shorthand `start,` both name `start`.
fn initialized_field_name(expression: &str) -> Option<&str> {
    let trimmed = expression.trim().trim_end_matches(',').trim();
    let name = match trimmed.find(':') {
        Some(colon) if trimmed[colon..].starts_with("::") => return None,
        Some(colon) => trimmed[..colon].trim(),
        None => trimmed,
    };
    let name = name.strip_prefix("r#").unwrap_or(name);
    (is_plain_identifier(name) && !name.starts_with(|ch: char| ch.is_ascii_digit())).then_some(name)
}

/// How deep [`type_compares_by_value`] follows workspace field types.
const EQUALITY_DEPTH_LIMIT: usize = 4;

/// RIPR-SPEC-0225 decision 9: the primitive integer type `field` of
/// `type_name` is declared with, when `type_name` is the struct a record
/// literal in the owner's body names, so comparing the field to an integer
/// literal is the built-in `==`. The struct is declared exactly once in the
/// owner's own file, in the owner's own inline module (a local item takes
/// the name from every import), with no attribute that may compile it out
/// or change it, no generic parameter, and no attribute on any enclosing
/// module; no other indexed file declares a type of that name. The field is
/// named once, carries no attribute, and its type is a standard integer
/// name that no workspace type, alias, rename or foreign import rebinds in
/// the owner's file. Anything else refuses.
pub(in crate::analysis) fn field_builtin_integer(
    owner: &FunctionSummary,
    type_name: &str,
    field: &str,
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
) -> Option<&'static str> {
    let key = (
        owner.file.clone(),
        owner.name.clone(),
        type_name.to_owned(),
        field.to_owned(),
    );
    if let Some(found) = syntax.field_integer_memo.borrow().get(&key) {
        return *found;
    }
    let found = field_builtin_integer_uncached(owner, type_name, field, index, syntax);
    syntax.field_integer_memo.borrow_mut().insert(key, found);
    found
}

fn field_builtin_integer_uncached(
    owner: &FunctionSummary,
    type_name: &str,
    field: &str,
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
) -> Option<&'static str> {
    let file = index.files().get(&owner.file)?;
    if file.used_lexical_fallback
        || index.files().iter().any(|(path, other)| {
            *path != owner.file
                && other.source.contains(type_name)
                && declares_type(&mask_comments_and_strings(&other.source), type_name)
        })
    {
        return None;
    }
    let parse = parse_clean_source_file(&file.source)?;
    let tree = parse.tree();
    let modules = |node: &SyntaxNode| {
        node.ancestors()
            .filter_map(ast::Module::cast)
            .collect::<Vec<_>>()
    };
    let mut owners = tree
        .syntax()
        .descendants()
        .filter_map(ast::Fn::cast)
        .filter(|function| {
            function
                .name()
                .is_some_and(|name| name.text() == owner.name.as_str())
                && function.syntax().parent().is_some_and(|parent| {
                    ast::SourceFile::can_cast(parent.kind())
                        || ast::ItemList::can_cast(parent.kind())
                })
        });
    let (Some(owner_fn), None) = (owners.next(), owners.next()) else {
        return None;
    };
    let owner_modules = modules(owner_fn.syntax());
    if owner_modules
        .iter()
        .any(|module| module.attrs().next().is_some())
    {
        return None;
    }
    let mut declarations = tree
        .syntax()
        .descendants()
        .filter_map(ast::Adt::cast)
        .filter(|adt| adt.name().is_some_and(|name| name.text() == type_name));
    let (Some(ast::Adt::Struct(declaration)), None) = (declarations.next(), declarations.next())
    else {
        return None;
    };
    if modules(declaration.syntax()) != owner_modules {
        return None;
    }
    let facts = local_type_equality(&file.source, type_name)?;
    if facts.generic_params || facts.other_attributes {
        return None;
    }
    let mut named = facts
        .fields
        .iter()
        .filter(|candidate| candidate.name.as_deref() == Some(field));
    let (Some(found), None) = (named.next(), named.next()) else {
        return None;
    };
    let ty = BUILTIN_INTEGERS
        .iter()
        .copied()
        .find(|integer| *integer == found.ty.trim())?;
    (!found.has_attributes
        && !type_declared_in_workspace(ty, index)
        && !syntax.macro_may_declare(ty, index)
        && !declaring_file_rebinds(&file.source, ty, false, index))
    .then_some(ty)
}

/// The names a macro in the workspace may declare a type under: every
/// identifier of a macro body or argument that also holds `struct`, `enum`,
/// `union` or `type` (`$` among them when a metavariable may supply the
/// name). `None` when any name may be declared: an unparsed file, or an
/// item-level call of a macro the workspace does not define, whose output
/// no scan reads (#8059 review: `shadow!(u32)` declared a local `u32`).
fn macro_type_names(index: &RustIndex) -> Option<BTreeSet<String>> {
    const ITEM_MACROS: &[&str] = &["thread_local", "compile_error"];
    let mut names = BTreeSet::new();
    let mut defined = BTreeSet::new();
    let mut called = Vec::new();
    for facts in index.files().values() {
        if facts.used_lexical_fallback {
            return None;
        }
        let parse = parse_clean_source_file(&facts.source)?;
        for node in parse.tree().syntax().descendants() {
            if let Some(rules) = ast::MacroRules::cast(node.clone()) {
                defined.insert(rules.name()?.text().to_string());
            } else if let Some(call) = ast::MacroCall::cast(node.clone()) {
                if call.syntax().parent().is_some_and(|parent| {
                    ast::SourceFile::can_cast(parent.kind())
                        || ast::ItemList::can_cast(parent.kind())
                        || ast::MacroItems::can_cast(parent.kind())
                }) {
                    called.push(call.path()?.segment()?.syntax().text().to_string());
                }
            } else if ast::TokenTree::can_cast(node.kind())
                && !node
                    .parent()
                    .is_some_and(|parent| ast::TokenTree::can_cast(parent.kind()))
            {
                let tokens: Vec<String> = node
                    .descendants_with_tokens()
                    .filter_map(|element| element.into_token())
                    .filter(|token| !token.kind().is_trivia())
                    .map(|token| token.text().trim_start_matches("r#").to_string())
                    .collect();
                if tokens
                    .iter()
                    .any(|token| matches!(token.as_str(), "struct" | "enum" | "union" | "type"))
                {
                    names.extend(tokens);
                }
            }
        }
    }
    called
        .iter()
        .all(|name| defined.contains(name) || ITEM_MACROS.contains(&name.as_str()))
        .then_some(names)
}

const BUILTIN_INTEGERS: &[&str] = &[
    "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16", "i32", "i64", "i128", "isize",
];

/// #6692 (RIPR-SPEC-0225 rules 3-4): whether `==` on `type_name` compares
/// its field `field` by value through the derived comparison. `type_name`
/// must have derived equality ([`derived_equality`]); `field` must carry no
/// attribute and its type must compare by value. Anything ripr cannot read
/// fails closed.
fn field_compares_with_derived_equality(type_name: &str, field: &str, index: &RustIndex) -> bool {
    derived_equality(type_name, index).is_some_and(|(facts, declaring)| {
        let mut named = facts
            .fields
            .iter()
            .filter(|candidate| candidate.name.as_deref() == Some(field));
        match (named.next(), named.next()) {
            (Some(found), None) => {
                !found.has_attributes && type_compares_by_value(&found.ty, declaring, index, 0)
            }
            _ => false,
        }
    })
}

/// The equality facts of `type_name` when its `==` is the derived one: it
/// is declared in exactly one parser-backed indexed file, as the one type
/// of that name there, with `PartialEq` in its `#[derive(..)]` list, no
/// other attribute that may change equality, and no indexed file holds an
/// `impl .. PartialEq .. for <type_name>` (gated or not). The declaring
/// file's source comes back too: it decides what the field types' names
/// refer to.
fn derived_equality<'a>(
    type_name: &str,
    index: &'a RustIndex,
) -> Option<(LocalTypeEquality, &'a str)> {
    let mut declaring = index.files().values().filter(|facts| {
        facts.source.contains(type_name)
            && declares_type(&mask_comments_and_strings(&facts.source), type_name)
    });
    let declaring_file = declaring.next()?;
    if declaring.next().is_some() || declaring_file.used_lexical_fallback {
        return None;
    }
    let facts = local_type_equality(&declaring_file.source, type_name)?;
    if !facts.derives.iter().any(|name| name == "PartialEq")
        || facts.other_attributes
        || facts.generic_params
        || facts.qualified_derives
        || declaring_file_rebinds(&declaring_file.source, "PartialEq", false, index)
    {
        return None;
    }
    let manual = index.files().values().any(|file| {
        trait_impl_self_types(&file.source, "PartialEq")
            .iter()
            .any(|self_ty| path_base_name(strip_type_arguments(self_ty)) == Some(type_name))
    });
    (!manual).then_some((facts, &*declaring_file.data().source))
}

/// #7063: whether an early error-variant pin may read `qualifier` as the
/// owner's own error enum and `variant` and `siblings` as its variants:
/// - the owner's file names the one workspace declaration (no import or
///   alias rebinds `qualifier`) and brings none of its variants in by `use`
///   (`use ConfigError::*`, `use ConfigError::MissingEquals as M`), which
///   would let a bare spelling build the variant unseen;
/// - every one of them is a declared variant of `qualifier`, not an
///   associated constant or function that may build any variant;
/// - its `==` is the derived one over fields that each compare by value
///   ([`error_enum_compares_payload`]).
fn error_enum_admits_variant_pin(
    qualifier: &str,
    variant: &str,
    siblings: &[String],
    owner: &FunctionSummary,
    index: &RustIndex,
) -> bool {
    owner_file_names_enum(qualifier, owner, index)
        && derived_equality(qualifier, index).is_some_and(|(facts, _)| {
            std::iter::once(variant)
                .chain(siblings.iter().map(String::as_str))
                .all(|name| facts.variants.iter().any(|declared| declared == name))
        })
        && error_enum_compares_payload(qualifier, index)
}

/// #7063: whether the owner's file names the one workspace declaration of
/// `qualifier` (no import or alias rebinds it) and brings none of its
/// variants in by `use`.
fn owner_file_names_enum(qualifier: &str, owner: &FunctionSummary, index: &RustIndex) -> bool {
    index.files().get(&owner.file).is_some_and(|facts| {
        !declaring_file_rebinds(&facts.source, qualifier, true, index)
            && !file_use_statements(&facts.source).iter().any(|statement| {
                let masked = mask_comments_and_strings(statement);
                whole_word_offsets(&masked, qualifier)
                    .into_iter()
                    .any(|offset| {
                        masked[offset + qualifier.len()..]
                            .trim_start()
                            .starts_with("::")
                    })
            })
    })
}

/// #7063: whether the error variant path `path` (`ConfigError::MissingEquals`
/// or `crate::ConfigError::MissingEquals`, [`local_variant_path`]) built in `owner` names a variant that a
/// declared workspace enum declares, under a name the owner's file does not
/// rebind ([`owner_file_names_enum`]). An alias (`use .. as CE`,
/// `type CE = ..`), `Self::` or a module path names no declared enum here.
pub(in crate::analysis) fn owner_builds_declared_error_variant(
    path: &str,
    owner: &FunctionSummary,
    index: &RustIndex,
) -> bool {
    let Some((qualifier, variant)) = local_variant_path(path) else {
        return false;
    };
    qualifier != "Self"
        && owner_file_names_enum(&qualifier, owner, index)
        && workspace_enum_declares_variant(&qualifier, &variant, index)
}

/// #7063: whether an indexed file declares an enum `qualifier` with a
/// variant `variant`, whatever its `==`.
fn workspace_enum_declares_variant(qualifier: &str, variant: &str, index: &RustIndex) -> bool {
    index.files().values().any(|facts| {
        facts.source.contains(qualifier)
            && declares_type(&mask_comments_and_strings(&facts.source), qualifier)
            && local_type_equality(&facts.source, qualifier)
                .is_some_and(|facts| facts.variants.iter().any(|name| name == variant))
    })
}

/// #7063: whether `qualifier` names one workspace type whose `==` is the
/// derived one over fields that each compare by value, so an equality
/// against one constructed variant compares that variant's payload.
fn error_enum_compares_payload(qualifier: &str, index: &RustIndex) -> bool {
    derived_equality(qualifier, index).is_some_and(|(facts, declaring)| {
        facts.fields.iter().all(|field| {
            !field.has_attributes && type_compares_by_value(&field.ty, declaring, index, 0)
        })
    })
}

/// Whether `type_name` also derives `Clone` (a hand-written `impl Clone`
/// beside it is cfg-gated or otherwise not the one every build runs).
fn derives_clone(type_name: &str, index: &RustIndex) -> bool {
    derived_equality(type_name, index)
        .is_none_or(|(facts, _)| facts.derives.iter().any(|name| name == "Clone"))
}

/// Standard types whose `==` compares by value.
const STD_VALUE_TYPES: &[&str] = &[
    "bool", "char", "str", "String", "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16",
    "i32", "i64", "i128", "isize", "f32", "f64",
];

/// Standard containers whose `==` compares their type arguments by value.
const STD_VALUE_CONTAINERS: &[&str] = &[
    "Option", "Result", "Vec", "VecDeque", "Box", "Rc", "Arc", "BTreeMap", "BTreeSet", "HashMap",
    "HashSet",
];

/// Bind a directly constructed test root's one field to the existing value
/// equality authority. A callee's `&mut Vec<_>` alone does not establish the
/// asserted field: a custom collection can coerce through `DerefMut`.
pub(in crate::analysis::classify) fn projected_collection_has_value_equality(
    constructor: &str,
    field: &str,
    receiver_type: &str,
    owner: &FunctionSummary,
    test: &TestSummary,
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
) -> bool {
    if owner.file != test.file
        || syntax.target_roots(index).root(&owner.file, index).as_ref() != Some(&owner.file)
        || targeted_type_name_is_unresolved(test, index, constructor)
    {
        return false;
    }
    let Some(source) = index
        .files()
        .get(&test.file)
        .map(|facts| &*facts.data().source)
    else {
        return false;
    };
    if !index
        .drop_in_manifests
        .unbound_standard_root(&test.file, "std")
        || !index
            .drop_in_manifests
            .unbound_standard_root(&test.file, "core")
        || index.files().values().any(|facts| {
            let masked = mask_comments_and_strings(&facts.source).replace("r#", "");
            let modules = declared_module_names(&masked);
            let imports = file_use_statements(&masked);
            STD_ROOTS.iter().any(|root| {
                modules.contains(root)
                    || declares_type(&masked, root)
                    || binds_extern_crate(&masked, root)
                    || file_renames_to(&masked, root)
                    || imports
                        .iter()
                        .any(|item| use_statement_binds_name(item, root))
            })
        })
    {
        return false;
    }
    let scope = OwnerScope::new(&owner.name, owner.start_line, &owner.file);
    if !matches!(
        named_or_slice(constructor, test, Some(source), index,
            &|_, name| file_imports_foreign_callee_name(source, name, &index.package_names), scope),
        Some(ReceiverType::Named(name)) if name == constructor
    ) {
        return false;
    }
    let Some(parse) = parse_clean_source_file(source) else {
        return false;
    };
    // The type namespace does not rule out a callable/value that shadows a
    // tuple constructor. A competing local, function, constant or static
    // keeps this deliberately bounded binding unestablished.
    let names_constructor = |name: String| name.strip_prefix("r#").unwrap_or(&name) == constructor;
    if index.files().iter().any(|(file, facts)| {
        let masked = mask_comments_and_strings(&facts.source).replace("r#", "");
        if file_aliases_type(&masked, constructor)
            || file_renames_to(&masked, constructor)
            || !fn_definition_offsets(&masked, constructor).is_empty()
            || file_use_statements(&masked).iter().any(|import| {
                ["test", "cfg"]
                    .iter()
                    .any(|name| use_statement_binds_name(import, name))
            })
            || flattened_use_paths(&masked).iter().any(|import| {
                let segments: Vec<_> = import.path.trim_start_matches("::").split("::").collect();
                if !segments
                    .last()
                    .is_some_and(|name| *name == constructor || *name == "*")
                {
                    return false;
                }
                // A constructor reached through another module may be a
                // callable re-export whose defining bytes were not indexed.
                // Only direct local namespace imports establish this bounded
                // same-file construction; a missing companion cannot clear it.
                !matches!(segments.as_slice(), ["crate" | "self" | "super", _])
            })
        {
            return true;
        }
        let Some(parsed) = parse_clean_source_file(&facts.source) else {
            return true;
        };
        parsed.tree().syntax().descendants().any(|node| {
            // Attribute/derive expansion can also manufacture a binding.
            // This bounded construction admits only the ordinary test
            // harness attributes; expansion is not type-identity evidence.
            ast::Attr::cast(node.clone()).is_some_and(|attr| {
                let text = attr.syntax().text().to_string();
                collapse_whitespace(&text) != "#[test]"
                    && !crate::analysis::facts::cfg_predicates::attribute_is_plain_test_gate(&text)
            }) ||
            // Arbitrary expansion can introduce a constructor binding that
            // the parsed item index never saw. The two observation macros
            // still require their carried canonical binding authority.
            ast::MacroCall::cast(node.clone()).is_some_and(|call| {
                call.path().is_none_or(|path| {
                    let path = collapse_whitespace(&path.syntax().text().to_string());
                    !matches!(
                        path.as_str(),
                        "assert_eq" | "vec" | "std::vec" | "::std::vec"
                    ) && !STD_ROOTED_ASSERT_EQ.contains(&path.as_str())
                })
            }) || (file != &test.file
                && ast::Adt::cast(node.clone())
                    .and_then(|item| item.name())
                    .is_some_and(|name| names_constructor(name.text().to_string())))
                || ast::Fn::cast(node.clone())
                    .and_then(|item| item.name())
                    .is_some_and(|name| names_constructor(name.text().to_string()))
                || ast::Const::cast(node.clone())
                    .and_then(|item| item.name())
                    .is_some_and(|name| names_constructor(name.text().to_string()))
                || ast::Static::cast(node.clone())
                    .and_then(|item| item.name())
                    .is_some_and(|name| names_constructor(name.text().to_string()))
                || ast::IdentPat::cast(node)
                    .and_then(|item| item.name())
                    .is_some_and(|name| names_constructor(name.text().to_string()))
        })
    }) {
        return false;
    }
    let definitions: Vec<_> = parse
        .tree()
        .syntax()
        .descendants()
        .filter_map(ast::Adt::cast)
        .filter(|item| {
            item.name()
                .is_some_and(|name| names_constructor(name.text().to_string()))
        })
        .collect();
    let [ast::Adt::Struct(definition)] = definitions.as_slice() else {
        return false;
    };
    let Some(function) = resolve_owner_fn(parse.tree().syntax(), source, scope) else {
        return false;
    };
    let (Some(owner_scope), Some(test_scope)) = (
        syntax.item_nesting(index, &owner.file, &owner.name, owner.start_line),
        syntax.item_nesting(index, &test.file, &test.name, test.start_line),
    ) else {
        return false;
    };
    if definition.syntax().parent() != function.syntax().parent()
        || !test_scope.modules.starts_with(&owner_scope.modules)
    {
        return false;
    }
    let Some(facts) = local_type_equality(source, constructor) else {
        return false;
    };
    if facts.generic_params || facts.other_attributes {
        return false;
    }
    let selected = if let Ok(position) = field.parse::<usize>() {
        facts
            .fields
            .get(position)
            .filter(|field| field.name.is_none())
    } else {
        facts
            .fields
            .iter()
            .find(|candidate| candidate.name.as_deref() == Some(field))
    };
    let Some(selected) = selected.filter(|field| !field.has_attributes) else {
        return false;
    };
    // Raw type bindings denote the same names. Give the existing lexical
    // equality authority their normalized spelling, without changing source.
    let declaring = mask_comments_and_strings(source).replace("r#", "");
    let standard_vec = |ty: &str| {
        let ty = collapse_whitespace(ty);
        let (path, arguments) = ty.split_once('<')?;
        let arguments = arguments.strip_suffix('>')?;
        let elements = top_level_arguments(arguments);
        let [element] = elements.as_slice() else {
            return None;
        };
        (matches!(path, "Vec" | "std::vec::Vec" | "::std::vec::Vec")
            && INTEGER_TYPES.contains(element)
            && !index.files().values().any(|facts| {
                let masked = mask_comments_and_strings(&facts.source).replace("r#", "");
                ["Vec", *element].iter().any(|name| {
                    declares_type(&masked, name)
                        || file_aliases_type(&masked, name)
                        || file_renames_to(&masked, name)
                        || flattened_use_paths(&masked).iter().any(|import| {
                            let segments: Vec<_> =
                                import.path.trim_start_matches("::").split("::").collect();
                            segments.first() == Some(&"alloc")
                                && segments
                                    .last()
                                    .is_some_and(|last| *last == *name || *last == "*")
                        })
                })
            })
            && !declares_type(&declaring, "Vec")
            && !type_declared_in_workspace("Vec", index)
            && type_compares_by_value(&ty, &declaring, index, 0))
        .then_some(collapse_whitespace(arguments))
    };
    standard_vec(&selected.ty)
        .zip(standard_vec(receiver_type))
        .is_some_and(|(field, receiver)| field == receiver)
}

/// RIPR-SPEC-0225 rule 4: whether a field type compares by value: a
/// standard value type, a reference, tuple, array or standard container of
/// such types, or a workspace type with derived equality whose own fields
/// do too, recursively. A workspace type of a standard name shadows it.
/// A multi-segment path must be rooted in `std`, `core` or `alloc`
/// (`foreign::String` is not `String`), and the declaring file must not
/// bind the base name some other way ([`declaring_file_rebinds`]).
fn type_compares_by_value(ty: &str, declaring: &str, index: &RustIndex, depth: usize) -> bool {
    if depth > EQUALITY_DEPTH_LIMIT {
        return false;
    }
    let ty = ty.trim();
    if let Some(referent) = ty.strip_prefix('&') {
        let referent = referent.trim_start();
        let referent = if referent.starts_with('\'') {
            referent
                .split_once(char::is_whitespace)
                .map_or("", |(_, rest)| rest)
        } else {
            referent
        };
        let referent = referent.strip_prefix("mut ").unwrap_or(referent);
        return type_compares_by_value(referent, declaring, index, depth + 1);
    }
    if let Some(inner) = ty.strip_prefix('(').and_then(|rest| rest.strip_suffix(')')) {
        return top_level_arguments(inner)
            .into_iter()
            .all(|element| type_compares_by_value(element, declaring, index, depth + 1));
    }
    if let Some(inner) = ty.strip_prefix('[').and_then(|rest| rest.strip_suffix(']')) {
        let element = inner.split(';').next().unwrap_or(inner);
        return type_compares_by_value(element, declaring, index, depth + 1);
    }
    let (path, arguments) = match ty.split_once('<') {
        Some((path, rest)) => match rest.strip_suffix('>') {
            Some(arguments) => (path.trim(), Some(arguments)),
            None => return false,
        },
        None => (ty, None),
    };
    let Some(base) = path_base_name(path) else {
        return false;
    };
    if let Some((root, _)) = path.trim_start_matches("::").split_once("::")
        && (!STD_ROOTS.contains(&root.trim()) || workspace_renames_to(index, root.trim()))
    {
        return false;
    }
    let workspace_type = type_declared_in_workspace(base, index);
    if declaring_file_rebinds(declaring, base, workspace_type, index) {
        return false;
    }
    if workspace_type {
        return arguments.is_none()
            && derived_equality(base, index).is_some_and(|(facts, declaring)| {
                facts.fields.iter().all(|field| {
                    !field.has_attributes
                        && type_compares_by_value(&field.ty, declaring, index, depth + 1)
                })
            });
    }
    match arguments {
        None => STD_VALUE_TYPES.contains(&base),
        Some(arguments) => {
            STD_VALUE_CONTAINERS.contains(&base)
                && top_level_arguments(arguments)
                    .into_iter()
                    .all(|argument| type_compares_by_value(argument, declaring, index, depth + 1))
        }
    }
}

/// The roots of standard library paths.
const STD_ROOTS: &[&str] = &["std", "core", "alloc"];

/// Whether `base`, named in a field type of a type declared in the file
/// `declaring`, may denote something other than the standard type (or,
/// when `workspace_type`, the one workspace declaration) of that name. It
/// may when the file renames an item to it (`use x::Thing as String;`),
/// aliases it (`type String = ..;`), or has a `use` that names it or globs
/// (`use foreign::Vec;`, `use foreign::*;`) rooted outside `std`, `core`
/// and `alloc`. A `crate`/`self`/`super` (or own-package) root is a
/// workspace path: it may bring the workspace declaration, but never a
/// standard name's own type, and only while no workspace `use` re-exports
/// the name or a glob from elsewhere. Lexical and file-wide: a `use` in any
/// module of the file counts. Anything else fails closed.
fn declaring_file_rebinds(
    declaring: &str,
    base: &str,
    workspace_type: bool,
    index: &RustIndex,
) -> bool {
    if file_renames_to(declaring, base) || file_aliases_type(declaring, base) {
        return true;
    }
    file_use_statements(declaring).iter().any(|statement| {
        let names = contains_as_whole_word(statement, base);
        if !(names || statement.contains('*')) {
            return false;
        }
        match use_statement_first_segment(statement) {
            Some(root) if STD_ROOTS.contains(&root) => workspace_renames_to(index, root),
            // A workspace path that names a standard name imports some
            // other item of it; a workspace glob brings only workspace items.
            Some(root) if is_workspace_root(root, index) => {
                (names && !workspace_type) || workspace_may_export_other(index, base)
            }
            _ => true,
        }
    })
}

/// `crate`, `self`, `super`, or the crate name of a workspace package.
fn is_workspace_root(root: &str, index: &RustIndex) -> bool {
    matches!(root, "crate" | "self" | "super")
        || index
            .package_names
            .iter()
            .any(|name| name.replace('-', "_") == root)
}

#[cfg(test)]
thread_local! {
    static LIBRARY_IMPORT_EXTRACTIONS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

fn library_import_statements(source: &str) -> Vec<String> {
    #[cfg(test)]
    LIBRARY_IMPORT_EXTRACTIONS.with(|count| count.set(count.get() + 1));
    file_use_statements(source)
}

/// Whether the library whose crate root is `owner_root` may export some other
/// item named `name` than the owner, so that another crate's
/// `use library::name;` could bind it. Fails closed (true) when:
/// - an `include!` was unresolved anywhere, or a file under the package's
///   `src/` has no established crate root (its exports are unread);
/// - a library file uses `include!`, or declares a `const` or `static` named
///   `name`;
/// - a `pub use` in a library file names `name` or globs, and its path is
///   rooted outside `crate`, `self` and `super` (`pub use fastscore::score;`)
///   or passes through a segment that is not a `mod` the library declares
///   (`use fastscore as fs; pub use self::fs::score;`).
pub(super) fn library_may_export_other(index: &RustIndex, owner_root: &Path, name: &str) -> bool {
    let Some(source_dir) = owner_root.parent() else {
        return true;
    };
    if !index.include_limitations.is_empty() {
        return true;
    }
    let src_dirs = BTreeSet::new();
    let mut library = Vec::new();
    for (path, facts) in index.files().iter() {
        if !path.starts_with(source_dir) {
            continue;
        }
        match target_root(path, index, &src_dirs) {
            None => return true,
            Some(root) if root == owner_root => {
                let masked = mask_comments_and_strings(&facts.source);
                let includes = whole_word_offsets(&masked, "include")
                    .into_iter()
                    .any(|offset| {
                        masked[offset + "include".len()..]
                            .trim_start()
                            .starts_with('!')
                    });
                if includes || declares_value_named(&masked, name) {
                    return true;
                }
                library.push(masked);
            }
            Some(_) => {}
        }
    }
    // A module name some `use` or `extern crate` also binds may name that
    // import instead (`pub use fastscore as fs;` beside an unrelated
    // `mod fs`), so it does not count as a library module.
    // Imports depend only on the captured file, not the module being checked.
    // Keep extraction lazy for files the short-circuiting walk never visits.
    let library_uses: Vec<OnceCell<Vec<String>>> =
        (0..library.len()).map(|_| OnceCell::new()).collect();
    let modules: BTreeSet<&str> = library
        .iter()
        .flat_map(|masked| declared_module_names(masked))
        .filter(|module| {
            !library.iter().zip(&library_uses).any(|(masked, uses)| {
                uses.get_or_init(|| library_import_statements(masked))
                    .iter()
                    .any(|statement| use_statement_binds_name(statement, module))
                    || binds_extern_crate(masked, module)
            })
        })
        .collect();
    index.files().iter().any(|(path, facts)| {
        target_root(path, index, &src_dirs).as_deref() == Some(owner_root)
            && public_use_statements(&facts.source)
                .iter()
                .any(|statement| {
                    (contains_as_whole_word(statement, name) || statement.contains('*'))
                        && !reexports_library_module(statement, &modules)
                })
    })
}

/// Whether a `pub use` path stays inside the library: rooted at `crate`,
/// `self` or `super`, with every segment before an imported item or glob a
/// module the library declares, including each path inside a brace group
/// (`pub use self::{fs::score};` reaches through `fs`).
fn reexports_library_module(statement: &str, modules: &BTreeSet<&str>) -> bool {
    let Some(path) = statement.trim_start().strip_prefix("use") else {
        return false;
    };
    let path = path.trim();
    let root_end = path.find("::").unwrap_or(path.len());
    matches!(path[..root_end].trim(), "crate" | "self" | "super")
        && use_tree_stays_local(path[root_end..].trim_start_matches("::"), modules)
}

/// Whether every path in a use tree (the text after its `crate`/`self`/
/// `super` root) passes only through `super` or declared library modules
/// before its imported item, glob or brace group. An unbalanced group fails
/// closed.
fn use_tree_stays_local(tree: &str, modules: &BTreeSet<&str>) -> bool {
    let tree = tree.trim();
    let Some(open) = tree.find('{') else {
        let mut segments: Vec<&str> = tree.split("::").map(str::trim).collect();
        // The last segment is the imported item, glob or `x as y` binding.
        segments.pop();
        return segments
            .iter()
            .all(|segment| *segment == "super" || modules.contains(segment));
    };
    let Some(close) = tree.rfind('}').filter(|close| *close > open) else {
        return false;
    };
    let prefix_local = tree[..open]
        .split("::")
        .map(str::trim)
        .filter(|segment| !segment.is_empty())
        .all(|segment| segment == "super" || modules.contains(segment));
    prefix_local
        && top_level_items(&tree[open + 1..close])
            .iter()
            .all(|item| use_tree_stays_local(item, modules))
}

/// The comma-separated items of a brace group's body, splitting only at
/// depth zero.
fn top_level_items(body: &str) -> Vec<&str> {
    let mut items = Vec::new();
    let mut depth = 0usize;
    let mut start = 0;
    for (offset, character) in body.char_indices() {
        match character {
            '{' => depth += 1,
            '}' => depth = depth.saturating_sub(1),
            ',' if depth == 0 => {
                items.push(&body[start..offset]);
                start = offset + 1;
            }
            _ => {}
        }
    }
    items.push(&body[start..]);
    items
        .into_iter()
        .map(str::trim)
        .filter(|item| !item.is_empty())
        .collect()
}

/// Whether masked source has `extern crate <name>` or `extern crate .. as
/// <name>`.
fn binds_extern_crate(masked: &str, name: &str) -> bool {
    whole_word_offsets(masked, "extern")
        .into_iter()
        .any(|offset| {
            let rest = masked[offset + "extern".len()..].trim_start();
            let Some(rest) = rest.strip_prefix("crate") else {
                return false;
            };
            let declaration = rest.split(';').next().unwrap_or_default();
            let bound = declaration
                .rsplit_once(" as ")
                .map_or(declaration, |(_, alias)| alias)
                .trim();
            bound == name
        })
}

/// Names of `mod <name>` declarations in masked source.
fn declared_module_names(masked: &str) -> Vec<&str> {
    whole_word_offsets(masked, "mod")
        .into_iter()
        .filter_map(|offset| {
            let rest = masked[offset + 3..].trim_start();
            let end = rest
                .find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
                .unwrap_or(rest.len());
            (end > 0).then(|| &rest[..end])
        })
        .collect()
}

/// Whether masked source declares a `const` or `static` (optionally `mut`)
/// named `name`.
fn declares_value_named(masked: &str, name: &str) -> bool {
    ["const", "static"].iter().any(|keyword| {
        whole_word_offsets(masked, keyword)
            .into_iter()
            .any(|offset| {
                let rest = masked[offset + keyword.len()..].trim_start();
                let rest = rest
                    .strip_prefix("mut")
                    .filter(|after| after.starts_with(char::is_whitespace))
                    .map_or(rest, str::trim_start);
                rest.strip_prefix(name).is_some_and(|after| {
                    !after.starts_with(|character: char| {
                        character.is_ascii_alphanumeric() || character == '_'
                    })
                })
            })
    })
}

/// The `use ..;` text of every `pub use` declaration in `source` (plain
/// `pub` only: a `pub(crate)` or `pub(in ..)` import is not visible to
/// another crate).
fn public_use_statements(source: &str) -> Vec<&str> {
    let masked = mask_comments_and_strings(source);
    let bytes = masked.as_bytes();
    let word = |at: usize, text: &str| {
        masked[at..].starts_with(text)
            && (at == 0 || !is_ident_byte(bytes[at - 1]))
            && bytes
                .get(at + text.len())
                .is_none_or(|byte| !is_ident_byte(*byte))
    };
    let mut statements = Vec::new();
    let mut at = 0;
    while let Some(offset) = masked[at..].find("pub") {
        let start = at + offset;
        at = start + 3;
        if !word(start, "pub") {
            continue;
        }
        let use_at = at + (masked[at..].len() - masked[at..].trim_start().len());
        if !word(use_at, "use") {
            continue;
        }
        let Some(end) = masked[use_at..].find(';') else {
            break;
        };
        statements.push(&source[use_at..use_at + end]);
        at = use_at + end;
    }
    statements
}

/// Whether a workspace path may lead to some item named `base` other than
/// its workspace declaration: a workspace `use` rooted outside the standard
/// library and the workspace names `base` or globs (a re-export of a
/// foreign item), or a workspace file renames an item to `base` or aliases
/// a type as `base`.
fn workspace_may_export_other(index: &RustIndex, base: &str) -> bool {
    index.files().values().any(|facts| {
        file_renames_to(&facts.source, base)
            || file_aliases_type(&facts.source, base)
            || file_use_statements(&facts.source).iter().any(|statement| {
                (contains_as_whole_word(statement, base) || statement.contains('*'))
                    && use_statement_first_segment(statement).is_none_or(|root| {
                        !(STD_ROOTS.contains(&root) || is_workspace_root(root, index))
                    })
            })
    })
}

/// Whether any indexed file renames an item to `name` (`extern crate
/// other as std;`).
fn workspace_renames_to(index: &RustIndex, name: &str) -> bool {
    index
        .files()
        .values()
        .any(|facts| file_renames_to(&facts.source, name))
}

/// The comma-separated items of `text` at bracket depth zero.
fn top_level_arguments(text: &str) -> Vec<&str> {
    let mut items = Vec::new();
    let mut depth = 0usize;
    let mut start = 0usize;
    for (offset, byte) in text.bytes().enumerate() {
        match byte {
            b'<' | b'(' | b'[' => depth += 1,
            b'>' | b')' | b']' => depth = depth.saturating_sub(1),
            b',' if depth == 0 => {
                items.push(text[start..offset].trim());
                start = offset + 1;
            }
            _ => {}
        }
    }
    let last = text[start..].trim();
    if !last.is_empty() {
        items.push(last);
    }
    items
}

/// `Window<T>` -> `Window`.
fn strip_type_arguments(self_ty: &str) -> &str {
    self_ty.split('<').next().unwrap_or(self_ty).trim()
}

/// #7066 review: whether `Ok` or `Some` may name something other than the
/// standard variant anywhere in the workspace: a type, `fn`, `const`,
/// `static`, `mod`, `trait` or macro of that name, a variant of a workspace
/// `enum`, a rename to it, or a `use` naming it from outside `std`, `core`
/// and `alloc`. Lexical and workspace-wide, so it fails closed.
fn wrapper_may_be_rebound(wrapper: &str, index: &RustIndex) -> bool {
    index.files().values().any(|facts| {
        facts.source.contains(wrapper) && {
            let masked = mask_comments_and_strings(&facts.source);
            let declared_after = |keyword: &str| {
                whole_word_offsets(&masked, keyword)
                    .into_iter()
                    .any(|offset| {
                        let rest = masked[offset + keyword.len()..].trim_start();
                        let rest = rest.strip_prefix('!').map_or(rest, str::trim_start);
                        starts_with_word(rest, wrapper)
                    })
            };
            declares_type(&masked, wrapper)
                || [
                    "fn",
                    "const",
                    "static",
                    "mod",
                    "trait",
                    "type",
                    "macro_rules",
                ]
                .into_iter()
                .any(declared_after)
                || whole_word_offsets(&masked, "enum")
                    .into_iter()
                    .any(|offset| {
                        let Some(open) = masked[offset..].find('{').map(|at| offset + at) else {
                            return true;
                        };
                        let mut depth = 0usize;
                        let close = masked[open..].char_indices().find_map(|(at, ch)| {
                            match ch {
                                '{' => depth += 1,
                                '}' => {
                                    depth -= 1;
                                    if depth == 0 {
                                        return Some(open + at);
                                    }
                                }
                                _ => {}
                            }
                            None
                        });
                        close.is_none_or(|close| {
                            contains_as_whole_word(&masked[open..close], wrapper)
                        })
                    })
                || file_renames_to(&facts.source, wrapper)
                || file_use_statements(&facts.source).iter().any(|statement| {
                    contains_as_whole_word(statement, wrapper)
                        && use_statement_first_segment(statement)
                            .is_none_or(|root| !STD_ROOTS.contains(&root))
                })
        }
    })
}

/// Whether masked `text` declares a struct, enum or union named `name`.
fn declares_type(text: &str, name: &str) -> bool {
    ["struct", "enum", "union"].iter().any(|keyword| {
        whole_word_offsets(text, keyword)
            .into_iter()
            .any(|offset| starts_with_word(text[offset + keyword.len()..].trim_start(), name))
    })
}

/// Whether masked text declares a `trait` named `name`.
fn declares_trait(masked: &str, name: &str) -> bool {
    whole_word_offsets(masked, "trait")
        .into_iter()
        .any(|offset| starts_with_word(masked[offset + "trait".len()..].trim_start(), name))
}

/// Whether any indexed file declares a trait named `name`.
fn workspace_declares_trait(index: &RustIndex, name: &str) -> bool {
    index.files().values().any(|facts| {
        facts.source.contains(name) && {
            let masked = mask_comments_and_strings(&facts.source);
            whole_word_offsets(&masked, "trait")
                .into_iter()
                .any(|offset| starts_with_word(masked[offset + "trait".len()..].trim_start(), name))
        }
    })
}

/// Whether masked text holds a `|` that is not a binary bitwise OR (#6675):
/// a `||` (lazy OR, or an empty closure), a `|=`, or a pipe in operand
/// position, which opens a closure parameter list (`map(|x| ..)`,
/// `move |x| ..`). A pipe is read as binary only when it directly follows a
/// completed operand: an identifier or number that is not a keyword, or a
/// closing `)`/`]` or `?`. A closure's closing pipe may follow its
/// parameter name, but its opening pipe never follows an operand, so every
/// closure still fails here. A pipe inside a macro invocation's
/// arguments (`matches!(k, A | B)`) or anywhere in a tail that binds with
/// `let` may separate pattern alternatives, which short-circuit, so it is
/// never read as binary. Anything else fails closed.
fn has_non_bitwise_pipe(masked: &str) -> bool {
    const OPERAND_POSITION_KEYWORDS: &[&str] = &[
        "async", "break", "else", "in", "let", "move", "mut", "return", "static", "yield",
    ];
    if !masked.contains('|') {
        return false;
    }
    if contains_as_whole_word(masked, "let") {
        return true;
    }
    let bytes = masked.as_bytes();
    // One entry per open delimiter: whether it opens a macro's arguments.
    let mut delimiters: Vec<bool> = Vec::new();
    for (offset, byte) in bytes.iter().enumerate() {
        match byte {
            b'(' | b'[' | b'{' => {
                let before = masked[..offset].trim_end();
                let opens_macro = before.strip_suffix('!').is_some_and(|head| {
                    head.ends_with(|character: char| {
                        character.is_alphanumeric() || character == '_'
                    })
                });
                delimiters.push(opens_macro);
                continue;
            }
            b')' | b']' | b'}' => {
                delimiters.pop();
                continue;
            }
            b'|' => {}
            _ => continue,
        }
        if delimiters.iter().any(|opens_macro| *opens_macro) {
            return true;
        }
        if matches!(bytes.get(offset + 1), Some(b'|' | b'='))
            || (offset > 0 && bytes[offset - 1] == b'|')
        {
            return true;
        }
        let before = masked[..offset].trim_end();
        let Some(previous) = before.bytes().last() else {
            return true;
        };
        let binary = match previous {
            b')' | b']' | b'?' => true,
            byte if byte.is_ascii_alphanumeric() || byte == b'_' => {
                let start = before
                    .char_indices()
                    .rev()
                    .find(|(_, character)| {
                        !(character.is_ascii_alphanumeric() || *character == '_')
                    })
                    .map_or(0, |(position, character)| position + character.len_utf8());
                !OPERAND_POSITION_KEYWORDS.contains(&&before[start..])
            }
            _ => false,
        };
        if !binary {
            return true;
        }
    }
    false
}

/// `Option`/`Result`/`bool` methods that evaluate or apply an argument only
/// on some inputs.
const CONDITIONAL_COMBINATORS: &[&str] = &[
    "and",
    "and_then",
    "filter",
    "get_or_insert_with",
    "is_none_or",
    "is_ok_and",
    "is_some_and",
    "map",
    "map_err",
    "map_or",
    "map_or_else",
    "ok_or",
    "ok_or_else",
    "or",
    "or_else",
    "then",
    "then_some",
    "unwrap_or",
    "unwrap_or_default",
    "unwrap_or_else",
    "xor",
    "zip",
];

/// Whether `text` is one outer `assert_eq!` invocation that must pass the
/// owner-return execution admission: bare `assert_eq!`, or the same macro
/// called through a drop-in assertion crate (`std::assert_eq!`,
/// `pretty_assertions::assert_eq!`). A qualified drop-in reads as an
/// assertion, so letting it skip this gate would credit an `assert_eq!` that
/// the bare spelling refuses (for example one under `if false`).
fn is_admission_gated_assert_eq(text: &str) -> bool {
    let Some(path) = outer_macro_path(text) else {
        return false;
    };
    let leaf = drop_in_assertion_leaf(&path).unwrap_or(&path);
    leaf.strip_prefix("r#").unwrap_or(leaf) == "assert_eq"
}

/// The outer invocation's path, without interpreting nested operand macros.
fn outer_macro_path(text: &str) -> Option<String> {
    let masked = mask_comments_and_strings(text);
    let mut invocation = masked.trim_start();
    // The parser includes a macro statement's attributes in its fact text.
    // Skip only complete attributes; do not mistake an inner invocation in
    // another oracle's token tree for that oracle's own identity.
    while let Some(attribute) = invocation.strip_prefix('#') {
        let attribute = attribute.trim_start();
        let close = matching_close(attribute, 0, b'[', b']')?;
        invocation = attribute[close + 1..].trim_start();
    }
    let (path, _) = invocation.split_once('!')?;
    Some(path.chars().filter(|c| !c.is_whitespace()).collect())
}

/// #6578: the actual operand and the expected literal of an inline
/// expect-test comparison, `expect![["text"]].assert_eq(actual)`, as
/// `[actual, "text"]`. `expect_test::Expect::assert_eq(&self, actual: &str)`
/// compares `actual` with the literal (indentation-trimmed when it spans
/// lines) and panics on a mismatch unless `UPDATE_EXPECT` is set. Only the
/// bare `expect!` with one string literal (or none, the empty expectation)
/// and one argument; a single leading `&` borrows the actual value and is
/// dropped. `assert_debug_eq` and a qualified `expect_test::expect!` stay
/// `snapshot` / medium (RIPR-SPEC-0231 step 6).
///
/// `expect_file!["path"].assert_eq(actual)` compares `actual` with the
/// committed file's whole text (CRLF read as LF; a missing file reads as
/// "") and panics on a mismatch the same way, so it pins too. Its file is
/// not read: the second operand is the path literal, standing in for a
/// fixed text the analyzer does not inspect. Only a path gate that admits
/// any value of the owner's type (`ReturnPathGate::Any` and the like)
/// accepts that stand-in; a gate that checks the expected value refuses it.
pub(in crate::analysis) fn inline_expect_operands(text: &str) -> Option<[String; 2]> {
    let statement = text.trim().trim_end_matches(';').trim_end();
    let parse = parse_clean_source_file(&format!("fn ripr_expect() {{ {statement}; }}"))?;
    let function = parse
        .tree()
        .syntax()
        .descendants()
        .find_map(ast::Fn::cast)?;
    let body = function.body()?.stmt_list()?;
    let mut statements = body.statements();
    let ast::Stmt::ExprStmt(only) = statements.next()? else {
        return None;
    };
    if statements.next().is_some() || body.tail_expr().is_some() {
        return None;
    }
    let ast::Expr::MethodCallExpr(call) = only.expr()? else {
        return None;
    };
    if call.name_ref()?.text() != "assert_eq" || call.generic_arg_list().is_some() {
        return None;
    }
    let ast::Expr::MacroExpr(receiver) = call.receiver()? else {
        return None;
    };
    let receiver = receiver.macro_call()?;
    receiver.excl_token()?;
    let path = receiver.path()?.syntax().text();
    let golden_file = if path == "expect" {
        false
    } else if path == "expect_file" {
        true
    } else {
        return None;
    };
    let tokens: Vec<_> = receiver
        .token_tree()?
        .syntax()
        .descendants_with_tokens()
        .filter_map(|element| element.into_token())
        .filter(|token| !token.kind().is_trivia())
        .map(|token| (token.kind(), token.text().to_string()))
        .collect();
    let texts: Vec<&str> = tokens.iter().map(|(_, text)| text.as_str()).collect();
    let literal = match texts.as_slice() {
        // `expect_file!["path"]`: one string literal naming the file.
        ["[", path, "]"] if golden_file => {
            if tokens[1].0 != ra_ap_syntax::SyntaxKind::STRING || !is_in_tree_relative_path(path) {
                return None;
            }
            (*path).to_string()
        }
        _ if golden_file => return None,
        ["[", "[", _, "]", "]"] | ["[", _, "]"] => {
            let (kind, text) = &tokens[tokens.len() / 2];
            // expect-test trims a multi-line literal's indentation before
            // comparing, so its raw text is not the compared value.
            if *kind != ra_ap_syntax::SyntaxKind::STRING || text.contains('\n') {
                return None;
            }
            text.clone()
        }
        ["[", "[", "]", "]"] | ["[", "]"] => "\"\"".to_string(),
        _ => return None,
    };
    let mut arguments = call.arg_list()?.args();
    let actual = arguments.next()?;
    if arguments.next().is_some() {
        return None;
    }
    let actual = match actual {
        ast::Expr::RefExpr(borrowed) => {
            if borrowed.mut_token().is_some() || borrowed.raw_token().is_some() {
                return None;
            }
            borrowed.expr()?.syntax().text().to_string()
        }
        other => other.syntax().text().to_string(),
    };
    Some([actual, literal])
}

/// #6578 review: `expect_file!` resolves its path against the test's own
/// source directory, so a relative path without `..` names a file under the
/// crate, which the commit fixes. An absolute path (`/tmp/x`, a drive-letter
/// path, a UNC `\\\\host`), a home-relative `~` or any `..` segment may name text
/// produced outside the commit, so it lends no pin. `path` is the literal's
/// source text, quotes and any raw-string hashes included.
fn is_in_tree_relative_path(path: &str) -> bool {
    let inner = path
        .trim_start_matches('r')
        .trim_matches('#')
        .trim_matches('"');
    let absolute = inner.starts_with(['/', '\\', '~']) || inner.as_bytes().get(1) == Some(&b':');
    // A non-raw literal's escapes (`\u{2e}\u{2e}/w.txt`) decode to segments
    // this text check cannot see, so any escape refuses.
    let escaped = !path.starts_with('r') && inner.contains('\\');
    !inner.is_empty()
        && !absolute
        && !escaped
        && !inner.split(['/', '\\']).any(|segment| segment == "..")
}

/// #6578 review: whether a test file renames an import from `std::fs` or
/// `std::env` (`use std::fs::write as save;`), which would let a bare
/// `save(..)` write the golden or set `UPDATE_EXPECT` unseen by
/// [`test_may_write_files`]. Fail-closed: any such rename refuses.
fn file_renames_fs_or_env_import(source: &str) -> bool {
    let masked = mask_comments_and_strings(source);
    // Word tokens rather than a statement prefix: a `use` may follow `{`, an
    // item's `}`, an attribute or `pub(crate)` inside the same `;` fragment.
    masked.split(';').any(|statement| {
        let mut words = statement
            .split(|c: char| !(c.is_alphanumeric() || c == '_'))
            .filter(|word| !word.is_empty())
            .skip_while(|word| *word != "use");
        if words.next().is_none() {
            return false;
        }
        let tree: Vec<&str> = words.collect();
        tree.iter().any(|word| matches!(*word, "fs" | "env")) && tree.contains(&"as")
    })
}

/// Whether an expect-test comparison's receiver is `expect_file!`.
fn is_golden_file_comparison(text: &str) -> bool {
    let masked = mask_comments_and_strings(text);
    let compact: String = masked.chars().filter(|c| !c.is_whitespace()).collect();
    compact.starts_with("expect_file!")
}

/// #6578 review: whether a test body may write the file a golden-file
/// comparison reads. Comments and strings are masked; anything that may
/// create, overwrite, copy or rename a file, or turn on expect-test's
/// `UPDATE_EXPECT` rewrite, counts. A bare `write(..)`/`create(..)` call
/// counts too, since `use std::fs::write;` makes it the file write.
/// Fail-closed: a test that writes some other file also lends no pin.
fn test_may_write_files(body: &str) -> bool {
    let masked = mask_comments_and_strings(body);
    let compact: String = masked.chars().filter(|c| !c.is_whitespace()).collect();
    const WRITERS: &[&str] = &[
        "fs::write",
        "fs::copy",
        "fs::rename",
        "fs::hard_link",
        "File::create",
        "File::options",
        "OpenOptions",
        "UPDATE_EXPECT",
        "set_var",
        // A subprocess, a symlink or a persisted temp file may also produce it.
        "Command",
        "symlink",
        "soft_link",
        "persist",
    ];
    WRITERS.iter().any(|writer| compact.contains(writer))
        || [
            "write(",
            "create(",
            "copy(",
            "rename(",
            "write::<",
            "create::<",
            "copy::<",
            "rename::<",
        ]
        .iter()
        .any(|call| {
            // A turbofish (`write::<_, _>(..)`) is the same call.
            compact.match_indices(call).any(|(at, _)| {
                let before = &compact[..at];
                // A bare or path-qualified call (`save::write(`, `<File>::create(`,
                // `fs_err::write(`) may write; a method call or `io::copy(`
                // between readers and writers does not.
                if before.ends_with("::") {
                    return !before.ends_with("io::");
                }
                before.chars().next_back().is_none_or(|previous| {
                    !(previous.is_alphanumeric() || matches!(previous, '_' | '.' | ':'))
                })
            })
        })
}

/// #8097: whether the expected operand's value comes from reading a file
/// that the same test body may write. The read may be inline
/// (`fs::read_to_string(..)`) or through plain bindings
/// (`let want = fs::read_to_string(..); assert_eq!(.., want)`), following
/// a few identifier hops and trivial wrappers (`&want`, `want.as_str()`).
/// Fail-closed with [`test_may_write_files`]: any writer in the body
/// taints any file read, and a file-scope renamed `std::fs`/`std::env`
/// import taints it too, as for the golden-file guard above. A writer in
/// a helper outside the test body is not visible here and remains a
/// known limitation.
fn expected_reads_written_file(
    test: &TestSummary,
    renamed_fs_import: bool,
    expected: &str,
) -> bool {
    let may_write = test_may_write_files(&test.body) || renamed_fs_import;
    if !may_write {
        return false;
    }
    let reads_file = |text: &str| {
        let compact: String = mask_comments_and_strings(text)
            .chars()
            .filter(|c| !c.is_whitespace())
            .collect();
        ["read_to_string", "fs::read", "read_to_end", "File::open"]
            .iter()
            .any(|marker| compact.contains(marker))
    };
    if reads_file(expected) {
        return true;
    }
    // Reduce wrappers (`&want`, `&mut want`, `(want)`, `want.as_str()`,
    // `want.clone()`, ...) until stable, leaving the plain identifier
    // whose binding may hold the file read.
    let reduce = |mut text: &str| -> String {
        loop {
            let before = text;
            text = text
                .trim()
                .trim_start_matches('&')
                .trim_start_matches('*')
                .trim();
            if text.starts_with("mut ") {
                text = text[4..].trim_start();
            }
            if text.starts_with('(') && text.ends_with(')') {
                text = text[1..text.len() - 1].trim();
            }
            for suffix in [".as_str()", ".clone()", ".trim()", ".as_ref()", ".unwrap()"] {
                if let Some(stripped) = text.strip_suffix(suffix) {
                    text = stripped.trim();
                }
            }
            if text == before {
                return text.to_string();
            }
        }
    };
    let operand = reduce(expected);
    // A method/parse chain rooted at a plain binding
    // (`want.trim().parse::<i32>().unwrap()`) still draws its value from
    // that binding.
    let operand = if is_plain_identifier(&operand) {
        operand
    } else {
        let root: String = operand
            .chars()
            .take_while(|c| c.is_alphanumeric() || *c == '_')
            .collect();
        if root.is_empty() || !is_plain_identifier(&root) {
            return false;
        }
        root
    };
    // Follow plain-identifier bindings a few hops. Every statement that
    // binds the current identifier counts (`let [mut] x = ..`, `x = ..`,
    // also inside blocks); any of them reading a file settles it, and
    // each plain-identifier right-hand side is followed in turn.
    let masked = mask_comments_and_strings(&test.body);
    let statements: Vec<&str> = masked.split(';').collect();
    let binding_rhs = |statement: &str, ident: &str| -> Option<String> {
        // A `let` binding may sit behind a block opener fragment; a bare
        // assignment may sit behind a block opener too.
        let rest = match statement.find("let ") {
            Some(at) => {
                let rest = statement[at + 4..].trim_start();
                rest.strip_prefix("mut ").unwrap_or(rest).to_string()
            }
            None => {
                let at = statement.match_indices(ident).find_map(|(at, _)| {
                    // A field assignment (`holder.want = ..`) does not
                    // bind the plain local `want`.
                    let before_ok = at == 0
                        || !statement[..at]
                            .chars()
                            .next_back()
                            .is_some_and(|c| c.is_alphanumeric() || c == '_' || c == '.');
                    before_ok.then_some(at)
                })?;
                statement[at..].to_string()
            }
        };
        let after = rest.trim_start().strip_prefix(ident)?;
        let boundary = after.trim_start();
        // Skip an optional `: Type` annotation before the `=`.
        let boundary = if let Some(annotated) = boundary.strip_prefix(':') {
            let eq = annotated.find('=')?;
            if annotated[eq..].starts_with("==") {
                return None;
            }
            &annotated[eq..]
        } else {
            boundary
        };
        if !boundary.starts_with('=') || boundary.starts_with("==") {
            return None;
        }
        Some(boundary[1..].to_string())
    };
    let mut frontier = vec![operand];
    let mut visited: Vec<String> = Vec::new();
    for _ in 0..4 {
        let mut next: Vec<String> = Vec::new();
        for ident in &frontier {
            for statement in &statements {
                let Some(rhs) = binding_rhs(statement, ident) else {
                    continue;
                };
                if reads_file(&rhs) || reads_file(statement) {
                    return true;
                }
                let reduced = reduce(&rhs);
                let reduced = if is_plain_identifier(&reduced) {
                    reduced
                } else {
                    reduced
                        .chars()
                        .take_while(|c| c.is_alphanumeric() || *c == '_')
                        .collect()
                };
                if is_plain_identifier(&reduced)
                    && !visited.contains(&reduced)
                    && !next.contains(&reduced)
                {
                    next.push(reduced);
                }
            }
        }
        visited.extend(frontier);
        if next.is_empty() {
            return false;
        }
        frontier = next;
    }
    false
}

/// RIPR-SPEC-0197: the compared operands of a plain `assert!(lhs == rhs)`
/// or of the assertion twin of a terminal Err-return guard
/// `if lhs != rhs { return Err(..) }` (RIPR-SPEC-0154). The condition must
/// be one top-level `==`; any other top-level comparison, `&&`, `||`, a
/// closure or a negated condition refuses. Owned, since a guard's operands
/// are read from its synthesized twin.
pub(in crate::analysis) fn equality_condition_operands(text: &str) -> Option<[String; 2]> {
    let condition = if is_plain_macro(text, "assert") {
        outer_assertion_condition(text)?
    } else {
        let (condition, twin) = err_return_guard_twin(text)?;
        // `if !a == b` is `(!a) == b`; never read it as `!(a == b)`.
        if condition.starts_with('!') {
            return None;
        }
        outer_assertion_condition(&twin)?
    };
    top_level_equality_operands(&condition)
}

/// The two sides of a condition's single top-level `==`, split outside
/// parentheses, brackets, braces, comments and strings.
fn top_level_equality_operands(condition: &str) -> Option<[String; 2]> {
    let condition = condition.trim();
    if condition.starts_with('!') {
        return None;
    }
    let masked = mask_comments_and_strings(condition);
    let bytes = masked.as_bytes();
    let mut depth = 0usize;
    let mut split = None;
    let mut at = 0;
    while let Some(&byte) = bytes.get(at) {
        let next = bytes.get(at + 1).copied();
        match byte {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth = depth.checked_sub(1)?,
            _ if depth > 0 => {}
            // `<`, `>`, `<=`, `>=`, `->`, `=>`, shifts, generics, closures
            // and `||` all refuse.
            b'<' | b'>' | b'|' => return None,
            b'&' if next == Some(b'&') => return None,
            b'!' if next == Some(b'=') => return None,
            b'=' if next == Some(b'=') => {
                if split.replace(at).is_some() {
                    return None;
                }
                at += 2;
                continue;
            }
            // An assignment or compound assignment is not a comparison.
            b'=' => return None,
            _ => {}
        }
        at += 1;
    }
    if depth != 0 {
        return None;
    }
    let split = split?;
    let left = condition.get(..split)?.trim();
    let right = condition.get(split + 2..)?.trim();
    (!left.is_empty() && !right.is_empty()).then(|| [left.to_string(), right.to_string()])
}

/// Whether `text` is one plain `assert_eq!` invocation: not
/// `debug_assert_eq!` (compiled out in release tests), not a crate's own
/// `*_assert_eq!`, not a path-qualified or repeated one.
/// The text is exactly one unqualified invocation of `macro_name`.
pub(in crate::analysis) fn is_plain_macro(text: &str, macro_name: &str) -> bool {
    let masked = mask_comments_and_strings(text);
    let invocations = macro_invocations(&masked);
    let [(name, _)] = invocations.as_slice() else {
        return false;
    };
    *name == macro_name
        && masked
            .find(macro_name)
            .is_some_and(|offset| !masked[..offset].trim_end().ends_with(':'))
}

/// [`is_plain_macro`], or the same single invocation under a `std` or `core`
/// root (`std::assert_eq!(..)`, `::core::assert_eq!(..)`). Admission
/// credits the qualified form only when [`OwnerPinSyntax`] proves the root
/// unrebound (#7857).
fn is_plain_or_std_macro(text: &str, macro_name: &str) -> bool {
    is_plain_macro(text, macro_name) || std_rooted_macro_path(text, macro_name).is_some()
}

/// The whitespace-free path of every `std`/`core`-rooted `assert_eq!` call
/// under `root` (#7857).
fn std_rooted_assert_eq_calls(root: &ra_ap_syntax::SyntaxNode) -> BTreeSet<String> {
    root.descendants()
        .filter_map(ast::MacroCall::cast)
        .filter_map(|call| call.path())
        .map(|path| {
            path.syntax()
                .text()
                .to_string()
                .split_whitespace()
                .collect::<String>()
        })
        .filter(|path| STD_ROOTED_ASSERT_EQ.contains(&path.as_str()))
        .collect()
}

/// The whitespace-free path (`std::assert_eq`, `::core::assert_eq`) when
/// `text` is one `macro_name` invocation under a `std` or `core` root.
fn std_rooted_macro_path(text: &str, macro_name: &str) -> Option<String> {
    let masked = mask_comments_and_strings(text);
    let invocations = macro_invocations(&masked);
    let [(name, _)] = invocations.as_slice() else {
        return None;
    };
    let offset = masked.find(macro_name)?;
    let root: String = masked[..offset]
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect();
    (*name == macro_name && matches!(root.as_str(), "std::" | "core::" | "::std::" | "::core::"))
        .then(|| format!("{root}{macro_name}"))
}

/// `assert_eq!` whose only nested macros are `expansion` (`format!`, which
/// [`helper_arguments::rendered_template_call`] reads, or `vec!`, which
/// [`single_element_index`] reads).
fn is_assert_eq_over(text: &str, expansion: &str) -> bool {
    let masked = mask_comments_and_strings(text);
    let invocations = macro_invocations(&masked);
    let [(first, _), nested @ ..] = invocations.as_slice() else {
        return false;
    };
    *first == "assert_eq"
        && !nested.is_empty()
        && nested.iter().all(|(name, _)| *name == expansion)
        && masked
            .find("assert_eq")
            .is_some_and(|offset| !masked[..offset].trim_end().ends_with(':'))
}

/// Whether a macro other than a known non-binding one mentions `name` in
/// its arguments: `let_assert!(Ok(p) = ..)` and similar macros bind
/// patterns ripr does not read.
fn bound_by_macro(masked: &str, name: &str) -> bool {
    macro_invocations(masked)
        .into_iter()
        .filter(|(macro_name, _)| !is_bounded_macro(macro_name))
        .any(|(_, delimiter)| {
            let (open, close) = match masked.as_bytes()[delimiter] {
                b'(' => (b'(', b')'),
                b'[' => (b'[', b']'),
                _ => (b'{', b'}'),
            };
            let end = matching_close(masked, delimiter, open, close).unwrap_or(masked.len());
            contains_as_whole_word(&masked[delimiter..end], name)
        })
}

/// Whether the file renames some item to `name` (`use a::b as name;`,
/// `extern crate a as name;`), so `name` may not be the item it looks like.
/// Related-test reach shares the single-file rename refusal (#7067).
///
/// Only an `as` inside a `use` or `extern crate` item renames: a cast
/// (`letters as u32`) or a qualified path (`<T as Clone>::clone`) in plain
/// code binds no name, so it does not make `u32` or `Clone` something
/// else. Lexical, so a `use` in any module, function body or macro body
/// counts. An `as` inside a macro invocation's arguments or an attribute
/// counts too: the macro may expand it into a `use`
/// (`import!(other::Fake as u32);`), and ripr does not expand macros.
pub(in crate::analysis) fn file_renames_to(source: &str, name: &str) -> bool {
    if !source.contains(name) {
        return false;
    }
    let masked = mask_comments_and_strings(source);
    let spans = rename_item_spans(&masked);
    whole_word_offsets(&masked, "as").into_iter().any(|offset| {
        starts_with_word(masked[offset + "as".len()..].trim_start(), name)
            && spans.iter().any(|span| span.contains(&offset))
    })
}

/// The byte spans in `masked` where an `as` may rename: every `use ..;`
/// and `extern crate ..;` item, from the keyword to its `;` (or the end of
/// the text when the `;` is missing, which keeps an unterminated item
/// renaming), every macro invocation's delimited arguments and every
/// attribute (`#[..]`, `#![..]`). An unmatched delimiter runs to the end of
/// the text, which fails closed.
fn rename_item_spans(masked: &str) -> Vec<std::ops::Range<usize>> {
    let bytes = masked.as_bytes();
    let delimited = |open_at: usize| {
        let (open, close) = match bytes[open_at] {
            b'(' => (b'(', b')'),
            b'[' => (b'[', b']'),
            _ => (b'{', b'}'),
        };
        open_at..matching_close(masked, open_at, open, close).unwrap_or(masked.len())
    };
    // Any `name!` followed by a delimiter, whatever the name: a Unicode or
    // keyword-like macro name still expands its arguments (#7926 review).
    // A negation such as `if !(x)` adds a span too, which only refuses more.
    let macro_spans = masked.match_indices('!').filter_map(|(bang, _)| {
        let named = masked[..bang]
            .trim_end()
            .chars()
            .next_back()
            .is_some_and(|character| character.is_alphanumeric() || character == '_');
        let after = masked[bang + 1..].trim_start();
        (named && after.starts_with(['(', '[', '{'])).then(|| delimited(masked.len() - after.len()))
    });
    let attribute_spans = masked.match_indices('#').filter_map(|(hash, _)| {
        let after = masked[hash + 1..].trim_start();
        let after = after.strip_prefix('!').map_or(after, str::trim_start);
        after
            .starts_with('[')
            .then(|| delimited(masked.len() - after.len()))
    });
    let mut spans: Vec<std::ops::Range<usize>> = macro_spans.chain(attribute_spans).collect();
    spans.extend(rename_statement_spans(masked));
    spans
}

/// The `use ..;` and `extern crate ..;` items of [`rename_item_spans`].
fn rename_statement_spans(masked: &str) -> Vec<std::ops::Range<usize>> {
    let item_end = |from: usize| {
        masked[from..]
            .find(';')
            .map_or(masked.len(), |end| from + end)
    };
    // `impl Trait + use<'a>` (precise capturing) is not an import.
    let mut spans: Vec<std::ops::Range<usize>> = whole_word_offsets(masked, "use")
        .into_iter()
        .filter(|offset| !masked[offset + "use".len()..].trim_start().starts_with('<'))
        // A raw identifier `r#use` is not the keyword (#7936).
        .filter(|offset| !masked[..*offset].ends_with("r#"))
        .map(|offset| offset..item_end(offset))
        .collect();
    spans.extend(
        whole_word_offsets(masked, "extern")
            .into_iter()
            .filter(|offset| {
                starts_with_word(masked[offset + "extern".len()..].trim_start(), "crate")
            })
            .map(|offset| offset..item_end(offset)),
    );
    spans
}

/// An alias cannot be excluded merely because its spelling differs from an
/// indexed impl's self type. Retain a named refusal instead.
pub(in crate::analysis) fn targeted_name_is_alias(index: &RustIndex, name: &str) -> bool {
    index
        .files()
        .values()
        .any(|facts| file_aliases_type(&facts.source, name) || file_renames_to(&facts.source, name))
}

pub(in crate::analysis) fn targeted_type_name_is_unresolved(
    test: &TestSummary,
    index: &RustIndex,
    name: &str,
) -> bool {
    if name == "Self" || targeted_name_is_alias(index, name) {
        return true;
    }
    let Some(facts) = index.files().get(&test.file) else {
        return true;
    };
    let Some(parse) = parse_clean_source_file(&facts.source) else {
        return true;
    };
    let Some(function) = resolve_owner_fn(
        parse.tree().syntax(),
        &facts.source,
        OwnerScope::new(&test.name, test.start_line, &test.file),
    ) else {
        return true;
    };
    function
        .syntax()
        .descendants()
        .filter_map(ast::TypeParam::cast)
        .any(|parameter| {
            parameter
                .name()
                .is_some_and(|parameter| parameter.text() == name)
        })
}

/// Admit only an actual parser-established free owner through the existing
/// binding authority. Candidate ambiguity is reported by the selector first;
/// unindexed/unsupported competing definitions still refuse here.
pub(in crate::analysis) fn targeted_free_call_reaches_owner(
    test: &TestSummary,
    owner: &FunctionSummary,
    prefix: Option<&str>,
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
) -> bool {
    if !owner.item.has_body
        || !matches!(pin_call(owner, index), Some(PinCall::Bare))
        || other_definition_competes(owner, index, CallKind::Bare, None)
        || index
            .files()
            .get(&owner.file)
            .is_none_or(|facts| facts.used_lexical_fallback)
        || index
            .files()
            .get(&test.file)
            .is_none_or(|facts| facts.used_lexical_fallback)
    {
        return false;
    }
    let Some(facts) = index.files().get(&test.file) else {
        return false;
    };
    let binding = FreeOwnerBinding {
        name: &owner.name,
        owner_file: &owner.file,
        owner_start_line: owner.start_line,
    };
    if let Some(prefix) = prefix {
        return binding.path_reaches_owner(prefix, test, &facts.source, index, syntax);
    }
    let masked_body = mask_comments_and_strings(&test.body);
    !syntax
        .item_nesting(index, &owner.file, &owner.name, owner.start_line)
        .is_none_or(|owner| owner.cfg_gated)
        && !syntax.file_cfg_gated(index, &owner.file)
        && !test_body_shadows_owner(test, &owner.name)
        && !binds_outside_let(&masked_body, &owner.name)
        && !bound_by_macro(&masked_body, &owner.name)
        && !file_renames_to(&facts.source, &owner.name)
        && binding.bare_call_reaches_owner(test, &facts.source, index, syntax)
}

/// Whether the file declares a type alias `type name`.
fn file_aliases_type(source: &str, name: &str) -> bool {
    if !source.contains(name) {
        return false;
    }
    let masked = mask_comments_and_strings(source);
    whole_word_offsets(&masked, "type")
        .into_iter()
        .any(|offset| starts_with_word(masked[offset + "type".len()..].trim_start(), name))
}

/// #7097: one file's module scopes — the file top plus every inline
/// module with a body — each with its direct `use`s and the items that
/// can take a value call. A bare call resolves through the test's own
/// scope only, so ancestor scopes are consulted solely as glob targets.
#[derive(Clone, Debug, Default)]
struct FileScopes {
    scopes: Vec<ModuleScope>,
    /// Every `fn` in the file, at any depth, for test-fn ancestry.
    fns: Vec<ScopeFn>,
}

/// #7097: one `fn` item's name and byte span.
#[derive(Clone, Debug)]
struct ScopeFn {
    name: String,
    start: u32,
    end: u32,
}

/// #7097: one module scope: its inline-module stack from the file top
/// (empty at file top), its byte span, every direct `use` flattened,
/// every direct value-taking item's name, and macro text that may emit
/// or mention one.
#[derive(Clone, Debug)]
struct ModuleScope {
    stack: Vec<String>,
    start: u32,
    end: u32,
    uses: Vec<UsePath>,
    twins: Vec<String>,
    macro_args: Vec<String>,
    macro_defs: Vec<String>,
}

impl OwnerPinSyntax {
    /// #7097: out-of-line module children, built once per run from the
    /// recorded module edges. Two children under one (parent, name) —
    /// cfg'd alternatives — resolve to neither.
    fn mod_children(&self, index: &RustIndex) -> &BTreeMap<(PathBuf, String), Option<PathBuf>> {
        self.mod_children.get_or_init(|| {
            let mut children: BTreeMap<(PathBuf, String), Option<PathBuf>> = BTreeMap::new();
            for (child, facts) in index.files().iter() {
                // Only the innermost edge names the direct parent: earlier
                // edges are the ancestor chain, which every descendant
                // repeats.
                let Some(edge) = facts.role_provenance.edges.last() else {
                    continue;
                };
                if edge.kind != SourceRoleProvenanceEdgeKind::Module {
                    continue;
                }
                let Some(name) = module_declaration_name(&edge.declaration) else {
                    continue;
                };
                children
                    .entry((edge.parent.clone(), name))
                    .and_modify(|slot| {
                        if slot.as_ref() != Some(child) {
                            *slot = None;
                        }
                    })
                    .or_insert_with(|| Some(child.clone()));
            }
            children
        })
    }

    /// #7097: `file`'s scope table, parsed once per run and shared:
    /// lookups clone the `Arc`, never the table (#7176 review).
    fn file_scopes(&self, index: &RustIndex, file: &Path) -> Option<Arc<FileScopes>> {
        if let Some(known) = self.file_scopes.borrow().get(file) {
            return known.clone();
        }
        let scopes = index
            .files()
            .get(file)
            .and_then(|facts| build_file_scopes(&facts.source))
            .map(Arc::new);
        self.file_scopes
            .borrow_mut()
            .insert(file.to_path_buf(), scopes.clone());
        scopes
    }
}

/// #7097: the scope table of `source`, or `None` when it does not parse.
fn build_file_scopes(source: &str) -> Option<FileScopes> {
    let parse = parse_clean_source_file(source)?;
    let tree = parse.tree();
    let end: u32 = tree.syntax().text_range().end().into();
    let mut scopes = FileScopes::default();
    scopes.push_scope(tree.syntax(), Vec::new(), 0, end);
    for func in tree.syntax().descendants().filter_map(ast::Fn::cast) {
        if let Some(name) = func.name() {
            let text = name.text().to_string();
            let range = func.syntax().text_range();
            let start: u32 = range.start().into();
            let end: u32 = range.end().into();
            scopes.fns.push(ScopeFn {
                name: strip_raw(&text).to_string(),
                start,
                end,
            });
        }
    }
    Some(scopes)
}

impl FileScopes {
    /// Record `container` (the file root or an inline module body) as one
    /// scope, then recurse into its direct child modules.
    fn push_scope(&mut self, container: &SyntaxNode, stack: Vec<String>, start: u32, end: u32) {
        let mut scope = ModuleScope {
            stack,
            start,
            end,
            uses: Vec::new(),
            twins: Vec::new(),
            macro_args: Vec::new(),
            macro_defs: Vec::new(),
        };
        let mut children = Vec::new();
        for item in container.children().filter_map(ast::Item::cast) {
            scope.absorb(&item);
            if let ast::Item::Module(module) = &item
                && let Some(body) = module.item_list()
                && let Some(name) = module.name()
            {
                let text = name.text().to_string();
                let mut stack = scope.stack.clone();
                stack.push(strip_raw(&text).to_string());
                let range = module.syntax().text_range();
                let start: u32 = range.start().into();
                let end: u32 = range.end().into();
                children.push((body.syntax().clone(), stack, start, end));
            }
        }
        self.scopes.push(scope);
        for (container, stack, start, end) in children {
            self.push_scope(&container, stack, start, end);
        }
    }

    /// The test's own module scope: exact scope first, from the test
    /// fn's own span — line spans coincide for same-line siblings (`mod
    /// outer { mod nested { ... #[test] fn check() ... } }` on one line),
    /// where the line alone resolves to the file top. A macro-generated
    /// test has no matching `fn` node, so it keeps the line-span fallback
    /// to the module its invocation expands in. Duplicate `fn` nodes are
    /// already refused by assertion admission; here they fail closed.
    fn scope_of_test(&self, source: &str, test: &TestSummary) -> Option<&ModuleScope> {
        let wanted = strip_raw(&test.name);
        let line_of = |offset: u32| {
            source
                .get(..offset as usize)
                .map(|prefix| prefix.matches('\n').count() + 1)
        };
        let found: Vec<&ScopeFn> = self
            .fns
            .iter()
            .filter(|func| {
                func.name == wanted
                    && line_of(func.start).is_some_and(|start| start <= test.end_line)
                    && line_of(func.end).is_some_and(|end| test.start_line <= end)
            })
            .collect();
        if let [func] = found.as_slice() {
            let offset = func.start;
            return self
                .scopes
                .iter()
                .filter(|scope| scope.start <= offset && offset <= scope.end)
                .max_by_key(|scope| scope.stack.len());
        }
        if found.is_empty() {
            return self.scope_at(source, test.start_line);
        }
        None
    }

    /// The deepest scope containing `line` (1-based) in `source`: the
    /// test's own module, or the file top.
    fn scope_at(&self, source: &str, line: usize) -> Option<&ModuleScope> {
        let mut offset = 0usize;
        for _ in 1..line {
            let Some(relative) = source.get(offset..)?.find('\n') else {
                break;
            };
            offset = offset.saturating_add(relative + 1);
        }
        let offset = u32::try_from(offset).ok()?;
        self.scopes
            .iter()
            .filter(|scope| scope.start <= offset && offset <= scope.end)
            .max_by_key(|scope| scope.stack.len())
    }

    /// The scope with exactly `stack`, when the file declares it.
    fn scope_with_stack(&self, stack: &[String]) -> Option<&ModuleScope> {
        self.scopes.iter().find(|scope| scope.stack == stack)
    }
}

impl ModuleScope {
    /// One direct item: `use`s flatten, value-taking items record their
    /// name, and macros record the text that may emit or mention one. A
    /// direct `fn` is never a twin: the establish gate already refused
    /// every other `fn` of the name, so a remaining one is the owner
    /// itself. Type-only items (`mod`, `trait`, `type`, `enum`, `union`,
    /// non-tuple `struct`) share no namespace with a value call.
    fn absorb(&mut self, item: &ast::Item) {
        match item {
            ast::Item::Use(item) => {
                self.uses
                    .extend(flattened_use_paths(&item.syntax().text().to_string()));
            }
            ast::Item::Static(item) => self.twin_name(item.name()),
            ast::Item::Const(item) => self.twin_name(item.name()),
            ast::Item::Struct(item) => {
                // Tuple and unit structs take the value namespace (a unit
                // struct's constructor collides with an imported fn, E0255;
                // braced structs do not conflict — both probed with rustc,
                // #7176 review).
                if matches!(
                    item.kind(),
                    ast::StructKind::Tuple(_) | ast::StructKind::Unit
                ) {
                    self.twin_name(item.name());
                }
            }
            ast::Item::ExternBlock(block) => {
                // Extern items hang under the EXTERN_ITEM_LIST node, not
                // under the block itself (#7176 review).
                if let Some(list) = block.extern_item_list() {
                    for child in list.extern_items() {
                        match &child {
                            ast::ExternItem::Fn(item) => self.twin_name(item.name()),
                            ast::ExternItem::Static(item) => self.twin_name(item.name()),
                            _ => {}
                        }
                    }
                }
            }
            // An invocation may emit the name from its arguments (`emit!(weight)`);
            // only the token tree counts, never the macro's own name.
            ast::Item::MacroCall(call) => {
                if let Some(tree) = call.token_tree() {
                    self.macro_args.push(tree.syntax().text().to_string());
                }
            }
            // A definition may hardcode the twin; its text decides, as for
            // types (#6948). The parse is error-free, so no item is unparsed.
            ast::Item::MacroRules(rules) => {
                self.macro_defs.push(rules.syntax().text().to_string());
            }
            ast::Item::MacroDef(def) => {
                self.macro_defs.push(def.syntax().text().to_string());
            }
            _ => {}
        }
    }

    fn twin_name(&mut self, name: Option<ast::Name>) {
        if let Some(name) = name {
            let text = name.text().to_string();
            self.twins.push(strip_raw(&text).to_string());
        }
    }

    /// Whether the scope holds a twin of `name`: a value-taking item, a
    /// macro invocation mentioning it, or a macro definition spelling a
    /// twin declaration of it.
    fn has_twin(&self, name: &str) -> bool {
        let name = strip_raw(name);
        self.twins.iter().any(|twin| twin == name)
            || self
                .macro_args
                .iter()
                .any(|text| contains_as_whole_word(&mask_comments_and_strings(text), name))
            || self
                .macro_defs
                .iter()
                .any(|text| declares_value_twin(&mask_comments_and_strings(text), name))
    }
}

/// #7097: where a `use` is read from: its file, that file's source,
/// and the inline-module stack of the scope holding it.
#[derive(Clone, Copy)]
struct ScopeContext<'a> {
    file: &'a Path,
    source: &'a str,
    stack: &'a [String],
}

/// #7097: the module name a `mod name;` declaration binds, or `None`
/// when the declaration is unreadable.
fn module_declaration_name(declaration: &str) -> Option<String> {
    let mut words = declaration
        .split_whitespace()
        .skip_while(|word| *word != "mod");
    words.next()?;
    let name = words.next()?.trim_end_matches(';');
    let name = strip_raw(name);
    (!name.is_empty() && is_plain_identifier(name)).then(|| name.to_string())
}

/// Whether masked text declares a value-taking item of `name` outside a
/// `fn`: a `static`/`const` (any form) or a tuple struct. Type-only
/// items share no namespace with a value call.
fn declares_value_twin(masked: &str, name: &str) -> bool {
    let name = strip_raw(name);
    ["static", "const"].iter().any(|keyword| {
        whole_word_offsets(masked, keyword)
            .into_iter()
            .any(|offset| {
                let rest = masked[offset + keyword.len()..].trim_start();
                // `static mut name` carries a qualifier between the keyword
                // and the name (#7176 review); `const` never does.
                let rest = if *keyword == "static" {
                    skip_mut_qualifier(rest)
                } else {
                    rest
                };
                strip_item_name(rest, name).is_some()
            })
    }) || whole_word_offsets(masked, "struct")
        .into_iter()
        .any(|offset| {
            strip_item_name(masked[offset + "struct".len()..].trim_start(), name)
                .and_then(skip_generics)
                // Tuple structs take the call; unit structs collide with an
                // imported fn (E0255, rustc-probed); braced structs share
                // no namespace with the call (#7176 review).
                .is_some_and(|after| after.starts_with('(') || after.starts_with(';'))
        })
}

/// The text after a `mut` qualifier, when `rest` opens with one as a
/// whole word. Anything else (including `mutx`) passes through.
fn skip_mut_qualifier(rest: &str) -> &str {
    let Some(after) = rest.strip_prefix("mut") else {
        return rest;
    };
    if after.starts_with(|c: char| c.is_ascii_alphanumeric() || c == '_') {
        return rest;
    }
    after.trim_start()
}

/// Whether the test body declares a value-taking item of `name`. A body
/// `fn` or `let` is already refused (`test_body_shadows_owner`); a
/// `static` (plain or `mut`), `const`, tuple or unit struct there shadows
/// every import the same way. Items in a nested block or `fn` cannot reach
/// the call, so counting them over-refuses (residual).
fn body_defines_value_twin(body: &str, name: &str) -> bool {
    declares_value_twin(&mask_comments_and_strings(body), name)
}

/// The text after an item name of `name` (raw marker dropped), or `None`
/// when `rest` names something else.
fn strip_item_name<'a>(rest: &'a str, name: &str) -> Option<&'a str> {
    let rest = strip_raw(rest);
    let after = rest.strip_prefix(name)?;
    if after.starts_with(|character: char| character.is_ascii_alphanumeric() || character == '_') {
        return None;
    }
    Some(after.trim_start())
}

/// The text after one `<...>` generic group, or `text` when it opens
/// with none; `None` when the group never closes.
fn skip_generics(text: &str) -> Option<&str> {
    let Some(rest) = text.strip_prefix('<') else {
        return Some(text);
    };
    let mut depth = 1u32;
    for (offset, byte) in rest.bytes().enumerate() {
        match byte {
            b'<' => depth += 1,
            b'>' => {
                depth -= 1;
                if depth == 0 {
                    return Some(rest[offset + 1..].trim_start());
                }
            }
            _ => {}
        }
    }
    None
}

/// #7097: the `use`s of `uses` that bind `name` explicitly, and the glob
/// imports. A rename to the name (`use x::y as name`) binds it too, so
/// it counts here; other aliases bind another name. The test file's own
/// renames refuse file-wide already (`file_renames_to`).
fn partition_name_uses<'a>(
    uses: &'a [UsePath],
    name: &str,
) -> (Vec<&'a UsePath>, Vec<&'a UsePath>) {
    let name = strip_raw(name);
    let mut bindings = Vec::new();
    let mut globs = Vec::new();
    for use_path in uses {
        if use_path.path.ends_with("::*") {
            globs.push(use_path);
            continue;
        }
        let binds = match use_path.alias.as_deref() {
            Some(alias) => strip_raw(alias) == name,
            None => use_path
                .path
                .rsplit("::")
                .next()
                .is_some_and(|terminal| strip_raw(terminal) == name),
        };
        if binds {
            bindings.push(use_path);
        }
    }
    (bindings, globs)
}

/// #7097: the crate root file `file` composes under: the outermost
/// recorded module edge's parent, or the file itself. Unlike
/// [`target_root`], this ignores the workspace-wide disabled switch and
/// the recognized-target shape: the manifest authority
/// (`import_names`) validates the root itself, and the assertion and
/// file rules already refused include-composed and unresolved files
/// before this gate runs — so an unrelated unresolvable module
/// elsewhere keeps other owners pinned, as the file rule requires.
fn composed_root(file: &Path, index: &RustIndex) -> PathBuf {
    index
        .files()
        .get(file)
        .and_then(|facts| {
            facts
                .role_provenance
                .edges
                .first()
                .map(|edge| edge.parent.clone())
        })
        .unwrap_or_else(|| file.to_path_buf())
}

/// Whether a `use` root segment names a workspace package: the manifest
/// name or its crate identifier (`foo-bar` imports as `foo_bar`).
fn crate_names_package(segment: &str, packages: &BTreeSet<String>) -> bool {
    packages
        .iter()
        .any(|name| name == segment || name.replace('-', "_") == segment)
}

/// An identifier with its raw marker dropped.
fn strip_raw(text: &str) -> &str {
    text.strip_prefix("r#").unwrap_or(text)
}

/// #7097: split a binding `use` path into its root segment and module
/// segments (raw markers dropped): `demo::scale::weight` gives
/// (`demo`, [`scale`]). `None` when the path binds another name, has a
/// single segment (an extern crate in edition 2018+, never the owner
/// fn), or renames another item to the name.
fn split_binding_use<'a>(use_path: &'a UsePath, name: &str) -> Option<(&'a str, Vec<&'a str>)> {
    if use_path
        .alias
        .as_deref()
        .is_some_and(|alias| strip_raw(alias) != strip_raw(name))
    {
        return None;
    }
    let stripped = use_path.path.strip_prefix("::").unwrap_or(&use_path.path);
    let segments: Vec<&str> = stripped.split("::").map(strip_raw).collect();
    let [first, rest @ ..] = segments.as_slice() else {
        return None;
    };
    let terminal = rest.last().copied()?;
    if strip_raw(terminal) != strip_raw(name) {
        return None;
    }
    Some((*first, rest[..rest.len() - 1].to_vec()))
}

/// #7097: split a glob `use` path into its root segment and full module
/// prefix: `demo::scale::*` gives (`demo`, [`scale`]).
fn split_glob_prefix(path: &str) -> Option<(&str, Vec<&str>)> {
    let stripped = path.strip_prefix("::").unwrap_or(path);
    let prefix = stripped.strip_suffix("::*")?;
    let segments: Vec<&str> = prefix.split("::").map(strip_raw).collect();
    let [first, rest @ ..] = segments.as_slice() else {
        return None;
    };
    Some((*first, rest.to_vec()))
}

/// #7097: `pop_super`, climbing past the file top into the declaring
/// parent through module edges: an out-of-line `tests.rs` at file-top
/// stack `[]` climbs `super::` into the inline scope holding its `mod`
/// declaration (#7176 review). Include edges never climb (a textual
/// paste has no parent module). Each pop consumes one `super`, so the
/// walk terminates.
fn pop_super_across_files<'a>(
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
    file: &Path,
    stack: &[String],
    first: &str,
    segments: &[&'a str],
) -> Option<(PathBuf, Vec<String>, Vec<&'a str>)> {
    let mut file = file.to_path_buf();
    let mut module = stack.to_vec();
    if first == "super" {
        climb_one_level(index, syntax, &mut file, &mut module)?;
    }
    let supers = segments
        .iter()
        .take_while(|segment| **segment == "super")
        .count();
    for _ in 0..supers {
        climb_one_level(index, syntax, &mut file, &mut module)?;
    }
    if segments[supers..]
        .iter()
        .any(|segment| matches!(*segment, "self" | "super" | "crate"))
    {
        return None;
    }
    Some((file, module, segments[supers..].to_vec()))
}

/// #7097: climb one `super` level: pop the inline stack, or — at the
/// file top — continue from the inline scope holding this file's `mod`
/// declaration in its declaring parent. Include edges never climb.
fn climb_one_level(
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
    file: &mut PathBuf,
    stack: &mut Vec<String>,
) -> Option<()> {
    if stack.pop().is_some() {
        return Some(());
    }
    let facts = index.files().get(file.as_path())?;
    let edge = facts.role_provenance.edges.last()?;
    if edge.kind != SourceRoleProvenanceEdgeKind::Module {
        return None;
    }
    let parent = index.files().get(&edge.parent)?;
    let scopes = syntax.file_scopes(index, &edge.parent)?;
    *stack = scopes
        .scope_at(&parent.data().source, edge.line)?
        .stack
        .clone();
    *file = edge.parent.clone();
    Some(())
}

/// #7097: walk `segments` from (`file`, `stack`): each names an inline
/// child module or a composed out-of-line `mod`. Returns the target's
/// file and file-relative inline stack, or `None` when a step is
/// unplaced or ambiguous. Each step consumes a segment, so module
/// cycles cannot loop.
fn resolve_module_path(
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
    file: &Path,
    stack: &[String],
    segments: &[&str],
) -> Option<(PathBuf, Vec<String>)> {
    let mut file = file.to_path_buf();
    let mut stack = stack.to_vec();
    for segment in segments {
        let scopes = syntax.file_scopes(index, &file)?;
        let mut child = stack.clone();
        child.push(segment.to_string());
        if scopes.scope_with_stack(&child).is_some() {
            stack = child;
            continue;
        }
        let key = (file.clone(), segment.to_string());
        file = syntax.mod_children(index).get(&key)?.clone()?;
        stack = Vec::new();
    }
    Some((file, stack))
}

/// Whether another workspace definition of the owner's name could take a
/// call by that name. A bare call competes with every other module-level
/// function of the name; a method call competes with every other method of
/// the name that has a body (overrides, inherent methods of other types,
/// other traits' methods), except a pure `(**self).name(..)` forward, which
/// dispatches to the same method on the pointee. A definition whose item
/// container is unknown (lexical fallback) always competes, and so does a
/// `fn name` the parser never indexed (inside a `macro_rules!` body).
///
/// An associated `T::name(..)` call (#6617, RIPR-SPEC-0172) competes with
/// every other definition of the name that is not a module-level or local
/// function: inherent and trait-impl functions of any type, trait items,
/// unknown containers, and every unindexed `fn name`. A free function
/// cannot be the target of a type path, so it never competes.
fn other_definition_competes(
    owner: &FunctionSummary,
    index: &RustIndex,
    kind: CallKind,
    settled_per_test: Option<&OwnerCallIdentity>,
) -> bool {
    let method = kind == CallKind::Method;
    let associated = kind == CallKind::Associated;
    let name = owner.name.as_str();
    let is_owner = |file: &PathBuf, line: usize| *file == owner.file && line == owner.start_line;
    let indexed_competes = index.functions().iter().any(|function| {
        if function.name != name || is_owner(&function.file, function.start_line) {
            return false;
        }
        match function.item.container {
            FunctionContainer::Unknown => true,
            FunctionContainer::Local => false,
            FunctionContainer::Free => {
                !method
                    && !associated
                    && !settled_per_test.is_some_and(|identity| identity.settles(function))
            }
            _ if associated => true,
            _ => {
                method
                    && function.item.has_self_param
                    && function.item.has_body
                    && !is_self_forward(&function.body, name)
            }
        }
    });
    if indexed_competes {
        return true;
    }
    index.files().iter().any(|(path, facts)| {
        // Masking only erases text, so a file whose raw source has no
        // `fn <name>` has none after masking either; skip the mask.
        if !facts.source.contains(name) || fn_definition_offsets(&facts.source, name).is_empty() {
            return false;
        }
        let masked = mask_comments_and_strings(&facts.source);
        fn_definition_offsets(&masked, name)
            .into_iter()
            .any(|offset| {
                let line = masked[..offset]
                    .bytes()
                    .filter(|byte| *byte == b'\n')
                    .count()
                    + 1;
                let indexed = facts
                    .functions
                    .iter()
                    .any(|function| function.name == name && function.start_line == line)
                    || is_owner(path, line);
                if indexed {
                    return false;
                }
                // An unindexed definition cannot be placed: it may be an
                // associated function of any type.
                if associated {
                    return true;
                }
                let Some(definition) = unindexed_definition(&facts.source, &masked, offset) else {
                    return true;
                };
                match definition.body {
                    None => false,
                    Some(body) => definition.has_self == method && !is_self_forward(body, name),
                }
            })
    })
}

struct UnindexedDefinition<'a> {
    has_self: bool,
    body: Option<&'a str>,
}

/// The parameter receiver and body of a `fn` definition the parser did not
/// index, read from its text.
fn unindexed_definition<'a>(
    source: &'a str,
    masked: &str,
    offset: usize,
) -> Option<UnindexedDefinition<'a>> {
    let params = offset + masked[offset..].find('(')?;
    let params_close = matching_close(masked, params, b'(', b')')?;
    let first_param = masked[params + 1..params_close]
        .split(',')
        .next()
        .unwrap_or("")
        .trim();
    let receiver = first_param.trim_start_matches('&').trim_start();
    let receiver = if receiver.starts_with('\'') {
        receiver
            .split_once(char::is_whitespace)
            .map_or("", |(_, rest)| rest.trim_start())
    } else {
        receiver
    };
    let receiver = receiver
        .strip_prefix("mut ")
        .map_or(receiver, str::trim_start);
    let has_self =
        receiver == "self" || receiver.starts_with("self:") || receiver.starts_with("self ");
    let mut depth = 0usize;
    for (relative, byte) in masked[params_close..].bytes().enumerate() {
        match byte {
            b'(' | b'[' => depth += 1,
            b')' | b']' => depth = depth.saturating_sub(1),
            b';' if depth == 0 => {
                return Some(UnindexedDefinition {
                    has_self,
                    body: None,
                });
            }
            b'{' if depth == 0 => {
                let open = params_close + relative;
                let close = matching_close(masked, open, b'{', b'}')?;
                return Some(UnindexedDefinition {
                    has_self,
                    body: Some(&source[open..=close]),
                });
            }
            _ => {}
        }
    }
    None
}

/// Whether `body` only forwards to the same method on the pointee:
/// `{ (**self).name(..) }` or `{ (*self).name(..) }`.
fn is_self_forward(body: &str, name: &str) -> bool {
    let masked = mask_comments_and_strings(body);
    let Some(open) = masked.find('{') else {
        return false;
    };
    let Some(close) = matching_close(&masked, open, b'{', b'}') else {
        return false;
    };
    let inner = body[open + 1..close].trim();
    ["(**self).", "(*self)."].iter().any(|prefix| {
        inner
            .strip_prefix(prefix)
            .is_some_and(|call| matches!(owner_call_shape(call, name), Some(CallShape::Bare)))
    })
}

/// Offsets of the `fn` keyword in every `fn <name>` definition.
fn fn_definition_offsets(masked: &str, name: &str) -> Vec<usize> {
    whole_word_offsets(masked, "fn")
        .into_iter()
        .filter(|offset| {
            let rest = masked[offset + 2..].trim_start();
            rest.strip_prefix(name).is_some_and(|after| {
                let after = after.trim_start();
                after.starts_with('(') || after.starts_with('<')
            })
        })
        .collect()
}

/// The name-keyed workspace scans [`OwnerReturnPin::establish`] runs for an
/// owner that files outside the index could still change (#5320). Each scan
/// is monotone in the files it sees, so once the index decides it, more
/// files cannot change it; an undecided scan names what a file must spell.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub(in crate::analysis) struct PinScopeNeeds {
    /// No other indexed `fn <name>` competes yet; another file's could.
    pub(in crate::analysis) competing_definitions: bool,
    /// The receiver type is not declared in the index yet; another file's
    /// `struct`/`enum`/`union` of this name would declare it.
    pub(in crate::analysis) receiver_type: Option<String>,
    /// A trait method's receivers come from every `impl <trait> for` block.
    pub(in crate::analysis) trait_impls: Option<String>,
    /// A test binding `let x = T::ctor()` pins this receiver type only when
    /// exactly one inherent `impl T { fn ctor }` exists; another file's
    /// `impl` block for a same-named type changes that count.
    pub(in crate::analysis) constructor_type: Option<String>,
}

/// What [`PinScopeNeeds`] says for `owner` over `index`.
pub(in crate::analysis) fn pin_scope_needs(
    owner: &FunctionSummary,
    index: &RustIndex,
) -> PinScopeNeeds {
    let mut needs = PinScopeNeeds::default();
    if !owner.item.has_body {
        return needs;
    }
    let kind = match (&owner.item.container, owner.item.has_self_param) {
        (FunctionContainer::Free, false) => CallKind::Bare,
        // #6617: another file's declaration of `T` (or a `mod`, `trait` or
        // `type` of its name) changes `associated_owner_type`, so the type
        // is always a need, declared yet or not.
        (FunctionContainer::Inherent { self_ty }, false) => {
            if !is_associated_type_name(self_ty) {
                return needs;
            }
            needs.receiver_type = Some(self_ty.clone());
            CallKind::Associated
        }
        (FunctionContainer::Inherent { self_ty }, true)
        | (FunctionContainer::TraitImpl { self_ty, .. }, true) => {
            needs.constructor_type = path_base_name(self_ty).map(str::to_string);
            if declared_receiver(self_ty, index).is_none() {
                // A shape `declared_receiver` never accepts stays refused
                // whatever else is indexed.
                if self_ty.starts_with(['&', '[', '(', '*']) || self_ty.starts_with("dyn ") {
                    return needs;
                }
                let Some(base) = path_base_name(self_ty) else {
                    return needs;
                };
                needs.receiver_type = Some(base.to_string());
            }
            CallKind::Method
        }
        (FunctionContainer::Trait { trait_name }, true) => {
            needs.trait_impls = Some(trait_name.clone());
            CallKind::Method
        }
        _ => return needs,
    };
    // Same rivals `establish` settles per test (#6544): once indexed they no
    // longer refuse, but files that define more of them still widen scope.
    let identity = match kind {
        CallKind::Bare => super::call_identity::shared_owner_call_identity(index, owner),
        CallKind::Method | CallKind::Associated => None,
    };
    needs.competing_definitions =
        !other_definition_competes(owner, index, kind, identity.as_deref());
    needs
}

/// #6617: a self type an associated-function pin can name: one CamelCase
/// identifier (no generics, path, reference or `Self`).
fn is_associated_type_name(self_ty: &str) -> bool {
    is_plain_identifier(self_ty)
        && self_ty != "Self"
        && self_ty.starts_with(|character: char| character.is_ascii_uppercase())
}

/// #6617: the type an associated-function owner's `T::name(..)` call must
/// name. `T` must be one CamelCase identifier that exactly one `struct`,
/// `enum` or `union` in the index declares, and no indexed file may give
/// the name to a `mod`, `trait` or `type` alias: a module `T` would turn
/// `T::name(..)` into a free-function path, and a second declaration or an
/// alias could be the `T` a test imports. Anything else refuses.
fn associated_owner_type(self_ty: &str, index: &RustIndex) -> Option<String> {
    if !is_associated_type_name(self_ty) {
        return None;
    }
    let mut declarations = 0usize;
    for facts in index.files().values() {
        if whole_word_offsets(&facts.source, self_ty).is_empty() {
            continue;
        }
        let masked = mask_comments_and_strings(&facts.source);
        declarations += ["struct", "enum", "union"]
            .iter()
            .map(|keyword| {
                whole_word_offsets(&masked, keyword)
                    .into_iter()
                    .filter(|offset| {
                        starts_with_word(masked[offset + keyword.len()..].trim_start(), self_ty)
                    })
                    .count()
            })
            .sum::<usize>();
        let names_other_item = ["mod", "trait", "type"].iter().any(|keyword| {
            whole_word_offsets(&masked, keyword)
                .into_iter()
                .any(|offset| {
                    starts_with_word(masked[offset + keyword.len()..].trim_start(), self_ty)
                })
        });
        if names_other_item || declarations > 1 {
            return None;
        }
    }
    (declarations == 1).then(|| self_ty.to_string())
}

/// #6617: whether a test body may rebind `type_name` itself: any nested
/// `use`, or a `struct`/`enum`/`union`/`type`/`trait`/`mod` item of that
/// name.
fn body_rebinds_type(masked: &str, type_name: &str) -> bool {
    !whole_word_offsets(masked, "use").is_empty()
        || ["struct", "enum", "union", "type", "trait", "mod"]
            .iter()
            .any(|keyword| {
                whole_word_offsets(masked, keyword)
                    .into_iter()
                    .any(|offset| {
                        starts_with_word(masked[offset + keyword.len()..].trim_start(), type_name)
                    })
            })
}

/// The receiver type an `impl` block's self type names, when it is one this
/// module can match a test binding against.
fn declared_receiver(self_ty: &str, index: &RustIndex) -> Option<ReceiverType> {
    if is_byte_slice_type(self_ty) {
        return Some(ReceiverType::ByteSlice);
    }
    if self_ty.starts_with(['&', '[', '(', '*']) || self_ty.starts_with("dyn ") {
        return None;
    }
    let base = path_base_name(self_ty)?;
    type_declared_in_workspace(base, index).then(|| ReceiverType::Named(base.to_string()))
}

/// Every receiver type with an `impl .. <trait_name> for <type>` block in
/// the workspace.
fn trait_impl_receivers(trait_name: &str, index: &RustIndex) -> Vec<ReceiverType> {
    let mut receivers = Vec::new();
    for facts in index.files().values() {
        for self_ty in trait_impl_self_types(&facts.source, trait_name) {
            if let Some(receiver) = declared_receiver(&self_ty, index)
                && !receivers.contains(&receiver)
            {
                receivers.push(receiver);
            }
        }
    }
    receivers
}

/// The base names of the self types `source` implements `trait_name` for:
/// the names whose declarations and inherent constructors decide a default
/// method's receivers (#5320).
pub(in crate::analysis) fn trait_impl_self_type_names(
    source: &str,
    trait_name: &str,
) -> BTreeSet<String> {
    trait_impl_self_types(source, trait_name)
        .iter()
        .filter_map(|self_ty| path_base_name(self_ty).map(str::to_string))
        .collect()
}

/// The self types of the `impl .. <trait_name> for <type>` headers in
/// `source`.
fn trait_impl_self_types(source: &str, trait_name: &str) -> Vec<String> {
    let mut self_types = Vec::new();
    if whole_word_offsets(source, trait_name).is_empty() {
        return self_types;
    }
    let masked = mask_comments_and_strings(source);
    for offset in whole_word_offsets(&masked, "impl") {
        let Some(header_end) = masked[offset..].find(['{', ';']) else {
            continue;
        };
        let header = collapse_whitespace(&masked[offset + "impl".len()..offset + header_end]);
        let header = strip_leading_generics(&header);
        let Some((trait_path, self_ty)) = header.split_once(" for ") else {
            continue;
        };
        let self_ty = self_ty.split(" where ").next().unwrap_or(self_ty).trim();
        if path_base_name(trait_path.trim()) == Some(trait_name) {
            self_types.push(self_ty.to_string());
        }
    }
    self_types
}

fn strip_leading_generics(header: &str) -> &str {
    let header = header.trim_start();
    if !header.starts_with('<') {
        return header;
    }
    let mut depth = 0usize;
    for (offset, byte) in header.bytes().enumerate() {
        match byte {
            b'<' => depth += 1,
            b'>' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return header[offset + 1..].trim_start();
                }
            }
            _ => {}
        }
    }
    header
}

fn type_declared_in_workspace(name: &str, index: &RustIndex) -> bool {
    let declares = |text: &str| {
        ["struct", "enum", "union"].iter().any(|keyword| {
            whole_word_offsets(text, keyword)
                .into_iter()
                .any(|offset| starts_with_word(text[offset + keyword.len()..].trim_start(), name))
        })
    };
    // The raw check is a superset of the masked one; mask only on a hit.
    index.files().values().any(|facts| {
        facts.source.contains(name)
            && declares(&facts.source)
            && declares(&mask_comments_and_strings(&facts.source))
    })
}

/// The type the test binds `receiver` to: every `let` that binds the name
/// is a simple `let [mut] receiver [: T] = ..;` whose type ripr can read,
/// and all of them agree. Other uses of the binding (borrows, arguments,
/// reassignments) cannot change a Rust binding's type; another binding of
/// the same name in a pattern ripr does not read (a closure parameter, a
/// `for` or match-arm pattern, a destructuring `let`, a nested `fn`)
/// leaves the type unestablished.
fn test_receiver_type(
    test: &TestSummary,
    receiver: &str,
    test_source: Option<&str>,
    index: &RustIndex,
    imports_foreign: ForeignImport<'_>,
    owner: OwnerScope<'_>,
    syntax: &OwnerPinSyntax,
) -> Option<ReceiverType> {
    let Some(bindings) = receiver_let_bindings(test, receiver) else {
        let annotation = parameter_annotation(test, receiver)?;
        return named_or_slice(
            &annotation,
            test,
            test_source,
            index,
            imports_foreign,
            owner,
        );
    };
    if bindings.is_empty() {
        // No `let` binds the receiver, so it is a path expression: a unit
        // struct names its own value (`Unit.advance()`).
        return binding_type(
            &format!("= {receiver}"),
            test,
            test_source,
            index,
            imports_foreign,
            owner,
            syntax,
        );
    }
    let mut bound: Option<ReceiverType> = None;
    for binding in bindings {
        let receiver_type = binding_type(
            binding,
            test,
            test_source,
            index,
            imports_foreign,
            owner,
            syntax,
        )?;
        match &bound {
            None => bound = Some(receiver_type),
            Some(existing) if *existing == receiver_type => {}
            Some(_) => return None,
        }
    }
    bound
}

/// #6578: the declared type of a test parameter `[mut] receiver: T` that
/// nothing in the body rebinds. rstest fills an unmarked parameter from the
/// same-named `#[fixture]`, and its annotation types the receiver the way
/// `let receiver: T = ..;` does: whatever the fixture builds, the call
/// dispatches on `T`. Whether the test runs its body at all is the owner-pin
/// syntax gate's decision, not this one. `None` when the name is not such a
/// parameter or a `let`, closure, `for` or match pattern binds it again.
fn parameter_annotation(test: &TestSummary, receiver: &str) -> Option<String> {
    let masked = mask_comments_and_strings(&test.body);
    let fns = whole_word_offsets(&masked, "fn");
    let [fn_at] = fns.as_slice() else {
        return None;
    };
    let (open, close) = fn_param_range(&masked, *fn_at)?;
    let mut blanked = masked.clone();
    blanked.replace_range(open + 1..close, &" ".repeat(close - open - 1));
    if binds_outside_let(&blanked, receiver) || let_patterns_bind(&blanked, receiver) {
        return None;
    }
    let parse = parse_clean_source_file(&test.body)?;
    let function = parse
        .tree()
        .syntax()
        .descendants()
        .find_map(ast::Fn::cast)?;
    let list = function.param_list()?;
    if list.self_param().is_some() {
        return None;
    }
    let mut annotation = None;
    for param in list.params() {
        let ast::Pat::IdentPat(pat) = param.pat()? else {
            continue;
        };
        if pat.name()?.text() != receiver {
            continue;
        }
        if pat.ref_token().is_some() || pat.pat().is_some() || annotation.is_some() {
            return None;
        }
        annotation = Some(param.ty()?.syntax().text().to_string());
    }
    annotation
}

/// The text after the name in every `let [mut] receiver [: T] = ..;` of the
/// test body (the optional annotation and the initializer), or `None` when
/// the name may be bound some other way ripr does not read.
fn receiver_let_bindings<'a>(test: &'a TestSummary, receiver: &str) -> Option<Vec<&'a str>> {
    let masked = mask_comments_and_strings(&test.body);
    if binds_outside_let(&masked, receiver) {
        return None;
    }
    let mut bindings = Vec::new();
    for offset in whole_word_offsets(&masked, "let") {
        let pattern_start = offset + "let".len();
        let Some(relative_end) = top_level_semicolon(&masked[pattern_start..]) else {
            // A `let` ripr cannot bound (an `if let` closing its block):
            // its pattern may still bind the name.
            let rest = &masked[pattern_start..];
            let end = rest.find(['=', '{']).unwrap_or(rest.len());
            if contains_as_whole_word(&rest[..end], receiver) {
                return None;
            }
            continue;
        };
        let statement_end = pattern_start + relative_end;
        let statement = &masked[pattern_start..statement_end];
        let pattern_end = statement
            .match_indices('=')
            .map(|(position, _)| position)
            .find(|position| {
                !matches!(statement.as_bytes().get(position + 1), Some(b'=' | b'>'))
                    && !matches!(
                        statement.as_bytes().get(position.wrapping_sub(1)),
                        Some(b'=' | b'!' | b'<' | b'>')
                    )
            })
            .unwrap_or(statement.len());
        if !contains_as_whole_word(&statement[..pattern_end], receiver) {
            continue;
        }
        let pattern = statement[..pattern_end].trim();
        let pattern = pattern
            .strip_prefix("mut ")
            .map_or(pattern, str::trim_start);
        let annotation = pattern.strip_prefix(receiver)?.trim_start();
        if !(annotation.is_empty() || annotation.starts_with(':')) {
            return None;
        }
        // The name's whole-word offset in the pattern (`let mut m`: not
        // the `m` inside `mut`).
        let name_at = whole_word_offsets(&statement[..pattern_end], receiver)
            .first()
            .copied()?;
        let binding = &test.body[pattern_start..statement_end];
        bindings.push(&binding[name_at + receiver.len()..]);
    }
    Some(bindings)
}

/// #6974: the initializer of `operand` when it is a plain identifier the
/// test binds exactly once, by an immutable `let operand [: T] = <init>;`,
/// and uses nowhere else but as a whole operand of its own `assert_eq!`
/// assertions after that `let`. Any other use (a `mut` binding, a borrow,
/// a method call, an argument, a second binding, a use before the `let`)
/// could change or replace the value, so it fails closed.
///
/// `scalar` (cell-0094): the owner returns a primitive scalar, so the
/// binding is `Copy` with no interior mutability and nothing can change
/// it. Its other uses may then also sit in any other std assertion macro
/// after the `let` (`assert!(b > 3); assert_eq!(b, 12);`), and statements
/// may stand between the `let` and the assertion. Every use still lies in
/// an assertion, so no item, pattern or macro outside one can rebind it.
fn let_bound_owner_call<'a>(
    test: &'a TestSummary,
    assertion: &OracleFact,
    operand: &str,
    name: &str,
    scalar: bool,
) -> Option<&'a str> {
    let operand = operand.trim();
    if !is_plain_identifier(operand) || operand == name || operand == "self" {
        return None;
    }
    let bindings = receiver_let_bindings(test, operand)?;
    let [binding] = bindings.as_slice() else {
        return None;
    };
    let binding: &'a str = binding;
    let masked = mask_comments_and_strings(&test.body);
    let binding_at = binding.as_ptr() as usize - test.body.as_ptr() as usize;
    let let_at = *whole_word_offsets(&masked[..binding_at], "let").last()?;
    // #7066 review: an attribute (`#[cfg(any())] let total = ..;`) may
    // compile the binding away, leaving the operand naming an outer item.
    if contains_as_whole_word(&masked[let_at..binding_at], "mut")
        || masked[..let_at].trim_end().ends_with(']')
    {
        return None;
    }
    let let_line = test.start_line + masked[..let_at].matches('\n').count();
    let uses = whole_word_offsets(&masked, operand).len();
    let mut asserted = 0;
    for other in &test.assertions {
        if !(test.start_line..=test.end_line).contains(&other.line) {
            continue;
        }
        let text = mask_comments_and_strings(&other.text);
        let in_text = whole_word_offsets(&text, operand).len();
        if in_text == 0 {
            continue;
        }
        let whole_operand = is_plain_macro(&other.text, "assert_eq")
            && assertion_comparison_operands(&other.text).is_some_and(|operands| {
                operands
                    .iter()
                    .filter(|candidate| candidate.trim() == operand)
                    .count()
                    == 1
                    && in_text == 1
            });
        // The reviewed assertion itself is always a whole operand, and
        // only once: `assert_eq!(b, b)` compares the result with itself.
        let reviewed = other.line == assertion.line && other.text == assertion.text;
        let read_only = scalar
            && !reviewed
            && READ_ONLY_ASSERTION_MACROS
                .iter()
                .any(|macro_name| is_plain_macro(&other.text, macro_name));
        if !(whole_operand || read_only) || other.line <= let_line {
            return None;
        }
        asserted += in_text;
    }
    // The `let` pattern is the one use outside the assertions.
    if uses != asserted + 1 {
        return None;
    }
    if scalar {
        let reviewed = mask_comments_and_strings(&assertion.text);
        return (assertion.line > let_line
            && whole_word_offsets(&reviewed, operand).len() == 1
            && same_block_after(&masked, binding_at, test.start_line, assertion))
        .then(|| let_initializer(binding))
        .flatten();
    }
    // Only the assertion right after the `let` is admitted: any statement
    // between them could change the value through a shared handle.
    let after_semicolon =
        binding_at + binding.len() + masked[binding_at + binding.len()..].find(';')? + 1;
    let gap = masked[after_semicolon..].len() - masked[after_semicolon..].trim_start().len();
    let next_at = after_semicolon + gap;
    let next_line = test.start_line + masked[..next_at].matches('\n').count();
    // The next statement must be an `assert_eq!` of the binding itself, not
    // `assert_eqx();`, and it must be the only statement on its lines.
    // Assertions carry a line but no column, so a second statement sharing
    // the line (`assert_eq!(v, f()); touch(); assert_eq!(v, 12);`) could
    // otherwise pass as the next one.
    let rest = &masked[next_at..];
    let end = rest.find(';')?;
    let next = &rest[..end];
    let after = &rest[end + 1..];
    let tail_of_line = &after[..after.find('\n').unwrap_or(after.len())];
    if !next.starts_with("assert_eq!")
        || !contains_as_whole_word(next, operand)
        || !tail_of_line.trim().is_empty()
        || assertion.line != next_line
    {
        return None;
    }
    let_initializer(binding)
}

/// cell-0094 review: whether the line `assertion_line` starts with a
/// statement in the same block as the `let` at `let_at`, at its depth.
/// Leaving the `let`'s block (`{ let b = f(); } assert_eq!(b, 12);`) or
/// entering a deeper one (`{ use super::*; assert_eq!(b, 12); }`) can put
/// another `b` in scope, so either refuses.
fn same_block_after(
    masked: &str,
    let_at: usize,
    start_line: usize,
    assertion: &OracleFact,
) -> bool {
    let assertion_line = assertion.line;
    let Some(line_start) = masked
        .match_indices('\n')
        .nth(assertion_line.saturating_sub(start_line + 1))
        .map(|(offset, _)| offset + 1)
    else {
        return false;
    };
    if line_start <= let_at || assertion_line <= start_line {
        return false;
    }
    let line = &masked[line_start..];
    let line = &line[..line.find('\n').unwrap_or(line.len())];
    // The assertion opens its line, so nothing before it on that line
    // (`a(); { use super::*; assert_eq!(b, 12); }`) escapes the scan.
    let reviewed = mask_comments_and_strings(&assertion.text);
    let reviewed = reviewed.lines().next().unwrap_or_default().trim();
    if reviewed.is_empty() || !line.trim_start().starts_with(reviewed) {
        return false;
    }
    let mut depth = 0_i64;
    for byte in masked[let_at..line_start].bytes() {
        match byte {
            b'{' => depth += 1,
            b'}' => depth -= 1,
            _ => {}
        }
        if depth < 0 {
            return false;
        }
    }
    depth == 0
}

/// The std assertion macros that only read their operands: a scalar
/// result they name cannot change or be rebound through them.
const READ_ONLY_ASSERTION_MACROS: &[&str] = &["assert", "assert_eq", "assert_ne"];

/// The initializer of one `let` binding's tail (`[: T] = <init>`).
fn let_initializer(binding: &str) -> Option<&str> {
    let initializer = binding.trim_start();
    let initializer = match initializer.strip_prefix(':') {
        Some(annotated) => &annotated[annotated.find('=')?..],
        None => initializer,
    };
    let initializer = initializer.strip_prefix('=')?;
    (!initializer.starts_with(['=', '>'])).then(|| initializer.trim())
}

const INTEGER_TYPES: &[&str] = &[
    "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize",
];

/// trap-ceiling-wide-min-control: the call inside `operand` when the
/// projection still pins it against the literal `expected` value `e`:
/// `call.min(k)` with `e < k` (a result of `e` below the bound means the
/// call returned `e`), `call.max(k)` with `e > k`, and `call * 1`,
/// `1 * call`, `call + 0` or `0 + call`, which keep every value. Both
/// numbers are plain decimal literals; anything else refuses.
fn exact_integer_projection<'a>(operand: &'a str, expected: &str) -> Option<&'a str> {
    let decimal = |text: &str| -> Option<u128> {
        let text = text.trim();
        // `_12` is an identifier, not a literal: the first byte is a digit.
        (text.as_bytes().first().is_some_and(u8::is_ascii_digit)
            && text.bytes().all(|b| b.is_ascii_digit() || b == b'_'))
        .then(|| text.replace('_', "").parse().ok())
        .flatten()
    };
    let expected = decimal(expected)?;
    let operand = operand.trim();
    for (method, keeps) in [
        (
            ".min(",
            (|e: u128, k: u128| e < k) as fn(u128, u128) -> bool,
        ),
        (".max(", |e, k| e > k),
    ] {
        if let Some(at) = operand.rfind(method)
            && let Some(bound) = operand[at + method.len()..].strip_suffix(')')
            && let Some(bound) = decimal(bound)
        {
            return keeps(expected, bound).then_some(operand[..at].trim_end());
        }
    }
    let after = |text: &'a str, operator: char, identity: char| {
        text.strip_suffix(identity)?
            .trim_end()
            .strip_suffix(operator)
            .map(str::trim_end)
    };
    let before = |text: &'a str, operator: char, identity: char| {
        text.strip_prefix(identity)?
            .trim_start()
            .strip_prefix(operator)
            .map(str::trim_start)
    };
    after(operand, '*', '1')
        .or_else(|| after(operand, '+', '0'))
        .or_else(|| before(operand, '*', '1'))
        .or_else(|| before(operand, '+', '0'))
        .filter(|call| !call.is_empty())
}

/// `.min(k)` and `.max(k)` on an integer resolve to the prelude's `Ord`
/// only while nothing rebinds that name: a local `trait Ord` (or an import
/// of one, including through a foreign glob) shadows it, and
/// `no_implicit_prelude` drops it. A workspace that declares its own
/// `fn min`/`fn max`, names `Ord` in a `use` or a `trait` item, drops the
/// prelude, or whose test file globs a foreign module refuses the
/// projection rather than crediting a method it may not bind (#7932
/// review). `* 1` and `+ 0` keep std's operator impls, which coherence
/// forbids redefining for a primitive.
fn ord_method_rebindable(operand: &str, test: &TestSummary, index: &RustIndex) -> bool {
    let method = match (operand.contains(".min("), operand.contains(".max(")) {
        (false, false) => return false,
        (true, false) => "min",
        (false, true) => "max",
        (true, true) => return true,
    };
    let Some(test_source) = index
        .files()
        .get(&test.file)
        .map(|facts| facts.data().source.clone())
    else {
        return true;
    };
    if may_saturate_macro_ambiguity(&test_source) {
        return true;
    }
    let ident = |byte: u8| byte.is_ascii_alphanumeric() || byte == b'_';
    // `keyword` as a whole word, followed by whitespace and `then`, which
    // `then` matches by its whole leading word or (for `use`) its item text.
    let declares = |masked: &str, keyword: &str, then: &dyn Fn(&str) -> bool| {
        masked.match_indices(keyword).any(|(offset, _)| {
            let rest = &masked[offset + keyword.len()..];
            let item = rest.trim_start();
            masked[..offset]
                .bytes()
                .next_back()
                .is_none_or(|byte| !ident(byte))
                && item.len() < rest.len()
                && then(item)
        })
    };
    let leading = |word: &'static str| {
        move |item: &str| {
            item.strip_prefix(word)
                .is_some_and(|tail| !tail.bytes().next().is_some_and(ident))
        }
    };
    let names_ord =
        |item: &str| contains_as_whole_word(item.split(';').next().unwrap_or(item), "Ord");
    index.files().iter().any(|(_, facts)| {
        let masked = mask_comments_and_strings(&facts.data().source);
        masked.contains("no_implicit_prelude")
            || declares(&masked, "fn", &leading(method))
            || declares(&masked, "trait", &leading("Ord"))
            || declares(&masked, "use", &names_ord)
    })
}

/// trap-pile-first-element-control: the call inside `vec![call][0]`, a
/// one-element vector indexed at zero, which is the call's own value. A
/// repeat form (`vec![call; n]`), a second element or any other index
/// refuses.
fn single_element_index(operand: &str) -> Option<&str> {
    let inner = operand
        .trim()
        .strip_suffix("[0]")?
        .trim_end()
        .strip_prefix("vec![")?
        .strip_suffix(']')?;
    // A `;` in a string or comment is not the repeat separator.
    if mask_comments_and_strings(inner).contains(';') {
        return None;
    }
    match split_top_level_arguments(inner)?.as_slice() {
        [call] => Some(call.trim()),
        [call, rest] if rest.trim().is_empty() => Some(call.trim()),
        _ => None,
    }
}

/// The callee of `subject` when it is one bare call `name(..)` whose first
/// parenthesis closes at its end: no path, receiver, projection or operator
/// around it (`weight(4).wrapping_sub(weight(4))`, `other::weight(4)`), so
/// the compared value is the call's own return (#7974 review).
pub(in crate::analysis) fn direct_call_name(subject: &str) -> Option<&str> {
    let subject = subject.trim();
    let open = subject.find('(')?;
    let name = subject[..open].trim_end();
    let mut chars = name.chars();
    if !chars
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        || !chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
    {
        return None;
    }
    let mut depth = 0usize;
    for (at, byte) in subject.bytes().enumerate().skip(open) {
        match byte {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return (at + 1 == subject.len()).then_some(name);
                }
            }
            _ => {}
        }
    }
    None
}

/// trap-tally-reached-assert-control: the compared call when `assertion` is
/// `assert_eq!(subject, e)` (either order, `e` an integer literal) and
/// `condition` is `subject <op> k` or `k <op> subject` (one comparison,
/// `k` an integer literal) that does not hold at `e`, so an
/// `if condition { return; }` before it spares the expected value. `None`
/// when the guard fires at `e` (left to the guarded-return refusal) or
/// either shape is anything else.
fn value_guard_subject<'a>(condition: &str, assertion: &'a str) -> Option<&'a str> {
    let integer = |text: &str| -> Option<i128> {
        let text = text.trim();
        let digits = text.strip_prefix('-').unwrap_or(text);
        (digits.as_bytes().first().is_some_and(u8::is_ascii_digit)
            && digits.bytes().all(|b| b.is_ascii_digit() || b == b'_'))
        .then(|| text.replace('_', "").parse().ok())
        .flatten()
    };
    let compact = |text: &str| text.split_whitespace().collect::<String>();
    if !is_plain_macro(assertion, "assert_eq") {
        return None;
    }
    let operands = assertion_comparison_operands(assertion)?;
    let (subject, expected) = match (integer(operands[0]), integer(operands[1])) {
        (None, Some(expected)) => (operands[0].trim(), expected),
        (Some(expected), None) => (operands[1].trim(), expected),
        _ => return None,
    };
    // `compact` drops whitespace inside a string or char literal too, so a
    // call with one stays out (#7974 review).
    if direct_call_name(subject).is_none()
        || subject.contains(['"', '\''])
        || ["&&", "||", "::<", "->"]
            .iter()
            .any(|op| condition.contains(op))
    {
        return None;
    }
    // The one comparison operator outside brackets.
    let bytes = condition.as_bytes();
    let mut depth = 0usize;
    let mut found = None;
    let mut at = 0;
    while at < bytes.len() {
        match bytes[at] {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth = depth.checked_sub(1)?,
            b'<' | b'>' | b'=' | b'!' if depth == 0 => {
                let width = if bytes.get(at + 1) == Some(&b'=') {
                    2
                } else {
                    1
                };
                let operator = &condition[at..at + width];
                if !matches!(operator, "<" | ">" | "<=" | ">=" | "==" | "!=") || found.is_some() {
                    return None;
                }
                found = Some((at, operator));
                at += width;
                continue;
            }
            _ => {}
        }
        at += 1;
    }
    let (at, operator) = found?;
    let (left, right) = (&condition[..at], &condition[at + operator.len()..]);
    // Read the guard as `subject <op> k`; `k < subject` is `subject > k`.
    let (operator, bound) = if compact(left) == compact(subject) {
        (operator, integer(right)?)
    } else if compact(right) == compact(subject) {
        let flipped = match operator {
            "<" => ">",
            ">" => "<",
            "<=" => ">=",
            ">=" => "<=",
            same => same,
        };
        (flipped, integer(left)?)
    } else {
        return None;
    };
    // The guard must spare a wrong value, or the assertion runs only when
    // it passes and the test is a certain gap (#7932 tally review): `!=`
    // returns for every wrong value. ripr does not know the integer type,
    // so `e - 1` counts only where every type holding `e` holds it too
    // (`e >= 1`, or a negative `e` above every signed minimum), and
    // `e + 1` only where `e` is no type's maximum; a neighbour on the
    // threshold's side is a value of the guard's own type.
    let maxima: [i128; 9] = [
        i8::MAX.into(),
        u8::MAX.into(),
        i16::MAX.into(),
        u16::MAX.into(),
        i32::MAX.into(),
        u32::MAX.into(),
        i64::MAX.into(),
        u64::MAX.into(),
        i128::MAX,
    ];
    let minima: [i128; 5] = [
        i8::MIN.into(),
        i16::MIN.into(),
        i32::MIN.into(),
        i64::MIN.into(),
        i128::MIN,
    ];
    let below = expected >= 1 || (expected < 0 && !minima.contains(&expected));
    let above = !maxima.contains(&expected);
    let spares_wrong = match operator {
        // Fires only at `k`: every other wrong value runs the assertion.
        "==" => bound != expected,
        // Spares `v <= k`, or `v <= k - 1` for `>=`.
        ">" => expected < bound || (expected == bound && below),
        ">=" => expected < bound && (expected.checked_add(1)? < bound || below),
        // Spares `v >= k`, or `v >= k + 1` for `<=`.
        "<" => expected > bound || (expected == bound && above),
        "<=" => expected > bound && (expected.checked_sub(1)? > bound || above),
        _ => false,
    };
    spares_wrong.then_some(subject)
}

/// cell-0094: whether `owner` declares a primitive scalar return type that
/// its own file does not shadow with a same-named item or import.
/// Residuals: a non-std glob import, a generic parameter or a
/// macro-generated item that names a type like the primitive.
fn returns_primitive_scalar(owner: &FunctionSummary, index: &RustIndex) -> bool {
    const SCALARS: &[&str] = &[
        "bool", "char", "f32", "f64", "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16",
        "u32", "u64", "u128", "usize",
    ];
    let Some(returned) = declared_return_type(&owner.body) else {
        return false;
    };
    if !SCALARS.contains(&returned.as_str()) {
        return false;
    }
    index.files().get(&owner.file).is_some_and(|facts| {
        let masked = mask_comments_and_strings(&facts.source);
        let declared = whole_word_offsets(&masked, &returned)
            .into_iter()
            .any(|offset| {
                // #7835 review: `type r#u32` declares the same name.
                let before = masked[..offset]
                    .strip_suffix("r#")
                    .unwrap_or(&masked[..offset]);
                let before = before.trim_end();
                ["struct", "enum", "union", "type", "trait"]
                    .iter()
                    .any(|keyword| before.ends_with(keyword))
            });
        // `use a::Gauge as u32;` or `use a::{u32};` binds the name.
        let imported = whole_word_offsets(&masked, "use")
            .into_iter()
            .any(|offset| {
                let rest = &masked[offset..];
                let end = rest.find(';').unwrap_or(rest.len());
                contains_as_whole_word(&rest[..end], &returned)
            });
        !declared && !imported
    })
}

/// Whether the expected operand of `assertion` in `test` reaches the owner
/// `name`: it names the owner, or names a test binding whose initializer
/// does (`assert_eq!(f(4), f(2) + f(2))`, `let e = f(4); assert_eq!(f(4),
/// e)`), so the assertion compares the owner with itself. Shared by the
/// owner-return pin and RIPR-SPEC-0265 element pairing.
pub(in crate::analysis::classify) fn expected_reaches_owner(
    test: &TestSummary,
    assertion: &str,
    expected: &str,
    name: &str,
) -> bool {
    contains_as_whole_word(&mask_comments_and_strings(expected), name)
        || (owner_named_outside(test, assertion, name)
            && expected_binding_calls_owner(test, expected, name))
}

/// RIPR-SPEC-0035, reveal side: the value the expected `operand` stands
/// for when it is a plain identifier the test binds once with a readable
/// `let`, or that names exactly one in-scope workspace constant, followed
/// through further such names (`let e = tax(2); let f = e;`). The reveal
/// side reads that value in place of the operand, so a name weakens an
/// assertion only where writing its initializer inline would. `None` when
/// the operand is no such name; a name the scan cannot read keeps credit.
pub(in crate::analysis) fn expected_operand_value(
    index: &RustIndex,
    test: &TestSummary,
    operand: &str,
    owner: &FunctionSummary,
) -> Option<String> {
    let in_scope = constant_scope(index, test, &owner.file);
    let mut seen = BTreeSet::new();
    let mut current = mask_comments_and_strings(operand).trim().to_string();
    let mut value = None;
    while is_plain_identifier(&current) && current != owner.name && seen.insert(current.clone()) {
        let next = match receiver_let_bindings(test, &current) {
            Some(bindings) => match bindings.as_slice() {
                [binding] => immutable_let_value(test, binding),
                [] => single_constant_value(index, &current, &in_scope),
                _ => None,
            },
            None => None,
        };
        let Some(next) = next else {
            break;
        };
        current = next.trim().to_string();
        value = Some(current.clone());
    }
    value
}

/// The value of the test's one `let` binding `binding` (its text after the
/// name), unless the `let` is `mut`, so a later assignment or `push` may
/// change it, or carries an attribute (`#[cfg(..)] let`) that may compile
/// it away (#7066 review), as [`let_bound_owner_call`] refuses.
fn immutable_let_value(test: &TestSummary, binding: &str) -> Option<String> {
    let masked = mask_comments_and_strings(&test.body);
    let binding_at = (binding.as_ptr() as usize).checked_sub(test.body.as_ptr() as usize)?;
    let let_at = *whole_word_offsets(masked.get(..binding_at)?, "let").last()?;
    if contains_as_whole_word(masked.get(let_at..binding_at)?, "mut")
        || masked.get(..let_at)?.trim_end().ends_with(']')
    {
        return None;
    }
    let binding = mask_comments_and_strings(binding);
    let value = assigned_value(&binding)?;
    // #8112: an immutable binding of an interior-mutable value
    // (`let e = Cell::new(f(2)); e.set(6);`) can change after its initializer.
    if has_interior_mutability(value) {
        return None;
    }
    Some(value.to_string())
}

/// #8112: whether an initializer names a type that allows mutation through
/// a shared binding, so the value the binding holds at the assertion may
/// differ from its initializer.
fn has_interior_mutability(initializer: &str) -> bool {
    [
        "Cell",
        "RefCell",
        "UnsafeCell",
        "OnceCell",
        "OnceLock",
        "LazyCell",
        "LazyLock",
        "Mutex",
        "RwLock",
        "AtomicBool",
        "AtomicI8",
        "AtomicI16",
        "AtomicI32",
        "AtomicI64",
        "AtomicIsize",
        "AtomicU8",
        "AtomicU16",
        "AtomicU32",
        "AtomicU64",
        "AtomicUsize",
        "AtomicPtr",
    ]
    .iter()
    .any(|word| contains_as_whole_word(initializer, word))
}

/// #8112: whether `file` declares `static mut name`, whose value the test
/// may have assigned before the assertion reads it.
fn declares_static_mut(index: &RustIndex, file: &Path, name: &str) -> bool {
    let Some(facts) = index.files().get(file) else {
        return false;
    };
    let masked = mask_comments_and_strings(&facts.source);
    whole_word_offsets(&masked, "static")
        .into_iter()
        .any(|offset| {
            let rest = masked[offset + "static".len()..].trim_start();
            rest.strip_prefix("mut")
                .filter(|after| after.starts_with(char::is_whitespace))
                .is_some_and(|after| {
                    let after = after.trim_start();
                    after.strip_prefix(name).is_some_and(|tail| {
                        !tail.starts_with(|c: char| c.is_ascii_alphanumeric() || c == '_')
                    })
                })
        })
}

/// The initializer of the one in-scope workspace constant named `name`.
/// An item read from text (`: T = init`) yields the text after its `=`.
fn single_constant_value(
    index: &RustIndex,
    name: &str,
    in_scope: &dyn Fn(&Path) -> bool,
) -> Option<String> {
    let constants = index
        .call_identity_memos
        .workspace_constants(|| workspace_constant_table(index));
    let mut matches = constants
        .get(name)?
        .iter()
        .filter(|(file, _)| in_scope(file));
    let (file, initializer) = matches.next()?;
    if matches.next().is_some() || declares_static_mut(index, file, name) {
        return None;
    }
    let initializer_text = initializer.trim_start();
    if initializer_text.starts_with(':') && !initializer_text.starts_with("::") {
        assigned_value(initializer).map(str::to_string)
    } else {
        Some(initializer.clone())
    }
}

/// The text after the assignment `=` of `[: T] = value`: the first `=`
/// outside angle brackets that is not part of `==`, `=>`, `<=`, `>=` or `!=`.
fn assigned_value(text: &str) -> Option<&str> {
    let bytes = text.as_bytes();
    let mut depth = 0usize;
    for (position, byte) in bytes.iter().enumerate() {
        match byte {
            b'<' => depth += 1,
            b'>' if bytes.get(position.wrapping_sub(1)) != Some(&b'-') => {
                depth = depth.saturating_sub(1);
            }
            b'=' if depth == 0
                && !matches!(bytes.get(position + 1), Some(b'=' | b'>'))
                && !matches!(
                    bytes.get(position.wrapping_sub(1)),
                    Some(b'=' | b'!' | b'<' | b'>')
                ) =>
            {
                return text.get(position + 1..);
            }
            _ => {}
        }
    }
    None
}

/// A constant from a package the test neither belongs to, tests, nor names
/// (`test_kit::EXPECTED` from `crates/test-kit/`) cannot be the one the
/// test reads; unscopable paths keep every match.
fn constant_scope(
    index: &RustIndex,
    test: &TestSummary,
    owner_file: &Path,
) -> impl Fn(&Path) -> bool {
    let test_package = super::related_tests::package_prefix(&test.file);
    let owner_package = super::related_tests::package_prefix(owner_file);
    let test_source = index
        .files()
        .get(&test.file)
        .map(|facts| facts.source.clone());
    move |file: &Path| match (&test_package, &owner_package) {
        (Some(test_package), Some(owner_package)) => super::related_tests::package_prefix(file)
            .is_none_or(|package| {
                &package == test_package
                    || &package == owner_package
                    || package
                        .trim_end_matches('/')
                        .rsplit('/')
                        .next()
                        .is_some_and(|crate_dir| {
                            test_source.as_deref().is_none_or(|source| {
                                contains_as_whole_word(source, &crate_dir.replace('-', "_"))
                            })
                        })
            }),
        _ => true,
    }
}

/// RIPR-SPEC-0035: whether an identifier in the expected operand names a
/// `const` or `static` whose initializer calls the owner, directly or
/// through further constants (`const EXPECTED: u32 = quota(2);
/// assert_eq!(quota(2), EXPECTED)` compares the owner with itself, as a
/// `let` binding would). Constants come from one memoized workspace table
/// keyed by name; any same-named item in the test's or the owner's package
/// counts: matching too many only withholds the pin. The call must have the pin's own shape (a bare or
/// module-path call for a free function, `T::name(..)` for an associated
/// one, `.name(..)` or `T::name(..)` for a method), so a constant built
/// with some other type's `new` or `len` keeps the pin. A test-file `use ..
/// as` rename of a constant and a constant file's rename of the owner are
/// followed. A constant computed through a helper that calls the owner is
/// not.
fn expected_constant_reaches_owner(
    index: &RustIndex,
    test: &TestSummary,
    expected: &str,
    name: &str,
    call: &PinCall,
    owner_file: &Path,
) -> bool {
    let constants = index
        .call_identity_memos
        .workspace_constants(|| workspace_constant_table(index));
    if constants.is_empty() {
        return false;
    }
    let in_scope = constant_scope(index, test, owner_file);
    // `use .. as` renames of the file a text was read from: the test file
    // for the expected operand, the constant's own file for an initializer.
    let renames = |file: &Path| -> Vec<UsePath> {
        index
            .files()
            .get(file)
            .filter(|facts| facts.source.contains(" as "))
            .map(|facts| flattened_use_paths(&facts.source))
            .unwrap_or_default()
    };
    let mut seen = BTreeSet::new();
    let mut pending = vec![(mask_comments_and_strings(expected), test.file.clone())];
    while let Some((text, file)) = pending.pop() {
        let mut words: Vec<String> = text
            .split(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
            .filter(|word| is_plain_identifier(word) && *word != name)
            .map(str::to_string)
            .collect();
        let renamed: Vec<String> = renames(&file)
            .into_iter()
            .filter(|import| {
                import
                    .alias
                    .as_deref()
                    .is_some_and(|alias| words.iter().any(|word| word == alias))
            })
            .filter_map(|import| import.path.rsplit("::").next().map(str::to_string))
            .collect();
        words.extend(renamed);
        for word in words {
            if !seen.insert(word.clone()) {
                continue;
            }
            let Some(initializers) = constants.get(&word) else {
                continue;
            };
            for (file, initializer) in initializers.iter().filter(|(file, _)| in_scope(file)) {
                if initializer_calls_owner(initializer, name, call)
                    || owner_aliases(index, file, name)
                        .iter()
                        .any(|alias| initializer_calls_owner(initializer, alias, call))
                {
                    return true;
                }
                pending.push((initializer.clone(), file.clone()));
            }
        }
    }
    false
}

/// Names `file` imports the owner `name` under (`use crate::quota as q;`).
fn owner_aliases(index: &RustIndex, file: &Path, name: &str) -> Vec<String> {
    index
        .files()
        .get(file)
        .map(|facts| {
            flattened_use_paths(&facts.source)
                .into_iter()
                .filter(|import| import.path.rsplit("::").next() == Some(name))
                .filter_map(|import| import.alias)
                .collect()
        })
        .unwrap_or_default()
}

/// Whether the masked `initializer` calls `name` in the pin's call shape.
/// A free function also counts when named as a value (`apply(quota, 2)`,
/// `let f = quota;`), and a `<..>::name` qualifier the scan cannot read
/// counts for every shape.
fn initializer_calls_owner(initializer: &str, name: &str, call: &PinCall) -> bool {
    whole_word_offsets(initializer, name).into_iter().any(|offset| {
        let after = initializer[offset + name.len()..].trim_start();
        let called = after.starts_with('(') || after.starts_with("::<");
        // A struct-literal field (`Limits { quota: 2 }`) is not the owner.
        if after.starts_with(':') && !after.starts_with("::") {
            return false;
        }
        let before = initializer[..offset].trim_end();
        let qualifier = before.strip_suffix("::").map(|path| {
            let path = path.trim_end();
            let start = path
                .char_indices()
                .rev()
                .find(|(_, character)| !(character.is_alphanumeric() || *character == '_'))
                .map_or(0, |(index, character)| index + character.len_utf8());
            &path[start..]
        });
        if qualifier == Some("") {
            return true;
        }
        let type_like = |segment: &str| segment.starts_with(char::is_uppercase);
        match call {
            PinCall::Bare => !before.ends_with('.') && !qualifier.is_some_and(type_like),
            PinCall::Associated { type_name } => {
                called && qualifier.is_some_and(|segment| segment == type_name || segment == "Self")
            }
            PinCall::Method { receivers, .. } => {
                called
                    && (before.ends_with('.')
                        || qualifier.is_some_and(|segment| {
                            segment == "Self"
                                || receivers.iter().any(|receiver| {
                                    matches!(receiver, ReceiverType::Named(type_name) if type_name == segment)
                                })
                        }))
            }
        }
    })
}

/// Every `const` and `static` of the workspace, by name, with its file and
/// masked initializer: one parse per file per index. Items a macro call
/// declares (`thread_local!`, `lazy_static!`) and items of a file that does
/// not parse cleanly are read from their text.
fn workspace_constant_table(index: &RustIndex) -> BTreeMap<String, Vec<(PathBuf, String)>> {
    let mut table: BTreeMap<String, Vec<(PathBuf, String)>> = BTreeMap::new();
    for (path, facts) in index.files().iter() {
        let source = &facts.source;
        if !source.contains("const") && !source.contains("static") {
            continue;
        }
        let mut add = |name: &str, initializer: String| {
            let name = name.strip_prefix("r#").unwrap_or(name);
            table
                .entry(name.to_string())
                .or_default()
                .push((path.clone(), initializer));
        };
        let Some(parsed) = parse_clean_source_file(source) else {
            for (name, initializer) in text_declared_constants(&mask_comments_and_strings(source)) {
                add(&name, initializer);
            }
            continue;
        };
        for node in parsed.tree().syntax().descendants() {
            let item = if let Some(item) = ast::Const::cast(node.clone()) {
                item.name().zip(item.body())
            } else if let Some(item) = ast::Static::cast(node.clone()) {
                item.name().zip(item.body())
            } else {
                if let Some(macro_call) = ast::MacroCall::cast(node)
                    && let Some(tokens) = macro_call.token_tree()
                {
                    let text = mask_comments_and_strings(&tokens.syntax().to_string());
                    for (name, initializer) in text_declared_constants(&text) {
                        add(&name, initializer);
                    }
                }
                None
            };
            if let Some((item_name, body)) = item {
                add(
                    item_name.text(),
                    mask_comments_and_strings(&body.syntax().to_string()),
                );
            }
        }
    }
    table
}

/// `const NAME: T = init;` and `static [ref] [mut] NAME: T = init;` read
/// from masked text as their `: T = init` text, for macro bodies and unparsed files. The type
/// annotation is required, so `const fn`, `*const u8` and `&'static str`
/// are not declarations.
fn text_declared_constants(text: &str) -> Vec<(String, String)> {
    let mut found = Vec::new();
    for keyword in ["const", "static"] {
        for offset in whole_word_offsets(text, keyword) {
            let mut rest = text[offset + keyword.len()..].trim_start();
            for modifier in ["ref", "mut"] {
                if let Some(stripped) = rest.strip_prefix(modifier)
                    && stripped.starts_with(char::is_whitespace)
                {
                    rest = stripped.trim_start();
                }
            }
            let raw = rest.strip_prefix("r#");
            let body = raw.unwrap_or(rest);
            let length = body
                .find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
                .unwrap_or(body.len());
            let name = &body[..length];
            if !is_plain_identifier(name) || !body[length..].trim_start().starts_with(':') {
                continue;
            }
            // The item runs to its first `;` outside brackets, so an array
            // type (`[u32; 4]`) or a block initializer stays whole. One with
            // no `=` there (`extern { static X: u32; }`) has no initializer.
            // The type stays in the text: an `=` inside it (`Item = u32`)
            // cannot hide the initializer, and its words only withhold.
            let declaration = &body[length..];
            let end = top_level_semicolon(declaration).unwrap_or(declaration.len());
            let item = &declaration[..end];
            if !item.contains('=') {
                continue;
            }
            found.push((name.to_string(), item.to_string()));
        }
    }
    found
}

/// #6974 review: whether the test body names the owner anywhere but the
/// assertion under review. When it does not, no binding in the test can
/// hold an owner call, so table-driven expected values (`#[case] want`,
/// `for (x, want) in cases`) need no binding scan.
fn owner_named_outside(test: &TestSummary, assertion: &str, name: &str) -> bool {
    let in_body = whole_word_offsets(&mask_comments_and_strings(&test.body), name).len();
    let in_assertion = whole_word_offsets(&mask_comments_and_strings(assertion), name).len();
    in_body > in_assertion
}

/// #6974 review: whether an identifier in the expected operand is a test
/// `let` whose initializer mentions the owner, directly or through further
/// `let`s (`let s = f(2) * 1; assert_eq!(f(2), s);` and
/// `let a = f(2); let b = a; assert_eq!(f(2), b);` compare the owner with
/// itself).
fn expected_binding_calls_owner(test: &TestSummary, expected: &str, name: &str) -> bool {
    let masked_body = mask_comments_and_strings(&test.body);
    let mut seen = BTreeSet::new();
    let mut pending = vec![mask_comments_and_strings(expected)];
    while let Some(text) = pending.pop() {
        for word in text
            .split(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
            .filter(|word| is_plain_identifier(word) && *word != name)
        {
            if !seen.insert(word.to_string()) {
                continue;
            }
            // A binding the scan cannot read (a pattern, a shadowed
            // name) may hold an owner call: fail closed (#6974 review).
            // A word the scan refuses only because a `let` annotation
            // names it (`let w: Window = ..`) is a type, not a binding.
            // A statement macro may bind the word (`s!(expected);`), and the
            // test may write through it (`EXPECTED.store(f(4))`): neither
            // is a `let` the scan reads, so the owner may feed the operand
            // (#7847).
            let bindings = receiver_let_bindings(test, word);
            let plain = bindings.as_deref().is_some_and(plain_let_values);
            if bound_by_macro(&masked_body, word) || written_by_test(&masked_body, word, plain) {
                return true;
            }
            let Some(bindings) = bindings else {
                if binds_outside_let(&masked_body, word) || let_patterns_bind(&masked_body, word) {
                    return true;
                }
                continue;
            };
            for binding in bindings {
                let initializer = mask_comments_and_strings(binding);
                if contains_as_whole_word(&initializer, name) {
                    return true;
                }
                pending.push(initializer);
            }
        }
    }
    false
}

/// #7847: whether the masked test body writes through `name` outside a
/// `let`: an assignment to the name or a place under it (`name = ..`,
/// `name.field = ..`, `name.0 = ..`, `name[i] += ..`), a `&mut name` borrow,
/// or a mutating call on it or a place under it (`name.store(..)`,
/// `name.sort()`, `name.0.push(..)`, any `*_mut`, `*_assign`, `fetch_*` or
/// `set_*` method). Lexical and conservative, so a static the test stores
/// the owner's value in is no independent expected value.
///
/// `plain` (#8795): every binding of `name` is a `let` of a plain value
/// (`plain_let_values`), which holds no interior mutability and no callee can
/// write through a shared borrow of it, so `&name` passed to a call is a
/// read. Method names stay mutators regardless (a test-local type may define
/// any `replace`/`take`). A static, a const or any other binding, and any
/// constructor call (it may be test-local), is never plain.
fn written_by_test(masked: &str, name: &str, plain: bool) -> bool {
    whole_word_offsets(masked, name).into_iter().any(|offset| {
        let before = masked[..offset].trim_end();
        // `let e: Config = ..`, `let e: crate::Config`, `let e: &Config` and
        // `let e: (Config, u8)` annotate a type: the `=` after it assigns the
        // binding, not the type name. Only a `let` pattern's annotation
        // qualifies; a struct-literal field value (`S { f: EXPECTED.swap(..) }`)
        // is an expression and stays scanned (#8795).
        if in_let_annotation(before) {
            return false;
        }
        if before.ends_with("&mut") {
            return true;
        }
        // A `let` (or `let mut`) declaration is the binding the let scan reads.
        if before.ends_with("let") || before.ends_with("mut") {
            return false;
        }
        // `write!(name, ..)` / `writeln!(name, ..)` write into their first
        // argument; the trusted-macro list keeps `bound_by_macro` from
        // seeing them.
        before.ends_with("write!(")
            || before.ends_with("writeln!(")
            || (!plain && borrowed_into_path_call(before))
            || place_is_written(&masked[offset + name.len()..])
            || (destructured_into(&masked[offset + name.len()..]) && !index_operand(before))
    })
}

/// A name passed by shared reference as an argument to any non-macro call
/// (`AtomicU32::store(&EXPECTED, ..)`, `write(&EXPECTED, ..)`,
/// `Cell::set(&expected, ..)`) may be written by the callee. A plain reader
/// callee and a macro (`assert_eq!(f(4), &EXPECTED)`) do not count.
fn borrowed_into_path_call(before: &str) -> bool {
    let Some(head) = before.strip_suffix('&') else {
        return false;
    };
    let head = head.trim_end().trim_end_matches('&').trim_end();
    if !head.ends_with(['(', ',']) {
        return false;
    }
    let mut depth = 0usize;
    let mut open = None;
    for (at, c) in head.char_indices().rev() {
        match c {
            ')' | ']' => depth += 1,
            '(' | '[' => {
                if depth == 0 {
                    open = Some(at);
                    break;
                }
                depth -= 1;
            }
            _ => {}
        }
    }
    let Some(open) = open else {
        return false;
    };
    let callee = head[..open].trim_end();
    if callee.ends_with('!') {
        return false;
    }
    // A turbofish callee (`store::<u32>(&X, ..)`) is unreadable: refuse.
    if callee.ends_with(['>', ')', ']', '}']) {
        return true;
    }
    let path: String = callee
        .chars()
        .rev()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == ':')
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    let last = path
        .rsplit_once("::")
        .map_or(path.as_str(), |(_, last)| last);
    !last.is_empty()
        && ![
            "load",
            "get",
            "read",
            "eq",
            "ne",
            "len",
            "clone",
            "cmp",
            "partial_cmp",
            "contains",
            "starts_with",
            "ends_with",
            "is_empty",
        ]
        .contains(&last)
}

/// Whether the text before a name sits inside a `let` pattern's type
/// annotation (#8795): the nearest preceding `let` has no `=`, `;`, `{` or
/// `}` after it, and a single `:` (not a `::` path separator) separates the
/// pattern from the name. A pattern with no annotation colon
/// (`let (a, name) = ..`) binds the name and is not an annotation; a struct
/// pattern's field colon sits inside `{}` and is excluded.
fn in_let_annotation(before: &str) -> bool {
    whole_word_offsets(before, "let")
        .into_iter()
        .next_back()
        .is_some_and(|at| {
            let tail = &before[at + "let".len()..];
            !tail.contains(['=', ';', '{', '}']) && has_single_colon(tail)
        })
}

fn has_single_colon(text: &str) -> bool {
    let bytes = text.as_bytes();
    bytes.iter().enumerate().any(|(at, byte)| {
        *byte == b':'
            && bytes.get(at + 1) != Some(&b':')
            && (at == 0 || bytes.get(at - 1) != Some(&b':'))
    })
}

/// Whether the name sits inside the `[..]` of an index expression
/// (`v[name] = ..`): the nearest unclosed group before it is a `[` that
/// directly follows an identifier or a closing bracket. The name is then an
/// index read, not the place an enclosing assignment writes (#8795). An
/// array pattern (`[name, ..] = p`) follows `;`, `=` or nothing, so it is not.
fn index_operand(before: &str) -> bool {
    let mut depth = 0usize;
    for (at, character) in before.char_indices().rev() {
        match character {
            ')' | ']' | '}' => depth += 1,
            '(' | '[' | '{' => {
                if depth > 0 {
                    depth -= 1;
                    continue;
                }
                return character == '['
                    && before[..at]
                        .trim_end()
                        .chars()
                        .next_back()
                        .is_some_and(|prev| {
                            prev.is_ascii_alphanumeric() || matches!(prev, '_' | ')' | ']')
                        });
            }
            ';' if depth == 0 => return false,
            _ => {}
        }
    }
    false
}

/// Whether every `let` binding of a name (the text after the name, as
/// `receiver_let_bindings` returns it) initializes it with a plain value: a
/// literal, a tuple or array of plain values, a `String` built from a
/// literal, or an uppercase constructor / struct literal of plain values.
/// Such a value has no interior mutability, so a shared borrow of it cannot
/// be written by a callee (#8795). No binding at all (a static, a const) is
/// not plain.
fn plain_let_values(bindings: &[&str]) -> bool {
    !bindings.is_empty()
        && bindings.iter().all(|binding| {
            let statement = binding.trim_end().trim_end_matches(';');
            let init = statement
                .match_indices('=')
                .map(|(position, _)| position)
                .find(|position| {
                    !matches!(statement.as_bytes().get(position + 1), Some(b'=' | b'>'))
                        && !matches!(
                            statement.as_bytes().get(position.wrapping_sub(1)),
                            Some(b'=' | b'!' | b'<' | b'>')
                        )
                })
                .map(|position| &statement[position + 1..]);
            init.is_some_and(is_plain_value)
        })
}

fn is_plain_value(expression: &str) -> bool {
    let expression = expression.trim();
    let unsigned = expression
        .strip_prefix('-')
        .map_or(expression, str::trim_start);
    if unsigned.starts_with(|c: char| c.is_ascii_digit()) {
        return unsigned
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '.'));
    }
    if unsigned.len() != expression.len() {
        return false;
    }
    if matches!(expression, "true" | "false") || is_string_literal(expression) {
        return true;
    }
    if expression.len() >= 3 && expression.starts_with('\'') && expression.ends_with('\'') {
        return !expression[1..expression.len() - 1].contains('\'');
    }
    if let Some((element, length)) =
        group_inner(expression, '[', ']').and_then(|inner| inner.split_once(';'))
    {
        let length = length.trim();
        return is_plain_value(element)
            && !length.is_empty()
            && length.chars().all(|c| c.is_ascii_digit() || c == '_');
    }
    if let Some(inner) =
        group_inner(expression, '(', ')').or_else(|| group_inner(expression, '[', ']'))
    {
        return split_top_level(inner)
            .iter()
            .all(|part| part.trim().is_empty() || is_plain_value(part));
    }
    let Some(open) = expression.find(['(', '{']) else {
        return false;
    };
    let head = expression[..open].trim();
    let constructor = head.rsplit("::").next().unwrap_or(head);
    if !constructor.starts_with(|c: char| c.is_ascii_uppercase())
        || !head
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | ':'))
    {
        return false;
    }
    // Only a struct literal: a parenthesized uppercase call may be a
    // test-local function, which can return an interior-mutable value.
    if expression.as_bytes()[open] != b'{' {
        return false;
    }
    group_inner(&expression[open..], '{', '}').is_some_and(|inner| {
        split_top_level(inner).iter().all(|field| {
            field.trim().is_empty()
                || field.split_once(':').is_some_and(|(name, value)| {
                    is_plain_identifier(name.trim()) && is_plain_value(value)
                })
        })
    })
}

fn is_string_literal(text: &str) -> bool {
    let text = text.strip_prefix('b').unwrap_or(text);
    text.len() >= 2
        && text.starts_with('"')
        && text.ends_with('"')
        && !text[1..text.len() - 1].contains(['"', '\\'])
}

/// The text inside `open..close` when `text` is exactly that one group.
fn group_inner(text: &str, open: char, close: char) -> Option<&str> {
    let rest = text.strip_prefix(open)?;
    let after = skip_balanced(text, open, close)?;
    if after.trim().is_empty() {
        rest.rfind(close).map(|end| &rest[..end])
    } else {
        None
    }
}

/// `text` split at commas outside any bracket pair.
fn split_top_level(text: &str) -> Vec<&str> {
    let mut parts = Vec::new();
    let mut depth = 0usize;
    let mut start = 0;
    for (at, character) in text.char_indices() {
        match character {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth = depth.saturating_sub(1),
            ',' if depth == 0 => {
                parts.push(&text[start..at]);
                start = at + 1;
            }
            _ => {}
        }
    }
    parts.push(&text[start..]);
    parts
}

/// Whether the place expression that continues `rest` (a chain of `.field`,
/// `.0`, `[..]` and calls) is assigned, or ends in a mutating call. An
/// unreadable chain fails closed.
fn place_is_written(rest: &str) -> bool {
    let mut rest = rest.trim_start();
    loop {
        if let Some(call) = rest.strip_prefix('.') {
            let call = call.trim_start();
            let method: String = call
                .chars()
                .take_while(|character| character.is_ascii_alphanumeric() || *character == '_')
                .collect();
            if method.is_empty() {
                return true;
            }
            rest = call[method.len()..].trim_start();
            // A turbofish or `?` is a shape the scan does not read.
            if rest.starts_with("::") || rest.starts_with('?') {
                return true;
            }
            if rest.starts_with('(') {
                if is_mutating_method(&method) {
                    return true;
                }
                match skip_balanced(rest, '(', ')') {
                    Some(after) => rest = after.trim_start(),
                    None => return true,
                }
            }
        } else if rest.starts_with('[') {
            match skip_balanced(rest, '[', ']') {
                Some(after) => rest = after.trim_start(),
                None => return true,
            }
        } else if rest.starts_with('?') {
            return true;
        } else {
            break;
        }
    }
    assignment_operator_at(rest)
}

/// Whether the name sits in a pattern that is the left side of an assignment
/// (`(name, _) = ..`, `[name, ..] = ..`, `S { f: name, .. } = ..`): after the
/// enclosing group closes, an `=` (not `==` or `=>`) or compound operator
/// follows. `rest` is the text after the name.
fn destructured_into(rest: &str) -> bool {
    let mut depth = 0usize;
    for (at, character) in rest.char_indices() {
        match character {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => {
                if depth > 0 {
                    depth -= 1;
                    continue;
                }
                // The enclosing group closed: what follows decides.
                let mut tail = rest[at..].trim_start_matches([')', ']', '}']);
                tail = tail.trim_start();
                return assignment_operator_at(tail);
            }
            ';' if depth == 0 => return false,
            _ => {}
        }
    }
    false
}

fn assignment_operator_at(rest: &str) -> bool {
    rest.strip_prefix('=')
        .is_some_and(|tail| !tail.starts_with(['=', '>']))
        || ["+=", "-=", "*=", "/=", "%=", "|=", "&=", "^=", "<<=", ">>="]
            .iter()
            .any(|operator| rest.starts_with(operator))
}

/// The text after the bracket that closes the one `text` opens with.
fn skip_balanced(text: &str, open: char, close: char) -> Option<&str> {
    let mut depth = 0usize;
    for (at, character) in text.char_indices() {
        if character == open {
            depth += 1;
        } else if character == close {
            depth = depth.checked_sub(1)?;
            if depth == 0 {
                return Some(&text[at + close.len_utf8()..]);
            }
        }
    }
    None
}

/// Methods that may mutate their receiver (#7847). Name families cover the
/// std mutators; an unlisted name is read-only to the scan.
fn is_mutating_method(method: &str) -> bool {
    const MUTATORS: &[&str] = &[
        "store",
        "set",
        "with",
        "nth",
        "splice",
        "replace_range",
        "replace",
        "swap",
        "append",
        "write",
        "lock",
        "take",
        "clear",
        "entry",
        "resize",
        "truncate",
        "get_or_init",
        "update",
        "next",
        "next_back",
        "next_chunk",
        "resize_with",
        "compare_and_swap",
        "try_lock",
        "try_write",
        "as_mut_ptr",
        "reverse",
        "split_off",
        "rotate_left",
        "rotate_right",
        "replace_with",
        "copy_within",
    ];
    MUTATORS.contains(&method)
        || [
            "push",
            "pop",
            "sort",
            "fill",
            "drain",
            "retain",
            "extend",
            "insert",
            "copy_",
            "clone_from",
            "remove",
            "or_insert",
            "get_or_insert",
            "dedup",
            "swap_",
            "write_",
            "make_ascii_",
            "compare_exchange",
            "next_if",
            "peek",
            "fetch_",
            "set_",
        ]
        .iter()
        .any(|prefix| method.starts_with(prefix))
        || ["_mut", "_assign"]
            .iter()
            .any(|suffix| method.ends_with(suffix))
}

/// #6578: whether the expected operand may carry a value an rstest fixture
/// built. A fixture parameter (one not marked `#[case]`) is filled by a
/// `#[fixture]` function outside the test body, which may call the owner
/// (`#[fixture] fn want() -> u32 { weight(4) }` makes
/// `assert_eq!(weight(4), want)` compare the owner with itself), and the
/// body-only owner scan cannot see it. In a test with a fixture, the
/// expected operand must name no fixture and nothing the body binds: a
/// body binding may hold a fixture value through a `let`, an assignment or
/// a mutation (`let mut w = 0; w = want;`, `v.push(want)`), so any `let`,
/// closure, `for` or match binding of an expected word fails closed, a
/// rebound `#[case]` parameter included. Unrebound `#[case]` parameters
/// (rows the syntax gate holds to literals) and names bound outside the
/// test (constants) pass.
fn expected_reaches_fixture(test: &TestSummary, expected: &str) -> bool {
    let masked = mask_comments_and_strings(&test.body);
    let Some(fixtures) = fixture_parameters(test, &masked) else {
        return true;
    };
    if fixtures.is_empty() {
        return false;
    }
    let Some((open, close)) = whole_word_offsets(&masked, "fn")
        .first()
        .and_then(|offset| fn_param_range(&masked, *offset))
    else {
        return true;
    };
    let mut body = masked.clone();
    body.replace_range(open + 1..close, &" ".repeat(close - open - 1));
    mask_comments_and_strings(expected)
        .split(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
        .filter(|word| is_plain_identifier(word))
        .any(|word| {
            fixtures.contains(word)
                || binds_outside_let(&body, word)
                || let_patterns_bind(&body, word)
        })
}

/// #6578: the names of the test's rstest fixture parameters (those not
/// marked `#[case]`), empty when the test takes none, or `None` when it
/// takes parameters ripr cannot read. `masked` is the test body with
/// comments and strings masked.
fn fixture_parameters(test: &TestSummary, masked: &str) -> Option<BTreeSet<String>> {
    // Most tests take no parameters: skip the parse. No readable `fn`
    // signature holds no fixture parameter; the owner-pin syntax gate
    // admits rstest only on a parsed `fn`.
    let Some((open, close)) = whole_word_offsets(masked, "fn")
        .first()
        .and_then(|offset| fn_param_range(masked, *offset))
    else {
        return Some(BTreeSet::new());
    };
    if masked[open + 1..close].trim().is_empty() {
        return Some(BTreeSet::new());
    }
    let parse = parse_clean_source_file(&test.body)?;
    let function = parse
        .tree()
        .syntax()
        .descendants()
        .find_map(ast::Fn::cast)?;
    let mut fixtures = BTreeSet::new();
    let Some(list) = function.param_list() else {
        return Some(fixtures);
    };
    for param in list.params() {
        let Some(ast::Pat::IdentPat(pat)) = param.pat() else {
            return None;
        };
        let name = pat.name()?;
        if !param
            .attrs()
            .any(|attr| attr.simple_name().as_deref() == Some("case"))
        {
            fixtures.insert(name.text().to_string());
        }
    }
    Some(fixtures)
}

/// The offsets of the parentheses around the parameter list of the `fn`
/// keyword at `fn_at` in `masked`.
fn fn_param_range(masked: &str, fn_at: usize) -> Option<(usize, usize)> {
    let open = fn_at + masked[fn_at..].find('(')?;
    let close = matching_close(masked, open, b'(', b')')?;
    Some((open, close))
}

/// #6974 review: whether any `let` pattern in `masked` may bind `word`:
/// the text after `let` up to its type annotation (a lone `:`), its `=`
/// or its `;`, whichever comes first.
fn let_patterns_bind(masked: &str, word: &str) -> bool {
    whole_word_offsets(masked, "let").into_iter().any(|offset| {
        let rest = &masked[offset + "let".len()..];
        let bytes = rest.as_bytes();
        let end = (0..bytes.len())
            .find(|&at| match bytes[at] {
                b'=' | b';' => true,
                b':' => bytes.get(at + 1) != Some(&b':') && (at == 0 || bytes[at - 1] != b':'),
                _ => false,
            })
            .unwrap_or(bytes.len());
        contains_as_whole_word(&rest[..end], word)
    })
}

/// Methods that may run the `clone` under test.
const CLONING_METHODS: &[&str] = &["clone", "clone_from", "cloned", "to_owned"];

/// #6692: whether the clone's receiver was built without the clone under
/// test, so a wrong `clone` cannot also have produced the value it is
/// compared with (`let w: Window = base.clone(); assert_eq!(w.clone(), w)`
/// passes for an idempotent wrong field). Every `let` of the receiver must
/// initialize it with a `type_name { .. }` or `type_name(..)` literal, or a
/// call to the type's one inherent constructor whose body clones nothing,
/// and no part of an initializer may clone. The test may not reassign or
/// mutably borrow the receiver. Anything else fails closed.
fn clone_receiver_is_independent(
    test: &TestSummary,
    receiver: &str,
    type_name: &str,
    index: &RustIndex,
) -> bool {
    let masked = mask_comments_and_strings(&test.body);
    if receiver_is_reassigned(&masked, receiver) {
        return false;
    }
    let Some(bindings) = receiver_let_bindings(test, receiver) else {
        return false;
    };
    !bindings.is_empty()
        && bindings
            .into_iter()
            .all(|binding| initializer_is_independent(binding, type_name, index))
}

/// Whether the test may change `receiver` after binding it: an assignment
/// (`w = ..`, `w += ..`), or any `mut` before the name (`let mut w`,
/// `&mut w`, `ref mut w`, `|mut w|`). A `let mut` binding alone refuses:
/// a field write (`w.start = w.end`), a `&mut w.start` borrow or a
/// `&mut self` method call (`w.set_start(9)`) all need one, and ripr does
/// not read them.
fn receiver_is_reassigned(masked: &str, receiver: &str) -> bool {
    const COMPOUND: &[&str] = &["+=", "-=", "*=", "/=", "%=", "^=", "&=", "|=", "<<=", ">>="];
    whole_word_offsets(masked, receiver)
        .into_iter()
        .any(|offset| {
            let after = masked[offset + receiver.len()..].trim_start();
            let assigns =
                (after.starts_with('=') && !after.starts_with("==") && !after.starts_with("=>"))
                    || COMPOUND.iter().any(|operator| after.starts_with(operator));
            let before = masked[..offset].trim_end();
            let mutable = before.strip_suffix("mut").is_some_and(|rest| {
                !rest
                    .as_bytes()
                    .last()
                    .is_some_and(|byte| is_ident_byte(*byte))
            });
            let let_binding = before.strip_suffix("let").is_some_and(|rest| {
                !rest
                    .as_bytes()
                    .last()
                    .is_some_and(|byte| is_ident_byte(*byte))
            });
            (assigns && !let_binding) || mutable
        })
}

/// One receiver initializer: a `type_name { .. }` or `type_name(..)`
/// literal, or a `type_name::ctor(..)` call to the type's one inherent
/// constructor, whose fields or arguments are all [`is_trivial_expression`]
/// without locals: no call, method, macro, index, block or local binding
/// may supply a value (a helper or a local could carry a wrong clone's
/// output, `Window::new(make(&base))`). The constructor body must be a
/// bare `Self`/`type_name` literal of its parameters
/// ([`constructor_body_is_plain_literal`]).
fn initializer_is_independent(binding: &str, type_name: &str, index: &RustIndex) -> bool {
    let masked = mask_comments_and_strings(binding);
    let Some(equals) = masked.find('=') else {
        return false;
    };
    let initializer = masked[equals + 1..].trim();
    if CLONING_METHODS
        .iter()
        .any(|method| contains_as_whole_word(initializer, method))
    {
        return false;
    }
    let Some(rest) = initializer.strip_prefix(type_name) else {
        return false;
    };
    if let Some(call) = rest.strip_prefix("::") {
        let call_end = call
            .find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
            .unwrap_or(call.len());
        let constructor = &call[..call_end];
        let arguments = call[call_end..].trim_start();
        if !arguments.starts_with('(')
            || matching_close(arguments, 0, b'(', b')') != Some(arguments.len() - 1)
            || !literal_items_are_trivial(&arguments[1..arguments.len() - 1], false, false)
        {
            return false;
        }
        let mut definitions = index.functions().iter().filter(|function| {
            function.name == constructor
                && !function.item.has_self_param
                && matches!(
                    &function.item.container,
                    FunctionContainer::Inherent { self_ty } if path_base_name(self_ty) == Some(type_name)
                )
        });
        let (Some(definition), None) = (definitions.next(), definitions.next()) else {
            return false;
        };
        return constructor_body_is_plain_literal(&definition.body, type_name);
    }
    plain_literal(rest.trim_start(), false)
}

/// Whether `rest` (the text after a type name) is exactly one `{ .. }` or
/// `( .. )` literal body whose items are trivial; `locals` admits plain
/// lowercase bindings (a constructor's parameters) and field shorthand.
fn plain_literal(rest: &str, locals: bool) -> bool {
    let (open, close, braced) = match rest.as_bytes().first() {
        Some(b'{') => (b'{', b'}', true),
        Some(b'(') => (b'(', b')', false),
        _ => return false,
    };
    matching_close(rest, 0, open, close) == Some(rest.len() - 1)
        && literal_items_are_trivial(&rest[1..rest.len() - 1], braced, locals)
}

/// Whether every comma-separated item of a literal or argument list is a
/// trivial expression; in a braced literal each item is `field: expr` (or,
/// with `locals`, the shorthand `field`). A `..base` update refuses.
fn literal_items_are_trivial(items: &str, braced: bool, locals: bool) -> bool {
    if items.contains("..") {
        return false;
    }
    top_level_arguments(items).into_iter().all(|item| {
        if !braced {
            return is_trivial_expression(item, locals);
        }
        match item.split_once(':') {
            Some((field, value)) => {
                is_plain_identifier(field.trim())
                    && !value.starts_with(':')
                    && is_trivial_expression(value, locals)
            }
            None => locals && is_plain_identifier(item.trim()),
        }
    })
}

/// Whether a constructor's (masked) body is nothing but a `Self { .. }`,
/// `type_name { .. }`, `Self(..)` or `type_name(..)` literal of trivial
/// items over its parameters: no `let`, call, method, macro or helper that
/// could run a clone.
fn constructor_body_is_plain_literal(definition: &str, type_name: &str) -> bool {
    let masked = mask_comments_and_strings(definition);
    let Some(open) = masked
        .find('(')
        .and_then(|params| matching_close(&masked, params, b'(', b')'))
        .and_then(|params_close| {
            masked[params_close..]
                .find('{')
                .map(|offset| params_close + offset)
        })
    else {
        return false;
    };
    let Some(close) = matching_close(&masked, open, b'{', b'}') else {
        return false;
    };
    if !masked[close + 1..].trim().is_empty() {
        return false;
    }
    let tail = masked[open + 1..close].trim();
    let Some(rest) = tail
        .strip_prefix("Self")
        .or_else(|| tail.strip_prefix(type_name))
    else {
        return false;
    };
    plain_literal(rest.trim_start(), true)
}

/// Primitive type names a trivial expression may cast to.
const CAST_TYPES: &[&str] = &[
    "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16", "i32", "i64", "i128", "isize", "f32",
    "f64", "char", "bool",
];

/// Whether a (masked) expression only combines literals, `true`/`false`,
/// constants and enum variants named by a path whose last segment starts
/// uppercase, `as` casts to primitives and arithmetic, comparison and
/// bitwise operators. Calls, methods, macros, indexing, blocks, closures,
/// derefs, ranges, `?` and lowercase bindings (unless `locals`) refuse:
/// any of them may carry a value the clone under test produced.
fn is_trivial_expression(expression: &str, locals: bool) -> bool {
    let bytes = expression.as_bytes();
    if expression.trim().is_empty() {
        return false;
    }
    let mut index = 0usize;
    let mut after_as = false;
    while index < bytes.len() {
        let byte = bytes[index];
        if byte.is_ascii_digit() {
            index += 1;
            while index < bytes.len()
                && (is_ident_byte(bytes[index])
                    || (bytes[index] == b'.'
                        && bytes.get(index + 1).is_some_and(u8::is_ascii_digit)))
            {
                index += 1;
            }
            continue;
        }
        if byte.is_ascii_alphabetic() || byte == b'_' {
            let start = index;
            while index < bytes.len()
                && (is_ident_byte(bytes[index])
                    || (bytes[index] == b':' && bytes.get(index + 1) == Some(&b':')))
            {
                index += if bytes[index] == b':' { 2 } else { 1 };
            }
            let path = &expression[start..index];
            let last = path.rsplit("::").next().unwrap_or(path);
            let next = bytes.get(index).copied();
            let string_prefix = matches!(path, "b" | "r" | "br" | "c" | "cr")
                && matches!(next, Some(b'"' | b'#' | b'\''));
            let admitted = if after_as {
                CAST_TYPES.contains(&path)
            } else if path == "as" {
                after_as = true;
                continue;
            } else {
                string_prefix
                    || matches!(path, "true" | "false")
                    || last.starts_with(|character: char| character.is_ascii_uppercase())
                    || (locals && path == last && is_plain_identifier(path))
            };
            after_as = false;
            if !admitted || last.is_empty() {
                return false;
            }
            continue;
        }
        if byte.is_ascii_whitespace()
            || matches!(
                byte,
                b'"' | b'\'' | b'#' | b'-' | b'+' | b'/' | b'%' | b'&' | b'^' | b'<' | b'>' | b'='
            )
        {
            index += 1;
            continue;
        }
        return false;
    }
    !after_as
}

/// Whether `name` may be bound by a pattern that is not a `let`: a closure
/// parameter list, a `for` pattern, a match arm, the test's own or a
/// nested `fn`'s parameters. Lexical and conservative: a `|` operator or an unrelated
/// match arm that mentions the name also counts.
fn binds_outside_let(masked: &str, name: &str) -> bool {
    let fns = whole_word_offsets(masked, "fn");
    if fns.len() > 1 {
        return true;
    }
    // The test's own parameters (`#[case] name: T`) bind the name too.
    let parameters = fns.first().and_then(|offset| {
        let open = offset + masked[*offset..].find('(')?;
        let close = matching_close(masked, open, b'(', b')')?;
        Some(&masked[open..close])
    });
    if parameters.is_none_or(|parameters| contains_as_whole_word(parameters, name)) {
        return true;
    }
    let bytes = masked.as_bytes();
    let pipes = bytes
        .iter()
        .enumerate()
        .filter(|(offset, byte)| {
            **byte == b'|'
                && bytes.get(offset + 1) != Some(&b'|')
                && (*offset == 0 || bytes[offset - 1] != b'|')
        })
        .map(|(offset, _)| offset)
        .collect::<Vec<_>>();
    // Every region between two consecutive pipes: a `|` operator must not
    // shift a closure's parameter list out of the pairing.
    if pipes
        .windows(2)
        .any(|pair| contains_as_whole_word(&masked[pair[0]..pair[1]], name))
    {
        return true;
    }
    let for_pattern = whole_word_offsets(masked, "for").into_iter().any(|offset| {
        let rest = &masked[offset + "for".len()..];
        let end = whole_word_offsets(rest, "in")
            .first()
            .copied()
            .unwrap_or(rest.len());
        contains_as_whole_word(&rest[..end], name)
    });
    if for_pattern {
        return true;
    }
    masked.match_indices("=>").any(|(arrow, _)| {
        let start = masked[..arrow]
            .rfind(['{', ',', '}'])
            .map_or(0, |position| position + 1);
        contains_as_whole_word(&masked[start..arrow], name)
    })
}

/// The type of one `let <receiver> ...;` binding: its annotation, or a
/// constructor-shaped initializer.
fn binding_type(
    binding: &str,
    test: &TestSummary,
    test_source: Option<&str>,
    index: &RustIndex,
    imports_foreign: ForeignImport<'_>,
    owner: OwnerScope<'_>,
    syntax: &OwnerPinSyntax,
) -> Option<ReceiverType> {
    let binding = binding.trim();
    let (annotation, initializer) = if let Some(rest) = binding.strip_prefix(':') {
        let (annotation, initializer) = rest.split_once('=')?;
        (Some(annotation.trim()), initializer.trim())
    } else {
        (None, binding.strip_prefix('=')?.trim())
    };
    if let Some(annotation) = annotation {
        return named_or_slice(annotation, test, test_source, index, imports_foreign, owner);
    }
    if is_byte_slice_expression(initializer) {
        return Some(ReceiverType::ByteSlice);
    }
    let (initializer, unwrapped) = strip_unwrap(initializer);
    if !unwrapped
        && !initializer.is_empty()
        && initializer
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
    {
        // `= Unit`: only a unit struct's own name is a value of that type.
        // `named_or_slice` refuses a lower-case name anyway; checking first
        // skips the workspace scan for every local-variable receiver.
        if !initializer.starts_with(|character: char| character.is_ascii_uppercase())
            || !unit_struct_value(initializer, &test.file, index, syntax)
        {
            return None;
        }
        return named_or_slice(
            initializer,
            test,
            test_source,
            index,
            imports_foreign,
            owner,
        );
    }
    let type_end = initializer
        .find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))?;
    let type_name = &initializer[..type_end];
    let rest = &initializer[type_end..];
    let constructor = if let Some(call) = rest.strip_prefix("::") {
        let call_end =
            call.find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))?;
        let masked = mask_comments_and_strings(&call[call_end..]);
        masked.starts_with('(')
            && matching_close(&masked, 0, b'(', b')')
                .is_some_and(|closing| masked[closing + 1..].trim().is_empty())
            && constructor_returns_self(type_name, &call[..call_end], unwrapped, index)
    } else {
        let rest = rest.trim_start();
        let (open, close) = if rest.starts_with('{') {
            (b'{', b'}')
        } else {
            (b'(', b')')
        };
        let masked = mask_comments_and_strings(rest);
        !unwrapped
            && masked.as_bytes().first() == Some(&open)
            && matching_close(&masked, 0, open, close)
                .is_some_and(|closing| masked[closing + 1..].trim().is_empty())
    };
    if !constructor {
        return None;
    }
    named_or_slice(type_name, test, test_source, index, imports_foreign, owner)
}

impl OwnerPinSyntax {
    /// #7172: [`unit_struct_value`]'s name-independent inputs, computed
    /// once per run; the index is immutable, so the memo never goes stale.
    fn unit_struct_facts(&self, index: &RustIndex) -> &UnitStructFacts {
        self.unit_struct_facts
            .get_or_init(|| UnitStructFacts::collect(index))
    }
}

/// #7172: the name-independent inputs to [`unit_struct_value`], scanned
/// once per run over the immutable index. A bare-name receiver check runs
/// per assertion, and every call used to rebuild the module-name set and
/// mask + scan every indexed file; the per-name spelling checks stay per
/// call. Every verdict below conjoins exactly as the per-call scans did,
/// so hoisting them changes no admission.
#[derive(Clone, Debug, Default)]
struct UnitStructFacts {
    /// A glob in some file may reach outside the workspace's modules.
    glob_outside: bool,
    /// Some file splices unread text (`include!`) or redirects a module
    /// (`#[path]`, either spelling).
    spliced: bool,
    /// Some file's `macro_rules!` matcher takes an `:ident` or `:tt`
    /// fragment, which could declare any name it is given.
    macro_takes_name: bool,
    /// Files whose masked source mentions `macro_rules!`: only these can
    /// refuse a name by spelling it in a macro definition. Complete only
    /// while [`Self::refused`] is false: the scan stops at the first
    /// refusal verdict, and [`unit_struct_value`] reads this set only
    /// after that gate.
    macro_files: BTreeSet<PathBuf>,
}

impl UnitStructFacts {
    /// Scan the workspace once, stopping at the first refusal verdict:
    /// the predicates are name-independent, so no later file can change
    /// one. The module-name set feeds the glob verdict and is dropped;
    /// the predicates are the name-independent halves of
    /// [`unit_struct_value`]'s per-file checks, unchanged.
    fn collect(index: &RustIndex) -> Self {
        let modules = workspace_module_names(index);
        let mut glob_outside = false;
        let mut spliced = false;
        let mut macro_takes_name = false;
        let mut macro_files = BTreeSet::new();
        for (file, facts) in index.files().iter() {
            // Once any refusal verdict holds, the remaining files cannot
            // change it, and the caller refuses before reading
            // `macro_files`; stop paying for their masking.
            if glob_outside || spliced || macro_takes_name {
                break;
            }
            let masked = mask_comments_and_strings(&facts.source);
            // A glob that reaches outside the workspace's modules, in any
            // file, can bring the name to the test without spelling it.
            glob_outside |= glob_reaches_outside(&masked, &modules);
            // `include!` and `#[path]` splice in text the index may never
            // read, so no spelling scan covers them. The cheap filter
            // matches the bare words: `# [ path` may carry whitespace, and
            // rustc accepts the raw-identifier spelling `#[r#path = ..]`
            // too (#7098 review).
            if masked.contains("include") || masked.contains("path") {
                let compact = without_rust_whitespace(&masked);
                spliced |= compact.contains("include!")
                    || compact.contains("#[path")
                    || compact.contains("#[r#path");
            }
            // A macro may take the name as an `ident` or `tt` fragment; the
            // spelling half (no macro-defining file spells the name) stays
            // per name at the call.
            if masked.contains("macro_rules") {
                macro_files.insert(file.clone());
                let compact = without_rust_whitespace(&masked);
                macro_takes_name |= compact.contains(":ident") || compact.contains(":tt");
            }
        }
        Self {
            glob_outside,
            spliced,
            macro_takes_name,
            macro_files,
        }
    }

    /// Whether the workspace-wide scans refuse every name.
    fn refused(&self) -> bool {
        self.glob_outside || self.spliced || self.macro_takes_name
    }
}

/// Whether the bare name `name`, spelled in `test_file`, evaluates to the
/// workspace unit struct `name` (#7083). Reading what a bare name resolves
/// to needs name resolution, so the rule admits only a shape where nothing
/// else can supply the name:
///
/// - the workspace declares it exactly once, as a non-generic unit struct
///   (`struct name;`), in the test's own file;
/// - every other spelling of the name in the workspace is an `impl` header
///   (`impl name {`, `impl Trait for name {`), a method call (`name.f(..)`)
///   or a `let` initializer (`= name;`). An import, a type position, a raw
///   identifier (`r#name`), a pattern, an enum variant, a macro argument or
///   any `const`, `static`, `fn`, `type` or `as` rename refuses;
/// - no workspace `macro_rules!` matcher takes an `ident` or `tt` fragment,
///   which could declare the name from a spelling the scan reads as inert,
///   and no file that defines a macro spells the name, since one `struct
///   name;` in a macro body declares a type per invocation;
/// - every workspace glob import is a `crate`, `self` or `super` path
///   through declared workspace modules, so no glob brings in an outside
///   item (directly or through a renamed or re-exported outside module);
/// - the name is not a prelude value, and no workspace file uses `include!`
///   or `#[path]` (either spelling, including raw `#[r#path]`), which
///   splice in text the scan never reads.
///
/// Items a derive or attribute proc macro emits stay invisible, as for
/// every other pin rule, as do items an out-of-workspace `macro_rules!`
/// invocation emits (#7160).
fn unit_struct_value(
    name: &str,
    test_file: &Path,
    index: &RustIndex,
    syntax: &OwnerPinSyntax,
) -> bool {
    // A prelude value (`None`, `Some`, `Ok`, `Err`) is in scope without any
    // import, so the struct may not be the item the test names.
    if PRELUDE_VALUES.contains(&name) {
        return false;
    }
    // #7172: the workspace-wide scans ran once per call; they now come
    // from the run-scoped memo, and only the per-name spelling checks run.
    let unit_struct = syntax.unit_struct_facts(index);
    if unit_struct.refused() {
        return false;
    }
    let mut declared_in_test_file = 0usize;
    for (file, facts) in index.files().iter() {
        // Masking only blanks comments and strings, so a whole word in the
        // masked source is spelled in the raw source too: skipping files
        // without the name cannot skip a spelling the scan would refuse.
        if !facts.source.contains(name) {
            continue;
        }
        let masked = mask_comments_and_strings(&facts.source);
        // One spelling in a macro body declares a struct per invocation,
        // so no file that defines a macro may spell the name.
        if unit_struct.macro_files.contains(file) && !whole_word_offsets(&masked, name).is_empty() {
            return false;
        }
        for offset in whole_word_offsets(&masked, name) {
            let before = masked[..offset].trim_end();
            let after = masked[offset + name.len()..].trim_start();
            let word_start = before
                .rfind(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
                .map_or(0, |position| position + 1);
            let word = &before[word_start..];
            let item_end = after.starts_with('{') || starts_with_word(after, "where");
            let inert = match word {
                "struct" if after.starts_with(';') && file.as_path() == test_file => {
                    declared_in_test_file += 1;
                    true
                }
                "impl" | "for" => item_end,
                "" => {
                    (after.starts_with('.') && !after.starts_with(".."))
                        || (before.ends_with('=')
                            && !before.ends_with("==")
                            && !before.ends_with("!=")
                            && !before.ends_with("<=")
                            && !before.ends_with(">=")
                            && after.starts_with(';'))
                }
                _ => false,
            };
            if !inert {
                return false;
            }
        }
    }
    declared_in_test_file == 1
}

/// The prelude's value-namespace names a unit struct could share.
const PRELUDE_VALUES: &[&str] = &["None", "Some", "Ok", "Err"];

/// `text` without the characters rustc lexes as whitespace (Unicode
/// `Pattern_White_Space`: `char::is_whitespace` plus the left-to-right and
/// right-to-left marks).
fn without_rust_whitespace(text: &str) -> String {
    text.chars()
        .filter(|character| {
            !(character.is_whitespace() || matches!(character, '\u{200E}' | '\u{200F}'))
        })
        .collect()
}

/// Every name a workspace file declares with `mod`, less every name a `use`
/// or `extern crate` anywhere in the workspace may introduce. Names are not
/// resolved per crate or scope, so `use std::u32 as nums;` in one crate and
/// `mod nums` in another must not let `use crate::nums::*` pass (#7098
/// review): a segment that some import binds is never treated as a
/// workspace module.
fn workspace_module_names(index: &RustIndex) -> BTreeSet<String> {
    let mut modules = BTreeSet::new();
    let mut imported = BTreeSet::new();
    for (_, facts) in index.files().iter() {
        let masked = mask_comments_and_strings(&facts.source);
        for offset in whole_word_offsets(&masked, "mod") {
            let rest = masked[offset + "mod".len()..].trim_start();
            let end = rest
                .find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
                .unwrap_or(rest.len());
            if end > 0 {
                modules.insert(rest[..end].to_string());
            }
        }
        for keyword in ["use", "extern"] {
            for offset in whole_word_offsets(&masked, keyword) {
                let rest = &masked[offset + keyword.len()..];
                let Some(end) = rest.find(';') else {
                    continue;
                };
                imported.extend(import_bound_names(&rest[..end]));
            }
        }
    }
    modules.retain(|module| !imported.contains(module));
    modules
}

/// Every identifier in an import statement that is not followed by `::`
/// (Rust whitespace allowed between): each name the statement may bind,
/// whether a leaf, a group member or an `as` rename, plus harmless keywords.
fn import_bound_names(statement: &str) -> Vec<String> {
    let mut names = Vec::new();
    let mut position = 0;
    while position < statement.len() {
        let rest = &statement[position..];
        let length = rest
            .find(|character: char| !(character.is_alphanumeric() || character == '_'))
            .unwrap_or(rest.len());
        if length == 0 {
            position += rest.chars().next().map_or(1, char::len_utf8);
            continue;
        }
        let word = &rest[..length];
        let next = rest[length..].trim_start_matches(|character: char| {
            character.is_whitespace() || matches!(character, '\u{200E}' | '\u{200F}')
        });
        if !next.starts_with("::") {
            names.push(word.to_string());
        }
        position += length;
    }
    names
}

/// Whether `masked` holds a glob `use` that may reach items outside the
/// workspace's own modules. Only a plain `crate::`, `self::` or `super::`
/// path whose further segments are `super` or declared module names
/// passes. A foreign root, a renamed or re-exported outside module
/// (`use std::u32 as nums;` then `use crate::nums::*`), an enum's variants
/// and a glob inside a `{..}` group all refuse.
fn glob_reaches_outside(masked: &str, modules: &BTreeSet<String>) -> bool {
    whole_word_offsets(masked, "use").into_iter().any(|start| {
        let rest = &masked[start + "use".len()..];
        let Some(end) = rest.find(';') else {
            return false;
        };
        let statement = without_rust_whitespace(&rest[..end]);
        if !statement.contains('*') {
            return false;
        }
        let Some(path) = statement.trim_start_matches("::").strip_suffix("::*") else {
            return true;
        };
        let mut segments = path.split("::");
        let rooted = segments
            .next()
            .is_some_and(|root| matches!(root, "crate" | "self" | "super"));
        !(rooted && segments.all(|segment| segment == "super" || modules.contains(segment)))
    })
}

/// The initializer without a trailing `?`, `.unwrap()` or `.expect(..)`,
/// and whether one was there.
fn strip_unwrap(initializer: &str) -> (&str, bool) {
    let initializer = initializer.trim();
    if let Some(rest) = initializer
        .strip_suffix('?')
        .or_else(|| initializer.strip_suffix(".unwrap()"))
    {
        return (rest.trim_end(), true);
    }
    let masked = mask_comments_and_strings(initializer);
    if masked.ends_with(')')
        && let Some(position) = masked.rfind(".expect(")
        && matching_close(&masked, position + ".expect".len(), b'(', b')') == Some(masked.len() - 1)
    {
        return (initializer[..position].trim_end(), true);
    }
    (initializer, false)
}

/// Whether `type_name::constructor(..)` (unwrapped when `unwrapped`)
/// evaluates to a `type_name`. `default` and `from` return `Self` by their
/// traits' signatures and `try_from` returns `Result<Self, _>`; any other
/// associated function must be the type's one inherent definition of that
/// name, returning `Self` (or the type) directly, or inside
/// `Result`/`Option` when unwrapped.
fn constructor_returns_self(
    type_name: &str,
    constructor: &str,
    unwrapped: bool,
    index: &RustIndex,
) -> bool {
    match constructor {
        "default" | "from" => return !unwrapped,
        "try_from" => return unwrapped,
        _ => {}
    }
    let mut definitions = index.functions().iter().filter(|function| {
        function.name == constructor
            && !function.item.has_self_param
            && matches!(
                &function.item.container,
                FunctionContainer::Inherent { self_ty } if path_base_name(self_ty) == Some(type_name)
            )
    });
    let (Some(definition), None) = (definitions.next(), definitions.next()) else {
        return false;
    };
    let Some(returned) = declared_return_type(&definition.body) else {
        return false;
    };
    let names_type = |text: &str| {
        let text = text.trim();
        text == "Self" || path_base_name(text) == Some(type_name)
    };
    if unwrapped {
        ["Result<", "Option<"].iter().any(|wrapper| {
            returned
                .strip_prefix(wrapper)
                .and_then(|inner| inner.strip_suffix('>'))
                .is_some_and(|inner| names_type(inner.split(',').next().unwrap_or(inner)))
        })
    } else {
        names_type(&returned)
    }
}

/// The return type a `fn` definition declares, whitespace-collapsed.
pub(super) fn declared_return_type(definition: &str) -> Option<String> {
    let masked = mask_comments_and_strings(definition);
    let params = masked.find('(')?;
    let params_close = matching_close(&masked, params, b'(', b')')?;
    let body_open = params_close + masked[params_close..].find('{')?;
    let signature = collapse_whitespace(&definition[params_close + 1..body_open]);
    let signature = signature.split(" where ").next().unwrap_or(&signature);
    Some(signature.trim().strip_prefix("->")?.trim().to_string())
}

fn named_or_slice(
    type_text: &str,
    test: &TestSummary,
    test_source: Option<&str>,
    index: &RustIndex,
    imports_foreign: ForeignImport<'_>,
    owner: OwnerScope<'_>,
) -> Option<ReceiverType> {
    if is_byte_slice_type(type_text) {
        return Some(ReceiverType::ByteSlice);
    }
    let base = path_base_name(type_text)?;
    if !base.starts_with(|character: char| character.is_ascii_uppercase()) {
        return None;
    }
    // A test file that imports the name from outside the workspace, renames
    // another item to it, aliases it, or declares it in the test's own
    // module scope — in its own file (#6905) or in an out-of-line parent
    // module (#6950) — binds a different type than the workspace declaration.
    let source = test_source?;
    // `r#Window` denotes `Window`: a raw-identifier alias rebinds the name
    // too (#7067, mirroring the #7051 parent-root check).
    let raw = format!("r#{base}");
    if imports_foreign(&test.file, base)
        || file_renames_to(source, base)
        || file_renames_to(source, raw.as_str())
        || file_aliases_type(source, base)
        || test_module_shadows_type(test, source, base, owner.in_file(&test.file))
        || parent_chain_shadows_type(test, base, owner, index)
    {
        return None;
    }
    Some(ReceiverType::Named(base.to_string()))
}

/// The owner's identity, for the #6957 shadow exemption: the owner's own
/// scope holds the production declaration, so it is not a test-local
/// shadow. The single-file check resolves the scope in the test file's own
/// parse only ([`OwnerScope::in_file`]); the parent-chain walk resolves it
/// in whichever chain file holds the owner (#6950).
#[derive(Clone, Copy)]
pub(in crate::analysis) struct OwnerScope<'a> {
    name: &'a str,
    start_line: usize,
    file: &'a Path,
}

impl<'a> OwnerScope<'a> {
    /// The owner's total identity.
    pub(in crate::analysis) fn new(name: &'a str, start_line: usize, file: &'a Path) -> Self {
        Self {
            name,
            start_line,
            file,
        }
    }

    /// This scope when the owner lives in `test_file`, or `None` when a
    /// cross-file owner keeps the fail-closed single-file check.
    /// Related-test reach reuses the #6957 exemption through this (#6951).
    pub(in crate::analysis) fn in_file(&self, test_file: &Path) -> Option<Self> {
        (test_file == self.file).then_some(*self)
    }
}

/// Whether the test's own inline-module scope declares the receiver type
/// name (#6905): a `struct`, `enum`, `union` or `type` alias that is a
/// direct item of an enclosing `mod` shadows the production type for the
/// test, so a binding of that name names the test-local type, not the
/// changed owner, and the pin is refused. Only direct items of enclosing
/// inline modules count: a same-name declaration in a sibling module or at
/// the file root (the production declaration itself, for same-file tests)
/// does not shadow the test's view. Nor does one in the owner's own
/// enclosing module (#6957): when the production declaration sits in an
/// enclosing non-root module, that module is the owner's scope, not a
/// shadow. A same-name declaration in any other enclosing module — the
/// test's own `mod tests` included — still refuses. An explicit import
/// naming the type in an inner scope would disambiguate, but this stays
/// lexical and fails closed. A file that textually declares the name
/// nowhere needs no parse; one that fails to parse fails closed.
///
/// Shared with related-test classification (#6951): a shadowed receiver
/// type also refuses `direct_owner_call` reach credit, for the same
/// entity-identity reason.
pub(in crate::analysis) fn test_module_shadows_type(
    test: &TestSummary,
    source: &str,
    base: &str,
    owner: Option<OwnerScope<'_>>,
) -> bool {
    test_module_shadows_item(test, source, base, owner, ShadowKind::Type)
}

/// Whether the test's own inline-module scope declares a `trait` named like
/// the owner's trait (#7053): inside that module `Render::render(..)` and
/// `.render()` name the test-local trait and its impls, so a call there is
/// no evidence about the production `impl Render for T`. Same scope rules
/// as [`test_module_shadows_type`].
pub(in crate::analysis) fn test_module_shadows_trait(
    test: &TestSummary,
    source: &str,
    trait_name: &str,
    owner: Option<OwnerScope<'_>>,
) -> bool {
    test_module_shadows_item(test, source, trait_name, owner, ShadowKind::Trait)
}

/// The kind of declaration a test-module shadow check looks for.
#[derive(Clone, Copy, PartialEq, Eq)]
enum ShadowKind {
    Type,
    Trait,
}

fn test_module_shadows_item(
    test: &TestSummary,
    source: &str,
    base: &str,
    owner: Option<OwnerScope<'_>>,
    kind: ShadowKind,
) -> bool {
    let masked = mask_comments_and_strings(source);
    // `r#Window` denotes `Window`: a raw-identifier declaration shadows too.
    let raw = format!("r#{base}");
    let declared = match kind {
        ShadowKind::Type => declares_type(&masked, base) || file_aliases_type(source, base),
        ShadowKind::Trait => declares_trait(&masked, base),
    };
    if !declared && !masked.contains(raw.as_str()) {
        return false;
    }
    let Some(parse) = parse_clean_source_file(source) else {
        return true;
    };
    // 1-based file lines, matching `TestSummary`.
    let line_of = |offset: u32| source[..offset as usize].matches('\n').count() + 1;
    let root = parse.tree().syntax().clone();
    let owner_module = owner.and_then(|owner| owner_enclosing_module(&root, source, owner));
    // The owner's own module is the production declaration's scope, never a
    // shadow; every other enclosing module still counts.
    let counts = |module: &ast::Module| {
        owner_module.is_none_or(|exempt| module.syntax().text_range() != exempt)
    };
    // Exact scope first: the test fn's own ancestor modules. Line spans can
    // coincide for same-line siblings (`mod s { struct W; } #[test] fn t()
    // {...}`), where byte-exact ancestry refuses nothing, so ancestry
    // decides whenever the test fn resolves. Macro-shaped tests whose fn
    // has no matching node keep the line-span fallback below.
    let test_name = test.name.strip_prefix("r#").unwrap_or(&test.name);
    let test_fns: Vec<_> = root
        .descendants()
        .filter_map(ast::Fn::cast)
        .filter(|func| {
            func.name().is_some_and(|name| {
                let text = name.text().to_string();
                text.strip_prefix("r#").unwrap_or(&text) == test_name
            }) && {
                let range = func.syntax().text_range();
                let start: u32 = range.start().into();
                let end: u32 = range.end().into();
                line_of(start) <= test.end_line && test.start_line <= line_of(end)
            }
        })
        .collect();
    if !test_fns.is_empty() {
        return test_fns.iter().any(|func| {
            func.syntax()
                .ancestors()
                .filter_map(ast::Module::cast)
                .filter(|module| counts(module))
                .any(|module| {
                    module.item_list().is_some_and(|items| {
                        items
                            .items()
                            .any(|item| module_item_names(&item, base, kind))
                    })
                })
        });
    }
    root.descendants()
        .filter_map(ast::Module::cast)
        .filter_map(|module| module.item_list().map(|items| (module, items)))
        .any(|(module, items)| {
            let range = module.syntax().text_range();
            let start: u32 = range.start().into();
            let end: u32 = range.end().into();
            line_of(start) <= test.start_line
                && test.end_line <= line_of(end)
                && counts(&module)
                && items
                    .items()
                    .any(|item| module_item_names(&item, base, kind))
        })
}

/// Whether an out-of-line parent module of the test file declares the
/// receiver type name (#6950): the parent chain through out-of-line `mod`
/// declarations (the test file's composed role provenance) is the test's
/// enclosing module scope beyond its own file. A `struct`, `enum`, `union`
/// or `type` alias that is a direct item of a parent file's root shadows
/// the production type for the test exactly as an enclosing inline
/// declaration does (#6905), as does a root-level `use ... as <name>`
/// rebinding, so a binding of that name names the test-local type and
/// the pin is refused.
///
/// Only parent roots count: the module-declaration producer emits
/// top-level declarations only, so a recorded edge's parent scope is the
/// file root, and a sibling inline module is out of scope by the same
/// precision rule as same-file siblings. The test file's own root stays
/// exempt (the #6905 single-file behavior, via
/// [`test_module_shadows_type`]); each parent root counts unless it is the
/// owner's own scope — the file holding the owner with the owner at its
/// root (the transposed #6957 exemption).
///
/// Shared with related-test classification like [`test_module_shadows_type`]:
/// a shadowed receiver also refuses `direct_owner_call` reach credit.
/// Fail-closed throughout: an unresolved chain
/// (`rust_module_ambiguous_parent` and its siblings), an `include!` edge
/// (whose scope needs site localization this lexical check does not do), a
/// missing parent file, and an unparseable parent that textually declares
/// the name all refuse rather than guess. A parent that textually declares
/// the name nowhere needs no parse.
pub(in crate::analysis) fn parent_chain_shadows_type(
    test: &TestSummary,
    base: &str,
    owner: OwnerScope<'_>,
    index: &RustIndex,
) -> bool {
    parent_chain_shadows_item(test, base, owner, index, ShadowKind::Type)
}

/// [`parent_chain_shadows_type`] for the owner's trait (#7087): a `trait`
/// item, or a macro whose own text declares one, at the root of an
/// out-of-line parent module of the test file names the test-local trait,
/// so `Trait::method(..)` and `.method()` there never reach the production
/// `impl Trait for T`. Same chain, fail-closed and owner-scope rules as the
/// type check; declarations only, like [`test_module_shadows_trait`].
pub(in crate::analysis) fn parent_chain_shadows_trait(
    test: &TestSummary,
    trait_name: &str,
    owner: OwnerScope<'_>,
    index: &RustIndex,
) -> bool {
    parent_chain_shadows_item(test, trait_name, owner, index, ShadowKind::Trait)
}

fn parent_chain_shadows_item(
    test: &TestSummary,
    base: &str,
    owner: OwnerScope<'_>,
    index: &RustIndex,
    kind: ShadowKind,
) -> bool {
    let Some(facts) = index.files().get(&test.file) else {
        return false;
    };
    let chain = &facts.role_provenance;
    let owner_ancestors = match kind {
        ShadowKind::Type => Vec::new(),
        ShadowKind::Trait => owner_module_ancestors(owner, index),
    };
    // The reason leads: an immediately ambiguous parent composes to empty
    // edges with the reason set, which is unresolved, not standalone.
    if chain.earliest_unresolved_reason.is_some() {
        return true;
    }
    if chain.edges.is_empty() {
        return false;
    }
    chain.edges.iter().any(|edge| {
        if edge.kind != SourceRoleProvenanceEdgeKind::Module {
            return true;
        }
        let Some(parent) = index.files().get(&edge.parent) else {
            return true;
        };
        parent_root_shadows_item(
            &parent.source,
            &edge.parent,
            base,
            owner,
            kind,
            &owner_ancestors,
        )
    })
}

/// Whether one parent file's root declares the receiver type name: the
/// per-edge step of [`parent_chain_shadows_type`] and
/// [`parent_chain_shadows_trait`]. A root-level
/// `use ... as <name>` rebinds the name to a different type and shadows
/// too; a plain root-level `use` may re-export production, so only
/// renames refuse. The owner's own root (the file holding a root-level
/// owner) is the production declaration's scope, never a shadow; every
/// other declaring root refuses.
fn parent_root_shadows_item(
    parent_source: &str,
    parent_file: &Path,
    base: &str,
    owner: OwnerScope<'_>,
    kind: ShadowKind,
    owner_ancestors: &[PathBuf],
) -> bool {
    let masked = mask_comments_and_strings(parent_source);
    // `r#Window` denotes `Window`: a raw-identifier declaration shadows too.
    let raw = format!("r#{base}");
    // Aliases and renames rebind a type name only; a trait is shadowed by a
    // declaration (#7087), matching the in-file trait check (#7053).
    let declared = match kind {
        ShadowKind::Type => {
            declares_type(&masked, base)
                || file_aliases_type(parent_source, base)
                || file_renames_to(parent_source, base)
        }
        ShadowKind::Trait => declares_trait(&masked, base),
    };
    if !declared && !masked.contains(raw.as_str()) {
        return false;
    }
    let Some(parse) = parse_clean_source_file(parent_source) else {
        return true;
    };
    let root = parse.tree().syntax().clone();
    let root_items: Vec<ast::Item> = root.children().filter_map(ast::Item::cast).collect();
    if !root_items
        .iter()
        .any(|item| module_item_names(item, base, kind))
        && !root_items.iter().any(|item| {
            if kind == ShadowKind::Trait || !matches!(item, ast::Item::Use(_)) {
                return false;
            }
            let text = item.syntax().text().to_string();
            // `r#Window` denotes `Window`: a raw-identifier alias rebinds
            // the name too.
            file_renames_to(&text, base) || file_renames_to(&text, raw.as_str())
        })
    {
        return false;
    }
    if owner.file == parent_file && owner_at_file_root(&root, parent_source, owner) {
        return false;
    }
    // A trait is commonly declared in an ancestor file of the file holding
    // its impls (#7111): a declaring root on the owner's own module chain is
    // the production declaration, not a shadow.
    if owner_ancestors
        .iter()
        .any(|ancestor| ancestor == parent_file)
    {
        return false;
    }
    true
}

/// The files whose module scope encloses the owner's file: the file itself
/// (its root encloses every inline module in it) and the parents on its
/// composed module chain. Empty when the owner file is not indexed, which
/// keeps the fail-closed shadow check.
fn owner_module_ancestors(owner: OwnerScope<'_>, index: &RustIndex) -> Vec<PathBuf> {
    let Some(facts) = index.files().get(owner.file) else {
        return Vec::new();
    };
    std::iter::once(owner.file.to_path_buf())
        .chain(
            facts
                .role_provenance
                .edges
                .iter()
                .filter(|edge| edge.kind == SourceRoleProvenanceEdgeKind::Module)
                .map(|edge| edge.parent.clone()),
        )
        .collect()
}

/// The text range of the inline module directly enclosing the owner
/// (#6957): for inline code the owner's own nearest enclosing `mod`
/// is the `impl`'s module, and a same-name type declared there is the
/// production declaration, not a shadow. `None` keeps the fail-closed
/// shadow check: a root-level owner has no enclosing module, and an owner
/// whose `fn` node does not resolve exactly once (macro-shaped, out-of-line
/// or ambiguous) resolves to no scope. Byte-exact ancestry, not line spans,
/// decides, so a same-line sibling module is never the owner's scope.
fn owner_enclosing_module(
    root: &SyntaxNode,
    source: &str,
    owner: OwnerScope<'_>,
) -> Option<TextRange> {
    resolve_owner_fn(root, source, owner)?
        .syntax()
        .ancestors()
        .filter_map(ast::Module::cast)
        .next()
        .map(|module| module.syntax().text_range())
}

/// Whether the owner fn resolves in `source` at the file root: exactly one
/// same-name `fn` spans the owner's start line, with no enclosing inline
/// module (#6950). A parent-file root holding both the receiver type and a
/// root-level owner is the production scope, not a shadow; an unresolvable
/// owner resolves to no scope and keeps the fail-closed check.
fn owner_at_file_root(root: &SyntaxNode, source: &str, owner: OwnerScope<'_>) -> bool {
    resolve_owner_fn(root, source, owner).is_some_and(|found| {
        found
            .syntax()
            .ancestors()
            .filter_map(ast::Module::cast)
            .next()
            .is_none()
    })
}

/// The owner's `fn` node in this file's parse: exactly one same-name `fn`
/// spanning the owner's start line. Byte-exact ancestry, not line spans,
/// decides, so a same-line sibling module is never the owner's scope; a
/// nested same-name `fn` sharing the owner's start line resolves to no
/// scope rather than the wrong one.
fn resolve_owner_fn(root: &SyntaxNode, source: &str, owner: OwnerScope<'_>) -> Option<ast::Fn> {
    // 1-based file lines, matching `FunctionSummary`.
    let line_of = |offset: u32| source[..offset as usize].matches('\n').count() + 1;
    let name = owner.name.strip_prefix("r#").unwrap_or(owner.name);
    let mut owners = root.descendants().filter_map(ast::Fn::cast).filter(|func| {
        func.name().is_some_and(|func_name| {
            let text = func_name.text().to_string();
            text.strip_prefix("r#").unwrap_or(&text) == name
        }) && {
            let range = func.syntax().text_range();
            let start: u32 = range.start().into();
            let end: u32 = range.end().into();
            line_of(start) <= owner.start_line && owner.start_line <= line_of(end)
        }
    });
    let found = owners.next()?;
    owners.next().is_none().then_some(found)
}

/// Whether a direct module item declares `base` as the given kind: a type
/// (see [`module_item_names_type`]) or, for [`ShadowKind::Trait`] (#7053), a
/// `trait` item or a macro whose own text declares one.
fn module_item_names(item: &ast::Item, base: &str, kind: ShadowKind) -> bool {
    if kind == ShadowKind::Type {
        return module_item_names_type(item, base);
    }
    let named = match item {
        ast::Item::Trait(item) => item.name(),
        _ => None,
    };
    if named.is_some_and(|name| {
        let text = name.text().to_string();
        text.strip_prefix("r#").unwrap_or(&text) == base
    }) {
        return true;
    }
    // A macro can declare the trait; its text decides, as for types.
    matches!(
        item,
        ast::Item::MacroRules(_) | ast::Item::MacroDef(_) | ast::Item::MacroCall(_)
    ) && {
        let text = mask_comments_and_strings(&item.syntax().text().to_string());
        declares_trait(&text, base) || declares_trait(&text, &format!("r#{base}"))
    }
}

/// Whether a direct module item declares the type name `base` (`r#Window`
/// denotes `Window`). A macro definition or invocation may emit the type
/// (#6948 review): the parsed item is the macro, not the struct, enum,
/// union or alias it generates, so a lexical declaration of the name inside
/// the macro's own text fails closed.
fn module_item_names_type(item: &ast::Item, base: &str) -> bool {
    let name = match item {
        ast::Item::Struct(item) => item.name(),
        ast::Item::Enum(item) => item.name(),
        ast::Item::Union(item) => item.name(),
        ast::Item::TypeAlias(item) => item.name(),
        _ => None,
    };
    if name.is_some_and(|name| {
        let text = name.text().to_string();
        text.strip_prefix("r#").unwrap_or(&text) == base
    }) {
        return true;
    }
    if !matches!(
        item,
        ast::Item::MacroRules(_) | ast::Item::MacroDef(_) | ast::Item::MacroCall(_)
    ) {
        return false;
    }
    let text = mask_comments_and_strings(&item.syntax().text().to_string());
    declares_type(&text, base)
        || declares_type(&text, &format!("r#{base}"))
        || file_aliases_type(&text, base)
}

/// A trait's methods are callable with method syntax only while the trait
/// is in scope: the test's file imports it by name from the workspace, or
/// declares it.
fn trait_in_scope(source: &str, trait_name: &str, index: &RustIndex) -> bool {
    if file_imports_foreign_callee_name(source, trait_name, &index.package_names) {
        return false;
    }
    if file_imports_own_item(source, trait_name, &index.package_names) {
        return true;
    }
    let masked = mask_comments_and_strings(source);
    whole_word_offsets(&masked, "trait")
        .into_iter()
        .any(|offset| {
            masked[offset + "trait".len()..]
                .trim_start()
                .strip_prefix(trait_name)
                .is_some_and(|after| {
                    !after.starts_with(|character: char| {
                        character.is_ascii_alphanumeric() || character == '_'
                    })
                })
        })
}

fn test_body_shadows_owner(test: &TestSummary, owner: &str) -> bool {
    if fact_body_defines_callee_fn(&test.nested_fn_names, owner)
        || fact_body_let_shadow_line(&test.let_bindings, owner).is_some()
    {
        return true;
    }
    let masked = mask_comments_and_strings(&test.body);
    test_body_defines_callee_fn(&masked, owner)
        || test_body_let_shadow_line(&masked, owner).is_some()
}

fn is_byte_slice_type(text: &str) -> bool {
    let compact: String = text.split_whitespace().collect();
    let Some(rest) = compact.strip_prefix('&') else {
        return false;
    };
    let rest = match rest.strip_prefix('\'') {
        Some(lifetime) => lifetime.trim_start_matches(|character: char| {
            character.is_ascii_alphanumeric() || character == '_'
        }),
        None => rest,
    };
    rest == "[u8]"
}

/// `&[..][..]` or `&b".."[..]`: a byte-slice expression.
fn is_byte_slice_expression(initializer: &str) -> bool {
    let Some(rest) = initializer.trim().strip_prefix('&') else {
        return false;
    };
    let Some(array) = rest.trim_end().strip_suffix("[..]") else {
        return false;
    };
    let array = array.trim();
    if let Some(bytes) = array.strip_prefix("b\"") {
        return bytes.ends_with('"');
    }
    let masked = mask_comments_and_strings(array);
    masked.starts_with('[')
        && matching_close(&masked, 0, b'[', b']').is_some_and(|close| close + 1 == masked.len())
}

/// The last `::` segment of a path, without generic arguments.
fn path_base_name(path: &str) -> Option<&str> {
    let path = path.trim();
    let without_generics = path.split('<').next()?.trim();
    let base = without_generics.rsplit("::").next()?.trim();
    is_plain_identifier(base).then_some(base)
}

fn is_plain_identifier(text: &str) -> bool {
    text.starts_with(|character: char| character.is_ascii_alphabetic() || character == '_')
        && text
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || character == '_')
}

fn is_ident_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_'
}

fn whole_word_offsets(text: &str, word: &str) -> Vec<usize> {
    let bytes = text.as_bytes();
    let mut offsets = Vec::new();
    let mut search = 0usize;
    while let Some(relative) = text[search..].find(word) {
        let offset = search + relative;
        let end = offset + word.len();
        let before_ok = offset == 0 || !is_ident_byte(bytes[offset - 1]);
        let after_ok = end >= bytes.len() || !is_ident_byte(bytes[end]);
        if before_ok && after_ok {
            offsets.push(offset);
        }
        search = end;
    }
    offsets
}

/// Offset of the first `;` outside brackets.
fn top_level_semicolon(masked: &str) -> Option<usize> {
    let mut depth = 0usize;
    for (offset, byte) in masked.bytes().enumerate() {
        match byte {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth = depth.checked_sub(1)?,
            b';' if depth == 0 => return Some(offset),
            _ => {}
        }
    }
    None
}

/// Whether `text` is one unqualified `assert!` whose only nested macro is a
/// `matches!`, as [`is_plain_macro`] reads a lone `assert!`.
fn is_plain_assert_of_matches(text: &str) -> bool {
    let masked = mask_comments_and_strings(text);
    let invocations = macro_invocations(&masked);
    let [("assert", _), ("matches", _)] = invocations.as_slice() else {
        return false;
    };
    masked
        .find("assert")
        .is_some_and(|offset| !masked[..offset].trim_end().ends_with(':'))
        && masked
            .find("matches")
            .is_some_and(|offset| !masked[..offset].trim_end().ends_with(':'))
}

/// RIPR-SPEC-0197 literal `matches!` pins: the scrutinee and the pinned value of a
/// `matches!(scrutinee, pattern)` condition whose pattern is literal-only, so
/// that matching it is equality with one value. Anything else refuses: a
/// guard, an or-pattern, a wildcard, a rest or range, a reference or slice
/// pattern, a binding without a literal subpattern, and every path or
/// constant, since the line cannot tell a constant from a binding or check
/// that a path names the std `Option`/`Result` variants.
fn literal_matches_operands(condition: &str) -> Option<[String; 2]> {
    let rest = condition.trim().strip_prefix("matches!")?.trim_start();
    let masked = mask_comments_and_strings(rest);
    let close = matching_close(&masked, 0, b'(', b')')?;
    if close + 1 != rest.len() {
        return None;
    }
    let inner = masked.get(1..close)?;
    let mut depth = 0usize;
    let mut commas = Vec::new();
    for (offset, byte) in inner.bytes().enumerate() {
        match byte {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth = depth.checked_sub(1)?,
            b',' if depth == 0 => commas.push(offset),
            _ => {}
        }
    }
    // `matches!` accepts one trailing comma after the pattern.
    let (comma, end) = match commas.as_slice() {
        [comma] => (*comma, inner.len()),
        [comma, trailing] if inner.get(trailing + 1..)?.trim().is_empty() => (*comma, *trailing),
        _ => return None,
    };
    let scrutinee = rest.get(1..comma + 1)?.trim();
    let pattern = literal_value_pattern(rest.get(comma + 2..end + 1)?)?;
    (!scrutinee.is_empty()).then(|| [scrutinee.to_string(), pattern])
}

/// A literal-only pattern rewritten as the value it matches: `Some(x @ 3)`
/// becomes `Some(3)`. Only `Some`, `Ok` and `Err` around a payload, `None`,
/// `true`, `false`, a numeric literal (optionally negated) and a plain string
/// literal are admitted.
fn literal_value_pattern(pattern: &str) -> Option<String> {
    let chars: Vec<char> = pattern.trim().chars().collect();
    let mut value = String::new();
    let mut at = 0;
    let mut depth = 0usize;
    // Whether the next token starts a subpattern (after `(`, `,` or `@`).
    let mut expects_pattern = true;
    while let Some(&ch) = chars.get(at) {
        if ch.is_whitespace() {
            at += 1;
            continue;
        }
        if ch == '"' {
            if !expects_pattern {
                return None;
            }
            let start = at;
            at += 1;
            loop {
                match chars.get(at)? {
                    '\\' => at += 2,
                    '"' => break,
                    _ => at += 1,
                }
            }
            at += 1;
            value.extend(&chars[start..at]);
            expects_pattern = false;
            continue;
        }
        if ch.is_ascii_digit() || (ch == '-' && expects_pattern) {
            if !expects_pattern {
                return None;
            }
            let start = at;
            at += 1;
            while chars
                .get(at)
                .is_some_and(|next| next.is_ascii_alphanumeric() || matches!(next, '_' | '.'))
            {
                at += 1;
            }
            let literal: String = chars[start..at].iter().collect();
            let digits = literal.strip_prefix('-').unwrap_or(&literal);
            if !digits.starts_with(|first: char| first.is_ascii_digit()) || literal.contains("..") {
                return None;
            }
            value.push_str(&literal);
            expects_pattern = false;
            continue;
        }
        if ch.is_alphabetic() || ch == '_' {
            let start = at;
            while chars
                .get(at)
                .is_some_and(|next| next.is_alphanumeric() || *next == '_')
            {
                at += 1;
            }
            let word: String = chars[start..at].iter().collect();
            let mut next = at;
            while chars.get(next).is_some_and(|next| next.is_whitespace()) {
                next += 1;
            }
            if !expects_pattern {
                return None;
            }
            match (word.as_str(), chars.get(next)) {
                ("Some" | "Ok" | "Err", Some('(')) => {
                    value.push_str(&word);
                    value.push('(');
                    depth += 1;
                    at = next + 1;
                }
                ("None" | "true" | "false", _) => {
                    value.push_str(&word);
                    expects_pattern = false;
                }
                // `name @ literal`: the binding names the value it matched.
                (_, Some('@'))
                    if word != "_"
                        && word.starts_with(|first: char| first.is_lowercase() || first == '_')
                        && !matches!(word.as_str(), "ref" | "mut") =>
                {
                    at = next + 1;
                }
                _ => return None,
            }
            continue;
        }
        match ch {
            ')' if depth > 0 && !expects_pattern => {
                depth -= 1;
                value.push(')');
            }
            // `Some(3,)`: one trailing comma before the constructor closes.
            ')' if depth > 0 && expects_pattern && value.ends_with(", ") => {
                depth -= 1;
                value.truncate(value.len() - ", ".len());
                value.push(')');
                expects_pattern = false;
            }
            ',' if depth > 0 && !expects_pattern => {
                value.push_str(", ");
                expects_pattern = true;
            }
            _ => return None,
        }
        at += 1;
    }
    (depth == 0 && !expects_pattern).then_some(value)
}

/// The offset of the bracket closing the one at `opening`, in masked text.
fn matching_close(masked: &str, opening: usize, open: u8, close: u8) -> Option<usize> {
    let bytes = masked.as_bytes();
    if bytes.get(opening) != Some(&open) {
        return None;
    }
    let mut depth = 0usize;
    for (offset, byte) in bytes.iter().enumerate().skip(opening) {
        if *byte == open {
            depth += 1;
        } else if *byte == close {
            depth = depth.checked_sub(1)?;
            if depth == 0 {
                return Some(offset);
            }
        }
    }
    None
}

fn collapse_whitespace(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

